function patchMembersByLocalGroup(values) {
  const members = new Map();
  (Array.isArray(values) ? values : []).forEach((row) => {
    const localPatchGroupId = Number(row?.local_patch_group_id);
    if (!Number.isInteger(localPatchGroupId) || localPatchGroupId <= 0) return;
    if (!members.has(localPatchGroupId)) members.set(localPatchGroupId, []);
    members.get(localPatchGroupId).push(row);
  });
  return members;
}

async function renderChannelNeighbors(channel, renderContext) {
  const p25 = isP25(channel);
  const directory = createAsyncSection('Neighbors', {
    action: exportCsvLink('channel-neighbors', { configuration_id: channel.configuration_id }),
    loadingMessage: 'Loading channel neighbors…',
    errorMessage: 'The channel neighbors could not be loaded.'
  });
  if (!renderIsCurrent(renderContext)) return;
  content.append(directory.element);
  await directory.load(
    () => apiPage(channelApiPath(channel.configuration_id, 'neighbors'), pageParameters()),
    (page) => pagedTableContent(page,
      p25 ? p25ChannelNeighborColumns() : trunkedChannelNeighborColumns(channel),
      p25 ? 'channel-neighbors-p25' : 'channel-neighbors-trunked', {
        itemLabel: 'Neighbors', emptyText: 'No neighbors recorded',
        tableOptions: {
          sortable: false, serverSort: false,
          layoutMenuHost: directory.titleActions, controller: directory.tableController
        }
      }),
    renderContext);
}

async function renderTrunkedChannelInfo(channel, renderContext) {
  const summary = [
    ['Metadata Updates', channel.observation_count], ['Frequencies', channel.frequencies], ['Neighbors', channel.neighbors]
  ];
  if (channelCapability(channel, 'frequency_bands')) summary.push(['Band Plans', channel.bands]);
  if (channelCapability(channel, 'patch_groups')) summary.push(['Patches', channel.patches]);
  if (channelCapability(channel, 'current_affiliations') && channelCapability(channel, 'radio_channel_presence')) {
    const label = number(channel.affiliated_radios);
    const linked = channel.radio_system_key && channel.configuration_id ? anchor(label,
      href('radio-system', { ...radioSystemRoute(channel), tab: 'radios', affiliated: true,
        configuration_id: channel.configuration_id })) : label;
    summary.push(['Affiliated Radios', channel.affiliated_radios, linked]);
  }

  const infoColumn = node('div', 'entity-info-column');
  infoColumn.append(section('Channel Info', keyValues([
    [radioSystemOwnerLabel(channel), radioSystemInfoFact(channel, false)],
    ['Site', siteNameValue(channel)], ['Name', nameValue(channel)],
    ['Configuration ID', channel.configuration_id],
    ['Alias List', aliasListLink(channel.alias_list_name, channel.alias_list_id)],
    ['Protocol', protocolFamily(channel)], ['Decoder', decoderDisplay(channel.decoder)],
    ['Configured Frequency', frequency(channel.primary_frequency_hz)],
    ['Current Control Frequency', frequency(channel.current_control_hz)],
    ['First Seen', dateTime(channel.first_seen_ms)], ['Last Seen', dateTime(channel.last_seen_ms)]
  ])));
  const protocolDetails = channelProtocolDetailRows(channel);
  if (protocolDetails.length) {
    infoColumn.append(section(`${protocolFamily(channel)} Details`, keyValues(protocolDetails)));
  }

  const activityColumn = node('div', 'entity-info-column');
  if (channelCapability(channel, 'group_identities')) {
    activityColumn.append(await channelTopGroupsSection(channel));
  }
  if (!renderIsCurrent(renderContext)) return;
  const layout = node('div', 'entity-info-layout');
  layout.append(infoColumn);
  if (activityColumn.childNodes.length) layout.append(activityColumn);
  content.append(metrics(summary), layout);
}

function renderTrunkedChannelBandPlans(channel, data) {
  const overrideActive = data.band_source === 'P25_OVERRIDE';
  const homeBandColumns = [
    { id: 'band', label: 'Band', key: 'band', className: 'numeric' },
    { id: 'base', label: 'Base', fullLabel: 'Base MHz', render: (row) => frequency(row.base_hz), className: 'numeric', sortValue: (row) => Number(row.base_hz || 0) },
    { id: 'spacing', label: 'Space', fullLabel: 'Spacing kHz', render: (row) => row.spacing_hz ? (row.spacing_hz / 1000).toFixed(3) : '', className: 'numeric', sortValue: (row) => Number(row.spacing_hz || 0) },
    { id: 'bandwidth', label: 'BW Hz', fullLabel: 'Bandwidth Hz', key: 'bandwidth_hz', className: 'numeric' },
    { id: 'offset', label: 'Offset', fullLabel: 'Offset MHz', render: (row) => row.transmit_offset_hz ? (row.transmit_offset_hz / 1000000).toFixed(5) : '', className: 'numeric', sortValue: (row) => Number(row.transmit_offset_hz || 0) },
    { id: 'tdma', label: 'TDMA', render: (row) => yesNo(row.tdma), sortValue: (row) => Boolean(row.tdma) },
    { id: 'slots', label: 'Slots', key: 'timeslots', className: 'numeric' }
  ];
  if (!overrideActive) homeBandColumns.push(
    { id: 'state', label: 'State', render: (row) => compactStateBadge(row.state), sortValue: (row) => row.state || '' },
    { id: 'observations', label: 'Obs', fullLabel: 'Observations',
      render: (row) => number(row.observation_count), className: 'numeric',
      sortValue: (row) => Number(row.observation_count || 0) },
    { id: 'last-seen', label: 'Seen', fullLabel: 'Last Seen', render: (row) => stackedDateTime(row.last_seen_ms), sortValue: (row) => Number(row.last_seen_ms || 0) }
  );
  const bandSource = badge(overrideActive ? 'P25 override' : 'OTA band plan',
    overrideActive ? 'state-current' : '');
  const issiTarget = capabilityAllowed(ACCESS_CAPABILITIES.RADIO) && channel.radio_system_key ?
    href('radio-system', { radio_system_key: channel.radio_system_key, tab: 'issi',
      issi_view: 'frequency-bands', configuration_id: channel.configuration_id }) : '';
  const issiContext = node('p', 'ui-section-note',
    'These foreign band plans are advertisements heard on this channel. ');
  if (issiTarget) issiContext.append(anchor('View this system’s ISSI Band Plans', issiTarget));
  return fragment(issiContext, tableSection('Home System Band Plan', data.home_bands || [], homeBandColumns,
    'No home-system band plan recorded', { type: overrideActive ? 'channel-frequency-bands-override' :
      'channel-frequency-bands', tableClass: 'ui-data-table-calm' }, null, bandSource),
  data.foreign_bands?.length ? tableSection('ISSI Advertised Band Plans', data.foreign_bands, [
    { id: 'system', label: 'System', fullLabel: 'Foreign System', render: (row) => relatedRadioSystemLink(row),
      sortValue: (row) => radioSystemDisplayName(relatedRadioSystem(row)) },
    { id: 'band', label: 'Band', key: 'band', className: 'numeric' },
    { id: 'mode', label: 'Mode', render: (row) => semanticLabel(row.access_mode) },
    { id: 'base', label: 'Base', fullLabel: 'Base MHz', render: (row) => frequency(row.base_hz), className: 'numeric', sortValue: (row) => Number(row.base_hz || 0) },
    { id: 'spacing', label: 'Space', fullLabel: 'Spacing kHz', render: (row) => row.spacing_hz ? (row.spacing_hz / 1000).toFixed(3) : '', className: 'numeric', sortValue: (row) => Number(row.spacing_hz || 0) },
    { id: 'bandwidth', label: 'BW Hz', fullLabel: 'Bandwidth Hz', key: 'bandwidth_hz', className: 'numeric' },
    { id: 'offset', label: 'Offset', fullLabel: 'Offset MHz', render: (row) => row.transmit_offset_hz ? (row.transmit_offset_hz / 1000000).toFixed(5) : '', className: 'numeric', sortValue: (row) => Number(row.transmit_offset_hz || 0) },
    { id: 'slots', label: 'Slots', key: 'timeslots', className: 'numeric' },
    { id: 'voice-rate', label: 'Voice Rate', render: (row) => semanticLabel(row.voice_rate) },
    { id: 'state', label: 'State', render: (row) => compactStateBadge(row.state), sortValue: (row) => row.state || '' },
    { id: 'observations', label: 'Obs', fullLabel: 'Observations',
      render: (row) => number(row.observation_count), className: 'numeric',
      sortValue: (row) => Number(row.observation_count || 0) },
    { id: 'last-seen', label: 'Seen', fullLabel: 'Last Seen', render: (row) => stackedDateTime(row.last_seen_ms), sortValue: (row) => Number(row.last_seen_ms || 0) }
  ], 'No ISSI-advertised band plans recorded', { type: 'channel-foreign-frequency-bands',
    tableClass: 'ui-data-table-calm' }) :
    section('ISSI Advertised Band Plans',
      node('p', 'muted channel-frequency-note', 'No ISSI-advertised band plans recorded')));
}

async function renderTrunkedChannel(channel, configurationId, renderContext) {
  const requestedTab = route.get('tab') || 'info';
  const tabItems = trunkedChannelTabItems(channel);
  const normalizedTab = requestedTab === 'band-plan' ? 'frequencies' : requestedTab;
  const tab = tabItems.some((item) => item.id === normalizedTab) ? normalizedTab : 'info';
  const display = channelDisplayParts(channel);
  const siteVariant = trunkedVariant({ variant: channel.site_variant });
  const location = radioSystemPrimaryName(channel) ? channelSiteIdentity(channel) : channelLocationIdentity(channel);
  const context = [display.secondary, protocolFamily(channel), trunkedVariant(channel) || siteVariant,
    location].filter(Boolean).join(' · ');
  const subtitle = radioSystemPrimaryName(channel) ?
    fragment(radioSystemContextLink(channel), context ? ` · ${context}` : '') : context;
  if (!beginPage(renderContext, pageHeader(entityPageTitle('Site', channelValue(channel)), subtitle),
    trunkedChannelTabs(channel, tab))) return;

  if (tab === 'quality') {
    const signalHistory = await channelSignalHistorySection(channel);
    if (!renderIsCurrent(renderContext)) return;
    content.append(signalHistory);
  } else if (tab === 'frequencies') {
    const showFrequencies = channelCapability(channel, 'channels');
    const showBandPlans = channelCapability(channel, 'frequency_bands');
    const layout = node('div', `channel-frequency-layout${showFrequencies && showBandPlans ? ' two-columns' : ''}`);
    content.append(layout);
    const tasks = [];
    if (showFrequencies) {
      const frequencyColumn = node('div', 'channel-frequency-column');
      layout.append(frequencyColumn);
      tasks.push(renderTrunkedChannelFrequencies(channel, renderContext, frequencyColumn));
    }
    if (showBandPlans) {
      const bandPlanColumn = node('div', 'channel-band-plan-column');
      const bands = createAsyncSection('Band Plans', {
        bare: true,
        loadingMessage: 'Loading band plans…',
        errorMessage: 'The band plans could not be loaded.'
      });
      bandPlanColumn.append(bands.element);
      layout.append(bandPlanColumn);
      tasks.push(bands.load(() => api(channelApiPath(configurationId, 'frequency-bands')),
        (data) => renderTrunkedChannelBandPlans(channel, data), renderContext));
    }
    await Promise.all(tasks);
  } else if (tab === 'neighbors') {
    await renderChannelNeighbors(channel, renderContext);
  } else if (tab === 'patches') {
    const data = await api(channelApiPath(configurationId, 'patch-groups'), {
      offset: route.get('offset'), limit: 100
    });
    const talkgroups = patchMembersByLocalGroup(data.talkgroups);
    const radios = patchMembersByLocalGroup(data.radios);
    const memberValues = (values, formatter, omitted = 0) => {
      const span = node('span');
      const rendered = (values || []).map(formatter).filter((value) =>
        value !== null && value !== undefined && value !== '');
      rendered.forEach((value, index) => {
        if (index) span.append(document.createTextNode(', '));
        span.append(valueNode(value));
      });
      if (omitted > 0) {
        if (rendered.length) span.append(document.createTextNode(', '));
        span.append(node('span', 'muted', `+${number(omitted)} more`));
      }
      return span;
    };
    const omittedMembers = (row, member) => Math.max(0,
      Number(row?.[`${member.slice(0, -1)}_count`] || 0) - Number(row?.[`${member}_included`] || 0));
    const groups = data.groups || [];
    const columns = [
      { id: 'patch-id', label: 'Local Patch', fullLabel: 'Local Patch Talkgroup ID',
        render: (row) => groupIdentityLink(row, row.local_patch_group_id),
        className: 'numeric', sortValue: (row) => Number(row.local_patch_group_id) },
      { id: 'patch-name', label: 'Alias', fullLabel: 'Local Patch Alias', render: (row) =>
        row.patch_alias_name ? groupIdentityLink(row, row.local_patch_group_id, row.patch_alias_name) : '',
        className: 'alias-cell', sortValue: (row) => row.patch_alias_name || '' },
      { id: 'member-talkgroup-ids', label: 'Local TGIDs', fullLabel: 'Local Member Talkgroup IDs', render: (row) =>
        memberValues(talkgroups.get(row.local_patch_group_id), (member) =>
          groupIdentityLink(member, member.local_talkgroup_id), omittedMembers(row, 'talkgroups')) },
      { id: 'member-talkgroup-names', label: 'TG Aliases', fullLabel: 'Local Talkgroup Aliases',
        className: 'alias-cell', render: (row) =>
          memberValues(talkgroups.get(row.local_patch_group_id), (member) => member.alias_name ?
            groupIdentityLink(member, member.local_talkgroup_id, member.alias_name) : '',
          omittedMembers(row, 'talkgroups')) },
      { id: 'member-radio-ids', label: 'Local Radios', fullLabel: 'Local Radio IDs', render: (row) =>
        memberValues(radios.get(row.local_patch_group_id), (member) =>
          radioLink(member, member.local_radio_id), omittedMembers(row, 'radios')) },
      { id: 'member-radio-names', label: 'Radio Aliases', fullLabel: 'Local Radio Aliases',
        className: 'alias-cell', render: (row) =>
          memberValues(radios.get(row.local_patch_group_id), (member) => member.alias_name ?
            radioLink(member, member.local_radio_id, member.alias_name) : '', omittedMembers(row, 'radios')) },
      { id: 'state', label: 'State', render: (row) => stateBadge(row.state), sortValue: (row) => row.state || '' },
      { id: 'observations', label: 'Observations',
        render: (row) => number(row.observation_count), className: 'numeric',
        sortValue: (row) => Number(row.observation_count || 0) },
      { id: 'last-seen', label: 'Seen', fullLabel: 'Last Seen', render: (row) => dateTime(row.last_seen_ms), sortValue: (row) => Number(row.last_seen_ms || 0) }
    ];
    if (groups.some((row) => Number(row.version))) columns.splice(2, 0,
      { id: 'version', label: 'Version', key: 'version', className: 'numeric' });
    const patchPage = { rows: groups, offset: Number(data.offset || 0), limit: Number(data.limit || 100),
      has_more: Boolean(data.has_more), next_offset: data.next_offset };
    const trailing = fragment();
    if (data.members_truncated) trailing.append(node('p', 'ui-notice ui-notice-danger ui-notice-spaced',
      `Large patches are bounded to ${number(data.member_limit_per_group)} members per patch and ` +
      `${number(data.member_limit_total)} members per type on this page. Omitted counts are shown in the table.`));
    trailing.append(pager(patchPage, 'bottom', 'Patch groups'));
    content.append(tableSection('Patches', groups, columns, 'No patches recorded',
      { type: groups.some((row) => Number(row.version)) ? 'channel-patches-versioned' :
        'channel-patches' }, trailing));
  } else if (tab === 'activity') {
    await renderActivity({
      configuration_id: configurationId,
      radio_system_key: channel.radio_system_key,
      _activity_context: {
        kind: 'trunked-channel', protocol: protocolFamily(channel),
        radio_system_key: channel.radio_system_key, configuration_id: configurationId
      }
    });
  } else {
    await renderTrunkedChannelInfo(channel, renderContext);
  }
}

function specialIdentifierLabel(row, value, kind, prefix = '') {
  if (kind === 'radio' && p25CanonicalSubscriber(row, prefix || radioIdentityPrefix(row, value))) return '';
  const identifier = Number(value);
  if (isP25(row)) {
    if (kind === 'talkgroup') {
      return ({ 0x0000: 'No Talkgroup', 0xFFFF: 'Everyone' })[identifier] || '';
    }
    if (kind === 'radio') {
      return ({
        0x000000: 'No Unit',
        0xFFFFFC: 'FNE',
        0xFFFFFD: 'System Default',
        0xFFFFFE: 'Registration Default',
        0xFFFFFF: 'All Units'
      })[identifier] || '';
    }
  }

  // Mirrors Tier3Gateway: these values name network services or broadcast destinations, not subscriber identities.
  if (protocolFamily(row) === 'DMR') {
    return ({
      0x000000: 'Reserved',
      0xFFFEC0: 'PSTN Gateway',
      0xFFFEC1: 'PABX Gateway',
      0xFFFEC2: 'Line Gateway',
      0xFFFEC3: 'IP Gateway',
      0xFFFEC4: 'Supplementary Data Service',
      0xFFFEC5: 'UDT Short Data Service',
      0xFFFEC6: 'Registration Service',
      0xFFFEC7: 'Call Diversion to Radio Gateway',
      0xFFFEC9: 'Call Diversion Cancellation',
      0xFFFECA: 'Trunking System Controller',
      0xFFFECB: 'System Dispatcher',
      0xFFFECC: 'Radio Stun/Revive',
      0xFFFECD: 'Authentication',
      0xFFFECE: 'Call Diversion to Talkgroup Gateway',
      0xFFFECF: 'Radio Kill',
      0xFFFED0: 'PSTN-D Gateway',
      0xFFFED1: 'PABX-D Gateway',
      0xFFFED2: 'Line-D Gateway',
      0xFFFED3: 'System Dispatcher-D',
      0xFFFED4: 'All Radios/Talkgroups',
      0xFFFED5: 'IP-D Gateway',
      0xFFFED6: 'Dynamic Group Number Assignment',
      0xFFFED7: 'Talkgroup Subscribe/Attach Service',
      0xFFFFFD: 'All Radios at Site',
      0xFFFFFE: 'All Radios in Zone',
      0xFFFFFF: 'All Radios in System'
    })[identifier] || '';
  }

  // Mirrors NXDNRadioIdentifier/NXDNTalkgroupIdentifier. Type-D uses the same bits as a real HH-NNNN identity.
  if (protocolFamily(row) === 'NXDN' && row.address_domain !== 'nxdn_type_d') {
    if (kind === 'talkgroup') {
      return ({
        0x0000: 'Null Group',
        0xFFF0: 'Reserved Group',
        0xFFFF: 'All Groups'
      })[identifier] || '';
    }
    if (kind === 'radio') {
      return ({
        0x0000: 'No Unit',
        0xFFF0: 'Trunking Controller',
        0xFFF1: 'PSTN',
        0xFFF2: 'Special ID',
        0xFFF3: 'Special ID',
        0xFFF4: 'Special ID',
        0xFFF5: 'Conventional PSTN',
        0xFFFF: 'All Units'
      })[identifier] || '';
    }
  }

  return '';
}

function activityIdentifier(row, value, kind, reference, linked = true, prefix = '') {
  const identifier = kind === 'radio' ? radioIdentifierText(row, value, prefix) : identityNumber(row, value);
  if (identifier === '') return '';
  const specialLabel = specialIdentifierLabel(row, value, kind, prefix);
  if (specialLabel) {
    const protocol = protocolFamily(row);
    const result = node('span', 'special-identifier', specialLabel);
    result.title = `${protocol} ${specialLabel} (${identifier}): system or special signaling identifier`;
    result.setAttribute('aria-label',
      `${specialLabel}, ${protocol} system or special signaling identifier ${identifier}`);
    return result;
  }
  if (['talkgroup', 'patch_group'].includes(kind)) {
    return linked ? groupIdentityLink(row, value, identifier, reference) : identifier;
  }
  if (kind === 'radio') return linked ? radioLink(row, value, identifier, reference) : identifier;
  return identifier;
}

function activityTargetKind(row) {
  const kind = identityKind(row?.target_kind);
  return ['talkgroup', 'patch_group', 'radio'].includes(kind) ? kind : '';
}

function activityTargetIdentifier(row, linked = true) {
  if (isAnalogChannel(row)) return '';
  const kind = activityTargetKind(row);
  return activityIdentifier(row, row.target_id, kind, row.target_entity_ref, linked, kind === 'radio' ? 'target' : '');
}

function activitySourceAlias(row, linked = true) {
  const alias = row.source_alias_name || '';
  if (!alias) return '';
  return !linked || specialIdentifierLabel(row, row.source_radio_id, 'radio', 'source') ?
    alias : radioLink(row, row.source_radio_id, alias, row.source_entity_ref);
}

function activitySourceTalkerAlias(row, linked = true) {
  const alias = String(row.source_talker_alias || '').trim();
  if (!alias) return '';
  return !linked || specialIdentifierLabel(row, row.source_radio_id, 'radio', 'source') ?
    alias : radioLink(row, row.source_radio_id, alias, row.source_entity_ref);
}

function activityTargetAlias(row, linked = true) {
  if (isAnalogChannel(row)) return '';
  const alias = row.target_alias_name || '';
  if (!alias) return '';
  const kind = activityTargetKind(row);
  if (!linked || specialIdentifierLabel(row, row.target_id, kind, kind === 'radio' ? 'target' : '')) return alias;
  if (['talkgroup', 'patch_group'].includes(kind)) {
    return groupIdentityLink(row, row.target_id, alias, row.target_entity_ref);
  }
  if (kind === 'radio') return radioLink(row, row.target_id, alias, row.target_entity_ref);
  return alias;
}

function activityChannel(row, linked = true) {
  const label = String(row.name || '').trim();
  const target = capabilityAllowed(ACCESS_CAPABILITIES.RADIO) ? entityRefHref(row.entity_ref) : '';
  const channel = label && target && linked ? anchor(label, target) : label;
  const details = [
    Number(row.frequency_hz) ? `${frequency(row.frequency_hz)} MHz` : '',
    row.lcn == null || row.lcn === '' ? '' : `LCN ${row.lcn}`,
    timeslotLabel(row.timeslot)
  ].filter(Boolean).join(' · ');
  if (!channel) return details;
  return details ? fragment(channel, node('small', 'identity-summary-context', details)) : channel;
}

function activityOptionLabel(value) {
  const labels = {
    ACKNOWLEDGE: 'Acknowledge', CHECK_ACK: 'Check Ack', PATCH_CANCEL: 'Patch Cancel',
    PATCH_CREATE: 'Patch Create', AUTOMATIC_REGISTRATION_SERVICE: 'Motorola ARS',
    CALL_DO_NOT_MONITOR: 'Call - Do Not Monitor', CALL_GROUP: 'Group Call',
    CALL_GROUP_ENCRYPTED: 'Encrypted Group Call', CALL_PATCH_GROUP: 'Patch Call',
    CALL_PATCH_GROUP_ENCRYPTED: 'Encrypted Patch Call', CALL_UNIT_TO_UNIT: 'Unit-to-Unit Call',
    CALL_UNIT_TO_UNIT_ENCRYPTED: 'Encrypted Unit-to-Unit Call', CALL_INTERCONNECT: 'Telephone Call',
    CALL_INTERCONNECT_ENCRYPTED: 'Encrypted Telephone Call', CALL_NO_TUNER: 'Call - No Tuner',
    DATA_CALL: 'Data Call', DATA_CALL_ENCRYPTED: 'Encrypted Data Call', ICMP_PACKET: 'ICMP Packet',
    ID_ANI: 'ANI', ID_UNIQUE: 'Unique ID', IP_PACKET: 'IP Packet', LRRP: 'Motorola LRRP',
    RADIO_REGISTRATION_SERVICE: 'Hytera RRS', REGISTER_ESN: 'ESN Registration',
    RESPONSE_PACKET: 'Response Packet', SDM: 'Short Data Message', SMS: 'SMS',
    UDP_PACKET: 'UDP/IP Packet', XCMP: 'Motorola XCMP'
  };
  return labels[value] || semanticLabel(value);
}

function activityFilterContext(scopeParameters) {
  const supplied = scopeParameters?._activity_context;
  const input = supplied && typeof supplied === 'object' && !Array.isArray(supplied) ? supplied : {};
  const kinds = new Set(['system', 'saved-system', 'talkgroup', 'patch-group', 'radio',
    'trunked-channel', 'conventional-digital', 'conventional-analog']);
  const kind = kinds.has(input.kind) ? input.kind : 'system';
  return Object.freeze({
    kind,
    protocol: String(input.protocol || '').trim().toUpperCase(),
    radioSystemKey: String(input.radio_system_key || scopeParameters?.radio_system_key || '').trim(),
    configurationId: String(input.configuration_id || scopeParameters?.configuration_id || '').trim(),
    radioIdentityKey: activityIdentityKey(input.radio_identity_key || scopeParameters?.radio_identity_key)
  });
}

function activityScopeParameters(scopeParameters) {
  const result = {};
  for (const key of ['radio_system_key', 'group_identity_key', 'radio_identity_key', 'configuration_id']) {
    const value = scopeParameters?.[key];
    if (value !== null && value !== undefined && value !== '') result[key] = value;
  }
  return result;
}

function activityContextCapabilities(context) {
  const kind = context?.kind || 'system';
  const analog = kind === 'conventional-analog';
  const digitalConventional = kind === 'conventional-digital';
  const systemIdentity = Boolean(context?.radioSystemKey) && !analog && !digitalConventional;
  const trunked = ['system', 'saved-system', 'talkgroup', 'patch-group', 'radio',
    'trunked-channel'].includes(kind);
  return Object.freeze({
    analog,
    digitalConventional,
    trunked,
    channel: ['system', 'talkgroup', 'patch-group', 'radio'].includes(kind),
    sourceIdentity: systemIdentity && ['system', 'saved-system', 'talkgroup', 'patch-group',
      'trunked-channel'].includes(kind),
    targetIdentity: systemIdentity && ['system', 'saved-system', 'trunked-channel'].includes(kind),
    radioRole: kind === 'radio',
    groupMatch: kind === 'talkgroup',
    rawIdentities: digitalConventional,
    encryption: !analog,
    grants: trunked,
    frequency: true,
    lcn: trunked,
    // Keep P25 timeslot route/API support for existing deep links, but only offer the control where a
    // timeslot is a useful operator-facing dimension. P25 activity uses it too sparsely to justify UI space.
    timeslot: !analog && (context?.protocol === 'DMR' || trunked && context?.protocol === 'P25'),
    timeslotFilter: !analog && context?.protocol === 'DMR'
  });
}

function activityInteger(value, minimum = 1, maximum = Number.MAX_SAFE_INTEGER) {
  const text = String(value ?? '').trim();
  if (!/^\d+$/.test(text)) return null;
  const parsed = Number(text);
  return Number.isSafeInteger(parsed) && parsed >= minimum && parsed <= maximum ? parsed : null;
}

function activityIdentityKey(value) {
  const key = String(value || '').trim().toLowerCase();
  return /^v1-[grp]-(?:x|[0-9a-f]{5})-(?:x|[0-9a-f]{3})-[0-9]+$/.test(key) ? key : '';
}

function activityRouteFilters(parameters, context, now = Date.now()) {
  const value = (key) => String(parameters?.get?.(key) || '').trim();
  const capabilities = activityContextCapabilities(context);
  const requestedRange = value('activity_range').toLowerCase();
  const range = ACTIVITY_LOG_RANGES.some((entry) => entry.value === requestedRange) ? requestedRange : 'all';
  let fromMs = activityInteger(value('activity_from_ms'));
  let toMs = activityInteger(value('activity_to_ms'));
  if (range === 'custom' && (!fromMs || !toMs || fromMs >= toMs)) {
    toMs = Math.max(1, Math.trunc(now));
    fromMs = Math.max(1, toMs - 24 * 60 * 60 * 1000);
  }
  const actionValue = value('activity_action').toUpperCase();
  const action = ACTIVITY_ACTION_VALUES.includes(actionValue) ? actionValue : '';
  const eventValue = value('activity_event_type').toUpperCase();
  const eventType = ACTIVITY_EVENT_TYPE_VALUES.includes(eventValue) ? eventValue : '';
  const encryptionValue = value('activity_encryption').toLowerCase();
  const encryption = capabilities.encryption && ['clear', 'encrypted'].includes(encryptionValue) ?
    encryptionValue : 'all';
  const roleValue = value('activity_radio_role').toLowerCase();
  let radioRole = capabilities.radioRole && ['source', 'target'].includes(roleValue) ? roleValue : 'any';
  const matchValue = value('activity_group_match').toLowerCase();
  const groupMatch = capabilities.groupMatch && ['direct', 'via_patch'].includes(matchValue) ?
    matchValue : 'all';
  let targetIdentityKey = activityIdentityKey(value('activity_target_identity_key'));
  const targetKindValue = value('activity_target_kind').toLowerCase();
  const targetKinds = capabilities.rawIdentities ? ['talkgroup', 'radio'] :
    ['talkgroup', 'patch_group', 'radio'];
  let targetKind = targetKinds.includes(targetKindValue) ? targetKindValue : '';
  if (targetIdentityKey) {
    targetKind = targetIdentityKey.startsWith('v1-r-') ? 'radio' :
      targetIdentityKey.startsWith('v1-p-') ? 'patch_group' : 'talkgroup';
  }
  const configurationId = capabilities.channel ? value('activity_configuration_id') : '';
  const frequencyHz = activityInteger(value('activity_frequency_hz'));
  const lcnValue = value('activity_lcn');
  const lcn = capabilities.lcn && /^\d+-\d+$/.test(lcnValue) ? lcnValue : '';
  const timeslotValue = activityInteger(value('activity_timeslot'), 1, 2);
  let sourceIdentityKey = activityIdentityKey(value('activity_source_identity_key'));
  const sourceId = capabilities.rawIdentities ?
    activityInteger(value('activity_source_id'), 0, 16_777_215) : null;
  const targetId = capabilities.rawIdentities ?
    activityInteger(value('activity_target_id'), 0, 16_777_215) : null;
  const allowSourceIdentity = capabilities.sourceIdentity ||
    (capabilities.radioRole && radioRole === 'target');
  const allowTargetIdentity = capabilities.targetIdentity ||
    (capabilities.radioRole && radioRole === 'source');
  if (!allowSourceIdentity) sourceIdentityKey = '';
  if (!allowTargetIdentity) targetIdentityKey = '';
  if (!allowTargetIdentity && !capabilities.rawIdentities) targetKind = '';
  return Object.freeze({
    range, fromMs, toMs, action, eventType, encryption,
    includeGrants: action === 'GRANT' || capabilities.grants &&
      value('activity_include_grants').toLowerCase() === 'true',
    configurationId,
    radioRole,
    groupMatch,
    sourceIdentityKey,
    targetIdentityKey,
    sourceId,
    targetId,
    targetKind,
    frequencyHz: capabilities.frequency ? frequencyHz : null,
    lcn,
    timeslot: capabilities.timeslot ? timeslotValue : null,
    context: context?.kind || 'system'
  });
}

function activityApiFilterParameters(filters, now = Date.now()) {
  const result = { hide_grants: !filters.includeGrants };
  const range = ACTIVITY_LOG_RANGES.find((entry) => entry.value === filters.range);
  if (range?.milliseconds) result.from_ms = Math.max(1, Math.trunc(now - range.milliseconds));
  else if (filters.range === 'custom') {
    result.from_ms = filters.fromMs;
    result.to_ms = filters.toMs;
  }
  if (filters.action) result.action = filters.action;
  if (filters.eventType) result.event_type = filters.eventType;
  if (filters.encryption !== 'all') result.encryption = filters.encryption;
  if (filters.configurationId) result.configuration_id = filters.configurationId;
  if (filters.radioRole !== 'any') result.radio_role = filters.radioRole;
  if (filters.groupMatch !== 'all') result.group_match = filters.groupMatch;
  if (filters.sourceIdentityKey) result.source_identity_key = filters.sourceIdentityKey;
  if (filters.targetIdentityKey) result.target_identity_key = filters.targetIdentityKey;
  if (filters.sourceId !== null) result.source_id = filters.sourceId;
  if (filters.targetId !== null) result.target_id = filters.targetId;
  if (filters.targetKind) result.target_kind = filters.targetKind;
  if (filters.frequencyHz !== null) result.frequency_hz = filters.frequencyHz;
  if (filters.lcn) result.lcn = filters.lcn;
  if (filters.timeslot !== null) result.timeslot = filters.timeslot;
  return result;
}

function activityFilterRouteOverrides(filters) {
  return {
    activity_range: filters.range === 'all' ? null : filters.range,
    activity_from_ms: filters.range === 'custom' ? filters.fromMs : null,
    activity_to_ms: filters.range === 'custom' ? filters.toMs : null,
    activity_action: filters.action || null,
    activity_event_type: filters.eventType || null,
    activity_encryption: filters.encryption === 'all' ? null : filters.encryption,
    activity_include_grants: filters.includeGrants && filters.action !== 'GRANT' ? true : null,
    activity_configuration_id: filters.configurationId || null,
    activity_radio_role: filters.radioRole === 'any' ? null : filters.radioRole,
    activity_group_match: filters.groupMatch === 'all' ? null : filters.groupMatch,
    activity_source_identity_key: filters.sourceIdentityKey || null,
    activity_target_identity_key: filters.targetIdentityKey || null,
    activity_source_id: filters.sourceId,
    activity_target_id: filters.targetId,
    activity_target_kind: filters.targetKind || null,
    activity_frequency_hz: filters.frequencyHz,
    activity_lcn: filters.lcn || null,
    activity_timeslot: filters.timeslot,
    before_id: null
  };
}

function activityActionControlValue(filters, capabilities) {
  if (filters?.action) return filters.action;
  return capabilities?.grants && filters?.includeGrants ? ACTIVITY_ACTION_INCLUDE_GRANTS : '';
}

function activityMoreFilterCount(filters, capabilities) {
  return [
    Boolean(filters?.eventType),
    capabilities?.encryption && Boolean(filters?.encryption) && filters.encryption !== 'all',
    Boolean(filters?.configurationId),
    filters?.groupMatch && filters.groupMatch !== 'all',
    filters?.frequencyHz !== null && filters?.frequencyHz !== undefined,
    Boolean(filters?.lcn),
    capabilities?.timeslotFilter && filters?.timeslot !== null && filters?.timeslot !== undefined
  ].filter(Boolean).length;
}

function activityListboxNavigationIndex(currentIndex, length, key) {
  if (!Number.isInteger(length) || length <= 0) return -1;
  if (key === 'Home') return 0;
  if (key === 'End') return length - 1;
  if (key === 'ArrowDown') return currentIndex < 0 || currentIndex >= length - 1 ? 0 : currentIndex + 1;
  if (key === 'ArrowUp') return currentIndex <= 0 ? length - 1 : currentIndex - 1;
  return -1;
}

function activityCellFilterPatch(context, row, columnId) {
  const capabilities = activityContextCapabilities(context);
  const sourceColumns = new Set(['source', 'source-alias', 'source-ota-alias']);
  const targetColumns = new Set(['target', 'target-alias']);
  if (columnId === 'action') {
    const action = String(row?.action || '').trim().toUpperCase();
    return ACTIVITY_ACTION_VALUES.includes(action) ? { action } : null;
  }
  if (columnId === 'event') {
    const eventType = String(row?.event_type || '').trim().toUpperCase();
    return ACTIVITY_EVENT_TYPE_VALUES.includes(eventType) ? { eventType } : null;
  }
  const encryptionValue = row?.encrypted;
  if (columnId === 'encryption' && capabilities.encryption &&
      (typeof encryptionValue === 'boolean' || encryptionValue === 0 || encryptionValue === 1)) {
    return { encryption: encryptionValue === true || encryptionValue === 1 ? 'encrypted' : 'clear' };
  }
  if (columnId === 'channel') {
    const configurationId = String(row?.configuration_id || '').trim();
    return capabilities.channel && configurationId ? { configurationId } : null;
  }
  if (sourceColumns.has(columnId)) {
    const sourceIdentityKey = activityIdentityKey(row?.source_identity_key);
    const sourceId = activityInteger(row?.source_radio_id, 0, 16_777_215);
    if (capabilities.rawIdentities && sourceId !== null) {
      return { sourceIdentityKey: '', sourceId };
    }
    if (capabilities.sourceIdentity && sourceIdentityKey) {
      return { sourceIdentityKey, sourceId: null };
    }
    if (!capabilities.radioRole || !sourceIdentityKey || !context?.radioIdentityKey) return null;
    if (sourceIdentityKey === context.radioIdentityKey) {
      return { radioRole: 'source', sourceIdentityKey: '', sourceId: null };
    }
    return {
      radioRole: 'target', sourceIdentityKey, sourceId: null,
      targetIdentityKey: '', targetId: null, targetKind: ''
    };
  }
  if (targetColumns.has(columnId)) {
    const targetIdentityKey = activityIdentityKey(row?.target_identity_key);
    const targetId = activityInteger(row?.target_id, 0, 16_777_215);
    const requestedKind = String(row?.target_kind || '').trim().toLowerCase();
    const targetKind = ['talkgroup', 'patch_group', 'radio'].includes(requestedKind) ? requestedKind : '';
    if (capabilities.rawIdentities && targetId !== null && ['talkgroup', 'radio'].includes(targetKind)) {
      return { targetIdentityKey: '', targetId, targetKind };
    }
    if (capabilities.targetIdentity && targetIdentityKey) {
      return { targetIdentityKey, targetId: null, targetKind };
    }
    if (!capabilities.radioRole || !targetIdentityKey || !context?.radioIdentityKey) return null;
    if (targetIdentityKey === context.radioIdentityKey) {
      return { radioRole: 'target', targetIdentityKey: '', targetId: null, targetKind: '' };
    }
    return {
      radioRole: 'source', targetIdentityKey, targetId: null, targetKind,
      sourceIdentityKey: '', sourceId: null
    };
  }
  return null;
}

function activityCellFilterRouteOverrides(filters, context, row, columnId) {
  const patch = activityCellFilterPatch(context, row, columnId);
  return patch ? activityFilterRouteOverrides({ ...filters, ...patch }) : null;
}

function activityLocalDateTimeValue(milliseconds) {
  const timestamp = Number(milliseconds);
  if (!Number.isFinite(timestamp) || timestamp <= 0) return '';
  const date = new Date(timestamp);
  const local = new Date(timestamp - date.getTimezoneOffset() * 60_000);
  return local.toISOString().slice(0, 16);
}

function activityLocalDateTimeMilliseconds(value) {
  const timestamp = new Date(String(value || '')).getTime();
  return Number.isFinite(timestamp) && timestamp > 0 ? Math.trunc(timestamp) : null;
}

function activityFilterField(labelText, control, detail = '', className = '') {
  const field = node('label', `ui-field activity-filter-field${className ? ` ${className}` : ''}`);
  field.append(node('span', 'ui-field-label', labelText), control);
  if (detail) field.append(node('small', 'ui-field-detail', detail));
  return field;
}

function activityFilterSelect(labelText, values, selectedValue, detail = '', className = '') {
  const select = uiSelect(values, selectedValue);
  return { select, field: activityFilterField(labelText, uiSelectFrame(select), detail, className) };
}

function activityIdentityDirectoryPath(context, kind) {
  if (!context?.radioSystemKey) return '';
  return radioSystemApiPath(context.radioSystemKey, kind === 'radio' ? 'radios' : 'group-identities');
}

function activityIdentityKindFromKey(value) {
  const key = activityIdentityKey(value);
  if (key.startsWith('v1-r-')) return 'radio';
  if (key.startsWith('v1-p-')) return 'patch_group';
  return key ? 'talkgroup' : '';
}

function activityIdentityKindLabel(kind, plural = false) {
  if (kind === 'radio') return plural ? 'Radios' : 'Radio';
  if (kind === 'patch_group') return plural ? 'Patches' : 'Patch';
  return plural ? 'Talkgroups' : 'Talkgroup';
}

function activityIdentitySuggestion(row, requestedKind = '', context = null) {
  const nativeId = row?.native_id ?? row?.radio_native_id ?? row?.group_native_id;
  const identityKey = activityIdentityKey(row?.identity_key || row?.radio_identity_key ||
    row?.group_identity_key);
  if (nativeId === null || nativeId === undefined || !identityKey) return null;
  const kind = requestedKind || activityIdentityKindFromKey(identityKey) || rowGroupIdentityKind(row);
  if (!['radio', 'talkgroup', 'patch_group'].includes(kind)) return null;
  const alias = String(aliasLabel(row) || row?.last_talker_alias || '').trim();
  const kindLabel = activityIdentityKindLabel(kind);
  const displayRow = p25ServingSystemKey(row) || !context?.radioSystemKey ? row :
    { ...row, radio_system_key: context.radioSystemKey };
  const displayId = String(kind === 'radio' ? radioIdentifierText(displayRow, nativeId) :
    identityNumber(row, nativeId));
  const [, , homeWacn, homeSystemId] = identityKey.split('-');
  const home = kind === 'radio' || homeWacn === 'x' ? '' : `${homeWacn}-${homeSystemId}`;
  return Object.freeze({ key: identityKey, id: Number(nativeId), displayId, alias, kind, kindLabel, home,
    label: `${kindLabel} ${displayId}${alias ? ` · ${alias}` : ''}${home ? ` · ${home}` : ''}` });
}

function activityIdentityInitialSelection(identityKey, requestedKind = '', context = null) {
  const key = activityIdentityKey(identityKey);
  if (!key) return null;
  const kind = requestedKind || activityIdentityKindFromKey(key);
  const parts = key.split('-');
  const id = Number(parts.at(-1));
  const qualifiedRadio = kind === 'radio' && parts[2] !== 'x' && parts[3] !== 'x';
  const displayId = qualifiedRadio ? radioIdentifierText({
    protocol: 'P25', radio_system_key: context?.radioSystemKey,
    canonical_identity: { wacn: parseInt(parts[2], 16), system_id: parseInt(parts[3], 16), subscriber_id: id }
  }, id) : parts.at(-1);
  const home = kind === 'radio' || parts[2] === 'x' ? '' : `${parts[2]}-${parts[3]}`;
  const kindLabel = activityIdentityKindLabel(kind);
  return Object.freeze({ key, id, displayId, alias: '', kind, kindLabel, home,
    label: `${kindLabel} ${displayId}${home ? ` · ${home}` : ''}` });
}

function activityIdentityPicker(context, options = {}) {
  const sequenceId = ++activityFilterControlSequence;
  const panelId = `activity-identity-picker-${sequenceId}`;
  const resultsId = `activity-identity-results-${sequenceId}`;
  const statusId = `activity-identity-status-${sequenceId}`;
  const destination = Boolean(options.destination);
  const pickerKind = destination ? 'destination' : 'source';
  const placeholder = destination ? 'Find talkgroup, radio, or patch' : 'Find ID or alias';
  const searchPlaceholder = destination ? 'Search talkgroup, radio, patch, or alias' :
    'Search radio ID or alias';
  const field = node('div', `ui-field activity-filter-field activity-filter-picker activity-filter-picker-${pickerKind}`);
  const trigger = node('button', 'ui-button ui-button-secondary activity-filter-picker-trigger');
  trigger.type = 'button';
  trigger.setAttribute('popovertarget', panelId);
  trigger.setAttribute('aria-controls', panelId);
  trigger.setAttribute('aria-haspopup', 'dialog');
  trigger.setAttribute('aria-expanded', 'false');
  const triggerLabel = node('span', 'activity-filter-picker-label');
  trigger.append(iconGlyph('icon-search'), triggerLabel);
  const panel = node('div', 'ui-popover activity-identity-picker-popover');
  panel.id = panelId;
  panel.setAttribute('popover', 'auto');
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', destination ? 'Choose a destination' : 'Choose a source radio');
  const search = node('div', 'ui-search activity-identity-search');
  const input = node('input', 'ui-input activity-identity-picker-search');
  input.type = 'search';
  input.autocomplete = 'off';
  input.placeholder = searchPlaceholder;
  input.setAttribute('role', 'combobox');
  input.setAttribute('aria-haspopup', 'listbox');
  input.setAttribute('aria-controls', resultsId);
  input.setAttribute('aria-expanded', 'false');
  input.setAttribute('aria-describedby', statusId);
  input.setAttribute('aria-autocomplete', 'list');
  search.append(iconGlyph('icon-search'), input);
  const results = node('div', 'activity-identity-results');
  results.id = resultsId;
  results.setAttribute('role', 'listbox');
  results.setAttribute('aria-label', destination ? 'Destination search results' : 'Source radio search results');
  const status = node('p', 'ui-field-detail activity-identity-status', 'Search by ID or alias.');
  status.id = statusId;
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  const footer = node('div', 'activity-identity-picker-footer');
  const clear = node('button', 'link-button activity-identity-picker-clear',
    destination ? 'Any destination' : 'Any source radio');
  clear.type = 'button';
  footer.append(clear, status);

  let activeKind = '';
  const committedKey = activityIdentityKey(options.identityKey);
  const committedKind = committedKey ? activityIdentityKindFromKey(committedKey) : options.kind || '';
  let selected = activityIdentityInitialSelection(options.identityKey, options.kind || '', context);
  if (!selected && destination && options.kind) {
    const kindLabel = activityIdentityKindLabel(options.kind);
    selected = Object.freeze({ key: '', id: null, displayId: '', alias: '', kind: options.kind,
      kindLabel, home: '', label: `Any ${kindLabel.toLowerCase()}`, kindOnly: true });
  }
  let loadedEntries = [];
  let searchGeneration = 0;
  let searchController = null;
  let repositionPanel = () => { };

  const cancelIdentitySearch = () => {
    searchGeneration += 1;
    searchController?.abort();
    searchController = null;
    input.removeAttribute('aria-busy');
  };
  const notifySelection = () => options.onSelection?.(selected);
  const updateSelection = () => {
    const committed = selected && (committedKey ? selected.key === committedKey :
      selected.kindOnly && selected.kind === committedKind);
    triggerLabel.textContent = !selected ? placeholder : committed ?
      (destination ? 'Replace destination' : 'Replace source radio') : selected.label;
    trigger.classList.toggle('has-selection', Boolean(selected));
    clear.hidden = !selected;
    notifySelection();
  };
  const filteredEntries = () => activeKind ?
    loadedEntries.filter((entry) => entry.kind === activeKind) : loadedEntries;
  const selectEntry = (entry) => {
    cancelIdentitySearch();
    selected = entry;
    input.value = '';
    input.setCustomValidity('');
    loadedEntries = [];
    results.replaceChildren();
    status.textContent = 'Search by ID or alias.';
    updateSelection();
    if (panel.matches(':popover-open')) panel.hidePopover();
    trigger.focus();
  };
  const exactNumericEntries = () => {
    const query = input.value.trim();
    if (!/^\d+$/.test(query)) return [];
    return filteredEntries().filter((entry) => String(entry.id) === query || entry.displayId === query);
  };
  const exactNumericEntry = () => {
    const matches = exactNumericEntries();
    return matches.length === 1 ? matches[0] : null;
  };
  const renderResults = (announce = !input.hasAttribute('aria-busy')) => {
    const entries = filteredEntries();
    const controls = [];
    if (destination && activeKind) {
      const kindLabel = activityIdentityKindLabel(activeKind);
      const any = node('button', 'ui-select-list-item activity-identity-result activity-identity-any-kind');
      any.type = 'button';
      any.setAttribute('role', 'option');
      any.setAttribute('aria-selected', String(Boolean(selected?.kindOnly && selected.kind === activeKind)));
      const anyKind = uiPill(kindLabel, 'blue');
      anyKind.classList.add('activity-identity-result-kind');
      any.append(anyKind, node('span', 'activity-identity-result-alias', `Any ${kindLabel.toLowerCase()}`));
      any.addEventListener('click', () => selectEntry(Object.freeze({ key: '', id: null,
        displayId: '', alias: '', kind: activeKind, kindLabel, home: '',
        label: `Any ${kindLabel.toLowerCase()}`, kindOnly: true })));
      controls.push(any);
    }
    entries.forEach((entry) => {
      const option = node('button', 'ui-select-list-item activity-identity-result');
      option.type = 'button';
      option.setAttribute('role', 'option');
      option.setAttribute('aria-selected', String(selected?.key === entry.key));
      option.dataset.identityKey = entry.key;
      const kindBadge = uiPill(entry.kindLabel, 'blue');
      kindBadge.classList.add('activity-identity-result-kind');
      option.append(kindBadge,
        node('span', 'activity-identity-result-alias', entry.alias || entry.kindLabel),
        node('span', 'activity-identity-result-id', entry.displayId));
      option.addEventListener('click', () => selectEntry(entry));
      controls.push(option);
    });
    const selectedIndex = controls.findIndex((control) => control.getAttribute('aria-selected') === 'true');
    const tabStop = selectedIndex >= 0 ? selectedIndex : 0;
    controls.forEach((control, index) => { control.tabIndex = index === tabStop ? 0 : -1; });
    results.replaceChildren(...controls);
    input.setAttribute('aria-expanded', String(panel.matches(':popover-open') && controls.length > 0));
    if (announce) {
      status.textContent = entries.length ?
        `${number(entries.length)} matching identit${entries.length === 1 ? 'y' : 'ies'}.` :
        input.value.trim() ? 'No matching identities. Try another ID or alias.' :
        destination && activeKind ?
          `Search within ${activityIdentityKindLabel(activeKind, true).toLowerCase()}, or choose any.` :
          'Search by ID or alias.';
    }
    repositionPanel();
  };

  let kindTabs = null;
  if (destination) {
    kindTabs = uiSegmentedControl([
      { value: '', label: 'All' },
      { value: 'talkgroup', label: 'Talkgroups' },
      { value: 'radio', label: 'Radios' },
      { value: 'patch_group', label: 'Patches' }
    ], '', (value) => {
      activeKind = value;
      renderResults();
    });
    kindTabs.classList.add('activity-identity-kind-tabs');
    kindTabs.setAttribute('aria-label', 'Destination type');
  }

  const load = async (query, passive = false) => {
    query = String(query || '').trim();
    if (!query && !passive) {
      cancelIdentitySearch();
      loadedEntries = [];
      renderResults();
      return [];
    }
    const radioPath = activityIdentityDirectoryPath(context, 'radio');
    const groupPath = destination ? activityIdentityDirectoryPath(context, 'talkgroup') : '';
    if (!radioPath && !groupPath) {
      status.textContent = 'Identity search is unavailable for this activity scope.';
      return [];
    }
    searchController?.abort();
    const controller = new AbortController();
    searchController = controller;
    const renderSignal = activeRenderController?.signal;
    const abortForRender = () => controller.abort();
    if (renderSignal?.aborted) controller.abort();
    else renderSignal?.addEventListener('abort', abortForRender, { once: true });
    const generation = ++searchGeneration;
    input.setAttribute('aria-busy', 'true');
    if (!passive) status.textContent = 'Searching identities…';
    try {
      const requests = [];
      if (radioPath) requests.push(apiPage(radioPath, { q: query || null, limit: 25 },
        { signal: controller.signal }).then((page) => ({ kind: 'radio', page })));
      if (groupPath) requests.push(apiPage(groupPath, { q: query || null, limit: 25 },
        { signal: controller.signal }).then((page) => ({ kind: 'group', page })));
      const settled = await Promise.allSettled(requests);
      if (generation !== searchGeneration || !input.isConnected) return [];
      const fulfilled = settled.filter((entry) => entry.status === 'fulfilled').map((entry) => entry.value);
      if (!fulfilled.length && settled.length) throw settled[0].reason;
      const deduplicated = new Map();
      fulfilled.forEach(({ kind, page }) => (page.rows || []).forEach((row) => {
        const rowKind = kind === 'radio' ? 'radio' : rowGroupIdentityKind(row);
        const entry = activityIdentitySuggestion(row, rowKind, context);
        if (entry) deduplicated.set(entry.key, entry);
      }));
      loadedEntries = [...deduplicated.values()].sort((left, right) => {
        const exactLeft = String(left.id) === String(query).trim() ? 0 : 1;
        const exactRight = String(right.id) === String(query).trim() ? 0 : 1;
        return exactLeft - exactRight || left.alias.localeCompare(right.alias) || left.id - right.id;
      });
      if (selected?.key) {
        const resolved = loadedEntries.find((entry) => entry.key === selected.key);
        if (resolved) {
          selected = resolved;
          updateSelection();
        }
      }
      const matches = loadedEntries;
      if (passive) loadedEntries = [];
      renderResults(true);
      return matches;
    } catch (error) {
      if (generation !== searchGeneration || error?.name === 'AbortError') return [];
      loadedEntries = [];
      results.replaceChildren();
      input.setAttribute('aria-expanded', 'false');
      status.textContent = 'Identity suggestions are unavailable. Try again.';
      return [];
    } finally {
      renderSignal?.removeEventListener('abort', abortForRender);
      if (searchController === controller) searchController = null;
      if (generation === searchGeneration) input.removeAttribute('aria-busy');
    }
  };

  const scheduleSearch = () => {
    const generation = ++searchGeneration;
    pageTimeout(() => {
      if (generation === searchGeneration && input.isConnected) void load(input.value.trim());
    }, ACTIVITY_IDENTITY_SEARCH_DELAY_MILLISECONDS);
  };
  input.addEventListener('input', () => {
    input.setCustomValidity('');
    if (input.value.trim()) {
      cancelIdentitySearch();
      loadedEntries = [];
      renderResults();
      status.textContent = 'Searching identities…';
      scheduleSearch();
    } else void load('');
  });
  input.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      const choices = [...results.querySelectorAll('[role="option"]')];
      const selectedChoice = choices.find((candidate) => candidate.getAttribute('aria-selected') === 'true');
      const choice = selectedChoice || (event.key === 'ArrowDown' ? choices[0] : choices.at(-1));
      if (choice) {
        event.preventDefault();
        choices.forEach((candidate) => { candidate.tabIndex = candidate === choice ? 0 : -1; });
        choice.focus();
      }
    } else if (event.key === 'Enter') {
      const exact = exactNumericEntry();
      if (exact) {
        event.preventDefault();
        selectEntry(exact);
      }
    }
  });
  results.addEventListener('keydown', (event) => {
    const option = event.target.closest?.('[role="option"]');
    if (!option || !results.contains(option)) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      input.focus();
      return;
    }
    const choices = [...results.querySelectorAll('[role="option"]')];
    const nextIndex = activityListboxNavigationIndex(choices.indexOf(option), choices.length, event.key);
    if (nextIndex < 0) return;
    event.preventDefault();
    choices.forEach((candidate, index) => { candidate.tabIndex = index === nextIndex ? 0 : -1; });
    choices[nextIndex].focus();
  });
  clear.addEventListener('click', () => {
    cancelIdentitySearch();
    selected = null;
    input.value = '';
    input.setCustomValidity('');
    loadedEntries = [];
    results.replaceChildren();
    status.textContent = 'Search by ID or alias.';
    updateSelection();
    if (panel.matches(':popover-open')) panel.hidePopover();
    trigger.focus();
  });
  const dropdownCleanup = bindAnchoredDropdown(trigger, panel, activeRenderController?.signal);
  repositionPanel = dropdownCleanup.position;
  panel.addEventListener('toggle', (event) => {
    const open = event.newState === 'open';
    trigger.setAttribute('aria-expanded', String(open));
    input.setAttribute('aria-expanded', String(open && results.childElementCount > 0));
    if (open) {
      input.focus();
      if (input.value.trim()) void load(input.value.trim());
      else renderResults();
    }
  });

  panel.append(search);
  if (kindTabs) panel.append(kindTabs);
  panel.append(results, footer);
  field.append(node('span', 'ui-field-label', options.label || (destination ? 'Destination' : 'Source radio')),
    trigger, panel);
  updateSelection();
  if (selected?.key) {
    pageTimeout(() => {
      if (input.isConnected) void load(String(selected.id), true);
    }, 0);
  }

  const read = () => {
    const query = input.value.trim();
    if (query) {
      const exact = exactNumericEntry();
      if (exact) selectEntry(exact);
      else {
        const exactMatches = exactNumericEntries();
        const message = !/^\d+$/.test(query) ? 'Choose an identity from the search results.' :
          exactMatches.length > 1 ? 'Choose the identity type because more than one uses this ID.' :
            'No matching identity was found. Try another ID.';
        input.setCustomValidity(message);
        return { key: '', id: null, kind: '', error: message };
      }
    }
    return { key: selected?.key || '', id: null, kind: selected?.kind || '' };
  };
  return Object.freeze({
    element: field,
    input,
    async resolve() {
      const query = input.value.trim();
      if (query && /^\d+$/.test(query) && !exactNumericEntry()) await load(query);
      return read();
    },
    read,
    close() {
      cancelIdentitySearch();
      input.setAttribute('aria-expanded', 'false');
      if (panel.matches(':popover-open')) panel.hidePopover();
    }
  });
}

function activityChannelFilter(context, selectedConfigurationId = '') {
  const values = [{ value: '', label: 'All channels / sites' }];
  if (selectedConfigurationId) values.push({ value: selectedConfigurationId, label: 'Selected channel' });
  const control = activityFilterSelect('Channel / site', values, selectedConfigurationId,
    'Limit this system or identity to one configured channel.');
  const status = node('small', 'ui-field-detail activity-channel-filter-status', 'Loading channels…');
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  control.field.append(status);
  const load = async () => {
    try {
      const page = await apiPage(radioSystemApiPath(context.radioSystemKey, 'channels'), { limit: 500 });
      if (!control.select.isConnected) return;
      const options = [{ value: '', label: 'All channels / sites' }, ...(page.rows || []).map((row) => ({
        value: row.configuration_id,
        label: [row.site_name, row.name, row.configuration_id].filter(Boolean).join(' · ')
      }))];
      if (selectedConfigurationId && !options.some((entry) => entry.value === selectedConfigurationId)) {
        options.push({ value: selectedConfigurationId, label: `Selected · ${selectedConfigurationId}` });
      }
      control.select.replaceChildren(...options.map((entry) => {
        const option = node('option', '', entry.label);
        option.value = entry.value;
        option.selected = entry.value === selectedConfigurationId;
        return option;
      }));
      status.textContent = page.has_more ? 'Showing the first 500 configured channels.' : '';
    } catch (error) {
      if (error?.name === 'AbortError') return;
      status.textContent = 'Channel choices could not be loaded; the current selection is still usable.';
    }
  };
  void load();
  return Object.freeze({ element: control.field, read: () => control.select.value });
}

function activityDestinationFilter(context, initialFilters, label = 'Destination') {
  return activityIdentityPicker(context, {
    label,
    destination: true,
    kind: initialFilters.targetKind || '',
    identityKey: initialFilters.targetIdentityKey,
    onSelection: initialFilters.onSelection
  });
}

function activityFilterGroup(title, controls, className = '') {
  if (!controls.length) return null;
  const section = node('section', `activity-filter-group${className ? ` ${className}` : ''}`);
  section.append(node('h3', 'activity-filter-group-title', title));
  const grid = node('div', 'activity-filter-grid');
  controls.forEach((control) => grid.append(control));
  section.append(grid);
  return section;
}

function activityFilterIdentitySummary(identityKey, explicitKind = '', numericId = null) {
  const key = activityIdentityKey(identityKey);
  const id = numericId ?? (key ? key.split('-').at(-1) : '');
  if (id === '' || id === null || id === undefined) {
    return explicitKind ? `Any ${activityIdentityKindLabel(explicitKind).toLowerCase()}` : '';
  }
  const parts = key ? key.split('-') : [];
  const home = parts[2] && parts[2] !== 'x' ? `${parts[2]}-${parts[3]}` : '';
  return `${id}${home ? ` · ${home}` : ''}`;
}

function activityIdentityChipValue(entry) {
  if (!entry) return '';
  if (entry.kindOnly) return entry.label;
  return `${entry.displayId}${entry.alias ? ` · ${entry.alias}` : ''}${entry.home ? ` · ${entry.home}` : ''}`;
}

function activityFilterChipDefinitions(filters, capabilities) {
  const chips = [];
  if (filters.range !== 'all') {
    const range = ACTIVITY_LOG_RANGES.find((entry) => entry.value === filters.range);
    chips.push({ id: 'time', prefix: 'Time:', value: range?.label || 'Custom dates',
      keys: ['activity_range', 'activity_from_ms', 'activity_to_ms'] });
  }
  if (filters.action) {
    chips.push({ id: 'action', prefix: 'Action:', value: activityOptionLabel(filters.action),
      keys: ['activity_action', 'activity_include_grants'] });
  } else if (capabilities.grants && filters.includeGrants) {
    chips.push({ id: 'grants', prefix: 'Action:', value: 'Grants included',
      keys: ['activity_include_grants'] });
  }
  if (filters.sourceIdentityKey || (filters.sourceId !== null && filters.sourceId !== undefined)) {
    chips.push({ id: 'source', prefix: 'Source:',
      value: activityFilterIdentitySummary(filters.sourceIdentityKey, 'radio', filters.sourceId),
      keys: ['activity_source_identity_key', 'activity_source_id'] });
  }
  if (filters.targetIdentityKey ||
      (filters.targetId !== null && filters.targetId !== undefined) || filters.targetKind) {
    const kind = filters.targetKind || activityIdentityKindFromKey(filters.targetIdentityKey);
    chips.push({ id: 'destination', prefix: 'Destination:',
      value: activityFilterIdentitySummary(filters.targetIdentityKey, kind, filters.targetId),
      kindLabel: kind && (filters.targetIdentityKey ||
        filters.targetId !== null && filters.targetId !== undefined) ? activityIdentityKindLabel(kind) : '',
      keys: ['activity_target_identity_key', 'activity_target_id', 'activity_target_kind'] });
  }
  if (capabilities.encryption && filters.encryption !== 'all') {
    chips.push({ id: 'encryption', value: filters.encryption === 'encrypted' ?
      'Encrypted only' : 'Clear only', keys: ['activity_encryption'] });
  }
  if (filters.eventType) {
    chips.push({ id: 'event', prefix: 'Event subtype:', value: activityOptionLabel(filters.eventType),
      keys: ['activity_event_type'] });
  }
  if (filters.configurationId) {
    chips.push({ id: 'channel', prefix: 'Channel/site:', value: 'Selected channel',
      keys: ['activity_configuration_id'] });
  }
  if (filters.radioRole !== 'any') {
    chips.push({ id: 'role', prefix: 'This radio was:',
      value: filters.radioRole === 'source' ? 'Source' : 'Destination',
      keys: ['activity_radio_role', 'activity_source_identity_key', 'activity_target_identity_key',
        'activity_source_id', 'activity_target_id', 'activity_target_kind'] });
  }
  if (filters.groupMatch !== 'all') {
    chips.push({ id: 'group-match', prefix: 'Group match:',
      value: filters.groupMatch === 'direct' ? 'Direct only' : 'Via patch only',
      keys: ['activity_group_match'] });
  }
  if (filters.frequencyHz !== null && filters.frequencyHz !== undefined) {
    chips.push({ id: 'frequency', prefix: 'Frequency:', value: `${frequency(filters.frequencyHz)} MHz`,
      keys: ['activity_frequency_hz'] });
  }
  if (filters.lcn) chips.push({ id: 'lcn', prefix: 'LCN:', value: filters.lcn, keys: ['activity_lcn'] });
  if (filters.timeslot !== null && filters.timeslot !== undefined) {
    chips.push({ id: 'timeslot', value: `Timeslot ${filters.timeslot}`, keys: ['activity_timeslot'] });
  }
  return chips;
}

function activityFilterToolbar(context, initialFilters) {
  const capabilities = activityContextCapabilities(context);
  const form = node('form', 'activity-filter-toolbar ui-toolbar data-workspace');
  form.setAttribute('aria-label', 'Filter retained activity');
  const primary = node('div', 'activity-filter-primary');
  const rangeControl = activityFilterSelect('Time', ACTIVITY_LOG_RANGES, initialFilters.range);
  const fromInput = node('input', 'ui-input');
  fromInput.type = 'datetime-local';
  fromInput.value = activityLocalDateTimeValue(initialFilters.fromMs);
  const toInput = node('input', 'ui-input');
  toInput.type = 'datetime-local';
  toInput.value = activityLocalDateTimeValue(initialFilters.toMs);
  const customDates = node('div', 'activity-filter-custom-dates');
  customDates.append(activityFilterField('From', fromInput, 'Inclusive'),
    activityFilterField('To', toInput, 'Exclusive'));
  customDates.hidden = initialFilters.range !== 'custom';
  rangeControl.select.addEventListener('change', () => {
    customDates.hidden = rangeControl.select.value !== 'custom';
    if (!customDates.hidden && (!fromInput.value || !toInput.value)) {
      const current = Date.now();
      fromInput.value = activityLocalDateTimeValue(current - 24 * 60 * 60 * 1000);
      toInput.value = activityLocalDateTimeValue(current);
    }
  });

  const actionControl = activityFilterSelect('Action', [
    { value: '', label: capabilities.grants ? 'All actions (grants hidden)' : 'All actions' },
    ...(capabilities.grants ? [{ value: ACTIVITY_ACTION_INCLUDE_GRANTS,
      label: 'All actions (including grants)' }] : []),
    ...ACTIVITY_ACTION_VALUES.map((value) => ({ value, label: activityOptionLabel(value) }))
  ], activityActionControlValue(initialFilters, capabilities));
  primary.append(rangeControl.field, actionControl.field);

  let chipsHost = null;
  const resolvedIdentityLabels = new Map();
  const updateIdentityChip = (id, entry) => {
    if (!entry) return;
    const label = activityIdentityChipValue(entry);
    resolvedIdentityLabels.set(id, label);
    const value = chipsHost?.querySelector(`[data-activity-filter-chip="${id}"] .activity-filter-chip-value`);
    if (value) value.textContent = label;
  };

  let sourceChooser = null;
  let destinationChooser = null;
  if (capabilities.sourceIdentity) {
    sourceChooser = activityIdentityPicker(context, {
      label: 'Source radio', kind: 'radio', identityKey: initialFilters.sourceIdentityKey,
      onSelection: (entry) => {
        if (entry?.key && entry.key === initialFilters.sourceIdentityKey) {
          updateIdentityChip('source', entry);
        }
      }
    });
    primary.append(sourceChooser.element);
  }
  if (capabilities.targetIdentity) {
    destinationChooser = activityDestinationFilter(context, {
      ...initialFilters,
      onSelection: (entry) => {
        const committed = entry?.key ? entry.key === initialFilters.targetIdentityKey :
          entry?.kindOnly && !initialFilters.targetIdentityKey && entry.kind === initialFilters.targetKind;
        if (committed) updateIdentityChip('destination', entry);
      }
    });
    primary.append(destinationChooser.element);
  }

  let radioRoleControl = null;
  let radioCounterpartHost = null;
  let radioSourceChooser = null;
  let radioDestinationChooser = null;
  const renderRadioCounterpart = () => {
    if (!radioCounterpartHost || !radioRoleControl) return;
    radioSourceChooser?.close();
    radioDestinationChooser?.close();
    radioCounterpartHost.replaceChildren();
    radioSourceChooser = null;
    radioDestinationChooser = null;
    if (radioRoleControl.select.value === 'target') {
      radioSourceChooser = activityIdentityPicker(context, {
        label: 'Other source radio', kind: 'radio', identityKey: initialFilters.sourceIdentityKey,
        onSelection: (entry) => {
          if (entry?.key && entry.key === initialFilters.sourceIdentityKey) {
            updateIdentityChip('source', entry);
          }
        }
      });
      radioCounterpartHost.append(radioSourceChooser.element);
    } else if (radioRoleControl.select.value === 'source') {
      radioDestinationChooser = activityDestinationFilter(context, {
        ...initialFilters,
        onSelection: (entry) => {
          const committed = entry?.key ? entry.key === initialFilters.targetIdentityKey :
            entry?.kindOnly && !initialFilters.targetIdentityKey && entry.kind === initialFilters.targetKind;
          if (committed) updateIdentityChip('destination', entry);
        }
      }, 'Other destination');
      radioCounterpartHost.append(radioDestinationChooser.element);
    }
  };
  if (capabilities.radioRole) {
    radioRoleControl = activityFilterSelect('This radio was', [
      { value: 'any', label: 'Source or destination' }, { value: 'source', label: 'Source' },
      { value: 'target', label: 'Destination' }
    ], initialFilters.radioRole);
    radioCounterpartHost = node('div', 'activity-filter-counterpart');
    primary.append(radioRoleControl.field, radioCounterpartHost);
    radioRoleControl.select.addEventListener('change', renderRadioCounterpart);
    renderRadioCounterpart();
  }

  let rawSourceInput = null;
  let rawTargetInput = null;
  let rawTargetKindControl = null;
  if (capabilities.rawIdentities) {
    rawSourceInput = node('input', 'ui-input');
    rawSourceInput.type = 'number';
    rawSourceInput.min = '0';
    rawSourceInput.max = '16777215';
    rawSourceInput.step = '1';
    rawSourceInput.placeholder = 'Any source ID';
    rawSourceInput.value = initialFilters.sourceId === null ? '' : String(initialFilters.sourceId);
    rawTargetInput = node('input', 'ui-input');
    rawTargetInput.type = 'number';
    rawTargetInput.min = '0';
    rawTargetInput.max = '16777215';
    rawTargetInput.step = '1';
    rawTargetInput.placeholder = 'Any destination ID';
    rawTargetInput.value = initialFilters.targetId === null ? '' : String(initialFilters.targetId);
    rawTargetKindControl = activityFilterSelect('Destination type', [
      { value: '', label: 'Any type' }, { value: 'talkgroup', label: 'Talkgroup' },
      { value: 'radio', label: 'Radio' }
    ], initialFilters.targetKind);
    primary.append(activityFilterField('Source ID', rawSourceInput),
      rawTargetKindControl.field, activityFilterField('Destination ID', rawTargetInput));
  }

  let encryptionControl = null;
  if (capabilities.encryption) {
    encryptionControl = activityFilterSelect('Encryption', [
      { value: 'all', label: 'All' }, { value: 'clear', label: 'Clear' },
      { value: 'encrypted', label: 'Encrypted' }
    ], initialFilters.encryption);
  }

  const eventControl = activityFilterSelect('Event subtype', [
    { value: '', label: 'All event subtypes' },
    ...ACTIVITY_EVENT_TYPE_VALUES.map((value) => ({ value, label: activityOptionLabel(value) }))
  ], initialFilters.eventType);

  let channelControl = null;
  if (capabilities.channel && context.radioSystemKey) {
    channelControl = activityChannelFilter(context, initialFilters.configurationId);
  }

  let groupMatchControl = null;
  if (capabilities.groupMatch) {
    groupMatchControl = activityFilterSelect('Group match', [
      { value: 'all', label: 'Direct or through a patch' },
      { value: 'direct', label: 'Direct only' },
      { value: 'via_patch', label: 'Through a patch only' }
    ], initialFilters.groupMatch);
  }

  let frequencyInput = null;
  let lcnInput = null;
  let timeslotControl = null;
  if (capabilities.frequency) {
    frequencyInput = node('input', 'ui-input');
    frequencyInput.type = 'number';
    frequencyInput.min = '0.000001';
    frequencyInput.step = '0.000001';
    frequencyInput.inputMode = 'decimal';
    frequencyInput.value = initialFilters.frequencyHz === null ? '' :
      String(initialFilters.frequencyHz / 1_000_000);
  }
  if (capabilities.lcn) {
    lcnInput = node('input', 'ui-input');
    lcnInput.type = 'text';
    lcnInput.inputMode = 'numeric';
    lcnInput.placeholder = 'Band-channel';
    lcnInput.pattern = '\\d+-\\d+';
    lcnInput.value = initialFilters.lcn;
  }
  if (capabilities.timeslotFilter) {
    timeslotControl = activityFilterSelect('Timeslot', [
      { value: '', label: 'All timeslots' }, { value: '1', label: 'Timeslot 1' },
      { value: '2', label: 'Timeslot 2' }
    ], initialFilters.timeslot === null ? '' : String(initialFilters.timeslot));
  }

  const moreSequence = ++activityFilterControlSequence;
  const morePanelId = `activity-filter-more-${moreSequence}`;
  const moreTrigger = node('button', 'ui-button ui-button-secondary activity-filter-more-trigger');
  moreTrigger.type = 'button';
  moreTrigger.setAttribute('popovertarget', morePanelId);
  moreTrigger.setAttribute('aria-controls', morePanelId);
  moreTrigger.setAttribute('aria-haspopup', 'dialog');
  moreTrigger.setAttribute('aria-expanded', 'false');
  moreTrigger.append(iconGlyph('icon-filter'), node('span', '', 'Filters'));
  const moreCount = activityMoreFilterCount(initialFilters, capabilities);
  if (moreCount) moreTrigger.append(uiPill(number(moreCount), 'neutral'));
  const morePanel = node('div', 'ui-popover activity-filter-more-panel');
  morePanel.id = morePanelId;
  morePanel.setAttribute('popover', 'auto');
  morePanel.setAttribute('role', 'dialog');
  morePanel.setAttribute('aria-label', 'Activity filters');
  const eventControls = [eventControl.field];
  if (encryptionControl) eventControls.push(encryptionControl.field);
  const scopeControls = [];
  if (channelControl) scopeControls.push(channelControl.element);
  if (groupMatchControl) scopeControls.push(groupMatchControl.field);
  const technicalControls = [];
  if (frequencyInput) technicalControls.push(activityFilterField('Frequency (MHz)', frequencyInput));
  if (lcnInput) technicalControls.push(activityFilterField('LCN', lcnInput));
  if (timeslotControl) technicalControls.push(timeslotControl.field);
  const moreContent = node('div', 'activity-filter-more-content');
  [activityFilterGroup('Scope', scopeControls),
    activityFilterGroup('Event details', eventControls),
    activityFilterGroup('Technical', technicalControls, 'activity-filter-group-technical')]
    .filter(Boolean).forEach((group) => moreContent.append(group));
  const moreFooter = node('div', 'activity-filter-more-footer');
  const moreDone = node('button', 'ui-button ui-button-primary activity-filter-more-done', 'Done');
  moreDone.type = 'button';
  moreDone.addEventListener('click', () => {
    if (morePanel.matches(':popover-open')) morePanel.hidePopover();
    moreTrigger.focus();
  });
  moreFooter.append(moreDone);
  morePanel.append(moreContent, moreFooter);
  morePanel.addEventListener('toggle', (event) => {
    moreTrigger.setAttribute('aria-expanded', String(event.newState === 'open'));
  });
  bindAnchoredDropdown(moreTrigger, morePanel, activeRenderController?.signal, { mobileSheet: true });
  primary.append(moreTrigger, morePanel);

  const primaryActions = node('div', 'activity-filter-primary-actions');
  const apply = node('button', 'ui-button ui-button-primary', 'Apply filters');
  apply.type = 'submit';
  primaryActions.append(apply);
  primary.append(primaryActions);

  chipsHost = node('div', 'activity-filter-chips');
  chipsHost.setAttribute('aria-label', 'Active filters');
  const chipDefinitions = activityFilterChipDefinitions(initialFilters, capabilities);
  chipDefinitions.forEach((definition) => {
    const chip = node('button', 'ui-button ui-button-secondary activity-filter-chip');
    chip.type = 'button';
    chip.dataset.activityFilterChip = definition.id;
    chip.setAttribute('aria-label', `Remove ${[definition.prefix, definition.value].filter(Boolean).join(' ')} filter`);
    if (definition.prefix) chip.append(node('span', 'activity-filter-chip-label', definition.prefix));
    if (definition.kindLabel) chip.append(uiPill(definition.kindLabel, 'blue'));
    chip.append(node('span', 'activity-filter-chip-value',
      resolvedIdentityLabels.get(definition.id) || definition.value), iconGlyph('icon-close'));
    chip.addEventListener('click', () => {
      const overrides = Object.fromEntries(definition.keys.map((key) => [key, null]));
      overrides.before_id = null;
      navigateTo(currentHref(overrides));
    });
    chipsHost.append(chip);
  });
  if (chipDefinitions.length) {
    const clear = node('button', 'link-button activity-filter-clear', 'Clear filters');
    clear.type = 'button';
    clear.addEventListener('click', () => {
      const overrides = Object.fromEntries(ACTIVITY_ROUTE_KEYS.map((key) => [key, null]));
      overrides.before_id = null;
      navigateTo(currentHref(overrides));
    });
    chipsHost.append(clear);
  } else chipsHost.hidden = true;

  const status = node('p', 'activity-filter-error ui-notice ui-notice-danger');
  status.setAttribute('role', 'alert');
  status.hidden = true;

  const invalidInteger = (input, label) => {
    if (!input || !input.value.trim()) return null;
    const value = activityInteger(input.value, 0, 16_777_215);
    if (value !== null) return value;
    input.setCustomValidity(`${label} must be a whole number from 0 through 16777215.`);
    return undefined;
  };
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    status.hidden = true;
    status.textContent = '';
    form.querySelectorAll('input').forEach((input) => input.setCustomValidity(''));
    const range = rangeControl.select.value;
    const fromMs = range === 'custom' ? activityLocalDateTimeMilliseconds(fromInput.value) : null;
    const toMs = range === 'custom' ? activityLocalDateTimeMilliseconds(toInput.value) : null;
    if (range === 'custom' && (!fromMs || !toMs || fromMs >= toMs)) {
      const message = 'Choose a valid custom range whose From time is earlier than its To time.';
      fromInput.setCustomValidity(message);
      status.textContent = message;
      status.hidden = false;
      fromInput.reportValidity();
      return;
    }

    let source = { key: '', id: null };
    let destination = { key: '', id: null, kind: '' };
    apply.disabled = true;
    if (sourceChooser) source = await sourceChooser.resolve();
    if (destinationChooser) destination = await destinationChooser.resolve();
    if (radioRoleControl?.select.value === 'target' && radioSourceChooser) {
      source = await radioSourceChooser.resolve();
    }
    if (radioRoleControl?.select.value === 'source' && radioDestinationChooser) {
      destination = await radioDestinationChooser.resolve();
    }
    if (source.error || destination.error) {
      status.textContent = source.error || destination.error;
      status.hidden = false;
      (source.error ? sourceChooser?.input || radioSourceChooser?.input :
        destinationChooser?.input || radioDestinationChooser?.input)?.reportValidity();
      apply.disabled = false;
      return;
    }
    if (capabilities.rawIdentities) {
      const sourceId = invalidInteger(rawSourceInput, 'Source ID');
      const targetId = invalidInteger(rawTargetInput, 'Target ID');
      if (sourceId === undefined || targetId === undefined) {
        status.textContent = rawSourceInput.validationMessage || rawTargetInput.validationMessage;
        status.hidden = false;
        (sourceId === undefined ? rawSourceInput : rawTargetInput).reportValidity();
        apply.disabled = false;
        return;
      }
      source = { key: '', id: sourceId };
      destination = { key: '', id: targetId, kind: rawTargetKindControl.select.value };
    }
    let frequencyHz = null;
    if (frequencyInput?.value.trim()) {
      const megahertz = Number(frequencyInput.value);
      frequencyHz = Number.isFinite(megahertz) && megahertz > 0 ? Math.round(megahertz * 1_000_000) : null;
      if (!frequencyHz) {
        const message = 'Frequency must be a positive value in MHz.';
        frequencyInput.setCustomValidity(message);
        status.textContent = message;
        status.hidden = false;
        frequencyInput.reportValidity();
        apply.disabled = false;
        return;
      }
    }
    const lcn = lcnInput?.value.trim() || '';
    if (lcn && !/^\d+-\d+$/.test(lcn)) {
      const message = 'LCN must use band-channel form, such as 1-125.';
      lcnInput.setCustomValidity(message);
      status.textContent = message;
      status.hidden = false;
      lcnInput.reportValidity();
      apply.disabled = false;
      return;
    }
    const actionSelection = actionControl.select.value;
    const action = actionSelection === ACTIVITY_ACTION_INCLUDE_GRANTS ? '' : actionSelection;
    const next = {
      range, fromMs, toMs, action, eventType: eventControl.select.value,
      encryption: encryptionControl?.select.value || 'all',
      includeGrants: action === 'GRANT' || actionSelection === ACTIVITY_ACTION_INCLUDE_GRANTS,
      configurationId: channelControl?.read() || '',
      radioRole: radioRoleControl?.select.value || 'any',
      groupMatch: groupMatchControl?.select.value || 'all',
      sourceIdentityKey: source.key || '', targetIdentityKey: destination.key || '',
      sourceId: source.id, targetId: destination.id,
      targetKind: destination.kind || '', frequencyHz, lcn,
      timeslot: timeslotControl ? (timeslotControl.select.value ?
        Number(timeslotControl.select.value) : null) : initialFilters.timeslot
    };
    if (next.radioRole === 'any' && capabilities.radioRole) {
      next.sourceIdentityKey = '';
      next.targetIdentityKey = '';
      next.sourceId = null;
      next.targetId = null;
      next.targetKind = '';
    }
    sourceChooser?.close();
    destinationChooser?.close();
    radioSourceChooser?.close();
    radioDestinationChooser?.close();
    if (morePanel.matches(':popover-open')) morePanel.hidePopover();
    navigateTo(currentHref(activityFilterRouteOverrides(next)));
  });

  form.append(primary, customDates, chipsHost, status);
  return form;
}

function activityCellNavigation(row, columnId) {
  if (!capabilityAllowed(ACCESS_CAPABILITIES.RADIO)) return null;
  if (['source', 'source-alias', 'source-ota-alias'].includes(columnId)) {
    const target = entityTarget(row?.source_entity_ref, { channel: 'radios' });
    return target ? {
      target,
      title: 'Open source details',
      description: 'Open the radio or saved-channel radio directory for this source.'
    } : null;
  }
  if (['target', 'target-alias'].includes(columnId)) {
    const kind = activityTargetKind(row);
    const target = entityTarget(row?.target_entity_ref,
      { channel: kind === 'radio' ? 'radios' : 'groups' });
    return target ? {
      target,
      title: 'Open target details',
      description: 'Open the radio, group, or saved-channel directory for this target.'
    } : null;
  }
  if (columnId === 'channel') {
    const target = entityRefHref(row?.entity_ref);
    return target ? {
      target,
      title: 'Open channel details',
      description: 'Open this channel or site and its saved details.'
    } : null;
  }
  return null;
}

function activityCellDimension(columnId) {
  return ({
    action: 'action', event: 'event subtype', source: 'source radio',
    'source-alias': 'source radio', 'source-ota-alias': 'source radio',
    target: 'target', 'target-alias': 'target', channel: 'channel',
    encryption: 'encryption state'
  })[columnId] || 'value';
}

let activeActivityCellActionTooltip = null;

function showActivityCellActionTooltip(trigger, dimension, text, filterTarget, navigation, options = {}) {
  const current = activeActivityCellActionTooltip;
  if (current?.trigger === trigger && current.panel.matches(':popover-open')) {
    if (options.pin) current.pinned = true;
    if (options.focus) current.filter.focus({ preventScroll: true });
    return current;
  }
  current?.close();

  const panel = node('div', 'ui-popover ui-icon-action-tooltip activity-cell-action-tooltip');
  panel.id = `activity-cell-action-tooltip-${++activityCellActionSequence}`;
  panel.setAttribute('popover', 'auto');
  panel.setAttribute('role', 'group');
  panel.setAttribute('aria-label', `${dimension} ${text} actions`);
  const action = (target, icon, label) => {
    const link = anchor(iconGlyph(icon), target,
      'ui-button ui-button-secondary ui-icon-button activity-cell-action-icon');
    link.setAttribute('aria-label', label);
    link.title = label;
    return link;
  };
  const filter = action(filterTarget, 'icon-filter', `Filter activity by this ${dimension}`);
  const details = action(navigation.target, 'icon-open-details', `Open ${dimension} details`);
  panel.append(filter, details);
  trigger.setAttribute('aria-controls', panel.id);
  const cleanupDropdown = bindAnchoredDropdown(trigger, panel, activeRenderController?.signal);
  let hideTimer = null;
  let closed = false;
  let state = null;
  const cancelHide = () => {
    window.clearTimeout(hideTimer);
    hideTimer = null;
  };
  const cleanup = () => {
    if (closed) return;
    closed = true;
    cancelHide();
    cleanupDropdown();
    panel.remove();
    trigger.removeAttribute('aria-controls');
    if (activeActivityCellActionTooltip === state) activeActivityCellActionTooltip = null;
  };
  const close = (returnFocus = false) => {
    if (!closed && panel.matches(':popover-open')) panel.hidePopover();
    cleanup();
    if (returnFocus && trigger.isConnected) {
      trigger.dataset.activityTooltipReturningFocus = '';
      trigger.focus({ preventScroll: true });
      window.queueMicrotask(() => delete trigger.dataset.activityTooltipReturningFocus);
    }
  };
  const scheduleHide = () => {
    if (state?.pinned) return;
    cancelHide();
    hideTimer = window.setTimeout(() => {
      if (!state?.pinned && !trigger.matches(':hover, :focus-visible') &&
          !panel.matches(':hover') && !panel.contains(document.activeElement)) close();
    }, 140);
  };
  panel.addEventListener('toggle', (event) => {
    if (event.newState === 'closed') cleanup();
  });
  panel.addEventListener('pointerenter', cancelHide);
  panel.addEventListener('pointerleave', scheduleHide);
  panel.addEventListener('focusout', (event) => {
    if (event.relatedTarget === trigger || panel.contains(event.relatedTarget)) return;
    window.setTimeout(() => {
      if (!panel.contains(document.activeElement) && document.activeElement !== trigger) close();
    }, 0);
  });
  panel.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    event.stopPropagation();
    close(true);
  });
  trigger.after(panel);
  panel.showPopover();
  state = { trigger, panel, filter, close, scheduleHide, pinned: Boolean(options.pin) };
  activeActivityCellActionTooltip = state;
  if (options.focus) filter.focus({ preventScroll: true });
  return state;
}

function activityCellValue(displayValue, row, columnId, context, filters) {
  const text = displayValue instanceof Node ? displayValue.textContent.trim() : String(displayValue || '').trim();
  if (!text) return displayValue;
  const filterOverrides = activityCellFilterRouteOverrides(filters, context, row, columnId);
  const filterTarget = filterOverrides ? currentHref(filterOverrides) : '';
  const navigation = activityCellNavigation(row, columnId);
  const dimension = activityCellDimension(columnId);
  if (!filterTarget && !navigation) return displayValue;
  if (!filterTarget) {
    const link = anchor(displayValue, navigation.target);
    link.title = navigation.title;
    return link;
  }
  if (!navigation) {
    const link = anchor(displayValue, filterTarget, 'activity-cell-filter-link');
    link.title = `Filter Activity by this ${dimension}`;
    link.setAttribute('aria-label', `Filter Activity by ${dimension} ${text}`);
    return link;
  }

  const rowKey = String(row?.id ?? `new-${++activityCellActionSequence}`).replace(/[^a-z0-9_-]/gi, '-');
  const triggerId = `activity-cell-action-${rowKey}-${columnId}`;
  const content = node('span', 'identity-summary activity-cell-action-content');
  content.append(valueNode(displayValue));
  const trigger = anchor(content, navigation.target, 'activity-cell-action-link');
  trigger.id = triggerId;
  trigger.setAttribute('aria-label', `${dimension} ${text} actions`);
  trigger.setAttribute('aria-expanded', 'false');
  trigger.append(iconGlyph('icon-chevron-down'));
  let hoverTimer = null;
  const clearHoverTimer = () => {
    window.clearTimeout(hoverTimer);
    hoverTimer = null;
  };
  const show = (options = {}) => showActivityCellActionTooltip(
    trigger, dimension, text, filterTarget, navigation, options);
  trigger.addEventListener('pointerenter', (event) => {
    if (event.pointerType !== 'mouse' && event.pointerType !== 'pen') return;
    clearHoverTimer();
    hoverTimer = window.setTimeout(() => show(), 250);
  });
  trigger.addEventListener('pointerleave', () => {
    clearHoverTimer();
    if (activeActivityCellActionTooltip?.trigger === trigger)
      activeActivityCellActionTooltip.scheduleHide();
  });
  trigger.addEventListener('focusin', () => {
    if (!trigger.hasAttribute('data-activity-tooltip-returning-focus') &&
        trigger.matches(':focus-visible')) show();
  });
  trigger.addEventListener('focusout', (event) => {
    const active = activeActivityCellActionTooltip;
    if (active?.trigger === trigger && !active.panel.contains(event.relatedTarget)) active.scheduleHide();
  });
  trigger.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && activeActivityCellActionTooltip?.trigger === trigger) {
      event.preventDefault();
      activeActivityCellActionTooltip.close(true);
    } else if (event.key === 'Enter' || event.key === ' ' || event.key === 'ArrowDown') {
      event.preventDefault();
      clearHoverTimer();
      show({ pin: true, focus: true });
    } else if (event.key === 'Tab' && !event.shiftKey &&
        activeActivityCellActionTooltip?.trigger === trigger) {
      event.preventDefault();
      activeActivityCellActionTooltip.filter.focus({ preventScroll: true });
    }
  });
  trigger.addEventListener('click', (event) => {
    if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    clearHoverTimer();
    show({ pin: true, focus: true });
  });
  return trigger;
}

function activityColumns(context, filters) {
  return [
    { id: 'time', label: 'Seen', fullLabel: 'Observed Time', render: (row) => dateTime(row.observed_at_ms), sortValue: (row) => Number(row.observed_at_ms || 0) },
    { id: 'action', label: 'Action', render: (row) =>
      activityCellValue(row.action, row, 'action', context, filters), sortValue: (row) => row.action || '' },
    { id: 'event', label: 'Event subtype', render: (row) =>
      activityCellValue(row.event_type, row, 'event', context, filters),
      sortValue: (row) => row.event_type || '' },
    { id: 'source', label: 'Src', fullLabel: 'Source ID',
      render: (row) => activityCellValue(activityIdentifier(row, row.source_radio_id, 'radio',
        row.source_entity_ref, false, 'source'), row, 'source', context, filters),
      className: 'numeric identifier-cell', sortValue: (row) => Number(row.source_radio_id || 0) },
    { id: 'source-alias', label: 'Src Alias', fullLabel: 'Source Alias',
      render: (row) => activityCellValue(activitySourceAlias(row, false), row, 'source-alias', context, filters),
      className: 'alias-cell',
      sortValue: (row) => row.source_alias_name || '' },
    { id: 'source-ota-alias', label: 'Src OTA Alias', fullLabel: 'Source Over-the-Air Talker Alias',
      render: (row) => activityCellValue(activitySourceTalkerAlias(row, false), row,
        'source-ota-alias', context, filters), className: 'alias-cell',
      sortValue: (row) => row.source_talker_alias || '' },
    { id: 'target', label: 'Tgt', fullLabel: 'Target ID', render: (row) =>
      activityCellValue(activityTargetIdentifier(row, false), row, 'target', context, filters),
      className: 'numeric identifier-cell', sortValue: (row) => Number(row.target_id || 0) },
    { id: 'target-alias', label: 'Tgt Alias', fullLabel: 'Target Alias', render: (row) =>
      activityCellValue(activityTargetAlias(row, false), row, 'target-alias', context, filters),
      className: 'alias-cell', sortValue: (row) => row.target_alias_name || '' },
    { id: 'channel', label: 'Channel', render: (row) =>
      activityCellValue(activityChannel(row, false), row, 'channel', context, filters), sortValue: (row) =>
      Number(row.frequency_hz || 0) },
    { id: 'encryption', label: 'Enc', fullLabel: 'Encryption', render: (row) =>
      activityCellValue(encryptionActivityValue(row), row, 'encryption', context, filters),
      className: 'encrypted', sortValue: (row) => row.encryption_display || (row.encrypted ? 'ENC' : '') }
  ];
}

function activityColumnsForContext(context, filters) {
  const columns = activityColumns(context, filters);
  if (context?.kind === 'conventional-analog') {
    const visible = new Set(['time', 'action', 'event', 'channel']);
    return columns.filter((column) => visible.has(column.id));
  }
  return columns;
}

function activityTableType(context) {
  return context?.kind === 'conventional-analog' ? 'activity-conventional-analog-v1' : 'activity';
}

async function renderActivity(scopeParameters, title = 'Activity') {
  const renderContext = captureRenderContext();
  const activityContext = activityFilterContext(scopeParameters);
  scopeParameters = activityScopeParameters(scopeParameters);
  const filters = activityRouteFilters(route, activityContext);
  const historyNotice = detailedHistoryNotice();
  if (!detailedHistoryAvailable()) {
    if (renderIsCurrent(renderContext)) {
      content.append(section(title, historyNotice));
    }
    return;
  }
  const data = await api('/api/v1/activity', {
    ...scopeParameters,
    ...activityApiFilterParameters(filters, Date.now()),
    before_id: route.get('before_id'),
    limit: 200
  });
  if (!renderIsCurrent(renderContext)) return;
  const columns = activityColumnsForContext(activityContext, filters);
  const initialRows = filters.includeGrants ? data.rows : withoutGrantActions(data.rows);
  const emptyMessage = historyNotice ? 'No saved activity matches this view.' :
    'Detailed event history is enabled, but no matching activity has been recorded yet.';
  const titleActions = node('div', 'section-title-actions ui-section-actions');
  const activityTable = table(initialRows, columns, emptyMessage,
    { type: activityTableType(activityContext), rowKey: (row) => row.id, layoutMenuHost: titleActions });
  activityTable.setAttribute('aria-live', 'off');
  const block = section(title, activityTable, titleActions);
  const filterToolbar = activityFilterToolbar(activityContext, filters);
  block.insertBefore(filterToolbar, activityTable);
  if (historyNotice) block.insertBefore(historyNotice, filterToolbar);
  const controls = browsingWorkflows.createBrowsingPager({ node, ariaLabel: 'Activity pages' });
  const updatePager = (page) => {
    controls.update({
      previous: { label: 'Newest', enabled: Boolean(route.get('before_id')),
        href: currentHref({ before_id: null }) },
      next: { label: 'Older', enabled: Boolean(page?.has_more),
        href: currentHref({ before_id: page?.next_before_id }) }
    });
  };
  updatePager(data);
  block.append(controls);
  content.append(block);

  if (!route.get('before_id') && filters.range !== 'custom' &&
      (!statsLoggingState().available || statsLoggingState().historyActive)) {
    const refreshControls = node('div', 'section-title-actions ui-section-actions activity-refresh-controls');
    const countdown = node('span', 'activity-refresh-countdown');
    countdown.setAttribute('role', 'timer');
    countdown.setAttribute('aria-live', 'off');
    const announcement = node('span', 'visually-hidden');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    const pause = node('button', 'ui-button ui-button-secondary', 'Pause refresh');
    pause.type = 'button';
    pause.setAttribute('aria-pressed', 'false');
    refreshControls.append(countdown, pause, announcement);
    titleActions.prepend(refreshControls);
    let paused = false;
    let refreshInFlight = false;
    let refreshFailed = false;
    let refreshGeneration = 0;
    let nextRefreshAt = Date.now() + ACTIVITY_REFRESH_INTERVAL_MILLISECONDS;
    const activityRowKey = (row) => row?.id === null || row?.id === undefined ? null : String(row.id);
    const updateRefreshDisplay = () => {
      const seconds = Math.max(0, Math.ceil((nextRefreshAt - Date.now()) / 1000));
      countdown.textContent = paused ? 'Refresh paused' : refreshInFlight ? 'Refreshing…' :
        `${refreshFailed ? 'Retry' : 'Refresh'} in ${seconds}s`;
      countdown.classList.toggle('is-error', refreshFailed && !refreshInFlight);
      pause.textContent = paused ? 'Resume refresh' : 'Pause refresh';
      pause.setAttribute('aria-pressed', String(paused));
    };
    const highlightActivityRows = (rowIds) => {
      if (!rowIds.size) return;
      const highlighted = [];
      activityTable.querySelectorAll('tbody tr[data-id]').forEach((row) => {
        if (rowIds.has(row.dataset.id)) {
          row.classList.add('activity-row-new');
          highlighted.push(row);
        }
      });
      pageTimeout(() => highlighted.forEach((row) => row.classList.remove('activity-row-new')), 8_000);
    };
    const refreshActivity = async () => {
      if (paused || refreshInFlight || document.hidden || !renderIsCurrent(renderContext) ||
          !block.isConnected) return;
      const generation = refreshGeneration;
      refreshInFlight = true;
      updateRefreshDisplay();
      try {
        const refreshed = await api('/api/v1/activity', {
          ...scopeParameters,
          ...activityApiFilterParameters(filters, Date.now()),
          limit: 200
        });
        if (generation !== refreshGeneration || paused || document.hidden || !renderIsCurrent(renderContext) ||
            !block.isConnected) return;
        const rows = filters.includeGrants ? refreshed.rows : withoutGrantActions(refreshed.rows);
        const currentRows = activityTable.tableController.rows();
        const currentIds = new Set(currentRows.map(activityRowKey).filter((key) => key !== null));
        const newIds = new Set(rows.map(activityRowKey)
          .filter((key) => key !== null && !currentIds.has(key)));
        if (JSON.stringify(rows) !== JSON.stringify(currentRows)) {
          activityTable.tableController.replaceRows(rows);
          highlightActivityRows(newIds);
        }
        updatePager(refreshed);
        if (newIds.size) {
          announcement.textContent = `${number(newIds.size)} new activity entr${newIds.size === 1 ? 'y' : 'ies'}.`;
        } else if (refreshFailed) announcement.textContent = 'Activity refresh recovered.';
        else announcement.textContent = '';
        refreshFailed = false;
      } catch (error) {
        if (generation !== refreshGeneration || document.hidden || !renderIsCurrent(renderContext) ||
            !block.isConnected || error?.name === 'AbortError') return;
        refreshFailed = true;
        announcement.textContent = 'Activity refresh failed. The current entries were retained; retrying automatically.';
      } finally {
        refreshInFlight = false;
        if (!renderIsCurrent(renderContext) || !block.isConnected) return;
        nextRefreshAt = generation === refreshGeneration && !paused && !document.hidden ?
          Date.now() + ACTIVITY_REFRESH_INTERVAL_MILLISECONDS : Date.now();
        updateRefreshDisplay();
      }
    };
    pause.addEventListener('click', () => {
      paused = !paused;
      refreshGeneration += 1;
      nextRefreshAt = paused ? nextRefreshAt : Date.now();
      updateRefreshDisplay();
      if (!paused && !refreshInFlight) void refreshActivity();
    });
    const refreshTick = () => {
      if (!renderIsCurrent(renderContext) || !block.isConnected) return;
      updateRefreshDisplay();
      if (!paused && !refreshInFlight && !document.hidden && Date.now() >= nextRefreshAt) {
        void refreshActivity();
      }
    };
    updateRefreshDisplay();
    pageInterval(refreshTick, 1_000);
  }
}

function channelAdminFrequencyList(values) {
  return (values || []).map((value) => frequency(value)).filter(Boolean).join(', ');
}

function uiActionButton(label, iconId, action, className = 'ui-button ui-button-secondary') {
  const button = node('button', className);
  button.type = 'button';
  if (iconId) button.append(iconGlyph(iconId));
  if (label) button.append(node('span', '', label));
  button.addEventListener('click', action);
  return button;
}

function channelAdminButton(label, action, className = 'ui-button ui-button-secondary', iconId = null) {
  return uiActionButton(label, iconId, action, className);
}

function uiSelect(values, selectedValue = '', includeBlank = false, blankLabel = 'None') {
  const select = node('select', 'ui-select');
  if (includeBlank) {
    const blank = node('option', '', blankLabel);
    blank.value = '';
    select.append(blank);
  }
  values.forEach((entry) => {
    const value = typeof entry === 'object' ? entry.value : entry;
    const label = typeof entry === 'object' ? entry.label : entry;
    const option = node('option', '', label);
    option.value = String(value ?? '');
    option.selected = String(value ?? '') === String(selectedValue ?? '');
    select.append(option);
  });
  return select;
}

function uiSelectFrame(select, className = '') {
  const frame = node('span', `ui-select-frame${className ? ` ${className}` : ''}`);
  frame.append(select, iconGlyph('icon-chevron-down'));
  return frame;
}

function uiToggle(checked, accessibleLabel = '') {
  const wrapper = node('label', 'ui-toggle');
  const input = node('input');
  input.type = 'checkbox';
  input.checked = Boolean(checked);
  if (accessibleLabel) input.setAttribute('aria-label', accessibleLabel);
  const track = node('span', 'ui-toggle-track');
  track.append(node('span', 'ui-toggle-thumb'));
  const state = node('span', 'ui-toggle-state', input.checked ? 'On' : 'Off');
  input.addEventListener('change', () => setUiToggle(input, input.checked));
  wrapper.append(input, track, state);
  return wrapper;
}

function uiToggleField(labelText, checked, accessibleLabel = labelText, detail = '') {
  const wrapper = node('div', 'ui-toggle-field');
  const copy = node('span', 'ui-toggle-copy');
  copy.append(node('strong', '', labelText));
  if (detail) copy.append(node('small', '', detail));
  wrapper.append(copy, uiToggle(checked, accessibleLabel));
  return wrapper;
}

function setUiToggle(input, checked) {
  input.checked = Boolean(checked);
  const state = input.closest('.ui-toggle')?.querySelector('.ui-toggle-state');
  if (state) state.textContent = input.checked ? 'On' : 'Off';
}

function uiPill(label, tone = 'neutral', iconId = null) {
  const value = node('span', `ui-pill ui-pill-${tone}`);
  if (iconId) value.append(iconGlyph(iconId));
  value.append(node('span', '', label));
  return value;
}

function uiStatus(label, tone = 'neutral') {
  return node('span', `ui-status ui-status-${tone}`, label);
}

function uiIconTile(iconId, tone = 'accent') {
  const tile = node('span', `ui-icon-tile ui-icon-tile-${tone}`);
  tile.append(iconGlyph(iconId));
  return tile;
}

function uiSegmentedControl(entries, initialValue, onChange) {
  const group = node('div', 'ui-segmented');
  group.setAttribute('role', 'group');
  group.dataset.value = initialValue;
  entries.forEach((entry) => {
    const button = node('button', 'ui-segmented-option', entry.label);
    button.type = 'button';
    button.dataset.value = entry.value;
    button.classList.toggle('active', entry.value === initialValue);
    button.setAttribute('aria-pressed', String(entry.value === initialValue));
    button.addEventListener('click', () => {
      group.dataset.value = entry.value;
      [...group.children].forEach((candidate) => {
        const active = candidate === button;
        candidate.classList.toggle('active', active);
        candidate.setAttribute('aria-pressed', String(active));
      });
      onChange?.(entry.value);
    });
    group.append(button);
  });
  return group;
}

function channelSummaryCards(catalog, editable) {
  const channels = catalog.channels || [];
  const cards = [
    ['Configured channels', channels.length, 'icon-conventional', 'accent'],
    ['Running now', channels.filter((row) => row.processing_state === 'RUNNING').length, 'icon-play', 'success']
  ];
  cards.push(editable ?
    ['Auto-start enabled', channels.filter((row) => row.auto_start_order != null).length, 'icon-play', 'secondary'] :
    ['Stopped', channels.filter((row) => row.processing_state !== 'RUNNING').length, 'icon-stop', 'neutral']);
  const wrapper = metrics(cards.map(([label, value, icon, tone]) =>
    [label, value, undefined, { icon, tone }]), true);
  wrapper.classList.add('channel-summary-grid');
  return wrapper;
}

function channelOriginName(label, row) {
  if (row?.remote_origin?.remote !== true) return label;
  const line = node('span', 'channel-origin-line');
  const origin = uiPill('Remote', 'neutral', 'icon-cloud');
  origin.classList.add('ui-pill-compact');
  origin.title = 'Remote channel; depends on another receiver';
  origin.setAttribute('aria-label', origin.title);
  line.append(label, origin);
  return line;
}

function channelViewLabel(row, context = '') {
  if (context === 'system') return 'View System';
  if (context === 'site' || String(row?.channel_kind || '').toUpperCase() === 'TRUNKED') return 'View Site';
  return 'View Channel';
}

function channelInlineNavigation(row, nameLinksToDetails = false) {
  const links = node('span', 'channel-row-links');
  if (row.editable !== false) {
    const edit = uiActionButton('Edit', 'icon-edit', () =>
      openChannelEditorModal('edit', row.configuration_id),
      'ui-button ui-button-secondary channel-edit-button');
    edit.title = `Edit ${row.name || 'channel'}`;
    links.append(edit);
  }
  if (!nameLinksToDetails) {
    const details = anchor(fragment(iconGlyph('icon-open-details'), node('span', '', 'Details')),
      href('channel', { configuration_id: row.configuration_id }), 'ui-button ui-button-secondary');
    details.title = channelViewLabel(row);
    links.append(details);
  }
  const live = anchor(fragment(iconGlyph('icon-live'), node('span', '', 'Live')),
    href('live', { channel: row.configuration_id }), 'ui-button ui-button-secondary');
  live.title = `Open ${row.name || 'channel'} in Live`;
  links.append(live);
  return links;
}

async function channelAdminMutation(path, options, statusHost, onSuccess = renderChannelSetup) {
  try {
    statusHost?.replaceChildren(node('span', 'muted', 'Working…'));
    const result = await requestJson(path, { timeoutMs: 30_000, ...options });
    const failed = (result?.results || []).filter((entry) => entry.success !== true);
    if (failed.length) throw new Error(failed.map((entry) => entry.message ||
      `${entry.configuration_id} could not be changed`).join(' '));
    statusHost?.replaceChildren();
    await onSuccess?.(result);
    return result;
  } catch (error) {
    statusHost?.replaceChildren(node('span', 'ui-status ui-status-danger', error.message));
    throw error;
  }
}

function asyncControlFocusGuard(control) {
  let retained = document.activeElement === control;
  const onFocusIn = (event) => {
    if (event.target !== control) retained = false;
  };
  if (retained) document.addEventListener('focusin', onFocusIn, true);
  return {
    shouldRestore: () => retained,
    release: () => document.removeEventListener('focusin', onFocusIn, true)
  };
}

function channelAdminColumns(selected, state, selectionChanged, renderSelectionHeader,
  moveAutoStart) {
  const selectedChanged = (id, checked, shiftKey, checkbox) => {
    const rows = [...checkbox.closest('tbody').querySelectorAll('tr[data-id]')];
    const visibleIds = rows.map((row) => row.dataset.id);
    const rowById = new Map(rows.map((row) => [row.dataset.id, row]));
    const previous = state.selectionAnchor;
    const first = visibleIds.indexOf(previous);
    const last = visibleIds.indexOf(id);
    const affected = shiftKey && first >= 0 && last >= 0 ?
      visibleIds.slice(Math.min(first, last), Math.max(first, last) + 1) : [id];
    affected.forEach((selectedId) => {
      if (checked) selected.add(selectedId); else selected.delete(selectedId);
      const row = rowById.get(selectedId);
      const input = row?.querySelector('.ui-selection-check');
      if (input) input.checked = checked;
      row?.classList.toggle('selected', checked);
    });
    state.selectionAnchor = id;
    selectionChanged?.();
  };
  const columns = [
    { id: 'select', label: '', layoutLabel: 'Select channels', className: 'channel-select-cell',
      essential: true, fixed: true, renderHeader: renderSelectionHeader, render: (row) => {
      const checkbox = node('input');
      checkbox.type = 'checkbox';
      checkbox.className = 'ui-selection-check';
      checkbox.checked = selected.has(row.configuration_id);
      checkbox.setAttribute('aria-label', `Select ${row.name || 'channel'}`);
      let shiftPressed = false;
      checkbox.addEventListener('click', (event) => { shiftPressed = event.shiftKey; });
      checkbox.addEventListener('change', () => selectedChanged(row.configuration_id,
        checkbox.checked, shiftPressed, checkbox));
      return checkbox;
    } },
    { id: 'name', label: 'Name', render: (row) => {
      const actions = node('div', 'channel-name-actions');
      const summary = node('div', 'channel-name-summary');
      let name;
      if (row.editable !== false) {
        const edit = node('button', 'link-button channel-edit-name', row.name || 'Unnamed channel');
        edit.type = 'button';
        edit.addEventListener('click', () => openChannelEditorModal('edit', row.configuration_id));
        name = edit;
      } else {
        name = anchor(row.name || 'Unnamed channel',
          href('channel', { configuration_id: row.configuration_id }), 'channel-name-link');
      }
      summary.append(channelOriginName(name, row));
      summary.append(node('span', 'channel-row-context',
        [row.system, row.site].filter(Boolean).join(' · ') || 'No system or site'));
      if (row.editable === false) {
        const locked = uiPill('Compatibility', 'warning', 'icon-lock');
        locked.title = row.restriction_message || 'This configuration is read-only on the web';
        summary.append(locked);
      }
      actions.append(summary, channelInlineNavigation(row, row.editable === false));
      return actions;
    }, sortValue: (row) => row.name || '' },
    { id: 'frequency', label: 'Frequencies', fullLabel: 'Frequencies (MHz)', render: (row) =>
      channelAdminFrequencyList(row.frequencies_hz), className: 'channel-frequency-cell',
      sortValue: (row) => Number(row.frequencies_hz?.[0] || 0) },
    { id: 'status', label: 'Status', render: (row) => uiPill(
      row.processing_state === 'RUNNING' ? 'Running' : 'Stopped',
      row.processing_state === 'RUNNING' ? 'success' : 'neutral',
      row.processing_state === 'RUNNING' ? 'icon-play' : 'icon-stop') },
    { id: 'auto-start', label: 'Order', fullLabel: 'Startup order', className: 'numeric channel-startup-order', render: (row) => {
      const controls = node('div', 'channel-order-controls');
      const restoreControls = () => {
        earlier.disabled = false;
        later.disabled = row.auto_start_order == null;
      };
      const earlier = uiActionButton('', 'icon-arrow-up', async () => {
        const focusGuard = asyncControlFocusGuard(earlier);
        earlier.disabled = later.disabled = true;
        try {
          await moveAutoStart(row.configuration_id, 'EARLIER', focusGuard.shouldRestore);
        } catch (_) {
          restoreControls();
        } finally {
          focusGuard.release();
        }
      }, 'ui-button ui-icon-button');
      earlier.dataset.channelOrderDirection = 'EARLIER';
      earlier.title = row.auto_start_order == null ? 'Enable auto start at the end' : 'Start earlier';
      earlier.setAttribute('aria-label', earlier.title);
      const order = node('span', 'channel-order-number', row.auto_start_order == null ? '—' : row.auto_start_order);
      const later = uiActionButton('', 'icon-arrow-down', async () => {
        if (row.auto_start_order == null) return;
        const focusGuard = asyncControlFocusGuard(later);
        later.disabled = earlier.disabled = true;
        try {
          await moveAutoStart(row.configuration_id, 'LATER', focusGuard.shouldRestore);
        } catch (_) {
          restoreControls();
        } finally {
          focusGuard.release();
        }
      }, 'ui-button ui-icon-button');
      later.dataset.channelOrderDirection = 'LATER';
      later.disabled = row.auto_start_order == null;
      later.title = 'Start later; moving the last channel later disables auto start';
      later.setAttribute('aria-label', later.title);
      controls.append(earlier, order, later);
      return controls;
    }, sortValue: (row) => row.auto_start_order == null ? Number.MAX_SAFE_INTEGER : row.auto_start_order },
    { id: 'alias-list', label: 'Alias List', key: 'alias_list_name', render: (row) =>
      aliasListLink(row.alias_list_name, row.alias_list_id) || '—',
      sortValue: (row) => row.alias_list_name || '' }
  ];
  return columns;
}

function channelProtocolGroup(row) {
  const label = String(row.protocol_label || protocolFamily(row) || 'Other').trim() || 'Other';
  const protocolId = String(row.protocol_id || '').trim().toLowerCase();
  if (protocolId === 'p25-phase1' || protocolId === 'p25-phase2') {
    return { key: 'p25-trunked', label: 'P25 Trunked' };
  }
  if (protocolId === 'p25-conventional') return { key: protocolId, label: 'P25 Conventional' };
  if (protocolId === 'dmr' || protocolId === 'nxdn') {
    const kind = String(row.channel_kind || row.settings?.channel_mode || '').toUpperCase();
    if (kind === 'TRUNKED' || kind === 'CONVENTIONAL') {
      return { key: `${protocolId}-${kind.toLowerCase()}`,
        label: `${protocolId.toUpperCase()} ${kind === 'TRUNKED' ? 'Trunked' : 'Conventional'}` };
    }
  }
  if (protocolId === 'nbfm') return { key: protocolId, label: 'FM' };
  if (protocolId && protocolId !== 'unsupported') return { key: protocolId, label };
  const unsupportedLabel = label.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
    .slice(0, 51).replace(/-+$/g, '') || 'other';
  return { key: `unsupported.${unsupportedLabel}`, label };
}

function channelProtocolOrder(left, right) {
  const leftGroup = channelProtocolGroup(left);
  const rightGroup = channelProtocolGroup(right);
  const groupOrder = {
    'p25-trunked': 0, 'p25-conventional': 1,
    'dmr-trunked': 2, 'dmr-conventional': 3, dmr: 3,
    'nxdn-trunked': 4, 'nxdn-conventional': 5, nxdn: 5,
    nbfm: 6, am: 7
  };
  const byProtocol = (groupOrder[leftGroup.key] ?? 8) - (groupOrder[rightGroup.key] ?? 8) ||
    leftGroup.label.localeCompare(
    rightGroup.label, undefined, { numeric: true, sensitivity: 'base' }) ||
    leftGroup.key.localeCompare(rightGroup.key);
  if (byProtocol) return byProtocol;
  return String(left.name || '').localeCompare(String(right.name || ''), undefined,
    { numeric: true, sensitivity: 'base' });
}

function channelAutoStartOrder(left, right) {
  const leftOrder = Number(left.auto_start_order);
  const rightOrder = Number(right.auto_start_order);
  const leftEnabled = Number.isInteger(leftOrder) && leftOrder > 0;
  const rightEnabled = Number.isInteger(rightOrder) && rightOrder > 0;
  if (leftEnabled !== rightEnabled) return leftEnabled ? -1 : 1;
  if (leftEnabled && leftOrder !== rightOrder) return leftOrder - rightOrder;
  return String(left.name || '').localeCompare(String(right.name || ''), undefined,
    { numeric: true, sensitivity: 'base' }) ||
    String(left.configuration_id || '').localeCompare(String(right.configuration_id || ''));
}

function channelCatalogAfterAutoStartMove(catalog, configurationId, direction) {
  const channels = (catalog.channels || []).map((row, index) => ({ row, index }));
  const enabled = channels.filter(({ row }) => row.auto_start_order != null).sort((left, right) => {
    const byOrder = Number(left.row.auto_start_order || Number.MAX_SAFE_INTEGER) -
      Number(right.row.auto_start_order || Number.MAX_SAFE_INTEGER);
    return byOrder || left.index - right.index ||
      String(left.row.configuration_id || '').localeCompare(String(right.row.configuration_id || ''));
  }).map(({ row }) => row.configuration_id);
  const position = enabled.indexOf(configurationId);
  if (direction === 'EARLIER') {
    if (position < 0) enabled.push(configurationId);
    else if (position > 0) [enabled[position - 1], enabled[position]] =
      [enabled[position], enabled[position - 1]];
  } else if (direction === 'LATER' && position >= 0 && position < enabled.length - 1) {
    [enabled[position], enabled[position + 1]] = [enabled[position + 1], enabled[position]];
  } else if (direction === 'LATER' && position === enabled.length - 1) {
    enabled.splice(position, 1);
  }
  const orderById = new Map(enabled.map((id, index) => [id, index + 1]));
  return {
    ...catalog,
    channels: (catalog.channels || []).map((row) => ({
      ...row,
      auto_start_order: orderById.get(row.configuration_id) ?? null
    }))
  };
}

function radioDirectoryAliasLists(row) {
  const entries = Array.isArray(row.alias_lists) ? row.alias_lists : [];
  if (!entries.length && row.alias_list_name) {
    return aliasListLink(row.alias_list_name, row.alias_list_id) || node('span', 'muted', '—');
  }
  if (!entries.length) return node('span', 'muted', '—');
  const values = node('span', 'radio-directory-alias-lists');
  entries.forEach((entry, index) => {
    if (index) values.append(node('span', 'muted', ' · '));
    values.append(aliasListLink(entry.name, entry.id));
  });
  return values;
}

function radioDirectoryTrunkedGroups(catalog, systems) {
  const channels = (catalog.channels || []).filter((row) =>
    String(row.channel_kind || '').toUpperCase() === 'TRUNKED');
  const byId = new Map(channels.map((row) => [String(row.configuration_id), row]));
  const assigned = new Set();
  const groups = (systems.rows || []).map((system) => {
    const children = (system.channel_preview || []).map((preview) => {
      const channel = byId.get(String(preview.configuration_id));
      if (!channel) return null;
      assigned.add(String(channel.configuration_id));
      return { ...preview, ...channel, directory_type: 'channel' };
    }).filter(Boolean);
    return {
      ...system,
      directory_type: 'radio_system',
      children,
      child_count: children.length,
      running_count: children.filter((row) => row.processing_state === 'RUNNING').length
    };
  });

  // The system directory preview is intentionally bounded. Keep every configured trunked channel visible.
  const unmatched = channels.filter((row) => !assigned.has(String(row.configuration_id)));
  const unmatchedBySystem = new Map();
  unmatched.forEach((row) => {
    const key = String(row.system || 'Other trunked channels');
    const rows = unmatchedBySystem.get(key) || [];
    rows.push({ ...row, directory_type: 'channel' });
    unmatchedBySystem.set(key, rows);
  });
  unmatchedBySystem.forEach((children, systemName) => {
    const existing = groups.find((group) => String(group.system_name || '').trim().toLowerCase() ===
      String(systemName).trim().toLowerCase());
    if (existing) {
      existing.children.push(...children);
      existing.child_count = existing.children.length;
      existing.running_count = existing.children.filter((row) => row.processing_state === 'RUNNING').length;
      return;
    }
    const aliasLists = [...new Map(children.filter((row) => row.alias_list_name).map((row) => [
      String(row.alias_list_id || row.alias_list_name), { id: row.alias_list_id, name: row.alias_list_name }
    ])).values()];
    groups.push({
      directory_type: 'radio_system', system_name: systemName, protocol: children[0]?.protocol_id,
      children, child_count: children.length,
      running_count: children.filter((row) => row.processing_state === 'RUNNING').length,
      alias_lists: aliasLists, local_catalog_group: true
    });
  });
  return groups.sort((left, right) => String(left.system_name || radioSystemLabel(left)).localeCompare(
    String(right.system_name || radioSystemLabel(right))));
}

function radioDirectoryConventionalGroups(rows) {
  const groups = new Map();
  (rows || []).forEach((row) => {
    const configuredSystem = String(row.system || row.system_name || '').trim();
    const systemName = configuredSystem && configuredSystem.toLowerCase() !== 'unknown' ?
      configuredSystem : 'Other channels';
    const key = systemName.toLowerCase();
    const group = groups.get(key) || {
      directory_type: 'conventional_system', system_name: systemName, children: []
    };
    group.children.push({ ...row, directory_type: 'channel' });
    groups.set(key, group);
  });
  const compareText = (left, right) => String(left || '').localeCompare(String(right || ''), undefined,
    { numeric: true, sensitivity: 'base' });
  const compareOptionalText = (left, right) => {
    const leftEmpty = !String(left || '').trim();
    const rightEmpty = !String(right || '').trim();
    return leftEmpty || rightEmpty ? (leftEmpty === rightEmpty ? 0 : leftEmpty ? 1 : -1) :
      compareText(left, right);
  };
  const firstFrequency = (row) => {
    const values = Array.isArray(row.frequencies_hz) ? row.frequencies_hz.map(Number).filter(Number.isFinite) : [];
    return values.length ? Math.min(...values) : Number.MAX_SAFE_INTEGER;
  };
  return [...groups.values()].map((group) => {
    group.children.sort((left, right) => compareOptionalText(left.site || left.site_name,
      right.site || right.site_name) ||
      compareText(left.name, right.name) || firstFrequency(left) - firstFrequency(right));
    group.child_count = group.children.length;
    group.running_count = group.children.filter((row) => row.processing_state === 'RUNNING').length;
    group.alias_lists = [...new Map(group.children.filter((row) => row.alias_list_name).map((row) => [
      String(row.alias_list_id || row.alias_list_name), { id: row.alias_list_id, name: row.alias_list_name }
    ])).values()];
    group.protocol_labels = [...new Set(group.children.map((row) =>
      row.protocol_label || protocolFamily(row) || 'Unknown protocol'))]
      .sort(compareText);
    return group;
  }).sort((left, right) => {
    if (left.system_name === 'Other channels') return 1;
    if (right.system_name === 'Other channels') return -1;
    return compareText(left.system_name, right.system_name);
  });
}

function radioDirectoryLiveState(row) {
  if (row.processing_state !== 'RUNNING') {
    return node('span', 'muted radio-directory-live-state', 'Stopped');
  }
  const channelName = row.name || 'channel';
  const link = anchor('Live', href('live', { channel: row.configuration_id }),
    'ui-button ui-button-secondary radio-directory-live-action');
  link.classList.add('ui-button-state-success');
  link.prepend(iconGlyph('icon-play'));
  link.setAttribute('aria-label', `Open ${channelName} in Live; channel is running`);
  link.title = `Open ${channelName} in Live · Running`;
  return link;
}

function radioDirectorySystemMetadata(row) {
  const metadata = node('div', 'radio-directory-system-meta');
  metadata.append(
    node('span', '', row.protocol_label || protocolFamily(row) || 'Unknown protocol'),
    node('span', 'radio-directory-meta-separator', '·'),
    node('span', '', `${number(row.child_count || 0)} ${Number(row.child_count) === 1 ? 'site' : 'sites'}`),
    node('span', 'radio-directory-meta-separator', '·'));
  const aliases = node('span', 'radio-directory-system-aliases');
  aliases.append('Alias List: ', radioDirectoryAliasLists(row));
  metadata.append(aliases);
  return metadata;
}

function radioDirectorySiteRow(row) {
  const site = node('div', 'radio-directory-site-row');
  const identity = node('div', 'radio-directory-item-identity');
  const name = anchor(row.name || 'Unnamed site', href('channel', {
    configuration_id: row.configuration_id
  }), 'channel-name-link');
  identity.append(channelOriginName(name, row), node('span', 'channel-row-context',
    row.site || row.site_name || 'Site not identified'));
  const frequencies = node('span', 'radio-directory-frequency-list',
    channelAdminFrequencyList(row.frequencies_hz) || 'No frequencies configured');
  site.append(identity, frequencies, radioDirectoryLiveState(row));
  return site;
}

function radioDirectorySystemCard(row) {
  const card = node('article', 'ui-surface radio-directory-system-card');
  const header = node('header', 'radio-directory-system-header');
  const identity = node('div', 'radio-directory-system-identity');
  const heading = node('h3');
  heading.append(radioSystemLink(row.entity_ref, radioSystemDisplayName(row) || 'Trunked system'));
  identity.append(heading, radioDirectorySystemMetadata(row));
  const headingGroup = node('div', 'radio-directory-system-heading');
  headingGroup.append(uiIconTile('icon-trunked'), identity);
  const total = Number(row.child_count || row.children?.length || 0);
  const running = Number(row.running_count || 0);
  const statusLabel = running === total && total > 0 ? `${number(running)} running` :
    running > 0 ? `${number(running)} of ${number(total)} running` : 'Stopped';
  header.append(headingGroup, uiStatus(statusLabel, running > 0 ? 'success' : 'neutral'));
  const sites = node('div', 'radio-directory-site-list');
  (row.children || []).forEach((channel) => sites.append(radioDirectorySiteRow(channel)));
  card.append(header, sites);
  return card;
}

function radioDirectoryConventionalRow(row) {
  const channel = node('div', 'radio-directory-site-row radio-directory-conventional-row');
  const identity = node('div', 'radio-directory-item-identity');
  identity.append(anchor(row.name || 'Unnamed channel', href('channel', {
    configuration_id: row.configuration_id
  }), 'channel-name-link'), node('span', 'channel-row-context', row.site || row.site_name || 'Site not specified'));
  const aliases = node('span', 'radio-directory-channel-alias');
  aliases.append('Alias List: ', aliasListLink(row.alias_list_name, row.alias_list_id) || '—');
  identity.append(aliases);
  const technical = node('span', 'radio-directory-channel-technical');
  technical.append(node('span', 'radio-directory-frequency-list',
    channelAdminFrequencyList(row.frequencies_hz) || 'No frequency'),
    node('span', 'radio-directory-meta-separator', '·'),
    node('span', '', row.protocol_label || protocolFamily(row) || 'Unknown protocol'));
  channel.append(identity, technical, radioDirectoryLiveState(row));
  return channel;
}

function radioDirectoryConventionalSystemCard(row) {
  const card = node('article', 'ui-surface radio-directory-system-card radio-directory-conventional-card');
  const header = node('header', 'radio-directory-system-header');
  const identity = node('div', 'radio-directory-system-identity');
  identity.append(node('h3', '', row.system_name || 'Other channels'));
  const metadata = node('div', 'radio-directory-system-meta');
  metadata.append(
    node('span', '', `${number(row.child_count || 0)} ${Number(row.child_count) === 1 ? 'channel' : 'channels'}`),
    node('span', 'radio-directory-meta-separator', '·'),
    node('span', '', (row.protocol_labels || []).join(', ') || 'Unknown protocol'),
    node('span', 'radio-directory-meta-separator', '·'));
  const aliases = node('span', 'radio-directory-system-aliases');
  aliases.append(`${(row.alias_lists || []).length === 1 ? 'Alias List' : 'Alias Lists'}: `,
    radioDirectoryAliasLists(row));
  metadata.append(aliases);
  identity.append(metadata);
  const headingGroup = node('div', 'radio-directory-system-heading');
  headingGroup.append(uiIconTile('icon-conventional', 'secondary'), identity);
  const total = Number(row.child_count || row.children?.length || 0);
  const running = Number(row.running_count || 0);
  const statusLabel = running === total && total > 0 ? `${number(running)} running` :
    running > 0 ? `${number(running)} of ${number(total)} running` : 'Stopped';
  header.append(headingGroup, uiStatus(statusLabel, running > 0 ? 'success' : 'neutral'));
  const channels = node('div', 'radio-directory-site-list');
  (row.children || []).forEach((channel) => channels.append(radioDirectoryConventionalRow(channel)));
  card.append(header, channels);
  return card;
}

function radioDirectoryCardSection(title, rows, kind, emptyText, summary = null) {
  const sectionElement = node('section', 'radio-directory-section');
  const header = node('header', 'radio-directory-section-header');
  const countLabel = summary || `${number(rows.length)} ${rows.length === 1 ? 'system' : 'systems'} shown`;
  header.append(node('h2', '', title), node('span', 'muted', countLabel));
  const grid = node('div', 'radio-directory-system-grid');
  if (rows.length) rows.forEach((row) => grid.append(kind === 'conventional' ?
    radioDirectoryConventionalSystemCard(row) : radioDirectorySystemCard(row)));
  else grid.append(node('div', 'empty radio-directory-empty', emptyText));
  sectionElement.append(header, grid);
  return sectionElement;
}

function radioDirectoryPerspectiveControl(activeView) {
  const control = uiSegmentedControl([
    { value: 'systems', label: 'Systems & channels' },
    { value: 'coverage', label: 'Alias inventory' }
  ], activeView, (value) => navigateTo(href('dashboard', value === 'coverage' ?
    { tab: 'health', directory_view: 'coverage' } : { tab: 'health' })));
  control.classList.add('radio-directory-perspective');
  control.setAttribute('aria-label', 'Radio Directory view');
  return control;
}

function radioDirectoryEmbeddedPanel(view, directory) {
  const body = node('div', 'radio-directory-panel-body');
  body.append(radioDirectoryPerspectiveControl(view), directory);
  return section('Radio directory', body);
}

function renderNestedRadioDirectory(renderContext) {
  if (route.get('directory_view') === 'coverage') return renderAliasCoverageDirectory(renderContext, true);
  const loading = createAsyncSection('Radio Directory', {
    bare: true,
    loadingMessage: 'Loading radio systems and channels…',
    errorMessage: 'The radio directory could not be loaded.'
  });
  content.append(radioDirectoryEmbeddedPanel('systems', loading.element));

  const loadDirectory = async (options = {}) => {
    const [catalog, systems] = await Promise.all([
      requestChannelConfigurationJson('/api/v1/channel-catalog', { csrf: false, ...options }),
      apiPage('/api/v1/radio-systems', { limit: 25, includeChannelPreview: true }, options)
    ]);
    return { catalog, systems };
  };

  return loading.load(() => loadDirectory(), (initial) => {
    let directory = initial;
    const wrapper = node('div', 'channel-admin-catalog radio-directory-local ui-catalog data-workspace');
    wrapper.dataset.uiDensity = 'compact';
    const summaryHost = node('div');
    const toolbar = node('div', 'channel-admin-toolbar ui-catalog-toolbar');
    const searchWrap = node('label', 'ui-search');
    searchWrap.append(iconGlyph('icon-search'));
    const search = node('input', 'ui-input');
    search.type = 'search';
    search.placeholder = 'Search systems, sites, channels, frequencies, protocols, or alias lists';
    search.setAttribute('aria-label', search.placeholder);
    searchWrap.append(search);
    let activeView = 'running';
    const filters = uiSegmentedControl([
      { value: 'running', label: 'Running' },
      { value: 'stopped', label: 'Stopped' },
      { value: 'all', label: 'All' }
    ], activeView, (value) => { activeView = value; draw(); });
    filters.setAttribute('aria-label', 'Filter radio directory');
    const exportLink = exportCsvLink('channels');
    const refresh = uiActionButton('', 'icon-refresh', () => renderDashboard(),
      'ui-button ui-button-secondary ui-icon-button');
    refresh.title = 'Refresh radio directory';
    refresh.setAttribute('aria-label', refresh.title);
    toolbar.append(searchWrap, filters, exportLink, refresh);
    const directoryHost = node('div', 'radio-directory-content');

    const matches = (row, term) => !term || [row.system_name, row.system, row.site_name, row.site,
      row.name, row.protocol, row.protocol_label, row.alias_list_name,
      ...(Array.isArray(row.alias_lists) ? row.alias_lists.map((entry) => entry.name) : []),
      channelAdminFrequencyList(row.frequencies_hz)]
      .some((value) => String(value || '').toLowerCase().includes(term));
    const draw = () => {
      const term = search.value.trim().toLowerCase();
      const matchesState = (row) => activeView === 'all' ||
        activeView === 'running' && row.processing_state === 'RUNNING' ||
        activeView === 'stopped' && row.processing_state !== 'RUNNING';
      const trunkedSystems = [];
      radioDirectoryTrunkedGroups(directory.catalog, directory.systems).forEach((parent) => {
        const parentMatches = matches(parent, term);
        const children = parent.children.filter((row) => matchesState(row) && (parentMatches || matches(row, term)));
        if (children.length) {
          trunkedSystems.push({ ...parent, children, child_count: children.length,
            running_count: children.filter((row) => row.processing_state === 'RUNNING').length });
        }
      });
      const conventionalRows = (directory.catalog.channels || []).filter((row) =>
        String(row.channel_kind || '').toUpperCase() === 'CONVENTIONAL' && matchesState(row) && matches(row, term));
      const conventionalSystems = radioDirectoryConventionalGroups(conventionalRows);
      summaryHost.replaceChildren(channelSummaryCards(directory.catalog, false));
      directoryHost.replaceChildren(
        radioDirectoryCardSection('Trunked Systems', trunkedSystems, 'system',
          'No trunked systems or sites match this search'),
        radioDirectoryCardSection('Conventional Channels', conventionalSystems, 'conventional',
          'No conventional channels match this search',
          `${number(conventionalSystems.length)} ${conventionalSystems.length === 1 ? 'system' : 'systems'} · ` +
          `${number(conventionalRows.length)} ${conventionalRows.length === 1 ? 'channel' : 'channels'} shown`)
      );
    };
    search.addEventListener('input', draw);
    wrapper.append(summaryHost, toolbar, directoryHost);
    draw();

    let refreshInFlight = false;
    pageInterval(async () => {
      if (refreshInFlight || !renderIsCurrent(renderContext) || !wrapper.isConnected || document.hidden) return;
      refreshInFlight = true;
      try {
        directory = await loadDirectory({ page: false });
        draw();
      } catch (_) { /* Preserve the last confirmed directory until the next refresh. */ }
      finally { refreshInFlight = false; }
    }, 5_000);
    return wrapper;
  }, renderContext);
}

async function renderModernChannelCatalog(renderContext) {
  const loading = createAsyncSection('Channels', {
    loadingMessage: 'Loading channel configuration…',
    errorMessage: 'Channel configuration could not be loaded.'
  });
  loading.element.classList.add('channel-catalog-section');
  if (!beginPage(renderContext, pageHeader('Channels',
    'Create, configure, order, start, and stop receiver channels'), loading.element)) return;
  await loading.load(async () => {
    const [catalog, protocols, options] = await Promise.all([
      requestChannelConfigurationJson('/api/v1/admin/channels', { csrf: false }),
      requestChannelConfigurationJson('/api/v1/admin/channels/protocols', { csrf: false }),
      requestChannelConfigurationJson('/api/v1/admin/channels/options', { csrf: false })
    ]);
    return { catalog, protocols, options };
  }, ({ catalog, protocols, options }) => {
    const selected = new Set();
    const state = { revision: Number(catalog.revision), catalog, visibleRows: [], selectionAnchor: null };
    const wrapper = node('div', 'channel-admin-catalog ui-catalog editor-workspace');
    wrapper.dataset.uiDensity = 'comfortable';
    const summaryHost = node('div');
    summaryHost.append(channelSummaryCards(catalog, true));
    const toolbar = node('div', 'channel-admin-toolbar ui-catalog-toolbar');
    const searchWrap = node('label', 'ui-search');
    searchWrap.append(iconGlyph('icon-search'));
    const search = node('input', 'ui-input');
    search.type = 'search';
    search.placeholder = 'Search channels, systems, protocols, frequencies, or alias lists';
    search.setAttribute('aria-label', search.placeholder);
    searchWrap.append(search);
    let activeStatus = 'all';
    let activeCatalogView = 'grouped';
    let draw = () => {};
    const viewToggle = uiSegmentedControl([
      { value: 'grouped', label: 'Grouped' },
      { value: 'auto-start', label: 'Startup order' }
    ], activeCatalogView, (value) => {
      activeCatalogView = value;
      draw({ rebuild: true });
    });
    viewToggle.setAttribute('aria-label', 'Channel table view');
    const statusFilter = uiSelect([
      { value: 'all', label: 'All statuses' },
      { value: 'running', label: 'Running' },
      { value: 'stopped', label: 'Stopped' },
      { value: 'auto-start', label: 'Auto-start' }
    ], activeStatus);
    statusFilter.classList.add('channel-status-filter');
    statusFilter.setAttribute('aria-label', 'Filter channels by status');
    statusFilter.addEventListener('change', () => {
      activeStatus = statusFilter.value;
      draw();
    });
    const statusHost = node('div', 'channel-admin-status');
    statusHost.setAttribute('role', 'status');
    statusHost.setAttribute('aria-live', 'polite');
    const newChannelButton = uiActionButton('New channel', 'icon-plus', () =>
      openChannelEditorModal('create', null, { protocols, options }), 'ui-button ui-button-primary');
    toolbar.append(newChannelButton);
    const findSystemsButton = capabilityAllowed(ACCESS_CAPABILITIES.ADMIN_TUNERS) ? uiActionButton('Find Trunked Systems',
      'icon-scan-search', () => openSpectrumSearchWizard({ node, openReadOnlyModal, requestJson, uiActionButton, iconButton,
        uiSelect, uiSelectFrame, uiPill, formField, anchor, href, entityRefHref, channelMHz, hex,
        channelEditorControl, channelEditorFieldValue, protocols }, {
        prepareReceiver: async (tuner) => {
          const count = Math.max(0, Number(tuner.channel_count) || 0);
          const stop = count > 0 || /channel|serving/i.test(String(tuner.reason || ''));
          const name = tuner.name || 'This receiver';
          const message = stop ? `${name} is running ${count ? `${count} active channel${count === 1 ? '' : 's'}` :
            'active channels'}. Stopping them will end any calls in progress; those calls will not resume. ` +
            'VCE will restart the same configured channels when you finish or close the search.' :
            `${name} has Lock center on. VCE will unlock it temporarily and restore the lock when you finish or close the search.`;
          if (!await confirmAction(message, { title: stop ? 'Stop channels for this search?' :
            'Unlock center temporarily?', confirmLabel: stop ? 'Stop channels and search' : 'Unlock and search',
            cancelLabel: 'Cancel', tone: 'primary' })) return null;
          return requestJson(`/api/v1/admin/tuners/${encodeURIComponent(tuner.id)}/browse`, {
            method: 'POST', body: { takeover: true }, page: false
          });
        }
      }), 'ui-button ui-button-secondary') : null;
    if (findSystemsButton) toolbar.append(findSystemsButton);
    const setupGuide = createChannelSetupGuide({ ui: { node, openReadOnlyModal }, account: accessSession.username,
      dismissalScope: accessSession.guideDismissalScope,
      channels: () => state.catalog.channels,
      isCurrent: () => renderIsCurrent(renderContext) && wrapper.isConnected,
      canPresent: () => !activeReadOnlyModal,
      loadTuners: () => requestJson('/api/v1/admin/spectrum-search/catalog', { csrf: false }),
      newChannelButton, findSystemsButton });
    const exportLink = exportCsvLink('channels');
    const refresh = uiActionButton('', 'icon-refresh', () => renderChannelSetup(), 'ui-button ui-icon-button');
    refresh.setAttribute('aria-label', 'Refresh channels');
    refresh.title = 'Refresh channels';
    toolbar.append(searchWrap, viewToggle, uiSelectFrame(statusFilter, 'channel-status-filter-frame'),
      exportLink, refresh, statusHost);

    const tableHost = node('div', 'channel-catalog-table-host');
    const tableController = {};
    const selectedBar = node('div', 'channel-selection-bar ui-selection-bar');
    selectedBar.hidden = true;
    const selectedSummary = node('strong');
    const hiddenSummary = node('span', 'muted');
    let enableAutoStart = null;
    let disableAutoStart = null;
    let cloneSelected = null;
    let selectAll = null;
    const updateSelection = () => {
      const visibleIds = new Set(state.visibleRows.map((row) => row.configuration_id));
      const visibleSelected = [...selected].filter((id) => visibleIds.has(id)).length;
      const hiddenSelected = selected.size - visibleSelected;
      selectedBar.hidden = selected.size === 0;
      selectedSummary.textContent = `${selected.size} selected`;
      hiddenSummary.textContent = hiddenSelected ? `${hiddenSelected} outside this filter` : '';
      const selectedRows = (state.catalog.channels || []).filter((row) => selected.has(row.configuration_id));
      if (enableAutoStart) enableAutoStart.disabled = selectedRows.length > 0 &&
        selectedRows.every((row) => row.auto_start_order != null);
      if (disableAutoStart) disableAutoStart.disabled = selectedRows.length > 0 &&
        selectedRows.every((row) => row.auto_start_order == null);
      if (cloneSelected) {
        cloneSelected.disabled = selectedRows.some((row) => row.remote_origin?.remote === true);
        cloneSelected.title = cloneSelected.disabled ? 'Remote channels cannot be cloned.' : '';
      }
      if (selectAll) {
        selectAll.checked = state.visibleRows.length > 0 && visibleSelected === state.visibleRows.length;
        selectAll.indeterminate = visibleSelected > 0 && visibleSelected < state.visibleRows.length;
      }
    };
    const renderSelectionHeader = () => {
      const checkbox = node('input', 'ui-selection-check');
      checkbox.type = 'checkbox';
      checkbox.setAttribute('aria-label', 'Select all matching channels');
      checkbox.addEventListener('change', () => {
        state.selectionAnchor = null;
        state.visibleRows.forEach((row) => checkbox.checked ? selected.add(row.configuration_id) :
          selected.delete(row.configuration_id));
        tableHost.querySelectorAll('tbody .ui-selection-check').forEach((rowCheckbox) => {
          rowCheckbox.checked = checkbox.checked;
        });
        tableHost.querySelectorAll('tbody tr[data-id]').forEach((row) =>
          row.classList.toggle('selected', checkbox.checked));
        updateSelection();
      });
      selectAll = checkbox;
      updateSelection();
      return checkbox;
    };
    const clearSelection = uiActionButton('Clear', null, () => {
      selected.clear();
      state.selectionAnchor = null;
      tableHost.querySelectorAll('.ui-selection-check').forEach((checkbox) => { checkbox.checked = false; });
      tableHost.querySelectorAll('tr.selected').forEach((row) => row.classList.remove('selected'));
      updateSelection();
    });
    let autoStartVerificationNotice = null;
    const applyCatalog = (refreshed) => {
      const revision = Number(refreshed.revision);
      if (!Number.isFinite(revision) || revision < state.revision) return false;
      state.revision = revision;
      state.catalog = refreshed;
      if (refreshed.channels?.length) setupGuide.close();
      const available = new Set((refreshed.channels || []).map((row) => row.configuration_id));
      [...selected].filter((id) => !available.has(id)).forEach((id) => selected.delete(id));
      summaryHost.replaceChildren(channelSummaryCards(refreshed, true));
      if (autoStartVerificationNotice) {
        if (statusHost.firstElementChild === autoStartVerificationNotice) statusHost.replaceChildren();
        autoStartVerificationNotice = null;
      }
      return true;
    };
    let autoStartMoveInFlight = false;
    let orderMoveHighlightSequence = 0;
    const highlightedOrderRows = new Map();
    const highlightOrderMoveRow = (configurationId) => {
      const highlightSequence = String(++orderMoveHighlightSequence);
      highlightedOrderRows.set(configurationId, highlightSequence);
      const row = tableHost.querySelector(`tr[data-id="${CSS.escape(configurationId)}"]`);
      if (row) {
        row.classList.remove('channel-order-row-moved');
        void row.offsetWidth;
        row.classList.add('channel-order-row-moved');
      }
      pageTimeout(() => {
        if (highlightedOrderRows.get(configurationId) !== highlightSequence) return;
        highlightedOrderRows.delete(configurationId);
        tableHost.querySelector(`tr[data-id="${CSS.escape(configurationId)}"]`)
          ?.classList.remove('channel-order-row-moved');
      }, 1_000);
    };
    const restoreOrderMovePosition = (configurationId, direction, scrollPosition, restoreFocus, highlightRow) => {
      window.requestAnimationFrame(() => {
        if (!wrapper.isConnected) return;
        window.scrollTo(scrollPosition.x, scrollPosition.y);
        const row = tableHost.querySelector(`tr[data-id="${CSS.escape(configurationId)}"]`);
        if (highlightRow) highlightOrderMoveRow(configurationId);
        if (!restoreFocus) return;
        const requested = row?.querySelector(`[data-channel-order-direction="${direction}"]:not(:disabled)`);
        const fallback = row?.querySelector('[data-channel-order-direction]:not(:disabled)');
        (requested || fallback)?.focus({ preventScroll: true });
        window.scrollTo(scrollPosition.x, scrollPosition.y);
      });
    };
    const moveAutoStart = async (configurationId, direction, shouldRestoreFocus) => {
      if (autoStartMoveInFlight) throw new Error('Another startup-order change is still being saved');
      autoStartMoveInFlight = true;
      const expectedRevision = state.revision;
      const catalogBeforeMove = state.catalog;
      try {
        await channelAdminMutation(
          `/api/v1/admin/channels/${encodeURIComponent(configurationId)}/auto-start/move`,
          { method: 'POST', body: { revision: expectedRevision, direction } }, statusHost,
          async (result) => {
            const committedRevision = Number(result.revision);
            if (!Number.isFinite(committedRevision)) throw new Error('The receiver returned an invalid revision');
            state.revision = Math.max(state.revision, committedRevision);
            let refreshed = null;
            let verificationPending = false;
            try {
              refreshed = await requestChannelConfigurationJson('/api/v1/admin/channels', { csrf: false });
              const confirmedRevision = Number(refreshed.revision);
              if (!Number.isFinite(confirmedRevision) || confirmedRevision < committedRevision) {
                throw new Error('The refreshed channel catalog is older than the saved startup order');
              }
            } catch (_) {
              const alreadyConfirmed = Number(state.catalog.revision) >= committedRevision;
              refreshed = alreadyConfirmed ? state.catalog :
                channelCatalogAfterAutoStartMove(catalogBeforeMove, configurationId, direction);
              refreshed.revision = Math.max(Number(refreshed.revision) || 0, committedRevision);
              verificationPending = !alreadyConfirmed;
            }
            const previousOrder = catalogBeforeMove.channels?.find((row) =>
              row.configuration_id === configurationId)?.auto_start_order ?? null;
            const confirmedOrder = refreshed?.channels?.find((row) =>
              row.configuration_id === configurationId)?.auto_start_order ?? null;
            const orderChanged = previousOrder !== confirmedOrder;
            const scrollPosition = { x: window.scrollX, y: window.scrollY };
            const restoreFocus = shouldRestoreFocus?.() === true;
            if (refreshed && applyCatalog(refreshed)) draw();
            if (verificationPending) {
              autoStartVerificationNotice = uiStatus('Order saved; live verification is pending', 'warning');
              statusHost.replaceChildren(autoStartVerificationNotice);
            }
            restoreOrderMovePosition(configurationId, direction, scrollPosition, restoreFocus, orderChanged);
          }
        );
      } finally {
        autoStartMoveInFlight = false;
      }
    };
    const action = (label, icon, actionName, confirmMessage = null, danger = false) =>
      uiActionButton(label, icon, async () => {
        const ids = [...selected];
        if (!ids.length) return;
        if (confirmMessage && !await confirmAction(confirmMessage.replace('{count}', String(ids.length)), {
          title: 'Delete selected channels', confirmLabel: `Delete ${ids.length} ${ids.length === 1 ? 'channel' : 'channels'}`
        })) return;
        if (!statusHost.isConnected) return;
        try {
          await channelAdminMutation('/api/v1/admin/channels/actions', {
            method: 'POST', body: { revision: state.revision, action: actionName, configuration_ids: ids }
          }, statusHost);
        } catch (_) { /* The inline error remains actionable. */ }
      }, `ui-button ${danger ? 'ui-button-danger' : 'ui-button-secondary'}`);
    enableAutoStart = action('Enable auto-start', 'icon-plus', 'ENABLE_AUTO_START');
    disableAutoStart = action('Disable auto-start', 'icon-clear-queue', 'DISABLE_AUTO_START');
    cloneSelected = action('Clone', 'icon-copy', 'CLONE');
    selectedBar.append(selectedSummary, hiddenSummary,
      action('Start', 'icon-play', 'START'), action('Stop', 'icon-stop', 'STOP'),
      enableAutoStart, disableAutoStart, cloneSelected,
      action('Delete', 'icon-trash', 'DELETE', 'Delete {count} selected channel(s)?', true), clearSelection);

    const filteredRows = () => {
      const term = search.value.trim().toLowerCase();
      const rows = (state.catalog.channels || []).filter((row) =>
        (activeStatus === 'all' || activeStatus === 'running' && row.processing_state === 'RUNNING' ||
          activeStatus === 'stopped' && row.processing_state !== 'RUNNING' ||
          activeStatus === 'auto-start' && row.auto_start_order != null) &&
        (!term || [row.name, row.system, row.site, row.protocol_label,
          channelProtocolGroup(row).label, row.alias_list_name,
          channelAdminFrequencyList(row.frequencies_hz)].some((value) =>
            String(value || '').toLowerCase().includes(term))));
      return rows.sort(activeCatalogView === 'auto-start' ? channelAutoStartOrder : channelProtocolOrder);
    };
    let channelTable = null;
    const renderChannelTable = () => {
      channelTable = table(state.visibleRows,
        channelAdminColumns(selected, state, updateSelection, renderSelectionHeader,
          moveAutoStart),
        'No channels match this view', {
          type: 'channel-catalog-admin-v2',
          sortable: false, controller: tableController,
          ...(activeCatalogView === 'grouped' ? {
            rowGroup: channelProtocolGroup, rowGroupNoun: 'channel',
            revealRowGroups: () => Boolean(search.value.trim())
          } : {}),
          rowKey: (row) => row.configuration_id,
          rowClass: (row) => [
            selected.has(row.configuration_id) ? 'selected' : '',
            highlightedOrderRows.has(row.configuration_id) ? 'channel-order-row-moved' : ''
          ].filter(Boolean).join(' '),
          tableClass: 'channel-catalog-table', wrapperClass: 'channel-catalog-table-wrap',
          mobileCards: true,
          layoutMenuHost: toolbar,
          wrapper: channelTable || undefined
        });
      if (!channelTable.parentElement) tableHost.append(channelTable);
    };
    draw = ({ rebuild = false } = {}) => {
      state.visibleRows = filteredRows();
      if (rebuild || !tableController.reconcileRows) renderChannelTable();
      else tableController.reconcileRows(state.visibleRows);
      updateSelection();
    };
    search.addEventListener('input', () => draw());
    draw({ rebuild: true });
    wrapper.append(summaryHost, toolbar, selectedBar, tableHost);
    updateSelection();
    pageTimeout(() => { void setupGuide.refresh(); }, 0);

    let refreshInFlight = false;
    pageInterval(async () => {
      if (refreshInFlight || autoStartMoveInFlight || !renderIsCurrent(renderContext) ||
          !wrapper.isConnected || document.hidden) return;
      refreshInFlight = true;
      try {
        const refreshed = await requestJson('/api/v1/admin/channels', { csrf: false });
        if (applyCatalog(refreshed)) { draw(); void setupGuide.refresh(); }
      } catch (_) { /* Preserve the last confirmed catalog; explicit actions still surface errors. */ }
      finally { refreshInFlight = false; }
    }, 5_000);
    const requestedChannel = route.get('channel');
    if (requestedChannel && state.catalog.channels?.some((row) =>
      row.configuration_id === requestedChannel && row.editable !== false)) {
      route.delete('channel');
      window.history.replaceState({}, '', currentHref());
      queueMicrotask(() => openChannelEditorModal('edit', requestedChannel, { protocols, options }));
    }
    return wrapper;
  }, renderContext);
}

function channelValueAt(value, path) {
  return String(path || '').split('.').reduce((current, key) => current?.[key], value);
}

function channelMHz(value) {
  return value == null || value === '' ? '' : String(Number(value) / 1_000_000);
}

function channelCreationProtocolLabel(profile) {
  return profile?.id === 'p25-phase2' ? 'P25 Phase 2 TDMA Control Channel (Uncommon)' :
    (profile?.label || profile?.id || 'Protocol');
}

function channelDefaultAliasListName(aliasFamily) {
  const family = String(aliasFamily || '').trim().toUpperCase();
  if (!family) return '';
  return family === 'NBFM' ? 'Default Analog' : `Default ${family}`;
}

function channelCreationDefaults(channel, profile, options) {
  const defaultName = channelDefaultAliasListName(profile?.alias_family).toLowerCase();
  const defaultAliasList = (options?.alias_lists || []).find((entry) =>
    entry.family === profile?.alias_family &&
    String(entry.name || '').trim().toLowerCase() === defaultName);
  return defaultAliasList ? { ...channel, alias_list_id: defaultAliasList.id } : channel;
}

function channelCreationPrefill(channel, profile, initialChannel) {
  if (initialChannel?.protocol_id !== profile.id) return channel;
  return { ...channel, source: { ...channel.source, ...initialChannel.source },
    settings: { ...channel.settings, ...initialChannel.settings } };
}

function channelFieldOptions(field, profile, options) {
  if (Array.isArray(field.options)) return field.options;
  if (field.path === 'alias_list_id') return (options.alias_lists || [])
    .filter((entry) => entry.family === profile.alias_family)
    .map((entry) => ({ value: entry.id, label: entry.name }));
  if (field.path === 'source.preferred_tuner') return (options.tuners || [])
    .map((value) => ({ value, label: value }));
  const outputLabels = {
    CALL_EVENT: 'Call events', DECODED_MESSAGE: 'Decoded messages',
    TRAFFIC_CALL_EVENT: 'Traffic-channel call events', TRAFFIC_DECODED_MESSAGE: 'Traffic decoded messages',
    BASEBAND: 'Baseband I/Q', DEMODULATED_BIT_STREAM: 'Demodulated bit stream',
    MBE_CALL_SEQUENCE: 'MBE call sequence', TRAFFIC_BASEBAND: 'Traffic baseband I/Q',
    TRAFFIC_DEMODULATED_BIT_STREAM: 'Traffic demodulated bit stream',
    TRAFFIC_MBE_CALL_SEQUENCE: 'Traffic MBE call sequence'
  };
  if (field.path === 'event_logs') return (profile.event_logs || [])
    .map((value) => ({ value, label: outputLabels[value] || semanticLabel(value) }));
  if (field.path === 'recorders') return (profile.recorders || [])
    .map((value) => ({ value, label: outputLabels[value] || semanticLabel(value) }));
  if (field.path === 'auxiliary_decoders') return (profile.auxiliary_decoders || [])
    .map((value) => ({ value, label: value }));
  return [];
}

function channelListEditor(field, values) {
  const editor = node('div', 'ui-repeater channel-list-editor');
  const rows = node('div', 'ui-repeater-rows');
  const add = uiActionButton('Add frequency', 'icon-plus', () => {
    append('');
    editor.dispatchEvent(new Event('change', { bubbles: true }));
  });
  const append = (value) => {
    const row = node('div', 'ui-repeater-row');
    const input = node('input', 'ui-input');
    input.type = 'number';
    input.step = '0.000001';
    input.min = '0.000001';
    input.placeholder = '851.012500';
    input.value = value == null || value === '' ? '' : channelMHz(value);
    input.setAttribute('aria-label', `${field.label} in MHz`);
    const unit = node('span', 'ui-input-unit', 'MHz');
    const remove = uiActionButton('', 'icon-trash', () => {
      row.remove();
      add.disabled = false;
      editor.dispatchEvent(new Event('change', { bubbles: true }));
    }, 'ui-button ui-icon-button ui-button-danger-quiet');
    remove.setAttribute('aria-label', 'Remove frequency');
    row.append(input, unit, remove);
    rows.append(row);
    const maximum = Number(field.maximum_items || 256);
    add.disabled = rows.children.length >= maximum;
  };
  (values || []).forEach(append);
  if (!rows.children.length) append('');
  editor.append(rows, add);
  return editor;
}

function channelMapEditor(field, values) {
  const editor = node('div', 'ui-repeater channel-map-editor');
  editor.classList.toggle('channel-map-with-uplink', Boolean(field.show_uplink));
  const header = node('div', 'channel-map-header');
  header.append(node('span', '', field.number_label || 'Channel'), node('span', '', 'Downlink MHz'));
  if (field.show_uplink) header.append(node('span', '', 'Uplink MHz'));
  header.append(node('span'));
  const rows = node('div', 'ui-repeater-rows');
  const labeledInput = (label, input) => {
    const wrapper = node('label', 'channel-map-field');
    wrapper.append(node('span', 'channel-map-mobile-label', label), input);
    return wrapper;
  };
  const add = uiActionButton('Add mapping', 'icon-plus', () => {
    append({});
    editor.dispatchEvent(new Event('change', { bubbles: true }));
  },
    'ui-button ui-button-secondary');
  const append = (value = {}) => {
    const row = node('div', 'ui-repeater-row channel-map-row');
    const channel = node('input', 'ui-input');
    channel.type = 'number';
    channel.step = '1';
    channel.min = String(field.number_minimum ?? 1);
    if (field.number_maximum != null) channel.max = String(field.number_maximum);
    channel.value = value.number ?? '';
    channel.setAttribute('aria-label', field.number_label || 'Channel number');
    const downlink = node('input', 'ui-input');
    downlink.type = 'number';
    downlink.step = '0.000001';
    downlink.min = '0.000001';
    downlink.value = value.downlink_hz ? channelMHz(value.downlink_hz) : '';
    downlink.setAttribute('aria-label', 'Downlink frequency in MHz');
    row.append(labeledInput(field.number_label || 'Channel', channel), labeledInput('Downlink MHz', downlink));
    if (field.show_uplink) {
      const uplink = node('input', 'ui-input');
      uplink.type = 'number';
      uplink.step = '0.000001';
      uplink.min = '0.000001';
      uplink.value = value.uplink_hz ? channelMHz(value.uplink_hz) : '';
      uplink.setAttribute('aria-label', 'Uplink frequency in MHz');
      row.append(labeledInput('Uplink MHz', uplink));
    }
    const remove = uiActionButton('', 'icon-trash', () => {
      row.remove();
      editor.dispatchEvent(new Event('change', { bubbles: true }));
    },
      'ui-button ui-icon-button ui-button-danger-quiet');
    remove.setAttribute('aria-label', 'Remove mapping');
    row.append(remove);
    rows.append(row);
  };
  (values || []).forEach(append);
  editor.append(header, rows, add);
  if (field.clipboard) {
    editor.append(node('small', 'ui-field-hint',
      `Paste is supported directly into each ${field.number_label || 'channel'} or frequency cell.`));
  }
  return editor;
}

const CHANNEL_ENCRYPTED_SKIP_PATH = 'settings.ignore_encrypted_calls';
const CHANNEL_ENCRYPTED_SKIP_LOCK_HELP =
  'Encrypted calls are processed while voice decryption is loaded. Your saved performance preference is preserved.';

function channelEncryptedCallSkipLocked(field, protocolCatalog) {
  return field?.path === CHANNEL_ENCRYPTED_SKIP_PATH && protocolCatalog?.voice_decryption_module_loaded === true;
}

function channelEditorControl(field, profile, options, channel, protocolCatalog) {
  const value = channelValueAt(channel, field.path);
  let control;
  if (field.type === 'boolean') {
    control = uiToggle(Boolean(value ?? field.default), field.label);
  } else if (field.type === 'enum' || field.type === 'dynamic_select') {
    const entries = [...channelFieldOptions(field, profile, options)];
    if (field.type === 'dynamic_select' && value != null && value !== '' &&
        !entries.some((entry) => String(entry.value) === String(value))) {
      entries.unshift({ value, label: `Current (unavailable): ${value}` });
    }
    control = uiSelect(entries, value ?? field.default ?? '', field.required !== true);
  } else if (field.type === 'multi_select') {
    const selected = new Set(value || []);
    control = node('fieldset', 'channel-multi-select');
    control.setAttribute('aria-label', field.label);
    channelFieldOptions(field, profile, options).forEach((entry) => {
      const toggle = uiToggle(selected.has(entry.value), entry.label);
      const input = toggle.querySelector('input');
      input.value = entry.value;
      const option = node('div', 'channel-output-option ui-toggle-field ui-toggle-field-compact');
      option.append(node('span', '', entry.label), toggle);
      control.append(option);
    });
    if (!control.children.length) control.append(node('div', 'empty', 'No options for this protocol'));
  } else if (field.type === 'frequency_list') {
    control = channelListEditor(field, value);
  } else if (field.type === 'frequency_map') {
    control = channelMapEditor(field, value);
  } else if (field.type === 'read_only') {
    const empty = value == null || Array.isArray(value) && !value.length ||
      typeof value === 'object' && !Array.isArray(value) && !Object.keys(value).length;
    control = node('div', 'channel-read-only');
    if (empty) control.append(uiPill('Not observed', 'neutral'));
    else if (Array.isArray(value)) value.forEach((entry) =>
      control.append(uiPill(field.path.includes('frequencies') ? `${channelMHz(entry)} MHz` : String(entry), 'blue')));
    else if (typeof value === 'object') Object.entries(value).forEach(([key, entry]) => {
      const item = node('div', 'channel-observed-item');
      item.append(node('span', '', semanticLabel(key)), node('strong', '', String(entry)));
      control.append(item);
    });
    else control.append(node('span', '', String(value)));
  } else if (field.type === 'frequency_select') {
    const frequencies = channelValueAt(channel, 'source.frequencies_hz') || [];
    const entries = frequencies.map((entry) => ({ value: entry, label: `${channelMHz(entry)} MHz` }));
    if (value != null && !entries.some((entry) => String(entry.value) === String(value)))
      entries.unshift({ value, label: `Current: ${channelMHz(value)} MHz` });
    control = uiSelect(entries, value ?? '', true);
  } else {
    control = node('input', 'ui-input');
    control.type = ['integer', 'number', 'frequency', 'frequency_select'].includes(field.type) ? 'number' : 'text';
    control.value = ['frequency', 'frequency_select'].includes(field.type) ? channelMHz(value) :
      (value ?? field.default ?? '');
    if (control.type === 'number') control.step = field.step || (field.type === 'integer' ? '1' : 'any');
    if (field.max_length != null && control.type === 'text') control.maxLength = Number(field.max_length);
    if (field.minimum != null && !['frequency', 'frequency_select'].includes(field.type)) control.min = field.minimum;
    if (field.maximum != null && !['frequency', 'frequency_select'].includes(field.type)) control.max = field.maximum;
  }
  if (field.type !== 'read_only') {
    const dataControl = field.type === 'boolean' ? control.querySelector('input') : control;
    dataControl.dataset.channelPath = field.path;
    dataControl.dataset.channelType = field.type;
    if (field.required === true && 'required' in dataControl) dataControl.required = true;
    if (field.type === 'boolean' && channelEncryptedCallSkipLocked(field, protocolCatalog)) {
      dataControl.dataset.channelPreservedValue = String(Boolean(value ?? field.default));
      setUiToggle(dataControl, false);
      dataControl.disabled = true;
      dataControl.title = CHANNEL_ENCRYPTED_SKIP_LOCK_HELP;
    }
  }
  return control;
}

function channelEditorSectionId(value) {
  const segment = String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return `channel-editor-section-${segment || 'section'}`;
}

function channelEditorSectionPlan(sections) {
  return (Array.isArray(sections) ? sections : []).map((definition) => ({
    definition,
    id: channelEditorSectionId(definition?.id),
    advanced: definition?.id === 'output' && Array.isArray(definition.fields) &&
      definition.fields.length > 0 && definition.fields.every((field) => field?.required !== true)
  }));
}

function channelEditorSectionNavigation(panels, plan) {
  const navigation = node('nav', 'channel-section-navigation ui-section-navigation');
  navigation.setAttribute('aria-label', 'Jump to channel editor section');
  const icons = {
    general: 'icon-edit',
    source: 'icon-tuner',
    protocol: 'icon-conventional',
    output: 'icon-recording'
  };
  plan.forEach(({ definition, id, advanced }) => {
    const link = anchor(definition.label, `#${id}`,
      'channel-section-navigation-link ui-section-navigation-link');
    link.prepend(iconGlyph(icons[definition.id] || 'icon-conventional'));
    link.setAttribute('aria-controls', id);
    if (advanced) link.append(node('small', 'muted', 'Optional'));
    link.addEventListener('click', (event) => {
      event.preventDefault();
      const panel = panels.get(definition.id);
      if (!panel) return;
      const disclosure = panel.closest('details');
      if (disclosure) disclosure.open = true;
      panel.scrollIntoView({ block: 'start' });
      panel.focus({ preventScroll: true });
    });
    navigation.append(link);
  });
  return navigation;
}

function channelEditorSectionDisclosureLayout(stack, groupName) {
  const mobile = window.matchMedia('(max-width: 720px)');
  const disclosures = [...stack.querySelectorAll('details.channel-editor-section-disclosure')];
  let selectedSection = 'general';
  const sync = () => {
    const focusedSection = document.activeElement?.closest('[data-channel-section]')?.dataset.channelSection;
    const selected = disclosures.find((entry) => entry.dataset.channelSection ===
      (focusedSection || selectedSection)) || disclosures[0];
    disclosures.forEach((entry) => entry.removeAttribute('name'));
    disclosures.forEach((entry) => {
      entry.open = mobile.matches ? entry === selected :
        entry.classList.contains('channel-editor-section-primary') || entry.open;
      if (mobile.matches) entry.name = groupName;
    });
  };
  const remember = (event) => {
    if (mobile.matches && disclosures.includes(event.target) && event.target.open) {
      selectedSection = event.target.dataset.channelSection;
    }
  };
  stack.addEventListener('toggle', remember, true);
  mobile.addEventListener('change', sync);
  sync();
  return () => {
    stack.removeEventListener('toggle', remember, true);
    mobile.removeEventListener('change', sync);
  };
}

function channelEditorVisibility(form) {
  form.querySelectorAll('[data-visible-path]').forEach((wrapper) => {
    const source = form.querySelector(`[data-channel-path="${CSS.escape(wrapper.dataset.visiblePath)}"]`);
    const actual = source?.dataset.channelType === 'boolean' ? source.checked : source?.value;
    const expected = JSON.parse(wrapper.dataset.visibleEquals);
    wrapper.hidden = actual !== expected && String(actual) !== String(expected);
  });
}

function channelEditorDependencies(form) {
  channelEditorVisibility(form);
  const preferred = form.querySelector('[data-channel-type="frequency_select"]');
  const frequencies = form.querySelector('[data-channel-type="frequency_list"]');
  if (!(preferred instanceof HTMLSelectElement) || !frequencies) return;
  const current = preferred.value;
  const values = [...frequencies.querySelectorAll('.ui-repeater-row input[type="number"]')]
    .map((input) => input.value.trim()).filter(Boolean)
    .map((value) => Math.round(Number(value) * 1_000_000)).filter(Number.isFinite);
  preferred.replaceChildren();
  const blank = node('option', '', 'None');
  blank.value = '';
  preferred.append(blank);
  values.forEach((value) => {
    const option = node('option', '', `${channelMHz(value)} MHz`);
    option.value = String(value);
    option.selected = String(value) === current;
    preferred.append(option);
  });
  if (current && !values.some((value) => String(value) === current)) preferred.value = '';
}

function channelParseFrequency(value, label, nullable = false) {
  if (String(value).trim() === '' && nullable) return null;
  const mhz = Number(value);
  if (!Number.isFinite(mhz) || mhz <= 0) throw new Error(`${label} must be a positive MHz frequency.`);
  return Math.round(mhz * 1_000_000);
}

function channelEditorFieldValue(control, field) {
  if (field.type === 'boolean') return control.dataset.channelPreservedValue == null ? control.checked :
    control.dataset.channelPreservedValue === 'true';
  if (field.type === 'multi_select') return [...control.querySelectorAll('input:checked')]
    .map((input) => input.value);
  if (field.type === 'frequency_list') {
    const values = [...control.querySelectorAll('.ui-repeater-row input[type="number"]')]
      .map((input) => input.value.trim()).filter(Boolean)
      .map((value) => channelParseFrequency(value, field.label));
    if (field.required && !values.length) throw new Error(`${field.label} requires at least one frequency.`);
    if (field.minimum_items != null && values.length < Number(field.minimum_items))
      throw new Error(`${field.label} requires at least ${field.minimum_items} value(s).`);
    if (field.maximum_items != null && values.length > Number(field.maximum_items))
      throw new Error(`${field.label} allows at most ${field.maximum_items} value(s).`);
    return values;
  }
  if (field.type === 'frequency_map') return [...control.querySelectorAll('.channel-map-row')].map((row, index) => {
    const inputs = row.querySelectorAll('input');
    const channelNumber = Number(inputs[0]?.value);
    const minimum = Number(field.number_minimum ?? 1);
    const maximum = Number(field.number_maximum ?? Number.MAX_SAFE_INTEGER);
    if (!Number.isInteger(channelNumber) || channelNumber < minimum || channelNumber > maximum || !inputs[1]?.value)
      throw new Error(`${field.label} row ${index + 1} needs a valid ${field.number_label || 'channel'} and downlink.`);
    return { number: channelNumber, downlink_hz: channelParseFrequency(inputs[1].value, field.label),
      uplink_hz: field.show_uplink && inputs[2]?.value ? channelParseFrequency(inputs[2].value, field.label) : 0 };
  });
  if (field.type === 'frequency_select') return control.value ? Number(control.value) : null;
  if (field.type === 'frequency')
    return channelParseFrequency(control.value, field.label, field.nullable === true || field.required !== true);
  if (field.type === 'integer') {
    if (control.value === '' && field.nullable) return null;
    const value = Number(control.value);
    if (!Number.isInteger(value)) throw new Error(`${field.label} must be a whole number.`);
    return value;
  }
  if (field.type === 'number') {
    if (control.value === '' && field.nullable) return null;
    const value = Number(control.value);
    if (!Number.isFinite(value)) throw new Error(`${field.label} must be a number.`);
    return value;
  }
  const text = control.value.trim();
  return text || null;
}

function channelIsRemote(channel) {
  return String(channel?.source?.source_type || '').toUpperCase() === 'REMOTE';
}

function channelEditorSections(profile, channel) {
  if (!channelIsRemote(channel)) return profile.sections;
  const applicable = new Set([
    'settings.traffic_channel_pool_size', 'settings.use_bandplan_override',
    'observed.p25_site_identity', 'event_logs'
  ]);
  return profile.sections.map((section) => ({
    ...section,
    label: section.id === 'source' ? 'Remote source' :
      section.id === 'output' ? 'Event logs' : section.label,
    fields: section.id === 'general' ? section.fields :
      section.fields.filter((field) => applicable.has(field.path))
  })).filter((section) => section.id === 'source' || section.fields.length);
}

function channelEditorPayload(form, profile, channel = null) {
  const remote = channelIsRemote(channel);
  const payload = { protocol_id: profile.id,
    settings: remote ? { ...channel.settings } : {},
    source: remote ? { ...channel.source, frequencies_hz: [...channel.source.frequencies_hz] } : {},
    frequency_map: [], event_logs: [],
    recorders: remote ? [...(channel.recorders || [])] : [], auxiliary_decoders: [] };
  profile.sections.forEach((section) => section.fields.forEach((field) => {
    if (field.type === 'read_only') return;
    const control = form.querySelector(`[data-channel-path="${CSS.escape(field.path)}"]`);
    const value = channelEditorFieldValue(control, field);
    if (field.path.startsWith('settings.')) payload.settings[field.path.substring(9)] = value;
    else if (field.path.startsWith('source.')) payload.source[field.path.substring(7)] = value;
    else payload[field.path] = value;
  }));
  return payload;
}

function channelRestoreProtocolDefaults(form, profile) {
  profile.sections.flatMap((section) => section.fields).filter((field) =>
    field.path.startsWith('settings.') && Object.hasOwn(field, 'default')).forEach((field) => {
      const control = form.querySelector(`[data-channel-path="${CSS.escape(field.path)}"]`);
      if (!control) return;
      if (field.type === 'boolean') {
        control.checked = Boolean(field.default);
        control.dispatchEvent(new Event('change', { bubbles: true }));
      } else {
        control.value = String(field.default ?? '');
        control.dispatchEvent(new Event('change', { bubbles: true }));
      }
  });
  channelEditorDependencies(form);
}

const CHANNEL_SQUELCH_PATHS = new Set([
  'settings.squelch_noise_open',
  'settings.squelch_noise_close',
  'settings.squelch_hysteresis_open',
  'settings.squelch_hysteresis_close'
]);

function channelSquelchQuality(noise) {
  return Math.max(0, Math.min(100, Math.round((0.5 - Number(noise || 0)) * 250)));
}

function channelSquelchNoise(quality) {
  return Math.max(0.1, Math.min(0.5, 0.5 - Number(quality || 0) / 250));
}

function channelSquelchTuner(profile, channel, entry, advancedFields) {
  const panel = node('section', 'channel-squelch-tuner');
  const heading = node('div', 'channel-squelch-heading');
  const headingCopy = node('div');
  headingCopy.append(node('h4', '', 'Squelch tuning'), node('p', 'muted',
    profile.id === 'am' ? 'Higher quality means the AM carrier is more stable.' :
      'Higher quality means the FM audio contains less high-frequency noise.'));
  const statePill = uiPill(entry?.processing_state === 'RUNNING' ? 'Connecting' : 'Channel stopped', 'neutral');
  heading.append(headingCopy, statePill);

  const qualityValue = node('strong', 'channel-squelch-quality-value', '—');
  const qualityMeter = node('progress', 'channel-squelch-quality-meter');
  qualityMeter.max = 100;
  qualityMeter.value = 0;
  qualityMeter.setAttribute('aria-label', 'Current signal quality');
  const qualityLine = node('div', 'channel-squelch-quality-line');
  qualityLine.append(node('span', '', 'Signal quality'), qualityValue);
  const quality = node('div', 'channel-squelch-quality');
  quality.append(qualityLine, qualityMeter);

  const history = node('div', 'channel-squelch-history');
  history.setAttribute('role', 'img');
  history.setAttribute('aria-label', 'Recent signal quality, newest at the right');
  const historyCells = Array.from({ length: 40 }, () => node('span', 'channel-squelch-history-cell'));
  history.append(...historyCells);
  const recent = node('div', 'channel-squelch-recent');
  recent.append(node('span', 'ui-field-label', 'Recent quality'), history,
    node('small', 'ui-field-detail', 'About the last two seconds · newest at right'));

  const advancedControl = (path) => advancedFields.map((wrapper) =>
    wrapper.querySelector(`[data-channel-path="${path}"]`)).find(Boolean);
  const openControl = advancedControl('settings.squelch_noise_open');
  const closeControl = advancedControl('settings.squelch_noise_close');
  const openTimingControl = advancedControl('settings.squelch_hysteresis_open');
  const closeTimingControl = advancedControl('settings.squelch_hysteresis_close');
  const startSlider = node('input', 'ui-range');
  const keepSlider = node('input', 'ui-range');
  [startSlider, keepSlider].forEach((slider) => {
    slider.type = 'range';
    slider.min = '0';
    slider.max = '100';
    slider.step = '1';
  });
  const startValue = node('output');
  const keepValue = node('output');
  const sliders = node('div', 'channel-squelch-sliders');
  const sliderField = (label, control, output, help) => {
    const field = node('label', 'ui-field channel-squelch-slider');
    const line = node('span', 'channel-squelch-slider-label');
    line.append(node('span', 'ui-field-label', label), output);
    field.append(line, control, node('small', 'ui-field-detail', help));
    return field;
  };
  sliders.append(
    sliderField('Start listening at', startSlider, startValue,
      'Raise this to require a cleaner signal before the channel opens.'),
    sliderField('Keep listening down to', keepSlider, keepValue,
      'Lower this to avoid cutting out as a signal fades.'));

  const syncSimpleControls = () => {
    const start = channelSquelchQuality(Number(openControl?.value));
    const keep = channelSquelchQuality(Number(closeControl?.value));
    startSlider.value = String(start);
    keepSlider.value = String(keep);
    startValue.textContent = `${start}% quality`;
    keepValue.textContent = `${keep}% quality`;
  };
  const writeThresholds = (changed) => {
    let start = Number(startSlider.value);
    let keep = Number(keepSlider.value);
    if (start < keep) {
      if (changed === startSlider) keep = start;
      else start = keep;
    }
    startSlider.value = String(start);
    keepSlider.value = String(keep);
    if (openControl) openControl.value = channelSquelchNoise(start).toFixed(2);
    if (closeControl) closeControl.value = channelSquelchNoise(keep).toFixed(2);
    openControl?.dispatchEvent(new Event('input', { bubbles: true }));
    closeControl?.dispatchEvent(new Event('input', { bubbles: true }));
    syncSimpleControls();
  };
  const previewNote = node('p', 'channel-squelch-save-note',
    entry?.processing_state === 'RUNNING' ?
      'Adjustments preview live. Save & restart makes them permanent; closing restores the saved settings.' :
      'Save the channel, then start it to see live feedback.');
  let previewLeaseId = null;
  let previewTimer = null;
  let previewHeartbeat = null;
  let previewClosed = false;
  let previewQueue = Promise.resolve();
  const previewPath = channel?.configuration_id ?
    `/api/v1/admin/channels/${encodeURIComponent(channel.configuration_id)}/squelch-preview` : null;
  const applyPreview = () => {
    if (previewClosed || entry?.processing_state !== 'RUNNING' || !previewPath) return;
    previewQueue = previewQueue.then(async () => {
      if (previewClosed) return;
      const result = await requestJson(previewPath, { method: 'POST', body: {
        action: 'APPLY',
        lease_id: previewLeaseId,
        noise_open: Number(openControl?.value),
        noise_close: Number(closeControl?.value),
        hysteresis_open: Number(openTimingControl?.value),
        hysteresis_close: Number(closeTimingControl?.value)
      } });
      previewLeaseId = result.lease_id;
      previewNote.textContent = 'Previewing these settings live. Save & restart makes them permanent.';
      if (!previewHeartbeat) previewHeartbeat = window.setInterval(applyPreview, 4_000);
    }).catch((error) => {
      previewNote.textContent = error.message || 'Live preview is temporarily unavailable.';
    });
  };
  const schedulePreview = () => {
    if (previewTimer) window.clearTimeout(previewTimer);
    previewTimer = window.setTimeout(applyPreview, 180);
  };
  startSlider.addEventListener('input', () => { writeThresholds(startSlider); schedulePreview(); });
  keepSlider.addEventListener('input', () => { writeThresholds(keepSlider); schedulePreview(); });
  [openControl, closeControl, openTimingControl, closeTimingControl].filter(Boolean).forEach((control) =>
    ['input', 'change'].forEach((eventName) => control.addEventListener(eventName, () => {
      syncSimpleControls();
      schedulePreview();
    })));
  syncSimpleControls();

  const listen = uiActionButton('Listen live', 'icon-play', () => {}, 'ui-button ui-button-secondary');
  const volume = node('input', 'ui-range');
  volume.type = 'range';
  volume.min = '0';
  volume.max = '1';
  volume.step = '0.05';
  volume.value = '0.7';
  volume.setAttribute('aria-label', 'Live channel volume');
  const volumeValue = node('output', '', '70%');
  const audioStatus = node('span', 'muted', 'Audio plays only while squelch is open.');
  const audioAllowed = capabilityAllowed(ACCESS_CAPABILITIES.CALL_AUDIO);
  if (!audioAllowed) {
    listen.disabled = true;
    audioStatus.textContent = 'This account does not have audio-listening access.';
  }
  const audioControls = node('div', 'channel-squelch-audio');
  audioControls.append(listen, node('span', '', 'Volume'), volume, volumeValue, audioStatus);

  const rawNoise = node('output', '', '—');
  const evidence = node('output', '', '—');
  const timing = node('output', '', '—');
  const diagnosticReadouts = node('dl', 'channel-squelch-diagnostics');
  [['Current detector value', rawNoise], ['Current evidence', evidence], ['Configured timing', timing]]
    .forEach(([label, value]) => {
      const detail = node('dd');
      detail.append(value);
      diagnosticReadouts.append(node('dt', '', label), detail);
    });
  const advanced = node('details', 'channel-squelch-advanced ui-section-disclosure');
  const advancedSummary = node('summary', 'ui-section-summary');
  advancedSummary.append(node('span', '', 'Advanced diagnostics'), node('small', 'muted', 'Exact values'));
  const advancedBody = node('div', 'channel-squelch-advanced-body');
  advancedBody.append(node('p', 'muted',
    'These are the exact manual thresholds used by the decoder. Timing values are 10 ms evidence steps; ' +
    'nothing is learned automatically.'), diagnosticReadouts);
  advancedFields.forEach((wrapper) => advancedBody.append(wrapper));
  advanced.append(advancedSummary, advancedBody);

  panel.append(heading, quality, recent, sliders, previewNote, audioControls, advanced);

  let stream = null;
  let generation = -1;
  let listening = false;
  const audioPlayer = diagnosticAudioPlayer(Number(volume.value));
  const historyValues = [];
  const setState = (label, tone = 'neutral') => {
    statePill.className = `ui-pill ui-pill-${tone}`;
    statePill.replaceChildren(node('span', '', label));
  };
  const updateHistory = (value) => {
    historyValues.push(value);
    if (historyValues.length > historyCells.length) historyValues.shift();
    const offset = historyCells.length - historyValues.length;
    historyCells.forEach((cell, index) => {
      const item = historyValues[index - offset];
      cell.dataset.quality = item == null ? '' : item >= 80 ? 'excellent' : item >= 60 ? 'good' :
        item >= 40 ? 'fair' : item >= 20 ? 'weak' : 'poor';
      cell.title = item == null ? '' : `${item}% quality`;
    });
  };
  const stopAudio = () => {
    listening = false;
    listen.replaceChildren(iconGlyph('icon-play'), document.createTextNode('Listen live'));
    audioPlayer.stop();
  };
  listen.addEventListener('click', async () => {
    if (listening) {
      stopAudio();
      return;
    }
    try { await audioPlayer.start(); }
    catch (error) { audioStatus.textContent = error.message; return; }
    listening = true;
    listen.replaceChildren(iconGlyph('icon-stop'), document.createTextNode('Stop listening'));
    audioStatus.textContent = 'Listening for open-squelch audio…';
  });
  volume.addEventListener('input', () => {
    volumeValue.textContent = `${Math.round(Number(volume.value) * 100)}%`;
    audioPlayer.volume(volume.value);
  });
  const playAudio = (frame) => {
    if (listening && audioPlayer.play(frame)) audioStatus.textContent = 'Playing live channel audio.';
  };

  const start = () => {
    const frequencyHz = Number(channel?.source?.preferred_frequency_hz || channel?.source?.frequencies_hz?.[0]);
    if (entry?.processing_state !== 'RUNNING' || !frequencyHz || !channel?.configuration_id) {
      listen.disabled = true;
      return;
    }
    const subscriptionId = randomLiveClientId();
    stream = binaryFrameConnection('channel_diagnostics', {
      configuration_id: channel.configuration_id,
      frequency_hz: frequencyHz,
      subscription_id: subscriptionId
    }, {
      onFrame: (frame) => {
        if (frame.type === DIAGNOSTIC_FRAME_TYPES.STATE) {
          const state = diagnosticJsonPayload(frame);
          if (state?.subscription_id !== subscriptionId) return;
          generation = frame.generation;
          if (state.squelch_state !== 'live') setState(state.squelch_state === 'waiting' ? 'Waiting' : 'Unavailable');
          return;
        }
        if (generation >= 0 && frame.generation !== generation) return;
        if (frame.type === DIAGNOSTIC_FRAME_TYPES.AUDIO_PCM16) {
          playAudio(frame);
          return;
        }
        if (frame.type !== DIAGNOSTIC_FRAME_TYPES.SQUELCH) return;
        const values = diagnosticFloatPayload(frame);
        if (values.length < 8) return;
        const currentQuality = channelSquelchQuality(values[0]);
        const closed = values[6] >= 0.5 && values[7] < 0.5;
        qualityMeter.value = currentQuality;
        qualityValue.textContent = `${currentQuality}%`;
        updateHistory(currentQuality);
        setState(closed ? 'Closed' : 'Open', closed ? 'neutral' : 'success');
        rawNoise.textContent = Number(values[0]).toFixed(4);
        evidence.textContent = `${Math.round(values[3])} of ${Math.round(closed ? values[4] : values[5])}`;
        timing.textContent = `open ${Math.round(values[4]) * 10}ms · close ${Math.round(values[5]) * 10}ms`;
      },
      onError: () => setState('Reconnecting', 'warning')
    });
  };
  const close = () => {
    previewClosed = true;
    if (previewTimer) window.clearTimeout(previewTimer);
    if (previewHeartbeat) window.clearInterval(previewHeartbeat);
    void previewQueue.finally(() => {
      if (previewLeaseId && previewPath) void requestJson(previewPath, {
        method: 'POST', body: { action: 'RESTORE', lease_id: previewLeaseId }
      }).catch(() => {});
    });
    stream?.close();
    stream = null;
    stopAudio();
  };
  return { element: panel, start, close };
}

async function openChannelEditorModal(mode = 'create', configurationId = null, prefetched = null) {
  const editing = mode === 'edit';
  const loading = node('div', 'loading', editing ? 'Loading channel settings…' : 'Preparing channel editor…');
  let squelchTuner = null;
  let removeSectionLayout = null;
  const modal = openReadOnlyModal(editing ? 'Edit Channel' : 'Create Channel', loading, {
    id: `${mode}-channel-${configurationId || 'new'}`, className: 'channel-editor-modal',
    returnFocusSelector: editing ?
      `tr[data-id="${CSS.escape(configurationId)}"] .channel-edit-button` :
      '.channel-admin-toolbar .ui-button-primary',
    cleanup: () => { squelchTuner?.close(); removeSectionLayout?.(); }
  });
  if (!modal || (modal.ready && !await modal.ready)) return;
  try {
    const [protocols, options, loadedEntry] = await Promise.all([
      requestJson('/api/v1/admin/channels/protocols', { csrf: false }),
      prefetched?.options ? Promise.resolve(prefetched.options) :
        requestJson('/api/v1/admin/channels/options', { csrf: false }),
      editing ? requestJson(`/api/v1/admin/channels/${encodeURIComponent(configurationId)}`, { csrf: false }) :
        Promise.resolve(null)
    ]);
    if (activeReadOnlyModal !== modal.state) return;
    let entry = loadedEntry;
    const profiles = protocols.profiles || [];
    let revision = Number(entry?.revision ?? options.revision ?? 0);
    const initialChannel = !editing ? prefetched?.initialChannel : null;
    let profile = profiles.find((candidate) => candidate.id ===
      (entry?.channel?.protocol_id || initialChannel?.protocol_id)) || profiles[0];
    let channel = entry?.channel || await requestJson(
      `/api/v1/admin/channels/protocols/${encodeURIComponent(profile.id)}/template`, { csrf: false });
    if (!editing) channel = channelCreationDefaults(channel, profile, options);
    if (!editing) channel = channelCreationPrefill(channel, profile, initialChannel);
    let baselineChannel = structuredClone(channel);
    let templateGeneration = 0;
    const host = node('div');

    const draw = () => {
      squelchTuner?.close();
      removeSectionLayout?.();
      squelchTuner = null;
      const form = node('form', 'channel-editor-form editor-workspace');
      form.dataset.uiDensity = 'comfortable';
      const hero = node('div', 'channel-editor-hero');
      const identity = node('div');
      identity.append(node('strong', '', channel.name || 'New channel'),
        node('span', '', `${profile.label} · ${semanticLabel(profile.channel_kind || 'Dynamic')}`));
      const systemName = node('span', '', String(channel.system || '').trim());
      systemName.hidden = !systemName.textContent;
      identity.append(systemName);
      const learnedSystemNames = [];
      hero.append(iconGlyph('icon-conventional'), identity);
      if (editing) hero.append(uiPill(entry.processing_state === 'RUNNING' ? 'Running' : 'Stopped',
        entry.processing_state === 'RUNNING' ? 'success' : 'neutral',
        entry.processing_state === 'RUNNING' ? 'icon-play' : 'icon-stop'));
      form.append(hero);
      if (editing && entry.processing_state === 'RUNNING') {
        const notice = node('div', 'channel-restart-notice ui-notice ui-notice-warning');
        notice.append(iconGlyph('icon-warning'), node('span', '',
          'Saving safely stops this channel, applies the change, and restores its running state.'));
        form.append(notice);
      }
      if (!editing) {
        const protocolSelect = uiSelect(profiles.map((candidate) =>
          ({ value: candidate.id, label: channelCreationProtocolLabel(candidate) })), profile.id);
        protocolSelect.addEventListener('change', async () => {
          if (modal.state.isBusy()) return;
          const generation = ++templateGeneration;
          modal.setBusy(true);
          try {
            profile = profiles.find((candidate) => candidate.id === protocolSelect.value);
            const loaded = await requestJson(
              `/api/v1/admin/channels/protocols/${encodeURIComponent(profile.id)}/template`, { csrf: false });
            if (generation !== templateGeneration || activeReadOnlyModal !== modal.state) return;
            channel = channelCreationDefaults(loaded, profile, options);
            baselineChannel = structuredClone(channel);
            draw();
            modal.setDirty(false);
          } catch (error) {
            host.replaceChildren(node('div', 'error', error.message));
          } finally { modal.setBusy(false); }
        });
        const protocolField = formField('Protocol', uiSelectFrame(protocolSelect, 'channel-protocol-select'),
          'The protocol determines the available source, decoder, logging, and recording settings.');
        protocolField.classList.add('channel-editor-field', 'channel-protocol-picker', 'ui-form-section');
        form.append(protocolField);
      }
      const panels = new Map();
      const sectionNodes = [];
      const editorProfile = { ...profile, sections: channelEditorSections(profile, channel) };
      const sectionPlan = channelEditorSectionPlan(editorProfile.sections);
      sectionPlan.forEach(({ definition: sectionDefinition, id, advanced }) => {
        const panel = node('fieldset', 'channel-editor-panel ui-form-section');
        const labelId = `${id}-label`;
        panel.id = id;
        panel.tabIndex = -1;
        panel.dataset.channelSection = sectionDefinition.id;
        if (!advanced) {
          const panelHeader = node('div', 'channel-editor-panel-header');
          const panelLabel = node('h3', 'channel-editor-panel-title', sectionDefinition.label);
          panelLabel.id = labelId;
          panel.setAttribute('aria-labelledby', labelId);
          panelHeader.append(panelLabel);
          if (sectionDefinition.id === 'protocol') panelHeader.append(
            uiActionButton('Restore defaults', 'icon-reset', () => {
              channelRestoreProtocolDefaults(form, editorProfile);
              modal.setDirty(true);
            }, 'ui-button ui-button-secondary'));
          if (sectionDefinition.id === 'protocol') panelHeader.classList.add('channel-editor-panel-header-actions');
          panel.append(panelHeader);
        }
        const grid = node('div', 'channel-editor-grid');
        if (channelIsRemote(channel) && sectionDefinition.id === 'source') {
          grid.append(node('p', 'muted channel-wide-field',
            'The sending VCE controls tuning. This channel follows its live control frequency.'));
        }
        const squelchFields = [];
        sectionDefinition.fields.forEach((field) => {
          const control = channelEditorControl(field, profile, options, channel, protocols);
          let presentedControl = control instanceof HTMLSelectElement ? uiSelectFrame(control) : control;
          if (field.unit && control instanceof HTMLInputElement) {
            const unit = node('span', 'channel-input-with-unit');
            unit.append(presentedControl, node('span', 'ui-input-unit', field.unit));
            presentedControl = unit;
          }
          presentedControl.classList?.add('channel-editor-control');
          const inlineAliasList = field.path === 'alias_list_id' && control instanceof HTMLSelectElement;
          let wrapper;
          if (inlineAliasList) {
            wrapper = node('div', 'channel-editor-field ui-field channel-wide-field channel-alias-field');
            control.id = `channel-alias-list-${profile.id}`;
            const label = node('label', 'ui-field-label', field.label);
            label.htmlFor = control.id;
            wrapper.append(label, presentedControl);
            if (field.help) wrapper.append(node('small', 'ui-field-detail', field.help));
          } else {
            wrapper = field.type === 'boolean' || field.type === 'multi_select' || field.type === 'read_only' ||
              field.type === 'frequency_map' || field.type === 'frequency_list' ?
              node('div', 'channel-editor-field ui-field channel-wide-field') :
              formField(field.label, presentedControl, field.help || '');
          }
          wrapper.classList.add('channel-editor-field');
          if (!wrapper.contains(control)) {
            wrapper.append(node('span', 'ui-field-label', field.label), presentedControl);
            if (field.help) wrapper.append(node('small', 'ui-field-detail', field.help));
          }
          if (channelEncryptedCallSkipLocked(field, protocols)) {
            wrapper.append(node('small', 'ui-field-detail', CHANNEL_ENCRYPTED_SKIP_LOCK_HELP));
          }
          if (inlineAliasList) {
            const aliasListCreator = aliasListPopupTrigger({
              select: control,
              family: profile.alias_family,
              getRevision: currentAliasListRevision,
              triggerLabel: 'New list',
              submitLabel: 'Create and use',
              helperText: 'The list is created immediately and selected for this channel.',
              onCreated: ({ aliasList }) => {
                const next = { id: aliasList.id, name: aliasList.name, family: aliasList.family };
                options.alias_lists = [...(options.alias_lists || [])
                  .filter((entry) => Number(entry.id) !== Number(next.id)), next]
                  .sort((left, right) => String(left.name || '').localeCompare(String(right.name || ''),
                    undefined, { numeric: true, sensitivity: 'base' }));
                let option = [...control.options].find((candidate) => candidate.value === String(next.id));
                if (!option) {
                  option = node('option');
                  option.value = String(next.id);
                  control.append(option);
                }
                option.textContent = next.name;
                control.value = option.value;
                control.dispatchEvent(new Event('change', { bubbles: true }));
              }
            });
            if (editing && aliasAdminAllowed()) {
              const openAliasList = externalAnchor('Open Alias List', href('aliases'),
                'ui-button ui-button-secondary channel-alias-open');
              const syncAliasListLink = () => {
                const listId = Number(control.value);
                const selected = Number.isInteger(listId) && listId > 0;
                openAliasList.hidden = !selected;
                if (selected) openAliasList.href = href('aliases', { list: listId });
              };
              control.addEventListener('change', syncAliasListLink);
              syncAliasListLink();
              wrapper.append(openAliasList);
            }
            wrapper.append(aliasListCreator);
          }
          if (field.path === 'settings.use_bandplan_override' &&
              capabilityAllowed(ACCESS_CAPABILITIES.ADMIN_SETTINGS)) {
            wrapper.append(anchor('Manage P25 band plan profiles', href('admin', { tab: 'protocol-p25' }),
              'channel-field-action'));
          }
          if (field.path === 'observed.p25_site_identity') {
            const learnedSystemName = node('strong', '', String(channel.system || '').trim());
            learnedSystemName.hidden = !learnedSystemName.textContent;
            wrapper.prepend(learnedSystemName);
            learnedSystemNames.push(learnedSystemName);
          }
          if (field.visible_when) {
            wrapper.dataset.visiblePath = field.visible_when.path;
            wrapper.dataset.visibleEquals = JSON.stringify(field.visible_when.equals);
          }
          if (sectionDefinition.id === 'protocol' && CHANNEL_SQUELCH_PATHS.has(field.path) &&
              (profile.id === 'am' || profile.id === 'nbfm')) squelchFields.push(wrapper);
          else grid.append(wrapper);
        });
        panel.append(grid);
        if (sectionDefinition.id === 'protocol' && squelchFields.length) {
          squelchTuner = channelSquelchTuner(profile, channel, entry, squelchFields);
          panel.append(squelchTuner.element);
        }
        panels.set(sectionDefinition.id, panel);
        const disclosure = node('details', 'channel-editor-section-disclosure ui-section-disclosure' +
          (advanced ? '' : ' channel-editor-section-primary'));
        disclosure.dataset.channelSection = sectionDefinition.id;
        const summary = node('summary', 'channel-editor-section-summary ui-section-summary');
        summary.id = `${id}-summary`;
        summary.append(node('span', '', sectionDefinition.label),
          node('small', 'muted', advanced ? 'Optional' : ''));
        if (advanced) panel.setAttribute('aria-labelledby', summary.id);
        disclosure.append(summary, panel);
        sectionNodes.push(disclosure);
      });
      const errors = node('div', 'channel-editor-message admin-form-message');
      errors.setAttribute('role', 'alert');
      errors.setAttribute('aria-live', 'assertive');
      errors.tabIndex = -1;
      const cancel = channelAdminButton('Cancel', modal.close);
      const reset = channelAdminButton('Reset changes', () => {
        channel = structuredClone(baselineChannel);
        draw();
        modal.setDirty(false);
      }, 'ui-button ui-button-secondary', 'icon-reset');
      const save = uiActionButton(editing && entry.processing_state === 'RUNNING' ? 'Save & restart' :
        (editing ? 'Save changes' : 'Create channel'), editing ? 'icon-edit' : 'icon-plus', () => {},
        'ui-button ui-button-primary');
      save.type = 'submit';
      const startStop = editing ? uiActionButton(entry.processing_state === 'RUNNING' ? 'Stop' : 'Start',
        entry.processing_state === 'RUNNING' ? 'icon-stop' : 'icon-play', async () => {
          if (modal.isDirty() || startStop.disabled || modal.state.isBusy()) return;
          const disabled = [...form.elements].filter(control => typeof control.disabled === 'boolean')
            .map(control => [control, control.disabled]);
          disabled.forEach(([control]) => { control.disabled = true; });
          modal.setBusy(true);
          form.setAttribute('aria-busy', 'true');
          errors.replaceChildren();
          try {
            const action = entry.processing_state === 'RUNNING' ? 'STOP' : 'START';
            const result = await requestJson('/api/v1/admin/channels/actions', {
              method: 'POST', body: { revision, action, configuration_ids: [configurationId] },
              timeoutMs: 30_000
            });
            const failure = (result?.results || []).find((value) => value.success !== true);
            if (failure) throw new Error(failure.message || 'Channel state could not be changed');
            entry = await requestJson(`/api/v1/admin/channels/${encodeURIComponent(configurationId)}`,
              { csrf: false });
            revision = Number(entry.revision);
            channel = entry.channel;
            baselineChannel = structuredClone(channel);
            draw();
          } catch (error) {
            errors.replaceChildren(node('div', 'ui-notice ui-notice-danger', error.message));
          } finally {
            disabled.forEach(([control, wasDisabled]) => { control.disabled = wasDisabled; });
            modal.setBusy(false);
            form.removeAttribute('aria-busy');
          }
        }, 'ui-button ui-button-secondary') : null;
      const sectionLayout = node('div', 'channel-editor-section-layout ui-editor-layout');
      const sectionStack = node('div', 'channel-editor-sections ui-editor-sections');
      sectionStack.append(...sectionNodes);
      removeSectionLayout = channelEditorSectionDisclosureLayout(sectionStack,
        `channel-editor-${mode}-${configurationId || 'new'}`);
      sectionLayout.append(channelEditorSectionNavigation(panels, sectionPlan), sectionStack);
      const footer = node('footer', 'channel-editor-footer ui-modal-footer ui-modal-footer-flush ui-action-row');
      footer.append(...[startStop, reset, node('span', 'channel-editor-footer-spacer ui-modal-footer-spacer'), cancel, save]
        .filter(Boolean));
      form.append(sectionLayout, errors, footer);
      const workflow = createFormWorkflow({ form, submit: save, modal,
        renderFeedback: (state, message) => {
          errors.setAttribute('role', state === 'error' ? 'alert' : 'status');
          errors.setAttribute('aria-live', state === 'error' ? 'assertive' : 'polite');
          if (state === 'error') return;
          errors.replaceChildren(...(message ? [node('div',
            `ui-feedback${state === 'loading' ? ' ui-feedback-loading' : ''}`, message)] : []));
        } });
      form.addEventListener('input', () => {
        if (modal.state.isBusy()) return;
        const name = String(form.querySelector('[data-channel-path="system"]')?.value || '').trim();
        for (const label of [systemName, ...learnedSystemNames]) {
          label.textContent = name;
          label.hidden = !name;
        }
        modal.setDirty(true);
        if (startStop) startStop.disabled = true;
        channelEditorDependencies(form);
      });
      form.addEventListener('change', () => {
        if (modal.state.isBusy()) return;
        modal.setDirty(true);
        if (startStop) startStop.disabled = true;
        channelEditorDependencies(form);
      });
      let firstInvalidField = null;
      form.addEventListener('invalid', (event) => {
        if (firstInvalidField) return;
        firstInvalidField = event.target;
        window.setTimeout(() => { firstInvalidField = null; }, 0);
        const disclosure = event.target.closest?.('details.channel-editor-section-disclosure');
        if (disclosure) disclosure.open = true;
      }, true);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (save.disabled || modal.state.isBusy()) return;
        errors.replaceChildren();
        await workflow.save(async () => {
          const payload = channelEditorPayload(form, editorProfile, channel);
          if (editing && entry.processing_state === 'RUNNING') {
            if (!await confirmAction('Save these settings and restart the running channel?', {
              title: 'Restart running channel', confirmLabel: 'Save and restart', cancelLabel: 'Keep editing', tone: 'primary'
            })) {
              throw new DOMException('Restart cancelled', 'AbortError');
            }
          }
          if (!modal.dialog.isConnected) throw new DOMException('Editor closed', 'AbortError');
          const result = await requestJson(editing ?
            `/api/v1/admin/channels/${encodeURIComponent(configurationId)}` : '/api/v1/admin/channels', {
            method: editing ? 'PUT' : 'POST', body: { revision, ...payload }, timeoutMs: 30_000
          });
          revision = Number(result.revision);
        }, {
          onSuccess: async () => {
            await renderChannelSetup();
            if (activeReadOnlyModal === modal.state) closeReadOnlyModal(true);
          },
          onError: (error) => {
            if (error.name === 'AbortError') { errors.replaceChildren(); return; }
            aliasMutationError(errors, error, () => {
              modal.setDirty(false);
              closeReadOnlyModal(true);
              openChannelEditorModal(mode, configurationId);
            });
            errors.scrollIntoView({ block: 'nearest' });
            errors.focus({ preventScroll: true });
          }
        });
      });
      host.replaceChildren(form);
      channelEditorDependencies(form);
      modal.content.replaceChildren(host);
      modal.dialog.querySelector('.modal-header h2').textContent = editing ?
        `Edit ${channel.name || 'Channel'}` : 'Create Channel';
      modal.setDirty(false);
      squelchTuner?.start();
    };
    draw();
  } catch (error) {
    modal.content.replaceChildren(node('div', 'error', error.message));
  }
}

async function renderChannelSetup() {
  const renderContext = captureRenderContext();
  await renderModernChannelCatalog(renderContext);
}

function identityActivityValue(row) {
  if (row.value != null) return identifierNumber(row.value);
  if (row.min_value != null && row.max_value != null) {
    return `${identifierNumber(row.min_value)}–${identifierNumber(row.max_value)}`;
  }
  return '—';
}

function aliasCoverageTime(value, emptyLabel = 'Never heard') {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) return node('span', 'ui-time-pair is-empty', emptyLabel);
  const pair = node('span', 'ui-time-pair');
  const relative = node('strong', '', elapsedLabel(timestamp));
  const exact = dateTime(timestamp);
  exact.classList.add('ui-time-pair-exact');
  pair.append(relative, exact);
  return pair;
}

function aliasCoverageAliasCell(row) {
  const details = [row.description, row.group].filter(Boolean).join(' · ');
  const target = entityTarget(row.entity_ref,
    { channel: row.identity_type === 'radio' ? 'radios' : 'groups' });
  return identitySummaryValue(row.name || `Alias ${row.alias_id}`, details, target);
}

function aliasCoverageIdentityCell(row) {
  const type = row.matcher_label || (row.identity_type === 'radio' ? 'Radio' :
    row.identity_type === 'talkgroup' ? 'Talkgroup' : 'Alias');
  const target = row.identity_type === 'radio' || row.identity_type === 'talkgroup' ?
    entityTarget(row.entity_ref, { channel: row.identity_type === 'radio' ? 'radios' : 'groups' }) : '';
  return identitySummaryValue(row.identity_display || identityActivityValue(row), type, target);
}

function aliasCoverageMetric(row, field) {
  return row.metrics_state === 'unsupported' ? node('span', 'muted', 'Not tracked') :
    number(row[field] || 0);
}

function aliasCoverageEvidenceTime(row, field) {
  return aliasCoverageTime(row.metrics_state === 'unsupported' ? null : row[field],
    row.metrics_state === 'unsupported' ? 'Not tracked' : 'Never heard');
}

function aliasCoverageAliasesColumns() {
  return [
    { id: 'name', label: 'Alias', render: aliasCoverageAliasCell,
      className: 'alias-cell', sort: 'name' },
    { id: 'identity', label: 'Identity', render: aliasCoverageIdentityCell, className: 'numeric', sort: 'identity' },
    { id: 'calls', label: 'Calls', render: (row) => aliasCoverageMetric(row, 'logical_call_count'), className: 'numeric',
      sort: 'logical_call_count' },
    { id: 'signals', label: 'Signals', render: (row) => aliasCoverageMetric(row, 'signaling_observation_count'),
      className: 'numeric', sort: 'signaling_observation_count' },
    { id: 'first', label: 'First heard', render: (row) => aliasCoverageEvidenceTime(row, 'first_evidence_ms'),
      sort: 'first_evidence' },
    { id: 'heard', label: 'Last heard', render: (row) => aliasCoverageEvidenceTime(row, 'last_evidence_ms'),
      sort: 'last_evidence' }
  ];
}

function aliasCoverageOwnerCell(row) {
  const owner = node('span', 'identity-summary');
  const systemLabel = radioSystemDisplayName(row);
  const channelLabel = row.channel_names || row.configuration_id;
  if (systemLabel) {
    const target = entityRefHref(row.radio_system_entity_ref);
    const primary = node('span', 'identity-summary-primary');
    primary.append(target ? anchor(systemLabel, target) : systemLabel);
    owner.append(primary);
  }
  if (channelLabel) {
    const target = entityTarget(row.channel_entity_ref, { channel: 'groups' });
    const context = node('small', 'identity-summary-context');
    context.append(target ? anchor(channelLabel, target) : channelLabel);
    owner.append(context);
  }
  if (!owner.childNodes.length) owner.append(node('span', 'identity-summary-primary', 'Unknown source'));
  return owner;
}

function aliasCoverageUnassignedIdentity(row) {
  const label = `${groupIdentityLabel(row, null, false)} ${identityNumber(row, row.group_identity_id)}`;
  return identitySummaryValue(label, '', entityTarget(row.entity_ref, { channel: 'groups' }));
}

function aliasCoverageUnassignedColumns() {
  return [
    { id: 'identity', label: 'Identity', render: aliasCoverageUnassignedIdentity,
      className: 'numeric', sort: 'group_identity' },
    { id: 'system', label: 'System / Channel', render: aliasCoverageOwnerCell, sort: 'system' },
    { id: 'calls', label: 'Calls', render: (row) => number(row.logical_call_count || 0), className: 'numeric',
      sort: 'logical_call_count' },
    { id: 'first', label: 'First heard', render: (row) => aliasCoverageTime(row.first_seen_ms), sort: 'first_seen' },
    { id: 'last', label: 'Last heard', render: (row) => aliasCoverageTime(row.last_seen_ms), sort: 'last_seen' }
  ];
}

function aliasCoverageSearch(placeholder, onNavigate) {
  const form = node('form', 'alias-coverage-search');
  form.method = 'get';
  for (const [key, value] of route.entries()) {
    if (key === 'q' || key === 'offset') continue;
    const hidden = node('input');
    hidden.type = 'hidden';
    hidden.name = key;
    hidden.value = value;
    form.append(hidden);
  }
  const field = node('label', 'ui-search');
  field.append(iconGlyph('icon-search'));
  const input = node('input', 'ui-input');
  input.type = 'search';
  input.name = 'q';
  input.value = route.get('q') || '';
  input.placeholder = placeholder;
  input.setAttribute('aria-label', placeholder);
  field.append(input);
  const submit = node('button', 'ui-button ui-button-primary', 'Search');
  submit.type = 'submit';
  form.append(field, submit);
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    onNavigate(currentHref({ q: input.value.trim() || null, offset: null }));
  });
  if (route.get('q')) form.append(anchor('Clear', currentHref({ q: null, offset: null }),
    'ui-button ui-button-secondary'));
  return form;
}

function aliasCoverageSummaryCards(totals, unassigned, countFailed = false) {
  const configured = Number(totals.configured_alias_count || 0);
  const activityEligible = Number(totals.activity_eligible_alias_count ?? configured);
  const recent = Number(totals.active_alias_count || 0);
  const summary = metrics([
    ['Configured aliases', configured, 'icon-identities', 'blue'],
    ['Heard in period', recent, 'icon-live', 'success'],
    ['Not heard in period', Math.max(0, activityEligible - recent), 'icon-pause', 'neutral'],
    ['Unassigned observed', unassigned?.total_count, 'icon-warning',
      unassigned ? 'warning' : 'neutral', unassigned ? undefined : countFailed ? 'Unavailable' : 'Loading…']
  ].map(([label, value, icon, tone, displayValue]) => [label, value, displayValue, { icon, tone }]), true);
  summary.classList.add('alias-coverage-summary');
  return summary;
}

function aliasCoverageScope(overview) {
  const rows = Array.isArray(overview.channels) ? overview.channels : [];
  const scope = node('section', 'ui-surface alias-coverage-scope');
  const header = node('header', 'alias-coverage-section-header');
  const copy = node('div');
  copy.append(node('h2', '', 'Channels using this Alias List'),
    node('p', 'muted', rows.length ?
      `${number(rows.length)} channel${rows.length === 1 ? '' : 's'} across ${number(overview.correlated_radio_system_count || 0)} radio system${Number(overview.correlated_radio_system_count) === 1 ? '' : 's'}` :
      'No configured channels currently reference this Alias List'));
  header.append(copy);
  const list = node('div', 'alias-coverage-scope-list');
  rows.forEach((row) => {
    const item = node('div', 'alias-coverage-scope-row');
    const channelTarget = entityTarget(row.channel_entity_ref);
    const systemTarget = entityRefHref(row.radio_system_entity_ref);
    const channelLabel = row.name || row.site_name || row.configuration_id;
    const channel = node('strong', '');
    channel.append(channelTarget ? anchor(channelLabel, channelTarget) : channelLabel);
    const context = node('span', 'muted');
    const systemLabel = radioSystemDisplayName(row);
    if (systemLabel) context.append(systemTarget ? anchor(systemLabel, systemTarget) : systemLabel);
    if (row.site_name && row.site_name !== channelLabel) context.append(` · ${row.site_name}`);
    item.append(channel, context);
    list.append(item);
  });
  if (!rows.length) list.append(node('div', 'empty alias-coverage-empty',
    'Assign this Alias List to a channel to connect future activity.'));
  scope.append(header, list);
  return scope;
}

async function loadAliasCoverageModel(parameters, previous = null, signal = null) {
  const selectedRange = parameters.get('range') || '24h';
  const activeTab = parameters.get('identity_tab') === 'unassigned' ? 'unassigned' : 'configured';
  const aliasStatus = ['recent', 'zero_calls', 'never_heard'].includes(parameters.get('alias_status')) ?
    parameters.get('alias_status') : 'all';
  const options = { signal };
  const availableLists = previous?.lists || await apiPage('/api/v1/identities/lists', { limit: 500 }, options);
  const lists = { ...availableLists, rows: availableLists.rows.filter((row) =>
    ['P25', 'DMR', 'NXDN'].includes(aliasListFamily(row))) };
  const requested = parameters.get('alias_list_id');
  const selected = lists.rows.find((row) => String(row.alias_list_id) === requested);
  if (!selected) return { lists, selectedListId: null, selectedRange, activeTab, aliasStatus };
  const selectedListId = selected.alias_list_id;
  const configuredSort = parameters.get('sort') || (aliasStatus === 'recent' ? 'last_evidence' : 'name');
  const configuredDirection = parameters.get('direction') || (aliasStatus === 'recent' ? 'desc' : 'asc');
  const common = { range: selectedRange, status: aliasStatus, q: parameters.get('q'), limit: 100,
    offset: parameters.get('offset') || 0, sort: configuredSort, direction: configuredDirection };
  const emptyPage = { rows: [], limit: 100, offset: 0, has_more: false, next_offset: null };
  const unassignedParameters = { q: parameters.get('q'), limit: 100,
    offset: parameters.get('offset') || 0, sort: parameters.get('sort') || 'logical_call_count',
    direction: parameters.get('direction') || 'desc' };
  const [overviewResult, aliases, unassigned] = await Promise.all([
    api(`/api/v1/identities/lists/${encodeURIComponent(selectedListId)}/overview`,
      { range: selectedRange }, options),
    activeTab === 'configured' ? apiPage(`/api/v1/identities/lists/${encodeURIComponent(selectedListId)}/aliases`,
      { ...common, type: parameters.get('type') }, options) : Promise.resolve(emptyPage),
    activeTab === 'unassigned' ?
      apiPage(`/api/v1/identities/lists/${encodeURIComponent(selectedListId)}/unassigned`,
        unassignedParameters, options) : Promise.resolve(null)
  ]);
  return { lists, selectedListId, overview: overviewResult, aliases, unassigned,
    selectedRange, activeTab, aliasStatus };
}

async function renderAliasCoverageDirectory(renderContext, embedded = false) {
  const directory = createAsyncSection('Alias inventory', {
    bare: true,
    loadingMessage: 'Loading Alias Lists…',
    errorMessage: 'Alias inventory could not be loaded.'
  });
  directory.host.classList.add('alias-coverage-loader');
  if (embedded) {
    content.append(radioDirectoryEmbeddedPanel('coverage', directory.element));
  } else if (!beginPage(renderContext, pageHeader('Radio Directory',
    'Browse aliases in a list, their activity, and the channels using them'),
    radioDirectoryPerspectiveControl('coverage'), directory.element)) return;

  let selectedModel = null;
  let updateSequence = 0;
  let updateController = null;
  let countController = null;
  const navigateCoverage = (target, options = {}) => routeFoundation.navigate(window, target, (nextRoute) => {
    route = nextRoute;
    void refreshCoverage(nextRoute, options);
  });
  const present = (model) => {
    const { lists, selectedListId, overview, aliases, unassigned,
      selectedRange, activeTab, aliasStatus } = model;
    const wrapper = node('div', 'alias-coverage ui-catalog data-workspace');
    wrapper.dataset.uiDensity = 'compact';
    const toolbar = node('div', 'alias-coverage-toolbar ui-catalog-toolbar');
    toolbar.classList.toggle('alias-coverage-awaiting-selection', !selectedListId);
    const listControl = node('label', 'alias-coverage-field ui-field');
    listControl.append(node('span', 'ui-field-label', 'Alias List'));
    const listSelect = uiSelect(lists.rows.map((row) => ({ value: row.alias_list_id,
      label: `${row.name} · ${aliasListFamilyLabel(row)} · ${number(row.alias_count)} ` +
        (Number(row.alias_count) === 1 ? 'alias' : 'aliases') })),
      selectedListId, true, lists.rows.length ? 'Select an alias list' :
        'No P25, DMR, or NXDN alias lists configured');
    listSelect.disabled = !lists.rows.length;
    listSelect.addEventListener('change', () => navigateCoverage(currentHref({ alias_list_id: listSelect.value,
      q: null, offset: null, sort: null, direction: null })));
    listControl.append(uiSelectFrame(listSelect));
    toolbar.append(listControl);
    if (!selectedListId) {
      wrapper.append(toolbar);
      if (lists.rows.length) queueMicrotask(() => {
        if (renderIsCurrent(renderContext) && directory.host.contains(wrapper))
          listSelect.focus({ preventScroll: true });
      });
      return wrapper;
    }
    const rangeControl = node('label', 'alias-coverage-field ui-field');
    rangeControl.append(node('span', 'ui-field-label', 'Recent period'));
    const rangeSelect = uiSelect([
      { value: '1h', label: 'Last 1h' }, { value: '24h', label: 'Last 1d' },
      { value: '7d', label: 'Last 7d' }, { value: '30d', label: 'Last 30d' }
    ], selectedRange);
    rangeSelect.addEventListener('change', () => navigateCoverage(currentHref({ range: rangeSelect.value, offset: null })));
    rangeControl.append(uiSelectFrame(rangeSelect));
    toolbar.append(rangeControl);
    const totals = overview.totals || {};
    const summary = aliasCoverageSummaryCards(totals, unassigned, model.unassignedCountFailed);

    const tabs = uiSegmentedControl([
      { value: 'configured', label: 'Configured aliases' },
      { value: 'unassigned', label: activeTab === 'unassigned' ?
        `Unassigned observations (${number(unassigned.total_count || 0)})` : 'Unassigned observations' }
    ], activeTab, (value) => navigateCoverage(currentHref({ identity_tab: value === 'configured' ? null : value,
      q: null, offset: null, sort: null, direction: null })));
    tabs.setAttribute('aria-label', 'Alias inventory');
    const tableSection = node('section', 'ui-surface alias-coverage-table-section');
    const tableHeader = node('header', 'alias-coverage-table-header');
    const tableHeading = node('div', 'alias-coverage-table-heading');
    const tableActions = sectionActionHost();
    tableActions.classList.add('alias-coverage-table-actions');
    tableHeading.append(node('h2', '', 'Alias inventory'));
    tableHeader.append(tableHeading, tabs, tableActions);
    const tableToolbar = node('div', 'alias-coverage-table-toolbar');
    tableToolbar.append(aliasCoverageSearch(activeTab === 'unassigned' ?
      'Search unassigned observations' : 'Search configured aliases', navigateCoverage));
    if (activeTab === 'configured') {
      const status = uiSegmentedControl([
        { value: 'all', label: 'All' }, { value: 'recent', label: 'Recently heard' },
        { value: 'zero_calls', label: `Zero calls (${number(totals.zero_call_alias_count || 0)})` },
        { value: 'never_heard', label: `Never heard (${number(totals.never_heard_alias_count || 0)})` }
      ], aliasStatus, (value) => navigateCoverage(currentHref({ alias_status: value === 'all' ? null : value,
        offset: null, sort: null, direction: null })));
      status.setAttribute('aria-label', 'Alias activity status');
      const kind = uiSegmentedControl([
        { value: 'all', label: 'All' }, { value: 'talkgroup', label: 'Talkgroups' },
        { value: 'radio', label: 'Radios' }, { value: 'other', label: 'Other' }
      ], route.get('type') || 'all', (value) => navigateCoverage(currentHref({ type: value === 'all' ? null : value,
        offset: null })));
      kind.setAttribute('aria-label', 'Alias type');
      tableToolbar.append(status, kind);
    }
    tableSection.append(tableHeader, tableToolbar, activeTab === 'unassigned' ?
      pagedTableContent(unassigned, aliasCoverageUnassignedColumns(), 'alias-coverage-unassigned-v1', {
        itemLabel: 'Observations', emptyText: 'Every observed identity is assigned in this Alias List',
        tableOptions: { defaultSort: 'logical_call_count', defaultDirection: 'desc',
          layoutMenuHost: tableActions } }) :
      pagedTableContent(aliases, aliasCoverageAliasesColumns(), 'alias-coverage-configured-v1', {
        itemLabel: 'Aliases', emptyText: 'No configured aliases match these filters',
        tableOptions: { defaultSort: aliasStatus === 'recent' ? 'last_evidence' : 'name',
          defaultDirection: aliasStatus === 'recent' ? 'desc' : 'asc', layoutMenuHost: tableActions } }));

    tableSection.addEventListener('click', (event) => {
      if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey ||
          event.shiftKey || event.altKey || !(event.target instanceof Element)) return;
      const link = event.target.closest('a[href]');
      if (!link || !tableSection.contains(link)) return;
      const target = routeFoundation.localTarget(window.location, link.href);
      if (target?.searchParams.get('view') !== 'dashboard' ||
          target.searchParams.get('directory_view') !== 'coverage') return;
      event.preventDefault();
      navigateCoverage(link.href, { scrollToTable: Boolean(link.closest('.pager')) });
    });
    wrapper.append(toolbar, summary, aliasCoverageScope(overview), tableSection);
    return wrapper;
  };

  const hydrateUnassignedCount = async (model) => {
    if (!model?.selectedListId || model.activeTab !== 'configured' || model.unassigned ||
        !renderIsCurrent(renderContext) || renderContext.signal?.aborted) return;
    countController?.abort();
    const controller = new AbortController();
    countController = controller;
    const sequence = updateSequence;
    const isCurrent = () => !controller.signal.aborted && sequence === updateSequence &&
      selectedModel === model && renderIsCurrent(renderContext) && directory.host.isConnected;
    try {
      const count = await apiPage(`/api/v1/identities/lists/${encodeURIComponent(model.selectedListId)}/unassigned`,
        { limit: 1, offset: 0, sort: 'logical_call_count', direction: 'desc' }, { signal: controller.signal });
      if (!isCurrent()) return;
      model.unassigned = count;
    } catch (error) {
      if (error?.name === 'AbortError' || !isCurrent()) return;
      model.unassignedCountFailed = true;
    } finally {
      if (countController === controller) countController = null;
    }
    if (isCurrent()) directory.host.querySelector('.alias-coverage-summary')?.replaceWith(
      aliasCoverageSummaryCards(model.overview.totals || {}, model.unassigned, model.unassignedCountFailed));
  };

  const refreshCoverage = async (parameters, options = {}) => {
    const sequence = ++updateSequence;
    updateController?.abort();
    countController?.abort();
    updateController = new AbortController();
    const tableSection = directory.host.querySelector('.alias-coverage-table-section');
    const oldTop = tableSection?.getBoundingClientRect().top;
    const status = uiStatus('Updating…', 'neutral');
    status.setAttribute('role', 'status');
    tableSection?.querySelector('.alias-coverage-table-actions')?.append(status);
    tableSection?.setAttribute('aria-busy', 'true');
    directory.host.querySelector('.alias-coverage-refresh-error')?.remove();
    try {
      const model = await loadAliasCoverageModel(parameters, selectedModel, updateController.signal);
      if (sequence !== updateSequence || !renderIsCurrent(renderContext) || !directory.host.isConnected) return;
      directory.host.replaceChildren(present(model));
      selectedModel = model;
      void hydrateUnassignedCount(model);
      const newTable = directory.host.querySelector('.alias-coverage-table-section');
      const newTop = newTable?.getBoundingClientRect().top;
      if (options.scrollToTable) newTable?.scrollIntoView({ block: 'start', behavior: 'instant' });
      else if (Number.isFinite(oldTop) && Number.isFinite(newTop)) window.scrollBy(0, newTop - oldTop);
    } catch (error) {
      if (error?.name === 'AbortError' || sequence !== updateSequence || !renderIsCurrent(renderContext)) return;
      const failure = node('div', 'error alias-coverage-refresh-error');
      failure.setAttribute('role', 'alert');
      failure.append(node('span', '', error.message || 'Alias inventory could not be updated.'),
        uiActionButton('Retry', null, () => void refreshCoverage(new URLSearchParams(route))));
      (tableSection || directory.host).prepend(failure);
      void hydrateUnassignedCount(selectedModel);
    } finally {
      if (sequence === updateSequence) {
        status.remove();
        tableSection?.removeAttribute('aria-busy');
      }
    }
  };
  renderContext.signal?.addEventListener('abort', () => {
    updateController?.abort();
    countController?.abort();
  }, { once: true });
  await directory.load(() => loadAliasCoverageModel(new URLSearchParams(route), null, renderContext.signal),
    (model) => { selectedModel = model; return present(model); }, renderContext);
  void hydrateUnassignedCount(selectedModel);
}

function channelTabItems(channel) {
  const values = { configuration_id: channel.configuration_id };
  const items = [];
  items.push({ id: 'info', label: 'Info',
    href: href('channel', { ...values, tab: 'info' }) });
  const analog = ['AM', 'NBFM'].includes(String(channel.decoder || '').toUpperCase());
  if (!analog && channelCapability(channel, 'group_identities')) {
    items.push({ id: 'groups', label: 'Groups',
      href: href('channel', { ...values, tab: 'groups' }) });
  }
  if (channelCapability(channel, 'radios')) {
    items.push({ id: 'radios', label: 'Radios',
      href: href('channel', { ...values, tab: 'radios' }) });
  }
  if (channelCapability(channel, 'activity')) {
    items.push({ id: 'activity', label: 'Activity',
      href: href('channel', { ...values, tab: 'activity' }) });
  }
  return items;
}

