async function renderConventionalChannel(data, channel, configurationId, renderContext) {
  const tabItems = channelTabItems(channel);
  const requestedTab = route.get('tab') || 'info';
  const tab = tabItems.some((item) => item.id === requestedTab) ? requestedTab : tabItems[0].id;
  if (!beginPage(renderContext,
    pageHeader(entityPageTitle('Channel', channel.name, Number(channel.primary_frequency_hz) > 0 ?
      `${frequency(channel.primary_frequency_hz)} MHz` : ''),
      [radioSystemPrimaryName(channel), protocolFamily(channel), 'Conventional'].filter(Boolean).join(' · ')),
    tabs(tabItems, tab))) return;

  if (tab === 'activity') {
    const analog = isAnalogChannel(channel);
    await renderActivity({
      configuration_id: configurationId,
      _activity_context: {
        kind: analog ? 'conventional-analog' : 'conventional-digital',
        protocol: protocolFamily(channel), configuration_id: configurationId
      }
    });
  } else if (tab === 'groups') {
    await renderChannelGroupIdentities(configurationId);
  } else if (tab === 'radios') {
    await renderChannelRadios(configurationId);
  } else {
    content.append(section('Channel Info', keyValues([
      ['Name', channel.name],
      ['System', radioSystemInfoFact(channel, false)],
      ['Protocol', protocolFamily(channel)], ['Decoder', decoderDisplay(channel.decoder)],
      ['Alias List', aliasListLink(channel.alias_list_name, channel.alias_list_id)],
      ['Frequency', frequency(channel.primary_frequency_hz)],
      ['NAC', hexDecimalPair(channel.nac, 3)], ['First Seen', dateTime(channel.first_seen_ms)],
      ['Last Seen', dateTime(channel.last_seen_ms)]
    ])));
    content.append(tableSection('Frequency Summaries', data.summaries || [], [
      { id: 'channel', label: 'Channel', render: (row) => [
        Number(row.frequency_hz) ? `${frequency(row.frequency_hz)} MHz` : '',
        timeslotLabel(row.timeslot)
      ].filter(Boolean).join(' · '), sortValue: (row) => Number(row.frequency_hz || 0) },
      { id: 'logical-calls', label: 'Logical Calls',
        render: (row) => number(row.logical_call_count), className: 'numeric',
        sortValue: (row) => Number(row.logical_call_count || 0) },
      { id: 'recorded-logical-calls', label: 'Rec', fullLabel: 'Recorded Logical Calls',
        render: (row) => number(row.recorded_logical_call_count), className: 'numeric',
        sortValue: (row) => Number(row.recorded_logical_call_count || 0) },
      { id: 'stream-submitted-logical-calls', label: 'Submitted', fullLabel: 'Submitted to Streamer',
        render: (row) => number(row.stream_submitted_logical_call_count), className: 'numeric',
        sortValue: (row) => Number(row.stream_submitted_logical_call_count || 0) },
      { id: 'encrypted-logical-calls', label: 'Enc', fullLabel: 'Encrypted Logical Calls',
        render: (row) => number(row.encrypted_logical_call_count), className: 'numeric encrypted',
        sortValue: (row) => Number(row.encrypted_logical_call_count || 0) },
      { id: 'first-seen', label: 'First', fullLabel: 'First Observed', render: (row) => dateTime(row.first_seen_ms), sortValue: (row) => Number(row.first_seen_ms || 0) },
      { id: 'last-seen', label: 'Seen', fullLabel: 'Last Observed', render: (row) => dateTime(row.last_seen_ms), sortValue: (row) => Number(row.last_seen_ms || 0) }
    ], 'No frequency summaries recorded', { type: 'channel-frequencies' }));
  }
}

async function renderChannel() {
  const renderContext = captureRenderContext();
  const configurationId = String(route.get('configuration_id') || '').trim();
  if (!configurationId) throw new Error('Channel configuration ID is missing from the URL');
  const data = await api(channelApiPath(configurationId));
  let channel = data?.channel;
  if (!channel || typeof channel !== 'object' || Array.isArray(channel)) {
    throw new Error('The channel response is invalid');
  }
  if (String(channel.channel_kind || '').toUpperCase() === 'TRUNKED') {
    if (route.get('tab') === 'quality' && channel.remote_origin?.remote !== true) {
      try {
        const catalog = await requestChannelConfigurationJson('/api/v1/channel-catalog', { csrf: false });
        if (!renderIsCurrent(renderContext)) return;
        const configured = (catalog.channels || []).find((row) =>
          row.configuration_id === configurationId);
        if (configured?.remote_origin?.remote === true) {
          channel = { ...channel, remote_origin: { remote: true } };
        }
      } catch (_) { /* Historical or temporarily unavailable catalogs retain normal quality behavior. */ }
    }
    await renderTrunkedChannel(channel, configurationId, renderContext);
  } else {
    await renderConventionalChannel(data, channel, configurationId, renderContext);
  }
}

function adminUserRecord(value) {
  return {
    username: String(value?.username || '').trim(),
    tier: accessTierFromWire(value?.tier) || 'PUBLIC',
    passwordChangedAtEpochMillis: Number(value?.password_changed_at_epoch_millis || 0),
    primaryAdmin: value?.primary === true
  };
}

function adminUserEndpoint(username) {
  return `/api/v1/admin/users/${encodeURIComponent(username)}`;
}

function adminStatusMessage(host, message, error = false) {
  if (!host) return;
  host.textContent = message || '';
  host.classList.toggle('has-error', error);
  host.classList.toggle('ui-notice-danger', error);
}

function userIdentityCell(account) {
  const wrapper = node('div', 'admin-user-identity');
  wrapper.append(node('h2', 'ui-record-card-title', account.username));
  if (account.primaryAdmin) {
    const primary = uiPill('Primary', 'success');
    wrapper.append(primary);
  }
  return wrapper;
}

function userTierControl(account) {
  return node('span', 'ui-muted admin-tier-locked', account.primaryAdmin ? 'Admin access' : 'User access');
}

function normalizedManagedUsername(value) {
  return String(value || '').normalize('NFKC').trim().toLowerCase();
}

function validateManagedUserInput(username, password, confirmation, creating) {
  const normalizedUsername = normalizedManagedUsername(username);
  if (creating && (!/^[a-z0-9][a-z0-9._-]{0,63}$/.test(normalizedUsername) || normalizedUsername === 'admin')) {
    return 'Use 1–64 characters. Start with a lowercase letter or number; use only lowercase letters, numbers, ' +
      'dots, underscores, or hyphens. The name admin is reserved.';
  }
  if (password.length < 7 || password.length > 256) return 'Password must contain 7–256 characters.';
  if (password !== confirmation) return 'Passwords do not match.';
  return null;
}

function openManagedUserModal(account, statusHost, returnFocusSelector) {
  const creating = !account;
  const form = node('form', 'admin-form managed-user-form');
  const username = node('input');
  username.name = 'username';
  username.autocomplete = 'username';
  username.maxLength = 64;
  username.required = true;
  username.value = account?.username || '';
  username.disabled = !creating;
  const password = node('input');
  password.type = 'password';
  password.name = 'password';
  password.autocomplete = 'new-password';
  password.minLength = 7;
  password.maxLength = 256;
  password.required = true;
  const confirmation = node('input');
  confirmation.type = 'password';
  confirmation.name = 'password-confirmation';
  confirmation.autocomplete = 'new-password';
  confirmation.minLength = 7;
  confirmation.maxLength = 256;
  confirmation.required = true;
  const message = node('div', 'admin-form-message');
  message.setAttribute('role', 'alert');
  const submit = node('button', 'ui-button ui-button-primary', creating ? 'Create account' : 'Change password');
  submit.type = 'submit';
  const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancel.type = 'button';
  const actions = aliasModalFooter(cancel, submit);
  form.append(formField('Username', username,
      creating ? 'Use 1–64 characters. Start with a lowercase letter or number; use only lowercase letters, ' +
        'numbers, dots, underscores, or hyphens.' : ''),
    formField('Password', password, 'Use 7–256 characters.'),
    formField('Confirm password', confirmation));
  form.append(message, actions);
  const modal = openReadOnlyModal(creating ? 'Create account' : `Change password · ${account.username}`, form, {
    id: creating ? 'create-user' : 'change-password', returnFocusSelector, className: 'admin-modal'
  });
  if (!modal) return;
  cancel.addEventListener('click', modal.close);
  const workflow = createFormWorkflow({ form, submit, feedback: message, modal });
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (submit.disabled) return;
    const validation = validateManagedUserInput(username.value, password.value, confirmation.value, creating);
    if (validation) {
      workflow.showFeedback('error', validation);
      return;
    }
    const saved = await workflow.save(async () => {
      if (creating) {
        await requestJson('/api/v1/admin/users', {
          method: 'POST', body: { username: normalizedManagedUsername(username.value), password: password.value }
        });
      } else {
        await requestJson(adminUserEndpoint(account.username), {
          method: 'PUT', body: { password: password.value }
        });
      }
    }, {
      saving: creating ? 'Creating account…' : 'Changing password…',
      onSuccess: async () => {
        password.value = '';
        confirmation.value = '';
        modal.close();
        adminStatusMessage(statusHost, creating ? 'Account created.' : `Password changed for ${account.username}.`);
        if (!creating) await refreshAccessSession(false);
        await render();
        if (returnFocusSelector) document.querySelector(returnFocusSelector)?.focus({ preventScroll: true });
      },
      onError: (error) => {
        password.value = '';
        confirmation.value = '';
        return { state: 'error', message: error.message };
      }
    });
    if (!saved && password.isConnected) password.focus();
  });
  modal.focus?.(creating ? username : password);
}

function openDeleteUserModal(account, statusHost, returnFocusSelector) {
  const body = node('div', 'admin-confirmation');
  body.append(node('p', '', `Delete ${account.username}? They will be signed out immediately.`));
  const message = node('div', 'admin-form-message');
  message.setAttribute('role', 'alert');
  const actions = aliasModalFooter();
  const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancel.type = 'button';
  const remove = node('button', 'ui-button ui-button-danger', 'Delete account');
  remove.type = 'button';
  actions.append(cancel, remove);
  body.append(message, actions);
  const modal = openReadOnlyModal(`Delete account · ${account.username}`, body, {
    id: 'delete-user', returnFocusSelector, className: 'admin-modal'
  });
  if (!modal) return;
  cancel.addEventListener('click', modal.close);
  remove.addEventListener('click', async () => {
    if (remove.disabled) return;
    remove.disabled = true;
    cancel.disabled = true;
    modal.setBusy(true);
    message.textContent = 'Deleting account…';
    try {
      await requestJson(adminUserEndpoint(account.username), { method: 'DELETE' });
      modal.setBusy(false);
      modal.close();
      adminStatusMessage(statusHost, `${account.username} was deleted.`);
      await refreshAccessSession(false);
      await render();
    } catch (error) {
      remove.disabled = false;
      cancel.disabled = false;
      modal.setBusy(false);
      message.textContent = error.message;
    }
  });
  modal.focus?.(cancel);
}

function userActions(account, statusHost) {
  if (account.primaryAdmin) {
    const managed = node('span', 'ui-permission-fixed admin-managed-note');
    managed.append(iconGlyph('icon-lock'), document.createTextNode('Managed in the desktop application'));
    return managed;
  }
  const actions = node('div', 'admin-row-actions');
  const reset = uiActionButton('Change password', 'icon-key', () => openManagedUserModal(account, statusHost,
    `.admin-row-actions button[data-username="${account.username}"][data-user-action="password"]`), 'ui-button ui-button-link');
  reset.setAttribute('aria-label', `Change password for ${account.username}`);
  reset.dataset.username = account.username;
  reset.dataset.userAction = 'password';
  const remove = uiActionButton('Delete', 'icon-trash', () => openDeleteUserModal(account, statusHost,
    `.admin-row-actions button[data-username="${account.username}"][data-user-action="delete"]`), 'ui-button ui-button-link ui-button-danger-quiet');
  remove.setAttribute('aria-label', `Delete ${account.username}`);
  remove.dataset.username = account.username;
  remove.dataset.userAction = 'delete';
  actions.append(reset, remove);
  return actions;
}

function adminUserCard(account, statusHost) {
  const card = node('article', 'ui-record-card admin-account-card');
  card.dataset.username = account.username;
  card.classList.toggle('admin-account-primary', account.primaryAdmin);
  const header = node('div', 'ui-record-card-header admin-account-header');
  const avatar = node('span', `ui-record-avatar${account.primaryAdmin ? ' ui-record-avatar-accent' : ''}`);
  avatar.append(iconGlyph(account.primaryAdmin ? 'icon-admin' : 'icon-users'));
  const copy = node('div', 'ui-record-card-copy admin-account-copy');
  copy.append(userIdentityCell(account));
  if (account.primaryAdmin) {
    const detail = node('div', 'ui-muted admin-account-detail');
    detail.append(userTierControl(account), document.createTextNode(' · Password changed '),
      valueNode(dateTime(account.passwordChangedAtEpochMillis)));
    copy.append(detail);
  } else copy.append(userTierControl(account));
  header.append(avatar, copy);
  const facts = keyValues([['Password changed', dateTime(account.passwordChangedAtEpochMillis)]]);
  facts.classList.add('ui-record-facts');
  const body = node('div', 'ui-record-card-body admin-account-body');
  body.append(facts);
  card.append(header);
  if (!account.primaryAdmin) card.append(body);
  if (account.primaryAdmin) header.append(userActions(account, statusHost));
  else {
    const footer = node('div', 'ui-record-card-footer');
    footer.append(userActions(account, statusHost));
    card.append(footer);
  }
  return card;
}

async function renderAdminUsers(renderContext = captureRenderContext()) {
  const response = await requestJson('/api/v1/admin/users', { csrf: false });
  if (!renderIsCurrent(renderContext)) return;
  const users = (Array.isArray(response) ? response : response?.users || []).map(adminUserRecord)
    .filter((account) => account.username)
    .sort((left, right) => Number(right.primaryAdmin) - Number(left.primaryAdmin) ||
      left.username.localeCompare(right.username));
  const statusHost = node('div', 'admin-operation-status ui-notice');
  statusHost.setAttribute('role', 'status');
  const create = node('button', 'ui-button ui-button-primary', 'Create account');
  create.type = 'button';
  create.id = 'admin-create-user';
  const maximumUsers = Number(response?.maximum_users || 0);
  if (maximumUsers > 0 && users.filter((account) => !account.primaryAdmin).length >= maximumUsers) {
    create.disabled = true;
    create.title = `Account limit reached (${number(maximumUsers)}).`;
  }
  create.addEventListener('click', () => openManagedUserModal(null, statusHost, '#admin-create-user'));
  create.prepend(iconGlyph('icon-plus'));
  const titleRow = content.querySelector('.ui-settings-title-row');
  if (titleRow) titleRow.append(create);
  const toolbar = node('div', 'admin-accounts-toolbar');
  const managedCount = users.filter((account) => !account.primaryAdmin).length;
  toolbar.append(node('span', 'ui-muted', `${number(managedCount)} managed account${managedCount === 1 ? '' : 's'}`));
  if (!titleRow) toolbar.append(create);
  if (capabilityAllowed(ACCESS_CAPABILITIES.ADMIN_ACCESS)) {
    const accessLink = anchor('Manage page access', href('admin', { tab: 'access' }), 'ui-button ui-button-link');
    accessLink.append(iconGlyph('icon-open-details'));
    toolbar.append(accessLink);
  }
  const cards = node('div', 'ui-record-grid admin-account-grid');
  users.forEach((account) => cards.append(adminUserCard(account, statusHost)));
  if (!users.length) cards.append(node('div', 'ui-empty-state', 'No accounts found'));
  content.append(toolbar, cards, statusHost);
}

function adminAccessPolicies(response) {
  if (!Array.isArray(response?.capabilities)) return [];
  return response.capabilities.map((entry) => {
    const requiredTier = accessTierFromWire(entry?.required_tier);
    if (!requiredTier) return null;
    return {
      id: typeof entry?.id === 'string' ? entry.id.trim() : '',
      displayName: typeof entry?.display_name === 'string' ? entry.display_name.trim() : '',
      requiredTier,
      configurable: entry?.configurable === true
    };
  }).filter((entry) => entry?.id && entry.displayName);
}

function accessPolicyTierControl(policy, statusHost) {
  const select = node('select', 'ui-select admin-tier-select');
  select.setAttribute('aria-label', `Minimum access level for ${policy.displayName || policy.id}`);
  ['PUBLIC', 'USER', 'ADMIN'].forEach((tier) => {
    const option = node('option', '', accessTierLabel(tier));
    option.value = tier;
    option.selected = tier === policy.requiredTier;
    select.append(option);
  });
  const fixedAdmin = policy.id.startsWith('admin-');
  select.disabled = !policy.configurable || fixedAdmin;
  if (select.disabled) select.title = 'This access level cannot be changed.';
  select.addEventListener('change', async () => {
    const previous = policy.requiredTier;
    const requested = accessTierValue(select.value);
    select.disabled = true;
    adminStatusMessage(statusHost, `Updating ${policy.displayName || policy.id}…`);
    try {
      await requestJson('/api/v1/admin/access', {
        method: 'PUT', body: { capability: policy.id, tier: accessTierToWire(requested) }
      });
      policy.requiredTier = requested;
      adminStatusMessage(statusHost,
        `${policy.displayName || policy.id} now requires ${accessTierLabel(requested)} access.`);
      await refreshAccessSession(false);
    } catch (error) {
      select.value = previous;
      adminStatusMessage(statusHost, error.message, true);
    } finally {
      select.disabled = !policy.configurable || fixedAdmin;
    }
  });
  return select;
}

function accessPolicyIdentity(policy) {
  const icons = { dashboard: 'icon-dashboard', live: 'icon-live', radio: 'icon-radio-tower',
    'call-audio': 'icon-speaker', 'csv-export': 'icon-download', credits: 'icon-about',
    'tuner-spectrum': 'icon-spectrum', 'user-settings': 'icon-admin', recordings: 'icon-recording',
    'admin-recordings': 'icon-recording-settings', 'receiver-health': 'icon-health' };
  const wrapper = node('div', 'ui-permission-identity admin-capability-identity');
  const icon = node('span', 'ui-record-card-icon');
  icon.append(iconGlyph(icons[policy.id] || 'icon-admin'));
  wrapper.append(icon, node('span', 'ui-permission-name', policy.displayName || policy.id));
  return wrapper;
}

function webAccessControl(policy, statusHost) {
  const wrapper = node('div', 'ui-record-card-header admin-web-access-control');
  const icon = node('span', 'ui-record-card-icon');
  icon.append(iconGlyph('icon-network-visualizer'));
  const copy = node('div', 'ui-record-card-copy ui-heading-group admin-web-access-copy');
  copy.append(node('h2', 'ui-record-card-title', policy.displayName),
    node('p', 'ui-muted', 'Individual pages can require a higher access level.'));
  const control = node('label', 'ui-field admin-web-access-tier');
  control.append(node('span', 'ui-field-label', 'Minimum access'), accessPolicyTierControl(policy, statusHost));
  wrapper.append(icon, copy, control);
  return wrapper;
}

function adminAccessRows(policies, statusHost, compactFixed = false) {
  const list = node('div', 'ui-permission-list');
  policies.forEach((policy) => {
    const row = node('div', 'ui-permission-row');
    row.dataset.capability = policy.id;
    const controls = node('div', 'ui-permission-tier');
    const select = accessPolicyTierControl(policy, statusHost);
    if (select.disabled) controls.append(node('span', 'ui-permission-fixed', 'Fixed'));
    if (compactFixed && select.disabled) {
      row.classList.add('ui-permission-row-compact');
      controls.classList.add('ui-permission-tier-fixed');
      select.classList.remove('admin-tier-select');
      select.classList.add('ui-select-static');
    }
    controls.append(select);
    row.append(compactFixed ? node('span', 'ui-permission-name', policy.displayName || policy.id) :
      accessPolicyIdentity(policy), controls);
    list.append(row);
  });
  if (!policies.length) list.append(node('div', 'ui-empty-state', 'No page access settings are available'));
  return list;
}

async function renderAdminAccess(renderContext = captureRenderContext()) {
  const response = await requestJson('/api/v1/admin/access', { csrf: false });
  if (!renderIsCurrent(renderContext)) return;
  const displayOrder = ['dashboard', 'live', 'radio', 'call-audio', 'csv-export', 'credits',
    'tuner-spectrum', 'user-settings', 'recordings', 'admin-recordings', 'admin-users', 'admin-access',
    'admin-aliases', 'admin-streaming', 'admin-channels', 'admin-tuners', 'admin-settings', 'receiver-health'];
  const order = (id) => displayOrder.includes(id) ? displayOrder.indexOf(id) : displayOrder.length;
  const policies = adminAccessPolicies(response).sort((left, right) => order(left.id) - order(right.id) ||
    (left.displayName || left.id).localeCompare(right.displayName || right.id));
  const webPolicy = policies.find((policy) => policy.id === ACCESS_CAPABILITIES.WEB_ACCESS);
  const recordingsPolicies = policies.filter((policy) =>
    [ACCESS_CAPABILITIES.RECORDINGS, ACCESS_CAPABILITIES.ADMIN_RECORDINGS].includes(policy.id));
  const administrationPolicies = policies.filter((policy) => !recordingsPolicies.includes(policy) &&
    (policy.id.startsWith('admin-') || policy.id === ACCESS_CAPABILITIES.RECEIVER_HEALTH));
  const featurePolicies = policies.filter((policy) => policy.id !== ACCESS_CAPABILITIES.WEB_ACCESS &&
    !recordingsPolicies.includes(policy) && !administrationPolicies.includes(policy));
  const statusHost = node('div', 'admin-operation-status ui-notice');
  statusHost.setAttribute('role', 'status');
  content.append(statusHost);
  if (webPolicy) {
    const gate = node('section', 'ui-record-card admin-access-gate');
    gate.append(webAccessControl(webPolicy, statusHost));
    content.append(gate);
  }
  content.append(section('Pages & features', adminAccessRows(featurePolicies, statusHost),
    node('span', 'ui-muted ui-label', 'Minimum access')));
  if (recordingsPolicies.length) {
    content.append(section('Recordings', adminAccessRows(recordingsPolicies, statusHost),
      node('span', 'ui-muted ui-label', 'Minimum access')));
  }
  if (administrationPolicies.length) {
    content.append(section('Administration', adminAccessRows(administrationPolicies, statusHost, true),
      uiPill('Admin access', 'neutral', 'icon-lock')));
  }
}

let selectedAdminScanListId = null;

function scanListAdminPayload(controls) {
  return {
    sort_order: Number(controls.sortOrder.value),
    name: controls.name.value.trim(),
    description: controls.description.value.trim(),
    published: controls.published.checked,
    default: controls.defaultScanList.checked
  };
}

function openScanListAdminModal(scanList, revision) {
  const editing = Boolean(scanList);
  const form = node('form', 'admin-form scan-list-admin-form');
  const name = node('input');
  name.required = true;
  name.maxLength = 100;
  name.value = scanList?.name || '';
  const description = node('textarea');
  description.maxLength = 1000;
  description.rows = 4;
  description.value = scanList?.description || '';
  const sortOrder = node('input');
  sortOrder.type = 'number';
  sortOrder.min = '0';
  sortOrder.max = '1000000';
  sortOrder.step = '1';
  sortOrder.required = true;
  sortOrder.value = String(scanList?.sort_order ?? 0);
  const publishedField = uiToggleField('Available to listeners', scanList?.published !== false,
    'Available to listeners', 'Hidden lists can still be edited.');
  const published = publishedField.querySelector('input');
  const defaultField = uiToggleField('Default scan list', scanList?.default === true, 'Default scan list',
    scanList?.default === true ? 'Choose another list as the default before changing or deleting this one.' :
      'Making this the default replaces the current default.');
  const defaultScanList = defaultField.querySelector('input');
  if (scanList?.default === true) {
    defaultScanList.disabled = true;
    published.disabled = true;
  }
  const syncDefault = () => {
    if (defaultScanList.checked) {
      setUiToggle(published, true);
      published.disabled = true;
    } else if (scanList?.default !== true) published.disabled = false;
  };
  defaultScanList.addEventListener('change', syncDefault);
  const message = node('div', 'admin-form-message');
  message.setAttribute('role', 'alert');
  const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancel.type = 'button';
  const submit = node('button', 'ui-button ui-button-primary', editing ? 'Save Scan List' : 'Create Scan List');
  submit.type = 'submit';
  const actions = aliasModalFooter(cancel, submit);
  form.append(formField('Name', name, 'Shown to listeners; up to 100 characters.'),
    formField('Description', description, 'Optional context for listeners.'),
    formField('Display order', sortOrder, 'Lower numbers appear first.'),
    publishedField, defaultField, message, actions);
  const modal = openReadOnlyModal(editing ? `Edit scan list · ${scanList.name}` : 'Create scan list', form, {
    id: editing ? `edit-scan-list-${scanList.id}` : 'create-scan-list',
    className: 'admin-modal scan-list-admin-modal',
    returnFocusSelector: editing ? `.admin-scan-list-edit[data-scan-list-id="${scanList.id}"]` :
      '#admin-create-scan-list'
  });
  if (!modal) return;
  cancel.addEventListener('click', modal.close);
  const controls = { name, description, sortOrder, published, defaultScanList };
  let original = JSON.stringify(scanListAdminPayload(controls));
  const workflow = createFormWorkflow({ form, submit, feedback: message, modal,
    changed: editing ? () => JSON.stringify(scanListAdminPayload(controls)) !== original : null });
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    await workflow.save(async () => {
      const path = editing ? `/api/v1/admin/scan-lists/${scanList.id}` : '/api/v1/admin/scan-lists';
      const result = await requestJson(path, {
        method: editing ? 'PUT' : 'POST',
        body: { revision, scan_list: scanListAdminPayload(controls) }
      });
      original = JSON.stringify(scanListAdminPayload(controls));
      return result;
    }, {
      saving: editing ? 'Saving scan list…' : 'Creating scan list…',
      onSuccess: async (result) => {
        if (!editing) {
          const createdId = Number(result?.scan_list_id ?? result?.scanListId);
          if (Number.isInteger(createdId) && createdId > 0) selectedAdminScanListId = createdId;
        }
        modal.setDirty(false);
        modal.close();
        await refreshPlaybackScanLists(true);
        await render();
        document.querySelector(editing ? `.admin-scan-list-edit[data-scan-list-id="${scanList.id}"]` :
          '#admin-create-scan-list')?.focus({ preventScroll: true });
      },
      onError: (error) => ({ state: 'error', message: error.status === 409 ?
        `${error.message} Reload Scan Lists and try again.` : error.message })
    });
  });
  modal.focus?.(name);
}

function openDeleteScanListAdminModal(scanList, revision) {
  if (scanList.default === true) return;
  const body = node('div', 'admin-confirmation');
  const aliasCount = Number(scanList.alias_count || 0);
  const unmatchedAliasListCount = Number(scanList.unmatched_alias_list_count || 0);
  body.append(node('p', '', `Delete ${scanList.name}?`),
    node('p', 'muted', `This removes the list from ${number(aliasCount)} aliases and the Call Handling Defaults of ` +
      `${number(unmatchedAliasListCount)} alias lists. The aliases and alias lists ` +
      'themselves are preserved.'));
  const message = node('div', 'admin-form-message');
  message.setAttribute('role', 'alert');
  const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancel.type = 'button';
  const remove = node('button', 'ui-button ui-button-danger', 'Delete Scan List');
  remove.type = 'button';
  const actions = aliasModalFooter();
  actions.append(cancel, remove);
  body.append(message, actions);
  const modal = openReadOnlyModal(`Delete scan list · ${scanList.name}`, body, {
    id: `delete-scan-list-${scanList.id}`, className: 'admin-modal',
    returnFocusSelector: `.admin-scan-list-delete[data-scan-list-id="${scanList.id}"]`
  });
  if (!modal) return;
  cancel.addEventListener('click', modal.close);
  remove.addEventListener('click', async () => {
    if (remove.disabled) return;
    remove.disabled = true;
    cancel.disabled = true;
    modal.setBusy(true);
    message.textContent = 'Deleting scan list…';
    try {
      await requestJson(`/api/v1/admin/scan-lists/${scanList.id}`, {
        method: 'DELETE', body: { revision }
      });
      const deletedSelected = selectedAdminScanListId === Number(scanList.id);
      if (deletedSelected) selectedAdminScanListId = null;
      modal.setBusy(false);
      modal.close();
      await refreshPlaybackScanLists(true);
      await render();
      if (deletedSelected) content.querySelector('.scan-list-selector[aria-pressed="true"]')?.focus();
    } catch (error) {
      message.textContent = error.status === 409 ?
        `${error.message} Reload Scan Lists and try again.` : error.message;
      remove.disabled = false;
      cancel.disabled = false;
      modal.setBusy(false);
    }
  });
  modal.focus?.(cancel);
}

function adminScanListActions(scanList, revision) {
  const actions = node('div', 'admin-row-actions scan-list-detail-actions');
  const members = anchor('Manage aliases', href('aliases', {
    scanListId: scanList.id, aliasTab: 'configure'
  }), 'ui-button ui-button-primary admin-scan-list-members');
  members.prepend(iconGlyph('icon-identities'));
  const count = Number(scanList.alias_count || 0);
  members.setAttribute('aria-label',
    `Manage ${number(count)} ${count === 1 ? 'alias' : 'aliases'} for ${scanList.name}`);
  const edit = uiActionButton('Edit details', 'icon-edit',
    () => openScanListAdminModal(scanList, revision),
    'ui-button ui-button-secondary admin-scan-list-edit');
  edit.setAttribute('aria-label', `Edit ${scanList.name} details`);
  edit.dataset.scanListId = String(scanList.id);
  const remove = iconButton('icon-trash', `Delete ${scanList.name}`,
    'ui-button ui-button-danger-quiet ui-icon-button admin-scan-list-delete');
  remove.dataset.scanListId = String(scanList.id);
  if (scanList.default === true) {
    const reason = 'Choose another default scan list before deleting this one.';
    remove.setAttribute('aria-disabled', 'true');
    remove.setAttribute('aria-description', reason);
    remove.title = reason;
  } else {
    remove.addEventListener('click', () => openDeleteScanListAdminModal(scanList, revision));
  }
  actions.append(members, edit, remove);
  return actions;
}

function adminScanListUnmatchedAliasLists(scanList) {
  const aliasLists = Array.isArray(scanList?.unmatched_alias_lists) ? scanList.unmatched_alias_lists : [];
  if (!aliasLists.length) return node('span', 'muted', 'None');
  const links = node('span', 'badge-group ui-badge-group');
  aliasLists.forEach((aliasList) => {
    const id = Number(aliasList?.alias_list_id);
    if (!Number.isInteger(id) || id <= 0) return;
    links.append(anchor(aliasList.name || `Alias List ${id}`, href('aliases', {
      list: id, aliasTab: 'configure'
    }), 'badge ui-pill'));
  });
  return links.childElementCount ? links : node('span', 'muted', 'None');
}

function adminScanListSelector(scanList) {
  const name = String(scanList?.name || 'Unnamed Scan List');
  const selector = node('button', 'scan-list-selector ui-select-list-item');
  selector.type = 'button';
  selector.dataset.scanListId = String(scanList.id);
  selector.setAttribute('aria-controls', 'admin-scan-list-detail');
  selector.setAttribute('aria-pressed', 'false');
  selector.tabIndex = -1;
  const main = node('span', 'scan-list-selector-main');
  main.append(node('strong', '', name));
  if (scanList.default === true) main.append(node('small', 'muted', 'Default'));
  else if (scanList.published === false) main.append(node('small', 'muted',
    browsingWorkflows.scanListAvailabilityLabel(scanList)));
  const count = Number(scanList.alias_count || 0);
  selector.append(main, node('span', 'scan-list-selector-count muted',
    `${number(count)} ${count === 1 ? 'alias' : 'aliases'}`));
  return selector;
}

function adminScanListDetail(scanList, revision) {
  const name = String(scanList?.name || 'Unnamed Scan List');
  const detail = node('section', 'scan-list-detail ui-surface');
  detail.id = 'admin-scan-list-detail';
  detail.dataset.scanListId = String(scanList.id);
  const header = node('header', 'scan-list-detail-header');
  const heading = node('div');
  const title = node('h2', 'scan-list-detail-title', name);
  title.id = `admin-scan-list-title-${String(scanList?.id ?? 'unknown')
    .replace(/[^a-z0-9_-]/gi, '-')}`;
  detail.setAttribute('aria-labelledby', title.id);
  const badges = badgeGroup([
    scanList.default === true ? badge('Default') : null,
    browsingWorkflows.scanListAvailabilityPill(node, scanList)
  ]);
  badges.classList.add('scan-list-detail-badges');
  heading.append(title, badges);
  header.append(heading);
  detail.append(header);

  const description = String(scanList.description || '').trim();
  if (description) detail.append(node('p', 'scan-list-detail-description muted', description));

  const facts = metrics([], true);
  facts.classList.add('scan-list-detail-facts');
  const assigned = metricCard('Assigned aliases', scanList.alias_count || 0,
    undefined, { icon: 'icon-aliases' });
  assigned.querySelector('.ui-metric-copy').append(node('small', 'ui-metric-detail',
    'Existing Aliases explicitly included in this Scan List.'));
  const defaults = metricCard('Alias Lists routing unmatched calls',
    scanList.unmatched_alias_list_count || 0, undefined, { icon: 'icon-scan-lists' });
  defaults.querySelector('.ui-metric-copy').append(node('small', 'ui-metric-detail',
    'Alias Lists set to send calls here when no talkgroup or patch-group Alias matches. ' +
    'Their existing Aliases are not automatically included.'));
  facts.append(assigned, defaults);

  const routes = node('div', 'scan-list-detail-routes');
  routes.append(node('p', 'muted', 'Routes unmatched calls from'));
  const routeLinks = node('div', 'scan-list-detail-route-links');
  routeLinks.append(adminScanListUnmatchedAliasLists(scanList));
  routes.append(routeLinks);
  detail.append(facts, routes, adminScanListActions(scanList, revision));
  return detail;
}

async function renderAdminScanLists() {
  const renderContext = captureRenderContext();
  const response = await requestJson('/api/v1/admin/scan-lists', { csrf: false });
  if (!renderIsCurrent(renderContext)) return;
  const revision = Number(response?.revision ?? 0);
  const scanLists = Array.isArray(response?.scan_lists) ? response.scan_lists : [];
  const heading = pageHeader('Scan Lists', 'Choose which calls listeners can hear together');
  heading.classList.add('scan-list-page-header');
  const create = uiActionButton('Create scan list', 'icon-plus', () =>
    openScanListAdminModal(null, revision), 'ui-button ui-button-primary');
  create.id = 'admin-create-scan-list';
  const actions = node('div', 'scan-list-heading-actions ui-section-actions');
  actions.append(create);
  heading.append(actions);
  if (!beginPage(renderContext, heading)) return;

  const workspace = node('div', 'scan-list-page editor-workspace');
  const catalog = node('section', 'scan-list-catalog ui-catalog');
  catalog.setAttribute('aria-label', 'Listener Scan Lists');
  if (!scanLists.length) {
    const empty = node('div', 'ui-empty-state');
    empty.append(node('h2', '', 'No scan lists are configured'),
      node('p', '', 'Create a scan list to group the calls that listeners can hear together.'));
    catalog.append(empty);
    workspace.append(catalog);
    content.append(workspace);
    return;
  }

  const entries = scanLists.map((scanList) => ({
    scanList,
    selector: adminScanListSelector(scanList)
  }));
  const list = node('div', 'scan-list-list ui-surface');
  list.setAttribute('role', 'group');
  list.setAttribute('aria-label', 'Select a scan list. Use Up and Down arrow keys to switch lists.');
  list.append(...entries.map((entry) => entry.selector));
  const noMatches = node('div', 'admin-scan-list-filter-empty scan-list-filter-empty ui-empty-state');
  noMatches.hidden = true;
  noMatches.append(node('h2', '', 'No scan lists match'),
    node('p', '', 'Try another search or choose a different availability filter.'));
  list.append(noMatches);
  const detailHost = node('div', 'scan-list-detail-host');
  detailHost.setAttribute('aria-live', 'off');
  const layout = node('div', 'scan-list-layout');
  layout.append(list, detailHost);

  const selectScanList = (scanList) => {
    selectedAdminScanListId = Number(scanList.id);
    entries.forEach(({ scanList: row, selector }) => {
      const selected = Number(row.id) === selectedAdminScanListId;
      selector.setAttribute('aria-pressed', String(selected));
      selector.tabIndex = selected ? 0 : -1;
    });
    detailHost.replaceChildren(adminScanListDetail(scanList, revision));
    detailHost.hidden = false;
  };
  entries.forEach(({ scanList, selector }) => {
    selector.addEventListener('click', () => selectScanList(scanList));
    selector.addEventListener('keydown', (event) => {
      if (!['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) return;
      const visible = entries.filter(({ selector: row }) => !row.hidden);
      const index = visible.findIndex(({ selector: row }) => row === selector);
      if (index < 0) return;
      event.preventDefault();
      const nextIndex = event.key === 'Home' ? 0 : event.key === 'End' ? visible.length - 1 :
        (index + (event.key === 'ArrowDown' ? 1 : -1) + visible.length) % visible.length;
      const next = visible[nextIndex];
      selectScanList(next.scanList);
      next.selector.focus();
    });
  });

  const searchControl = node('label', 'scan-list-search-control ui-field');
  searchControl.append(node('span', 'ui-field-label', 'Search scan lists'));
  const searchFrame = node('span', 'ui-search');
  searchFrame.append(iconGlyph('icon-search'));
  const search = node('input', 'ui-input');
  search.id = 'admin-scan-list-search';
  search.type = 'search';
  search.autocomplete = 'off';
  search.placeholder = 'Search name, description, or Alias List';
  searchFrame.append(search);
  searchControl.append(searchFrame);

  let activeFilter = 'all';
  let applyFilters = () => {};
  const filter = uiSegmentedControl([
    { value: 'all', label: 'All' },
    { value: 'available', label: 'Available' },
    { value: 'hidden', label: 'Hidden' }
  ], activeFilter, (value) => {
    activeFilter = value;
    applyFilters();
  });
  filter.classList.add('scan-list-filter');
  filter.setAttribute('aria-label', 'Show scan lists');
  filter.querySelectorAll('.ui-segmented-option').forEach((button) => {
    button.classList.add('admin-scan-list-filter');
    button.dataset.filter = button.dataset.value;
  });
  const filterControl = node('div', 'scan-list-filter-control ui-field');
  filterControl.append(node('span', 'ui-field-label', 'Show'), filter);
  const toolbar = node('div', 'scan-list-catalog-toolbar ui-catalog-toolbar');
  toolbar.append(searchControl, filterControl);

  const count = node('span', 'admin-scan-list-count');
  count.setAttribute('aria-live', 'polite');
  const meta = node('div', 'scan-list-catalog-meta muted');
  meta.append(count, anchor('Browse aliases', href('aliases', { aliasTab: 'configure' })));

  applyFilters = () => {
    const query = search.value.trim().toLocaleLowerCase();
    const visibleEntries = entries.filter(({ scanList, selector }) => {
      const aliasLists = Array.isArray(scanList.unmatched_alias_lists) ? scanList.unmatched_alias_lists : [];
      const searchable = [scanList.name, scanList.description,
        ...aliasLists.flatMap((aliasList) => [aliasList.name, aliasList.family])]
        .filter(Boolean).join(' ').toLocaleLowerCase();
      const published = scanList.published !== false;
      const matchesText = !query || searchable.includes(query);
      const matchesState = activeFilter === 'all' ||
        (activeFilter === 'available' ? published : !published);
      selector.hidden = !(matchesText && matchesState);
      return !selector.hidden;
    });
    const total = entries.length;
    count.textContent = visibleEntries.length === total ?
      `${number(total)} scan list${total === 1 ? '' : 's'}` :
      `${number(visibleEntries.length)} of ${number(total)} scan lists`;
    noMatches.hidden = visibleEntries.length > 0;
    if (!visibleEntries.length) {
      entries.forEach(({ selector }) => { selector.tabIndex = -1; });
      detailHost.hidden = true;
      return;
    }
    const selected = visibleEntries.find(({ scanList }) =>
      Number(scanList.id) === selectedAdminScanListId) ||
      visibleEntries.find(({ scanList }) => scanList.default === true) || visibleEntries[0];
    if (detailHost.hidden ||
      Number(detailHost.firstElementChild?.dataset.scanListId) !== Number(selected.scanList.id)) {
      selectScanList(selected.scanList);
    }
  };
  search.addEventListener('input', applyFilters);
  applyFilters();
  catalog.append(toolbar, meta, layout);
  workspace.append(catalog);
  content.append(workspace);
}

function radioReferenceAccountMessage(account) {
  const state = String(account?.state || 'SIGNED_OUT');
  const userName = String(account?.user_name || '').trim();
  const expiration = String(account?.account_expires || '').trim();
  switch (state) {
    case 'VALID_PREMIUM':
      return `Connected${userName ? ` as ${userName}` : ''}${expiration ? ` · Premium ${expiration}` : ''}.`;
    case 'EXPIRED_PREMIUM':
      return `Connected${userName ? ` as ${userName}` : ''}, but the Premium subscription is expired.`;
    case 'INVALID_CREDENTIALS': return 'RadioReference rejected the username or password.';
    case 'SECURE_TRANSPORT_REQUIRED': return 'Secure RadioReference transport is unavailable.';
    case 'UNAVAILABLE': return 'RadioReference is currently unavailable.';
    case 'CHECKING': return 'Checking the RadioReference account…';
    default: return 'RadioReference is not connected.';
  }
}

function replaceRadioReferenceOptions(select, options, selectedId, placeholder) {
  select.replaceChildren();
  const rows = Array.isArray(options) ? options : [];
  if (!rows.length) {
    const empty = node('option', '', placeholder);
    empty.value = '';
    select.append(empty);
    select.value = '';
    return false;
  }
  rows.forEach((item) => {
    const suffix = item.abbreviation ? ` (${item.abbreviation})` : '';
    const option = node('option', '', `${item.name}${suffix}`);
    option.value = String(item.id);
    select.append(option);
  });
  const requested = String(selectedId || '');
  select.value = rows.some((item) => String(item.id) === requested) ? requested :
    String(rows.find((item) => String(item.abbreviation).toUpperCase() === 'US')?.id || rows[0].id);
  return true;
}

async function renderAdminRadioReferenceSettings() {
  const renderContext = captureRenderContext();
  if (!beginPage(renderContext, pageHeader('RadioReference',
    'Browse systems and agencies, compare changes, and import'))) return;
  const page = node('div', 'radioreference-page');
  const loadingState = node('div', 'ui-feedback ui-feedback-loading',
    'Checking saved RadioReference sign-in…');
  loadingState.setAttribute('role', 'status');
  const gate = node('div', 'radioreference-login-gate ui-surface editor-workspace');
  gate.hidden = true;
  gate.append(node('span', 'radioreference-gate-eyebrow', 'RadioReference Premium'),
    node('h2', '', 'Connect your account'),
    node('p', 'muted', 'Sign in to browse systems, compare talkgroups, and import channels.'));
  const workspace = node('div', 'radioreference-connected-page');
  workspace.hidden = true;
  const workspaceHeader = node('div', 'radioreference-workspace-header');
  const accountStatus = uiPill('Connected · Premium', 'success');
  const settingsButton = node('button', 'ui-button ui-button-secondary radioreference-settings-trigger',
    'RadioReference settings');
  settingsButton.type = 'button';
  workspaceHeader.append(accountStatus, settingsButton);
  workspace.append(workspaceHeader);
  page.append(loadingState, gate, workspace);
  content.append(page);
  const accountForm = node('form', 'admin-form radioreference-account-form editor-workspace');
  const userName = node('input', 'ui-input');
  userName.name = 'radioreference-username';
  userName.autocomplete = 'username';
  userName.maxLength = 256;
  userName.required = true;
  const password = node('input', 'ui-input');
  password.type = 'password';
  password.name = 'radioreference-password';
  password.autocomplete = 'current-password';
  password.maxLength = 1024;
  password.required = true;
  const rememberSetting = preferenceCheckbox('radioreference-remember',
    'Remember credentials on this receiver', true,
    'Stores the credentials in this receiver’s protected portable settings.');
  const remember = rememberSetting.input;
  const accountMessage = node('div', 'admin-form-message');
  accountMessage.setAttribute('role', 'status');
  const setAccountMessage = (message, isError = false) => {
    accountMessage.textContent = message;
    accountMessage.classList.toggle('ui-notice', isError);
    accountMessage.classList.toggle('ui-notice-danger', isError);
    accountMessage.setAttribute('role', isError ? 'alert' : 'status');
  };
  const connect = node('button', 'ui-button ui-button-primary', 'Connect RadioReference');
  connect.type = 'submit';
  const signOut = node('button', 'ui-button ui-button-danger', 'Log out and clear saved credentials');
  signOut.type = 'button';
  signOut.disabled = true;
  signOut.hidden = true;
  const accountActions = node('div', 'admin-form-actions');
  accountActions.append(signOut, connect);
  accountForm.append(formField('Username', userName), formField('Password', password),
    rememberSetting.control, accountMessage, accountActions);

  const regionForm = node('form',
    'admin-form admin-settings-form settings-card settings-card-form radioreference-region-form');
  const country = uiSelect([]);
  const state = uiSelect([]);
  country.setAttribute('aria-label', 'Country');
  state.setAttribute('aria-label', 'State or region');
  country.required = true;
  state.required = true;
  country.disabled = true;
  state.disabled = true;
  replaceRadioReferenceOptions(country, [], null, 'Connect an account first');
  replaceRadioReferenceOptions(state, [], null, 'Choose a country first');
  const regionMessage = node('div', 'ui-status');
  regionMessage.setAttribute('role', 'status');
  const saveRegion = node('button', 'ui-button ui-button-primary', 'Save lookup region');
  saveRegion.type = 'submit';
  saveRegion.disabled = true;
  const regionActions = node('div', 'ui-action-row');
  regionActions.append(saveRegion);
  const regionFooter = node('div', 'settings-form-footer');
  regionFooter.append(regionMessage, regionActions);
  const cancelRegion = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancelRegion.type = 'button';
  const regionSaved = node('div', 'admin-form-message');
  regionSaved.setAttribute('role', 'status');
  regionSaved.hidden = true;
  workspace.append(regionSaved);
  regionForm.append(node('h3', 'admin-settings-form-title', 'Lookup region'),
    node('p', 'settings-card-description',
      'Choose a state or province for frequency lookups.'),
    formField('Country', uiSelectFrame(country)), formField('State or region', uiSelectFrame(state)), regionFooter);

  gate.append(accountForm);
  let settingsModal = null;
  let configuration = null;
  let savedRegionValid = false;
  let accountDirty = false;
  let regionDirty = false;
  let regionTouched = false;
  let accountBusy = false;
  let regionBusy = false;
  const synchronizeModal = () => {
    settingsModal?.setDirty(accountDirty || regionDirty);
    settingsModal?.setBusy(accountBusy || regionBusy);
    settingsButton.disabled = accountBusy || regionBusy;
    connect.disabled = accountBusy || regionBusy;
    signOut.disabled = accountBusy || regionBusy || configuration?.account?.state !== 'VALID_PREMIUM';
    saveRegion.disabled = accountBusy || regionBusy || !regionDirty || !state.value || state.disabled ||
      configuration?.account?.state !== 'VALID_PREMIUM';
  };
  const regionEdited = () => { regionTouched = true; };
  regionForm.addEventListener('input', regionEdited, { capture: true });
  regionForm.addEventListener('change', regionEdited, { capture: true });
  const regionWorkflow = createFormWorkflow({ form: regionForm, submit: saveRegion,
    feedback: regionMessage, ready: false,
    changed: () => regionTouched &&
      (Number(country.value) !== Number(configuration?.country_id) ||
        Number(state.value) !== Number(configuration?.state_id)),
    modal: {
      setDirty: (value) => { regionDirty = value; synchronizeModal(); },
      setBusy: (value) => { regionBusy = value; synchronizeModal(); }
    }
  });
  const canSaveRegion = () => configuration?.account?.state === 'VALID_PREMIUM' &&
    Boolean(country.value && state.value) && !state.disabled;
  const setRegionFooter = (inModal) => {
    if (inModal) {
      regionForm.insertBefore(regionMessage, regionFooter);
      regionFooter.className = 'ui-modal-footer ui-action-row';
      regionFooter.replaceChildren(cancelRegion, saveRegion);
    } else {
      regionFooter.className = 'settings-form-footer';
      regionActions.replaceChildren(saveRegion);
      regionFooter.replaceChildren(regionMessage, regionActions);
    }
  };
  const placeRegionForm = () => {
    if (settingsModal) return;
    setRegionFooter(false);
    if (configuration?.account?.state === 'VALID_PREMIUM' && !savedRegionValid) {
      workspaceHeader.after(regionForm);
    } else regionForm.remove();
  };
  cancelRegion.addEventListener('click', () => settingsModal?.close());
  settingsButton.addEventListener('click', async () => {
    const forms = node('div', 'radioreference-settings-stack');
    const accountDetails = node('details', 'radioreference-account-details ui-surface');
    const accountSummary = node('summary');
    accountSummary.append(node('strong', '', `Connected as ${userName.value || 'RadioReference account'}`),
      node('span', 'muted', 'Change account or sign out'));
    accountDetails.append(accountSummary);
    forms.append(accountDetails);
    let presented = false;
    const modal = openReadOnlyModal('RadioReference settings', forms, {
      id: 'radioreference-settings', className: 'radioreference-settings-modal',
      returnFocusSelector: '.radioreference-settings-trigger',
      onClose: () => {
        if (settingsModal !== modal) return;
        const discardDraft = presented && (accountDirty || regionDirty);
        gate.append(accountForm);
        settingsModal = null;
        if (discardDraft) {
          userName.value = configuration?.account?.user_name || configuration?.stored_user_name || '';
          password.value = '';
          setUiToggle(remember, configuration?.credentials_stored === true);
          setAccountMessage(radioReferenceAccountMessage(configuration?.account));
          accountDirty = false;
          regionDirty = false;
          regionTouched = false;
          void loadRegions().catch(() => regionWorkflow.showFeedback('error',
            'Lookup region could not be loaded. Reload this page and try again.'));
        }
        placeRegionForm();
      }
    });
    if (!modal) return;
    settingsModal = modal;
    if (!await modal.ready || settingsModal !== modal) return;
    presented = true;
    accountDetails.append(accountForm);
    forms.append(regionForm);
    setRegionFooter(true);
    synchronizeModal();
    modal.focus(state.disabled ? country : state);
  });

  const importWorkspace = createRadioReferenceImportWorkspace({
    node, iconGlyph, metricCard, formField, uiSelectFrame, uiPill, uiSegmentedControl, table, browsingWorkflows,
    openReadOnlyModal, closeReadOnlyModal, requestJson, formatFrequency: frequency, formatNumber: number,
    href, anchor, modalFooter: aliasModalFooter, createAliasListPopupTrigger: aliasListPopupTrigger,
    directoryTimeoutMs: RADIO_REFERENCE_DIRECTORY_TIMEOUT_MILLISECONDS,
    mutationTimeoutMs: 65_000
  });
  workspace.append(importWorkspace.element);

  const updateAccount = (next, initializeUserName = false) => {
    configuration = next || configuration || {};
    const account = configuration?.account || {};
    const connected = account.state === 'VALID_PREMIUM';
    setAccountMessage(account.state === 'SIGNED_OUT' ? '' : radioReferenceAccountMessage(account),
      ['EXPIRED_PREMIUM', 'INVALID_CREDENTIALS', 'SECURE_TRANSPORT_REQUIRED', 'UNAVAILABLE']
        .includes(account.state));
    if (initializeUserName || !userName.value) {
      userName.value = account.user_name || configuration?.stored_user_name || '';
    }
    setUiToggle(remember, configuration?.credentials_stored === true);
    signOut.disabled = account.state === 'SIGNED_OUT';
    signOut.hidden = !connected;
    connect.textContent = connected ? 'Update account' : 'Connect RadioReference';
    country.disabled = !connected;
    state.disabled = !connected || !country.value;
    savedRegionValid = Number(configuration?.country_id) > 0 && Number(configuration?.state_id) > 0;
    regionWorkflow.setReady(canSaveRegion());
    placeRegionForm();
    importWorkspace.setConfiguration(configuration);
    loadingState.hidden = true;
    gate.hidden = connected;
    workspace.hidden = !connected;
    if (!connected) gate.append(accountForm);
    return connected;
  };

  let regionLoadSequence = 0;
  const loadStates = async (countryId, selectedStateId = null, sequence = ++regionLoadSequence) => {
    state.disabled = true;
    regionWorkflow.setReady(false);
    replaceRadioReferenceOptions(state, [], null, 'Loading states or regions…');
    const response = await requestJson(`/api/v1/admin/radioreference/states?country_id=${
      encodeURIComponent(countryId)}`, { csrf: false,
      timeoutMs: RADIO_REFERENCE_DIRECTORY_TIMEOUT_MILLISECONDS });
    if (sequence !== regionLoadSequence || country.value !== String(countryId) ||
        configuration?.account?.state !== 'VALID_PREMIUM') return null;
    const items = Array.isArray(response?.items) ? response.items : [];
    const selected = items.some((item) => String(item.id) === String(selectedStateId)) ?
      String(selectedStateId) : '';
    state.replaceChildren(...uiSelect(items.map((item) => ({ value: item.id,
      label: `${item.name}${item.abbreviation ? ` (${item.abbreviation})` : ''}` })), selected, true,
    items.length ? 'Choose a state or region' : 'No states or regions available').children);
    state.value = selected;
    state.disabled = !items.length;
    regionWorkflow.setReady(canSaveRegion());
    return Boolean(selected);
  };

  const loadRegions = async () => {
    const sequence = ++regionLoadSequence;
    country.disabled = true;
    state.disabled = true;
    regionWorkflow.setReady(false);
    regionWorkflow.showFeedback('loading', 'Loading lookup region…');
    try {
      const response = await requestJson('/api/v1/admin/radioreference/countries', { csrf: false,
        timeoutMs: RADIO_REFERENCE_DIRECTORY_TIMEOUT_MILLISECONDS });
      if (sequence !== regionLoadSequence || configuration?.account?.state !== 'VALID_PREMIUM') return;
      const items = sortRadioReferenceCountries(response?.items);
      const savedCountryAvailable = items.some((item) => String(item.id) === String(configuration?.country_id));
      const available = replaceRadioReferenceOptions(country, items, configuration?.country_id,
        'No countries available');
      const savedStateAvailable = available && await loadStates(country.value,
        savedCountryAvailable ? configuration?.state_id : null, sequence);
      if (sequence !== regionLoadSequence || configuration?.account?.state !== 'VALID_PREMIUM') return;
      country.disabled = !available;
      savedRegionValid = savedCountryAvailable && savedStateAvailable;
      regionWorkflow.setReady(canSaveRegion());
      placeRegionForm();
      regionWorkflow.showFeedback(available ? 'status' : 'error',
        available ? '' : 'Countries could not be loaded. Reload this page and try again.');
    } catch (error) {
      if (sequence !== regionLoadSequence || configuration?.account?.state !== 'VALID_PREMIUM') return;
      throw error;
    }
  };

  const accountEdited = () => { accountDirty = true; synchronizeModal(); };
  accountForm.addEventListener('input', accountEdited);
  accountForm.addEventListener('change', accountEdited);

  accountForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (accountBusy || regionBusy || !accountForm.reportValidity() || connect.disabled) return;
    connect.disabled = true;
    signOut.disabled = true;
    accountBusy = true;
    synchronizeModal();
    setAccountMessage('Connecting to RadioReference…');
    try {
      const next = await requestJson('/api/v1/admin/radioreference/session', {
        method: 'PUT', body: { userName: userName.value, password: password.value, remember: remember.checked },
        timeoutMs: 15_000
      });
      radioReferenceDetailCache.clear();
      password.value = '';
      accountDirty = false;
      synchronizeModal();
      if (updateAccount(next)) {
        importWorkspace.reload();
        try {
          await loadRegions();
        } catch (error) {
          regionWorkflow.showFeedback('error',
            'Lookup region could not be loaded. Reload this page and try again.');
        }
      }
    } catch (error) {
      password.value = '';
      setAccountMessage(error.message, true);
    } finally {
      accountBusy = false;
      synchronizeModal();
    }
  });

  signOut.addEventListener('click', async () => {
    if (accountBusy || regionBusy || signOut.disabled) return;
    signOut.disabled = true;
    connect.disabled = true;
    accountBusy = true;
    synchronizeModal();
    setAccountMessage('Signing out of RadioReference…');
    try {
      const next = await requestJson('/api/v1/admin/radioreference/session', { method: 'DELETE' });
      radioReferenceDetailCache.clear();
      password.value = '';
      userName.value = '';
      accountDirty = false;
      regionDirty = false;
      regionTouched = false;
      ++regionLoadSequence;
      settingsModal?.setBusy(false);
      settingsModal?.setDirty(false);
      closeReadOnlyModal(true);
      settingsModal = null;
      gate.append(accountForm);
      updateAccount(next);
      replaceRadioReferenceOptions(country, [], null, 'Connect an account first');
      replaceRadioReferenceOptions(state, [], null, 'Choose a country first');
      regionSaved.hidden = true;
      regionWorkflow.showFeedback('status', '');
    } catch (error) {
      setAccountMessage(error.message, true);
    } finally {
      accountBusy = false;
      synchronizeModal();
    }
  });

  country.addEventListener('change', async () => {
    regionSaved.hidden = true;
    regionWorkflow.showFeedback('loading', 'Loading states or regions…');
    const loading = loadStates(country.value);
    const sequence = regionLoadSequence;
    try {
      await loading;
      if (sequence !== regionLoadSequence) return;
      regionWorkflow.showFeedback('status', '');
    } catch (error) {
      if (sequence !== regionLoadSequence) return;
      regionWorkflow.showFeedback('error',
        'States or regions could not be loaded. Reload this page and try again.');
    }
  });
  state.addEventListener('change', () => {
    regionSaved.hidden = true;
    regionWorkflow.setReady(canSaveRegion());
  });

  regionForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (accountBusy || regionBusy) return;
    const savedInline = !settingsModal;
    await regionWorkflow.save(async () => {
      configuration = await requestJson('/api/v1/admin/radioreference/location', {
        method: 'PUT', body: { countryId: Number(country.value), stateId: Number(state.value) }
      });
      savedRegionValid = Number(configuration?.country_id) > 0 && Number(configuration?.state_id) > 0;
      importWorkspace.setConfiguration(configuration);
    }, {
      saving: 'Saving lookup region…', success: 'Lookup region saved.',
      onSuccess: () => {
        placeRegionForm();
        if (savedInline) {
          regionSaved.textContent = 'Lookup region saved.';
          regionSaved.hidden = false;
          settingsButton.focus({ preventScroll: true });
        }
      }
    });
  });

  try {
    const initial = await requestJson('/api/v1/admin/radioreference', { csrf: false });
    if (updateAccount(initial, true)) {
      try {
        await loadRegions();
      } catch (error) {
        regionWorkflow.showFeedback('error',
          'Lookup region could not be loaded. Reload this page and try again.');
      }
    }
  } catch (error) {
    setAccountMessage(error.message, true);
    loadingState.hidden = true;
    gate.hidden = false;
    gate.append(accountForm);
    connect.disabled = false;
  }
}

async function renderAdminSpectrumSnapSettings(target = content) {
  const body = node('div', 'admin-section-body spectrum-snap-settings');
  const form = node('form', 'admin-form settings-page-form ui-settings-form');
  const country = node('select');
  country.required = true;
  country.disabled = true;
  country.append(node('option', '', 'Loading countries…'));
  const message = node('div', 'admin-form-message', 'Loading…');
  message.setAttribute('role', 'status');
  const save = node('button', 'ui-button ui-button-primary', 'Save country');
  save.type = 'submit';
  save.disabled = true;
  const actions = node('div', 'admin-form-actions');
  actions.append(save);
  const footer = node('div', 'settings-form-footer');
  footer.append(message, actions);
  form.append(formField('Country', country, 'Only the United States is currently available.'), footer);
  body.append(form);
  const panel = section('Spectrum country', body);
  panel.classList.add('ui-settings-panel');
  target.append(panel);

  let confirmed = null;
  const workflow = createFormWorkflow({ form, submit: save, feedback: message, ready: false,
    changed: () => Boolean(confirmed) && country.value !== confirmed.countryCode });
  workflow.showFeedback('loading', 'Loading spectrum country…');
  const apply = (documentValue) => {
    confirmed = documentValue;
    country.replaceChildren(...documentValue.countries.map((item) => {
      const option = node('option', '', item.label);
      option.value = item.code;
      return option;
    }));
    country.value = documentValue.countryCode;
    country.disabled = false;
  };
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    await workflow.save(async () => {
      apply(await requestSpectrumSnapPresetDocument('/api/v1/admin/spectrum-snap-presets', 'PUT',
        country.value, confirmed.revision));
    }, { saving: 'Saving country…', success: 'Country saved.', onError: (error) => {
      if (!error.current) return { state: 'error', message: error.message };
      apply(error.current);
      return { state: 'warning', message: 'The spectrum country changed elsewhere. The saved value was loaded.' };
    } });
  });
  try {
    apply(await requestSpectrumSnapPresetDocument('/api/v1/admin/spectrum-snap-presets'));
    workflow.setReady(true);
    workflow.showFeedback('status', '');
  } catch (error) {
    workflow.showFeedback('error', error.message);
  }
}

function decodeReceiverSettingsEnvelope(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
      !Number.isInteger(value.revision) || value.revision < 1 ||
      !value.settings || typeof value.settings !== 'object' || Array.isArray(value.settings) ||
      Object.keys(value).sort().join('|') !== 'revision|settings' ||
      Object.keys(value.settings).sort().join('|') !== 'traffic_grant_age_out_milliseconds' ||
      !Number.isInteger(value.settings.traffic_grant_age_out_milliseconds) ||
      value.settings.traffic_grant_age_out_milliseconds < 100 ||
      value.settings.traffic_grant_age_out_milliseconds > 15000) {
    const error = new Error('Live timing could not be loaded. Reload the page and try again.');
    error.code = 'invalid_receiver_settings_response';
    throw error;
  }
  return {
    revision: value.revision,
    settings: { ...value.settings }
  };
}

async function requestReceiverSettings(method = 'GET', settings = null, revision = null) {
  const headers = { Accept: 'application/json' };
  const options = { method, headers };
  if (method === 'PUT') {
    if (!Number.isInteger(revision) || revision < 1) throw new Error('Reload Live timing before saving.');
    headers['Content-Type'] = 'application/json';
    headers['If-Match'] = `"${revision}"`;
    options.body = JSON.stringify(settings);
  }
  const response = await jsonDocumentFetch('/api/v1/admin/receiver-settings', options);
  let documentValue = null;
  try {
    documentValue = await response.json();
  } catch (_) { }
  if (!response.ok) {
    const failure = documentValue?.error && typeof documentValue.error === 'object' ? documentValue.error : null;
    const error = new Error(failure?.message || 'Live timing could not be saved. Try again.');
    error.status = response.status;
    error.code = failure?.code || (response.status === 409 ? 'receiver_settings_conflict' : 'receiver_settings_failed');
    if (response.status === 409) {
      try { error.current = decodeReceiverSettingsEnvelope(documentValue); } catch (_) { }
    }
    throw error;
  }
  return decodeReceiverSettingsEnvelope(documentValue);
}

async function renderAdminReceiverBehaviorSettings(target = content) {
  const body = node('div', 'admin-section-body receiver-settings');
  const form = node('form', 'admin-form settings-page-form ui-settings-form receiver-settings-form');
  const grantAge = node('input');
  grantAge.type = 'number';
  grantAge.min = '100';
  grantAge.max = '15000';
  grantAge.required = true;
  grantAge.disabled = true;
  const message = node('div', 'admin-form-message', 'Loading Live timing…');
  message.setAttribute('role', 'status');
  const save = node('button', 'ui-button ui-button-primary', 'Save Live timing');
  save.type = 'submit';
  save.disabled = true;
  const actions = node('div', 'admin-form-actions');
  actions.append(save);
  const footer = node('div', 'settings-form-footer');
  footer.append(message, actions);
  form.append(formField('Mark a traffic row idle after (milliseconds)', grantAge,
    'Applies to traffic rows on the Live page.'), footer);
  body.append(form);
  const panel = section('Live timing', body);
  panel.classList.add('ui-settings-panel');
  target.append(panel);

  let confirmed = null;
  const workflow = createFormWorkflow({ form, submit: save, feedback: message, ready: false,
    changed: () => Boolean(confirmed) && Number(grantAge.value) !==
      confirmed.settings.traffic_grant_age_out_milliseconds });
  workflow.showFeedback('loading', 'Loading Live timing…');
  const apply = (envelope) => {
    confirmed = envelope;
    const value = envelope.settings;
    grantAge.value = String(value.traffic_grant_age_out_milliseconds);
  };
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    await workflow.save(async () => {
      const next = await requestReceiverSettings('PUT', {
        traffic_grant_age_out_milliseconds: Number(grantAge.value)
      }, confirmed?.revision);
      apply(next);
    }, { saving: 'Saving Live timing…', success: 'Live timing saved.', onError: (error) => {
      if (error?.code === 'receiver_settings_conflict' && error.current) {
        apply(error.current);
        return { state: 'warning', message: 'Live timing changed elsewhere. The latest saved value was loaded.' };
      }
      return { state: 'error', message: error.message };
    } });
  });
  try {
    apply(await requestReceiverSettings());
    grantAge.disabled = false;
    workflow.setReady(true);
    workflow.showFeedback('status', '');
  } catch (error) {
    workflow.showFeedback('error', error.message);
  }
}

function decodeOperationalPreferencesEnvelope(value) {
  const settings = value?.settings;
  const options = value?.options;
  const fields = [
    'patch_group_streaming_option', 'audio_record_format', 'mp3_setting', 'mp3_input_audio_format',
    'mp3_normalize_audio', 'stats_logging_enabled', 'stats_detailed_history_enabled',
    'stats_logging_retention_days'
  ];
  if (!value || !/^[0-9a-f]{64}$/.test(String(value.revision || '')) ||
      !settings || typeof settings !== 'object' || Array.isArray(settings) ||
      !options || typeof options !== 'object' || Array.isArray(options) ||
      !fields.every((field) => Object.hasOwn(settings, field)) ||
      !Array.isArray(options.patch_group_streaming_options) ||
      !Array.isArray(options.audio_record_formats) || !Array.isArray(options.mp3_settings) ||
      !options.mp3_input_audio_formats_by_setting ||
      !Number.isInteger(options.minimum_stats_logging_retention_days) ||
      !Number.isInteger(options.maximum_stats_logging_retention_days)) {
    throw new Error('The receiver returned settings this page could not read. Reload the page and try again.');
  }
  return value;
}

async function requestOperationalPreference(method = 'GET', field = '', value = undefined, revision = '') {
  const path = `/api/v1/admin/operational-preferences${field ? `/${field}` : ''}`;
  const headers = { Accept: 'application/json' };
  const options = { method, headers };
  if (method === 'PUT') {
    if (!/^[0-9a-f]{64}$/.test(revision)) throw new Error('Reload the saved settings before saving.');
    headers['Content-Type'] = 'application/json';
    headers['If-Match'] = `"${revision}"`;
    options.body = JSON.stringify({ value });
  }
  const response = await jsonDocumentFetch(path, options);
  let documentValue = null;
  try { documentValue = await response.json(); } catch (_) { }
  if (!response.ok) {
    const failure = documentValue?.error && typeof documentValue.error === 'object' ? documentValue.error : null;
    const error = new Error(failure?.message || 'The setting could not be saved. Reload the page and try again.');
    error.status = response.status;
    if (response.status === 409) {
      try { error.current = decodeOperationalPreferencesEnvelope(documentValue); } catch (_) { }
    }
    throw error;
  }
  return decodeOperationalPreferencesEnvelope(documentValue);
}

async function renderAdminOperationalPreferences(renderContext = captureRenderContext(), options = {}) {
  const body = node('div', 'admin-section-body');
  const status = node('div', 'admin-form-message', 'Loading settings…');
  status.setAttribute('role', 'status');
  const reload = node('button', 'ui-button ui-button-secondary', 'Reload saved settings');
  reload.type = 'button';
  reload.disabled = true;
  const workspace = options.fields ? node('div', 'operational-preferences operational-preferences-focused') :
    node('div', 'settings-page-form ui-settings-form operational-preferences');
  const lanes = node('div', 'operational-preference-lanes');
  workspace.append(status, lanes);
  body.append(workspace);
  const panel = options.fields ? node('div', 'operational-preferences-page') :
    section('Call output & activity', body, sectionActionHost(reload));
  if (options.fields) {
    panel.append(body);
    lanes.append(section(options.title || 'Settings', null, sectionActionHost(reload)));
  }
  (options.target || content).append(panel);
  let confirmed = null;
  let saving = false;
  const drafts = new Map();

  const groups = [
    { area: 'output', title: 'Patch-group streaming',
      description: 'A patch group joins two or more talkgroups for one conversation.', fields: [
      { id: 'patch_group_streaming_option', label: 'Send each patch-group call as', kind: 'select',
        options: 'patch_group_streaming_options',
        detail: 'Individual Talkgroups may repeat the same audio.' }
    ] },
    { area: 'output', title: 'Call recordings',
      description: 'MP3 uses less storage; WAVE keeps uncompressed audio.', fields: [
      { id: 'audio_record_format', label: 'Recording format', kind: 'select',
        options: 'audio_record_formats' }
    ] },
    { area: 'output', title: 'MP3 audio',
      description: '', layout: 'wide', fields: [
      { id: 'mp3_setting', label: 'MP3 bit rate and quality', kind: 'select', options: 'mp3_settings',
        detail: 'Higher bit rates improve quality but use more storage and network bandwidth. Choices depend on ' +
          'the sample rate.' },
      { id: 'mp3_input_audio_format', label: 'MP3 sample rate and bit depth', kind: 'select' },
      { id: 'mp3_normalize_audio', label: 'Even out MP3 volume', kind: 'boolean' }
    ] },
    { area: 'activity', title: 'Saved activity',
      description: '', fields: [
      { id: 'stats_logging_enabled', label: 'Save activity summaries', kind: 'boolean',
        detail: 'When off: Main charts and saved system, channel, talkgroup, radio, and signal data stop updating. ' +
          'Activity tabs, P25 Visualizer, and activity in problem reports stop receiving new data.' },
      { id: 'stats_detailed_history_enabled', label: 'Save individual activity events', kind: 'boolean',
        detail: 'Requires activity summaries. When off: Activity tabs, source-radio lists, P25 Visualizer, and ' +
          'event history in problem reports stop receiving new events. Main charts and other saved summaries ' +
          'keep updating.' },
      { id: 'stats_logging_retention_days', label: 'Keep activity history for (days)', kind: 'number',
        detail: 'Automatically removes activity older than this many days. Lowering the value can permanently ' +
          'remove older saved activity.' }
    ] }
  ];

  function optionsFor(field) {
    if (field.id === 'mp3_input_audio_format') {
      return confirmed.options.mp3_input_audio_formats_by_setting[confirmed.settings.mp3_setting] || [];
    }
    const all = confirmed.options[field.options] || [];
    if (field.id !== 'mp3_setting') return all;
    const selectedFormat = confirmed.settings.mp3_input_audio_format;
    return all.filter((option) =>
      (confirmed.options.mp3_input_audio_formats_by_setting[option.value] || [])
        .some((format) => format.value === selectedFormat));
  }

  function renderFields() {
    if (!confirmed || !renderIsCurrent(renderContext)) return;
    const rendered = groups.filter((group) => !options.fields ||
      group.fields.some((field) => options.fields.includes(field.id))).map((group) => {
      const forms = group.fields.filter((field) => !options.fields || options.fields.includes(field.id)).map((field) => {
        const form = node('form', 'admin-form operational-preference-form');
        form.dataset.preference = field.id;
        const current = confirmed.settings[field.id];
        const draft = drafts.has(field.id) ? drafts.get(field.id) : current;
        let input;
        if (field.kind === 'select') {
          input = node('select');
          input.required = true;
          const choices = optionsFor(field);
          input.append(...choices.map((choice) => {
            const option = node('option', '', choice.label);
            option.value = choice.value;
            return option;
          }));
          if (draft !== current && !choices.some((choice) => choice.value === draft)) drafts.delete(field.id);
          input.value = drafts.has(field.id) ? drafts.get(field.id) : current;
          form.append(formField(field.label, input, field.detail || ''));
        } else if (field.kind === 'boolean') {
          const toggle = uiToggleField(field.label, draft, field.label, field.detail || '');
          input = toggle.querySelector('input');
          form.append(toggle);
        } else {
          input = node('input');
          input.type = 'number';
          input.required = true;
          input.step = '1';
          input.min = String(confirmed.options.minimum_stats_logging_retention_days);
          input.max = String(confirmed.options.maximum_stats_logging_retention_days);
          input.value = String(draft);
          form.append(formField(field.label, input, field.detail || ''));
        }
        const save = node('button', 'ui-button ui-button-primary', 'Save');
        save.type = 'submit';
        const state = node('span', 'operational-preference-state');
        const actions = node('div', 'ui-action-row operational-preference-actions');
        actions.append(state, save);
        const readValue = () => field.kind === 'boolean' ? input.checked :
          field.kind === 'number' ? Number(input.value) : input.value;
        const updateSave = () => {
          const changed = readValue() !== current;
          if (changed) drafts.set(field.id, readValue());
          else drafts.delete(field.id);
          save.disabled = saving || !changed;
          form.classList.toggle('is-dirty', changed);
          state.textContent = changed ? 'Unsaved change' : '';
          actions.hidden = !changed;
        };
        updateSave();
        input.addEventListener(field.kind === 'number' ? 'input' : 'change', updateSave);
        form.append(actions);
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          if (saving || save.disabled || !form.reportValidity()) return;
          saving = true;
          save.disabled = true;
          status.textContent = 'Saving…';
          try {
            confirmed = await requestOperationalPreference('PUT', field.id, readValue(), confirmed.revision);
            drafts.delete(field.id);
            status.textContent = 'Saved.';
            if (field.id === 'stats_logging_enabled' || field.id === 'stats_detailed_history_enabled') {
              await loadStatus(true);
            }
          } catch (error) {
            if (error.current) {
              confirmed = error.current;
              drafts.clear();
              status.textContent = 'These settings changed elsewhere. The saved settings were reloaded.';
            } else {
              status.textContent = error.message || 'The setting could not be saved. Reload the page and try again.';
            }
          } finally {
            saving = false;
            renderFields();
          }
        });
        return form;
      });
      const card = options.fields ? section(options.title || group.title,
        node('div', 'settings-card-body'), sectionActionHost(reload)) :
        settingsCard(group.title, group.description, ...forms);
      if (options.fields) {
        card.classList.add('ui-settings-panel');
        const cardBody = card.querySelector('.settings-card-body');
        if (group.description) cardBody.append(node('p', 'settings-card-description', group.description));
        cardBody.append(...forms);
      }
      card.classList.add('operational-preference-card');
      if (group.layout === 'wide') card.classList.add('operational-preference-card-wide');
      return { area: group.area, card };
    });
    const lane = (area, label) => {
      const host = node('div', 'operational-preference-lane');
      host.dataset.preferenceArea = area;
      const labelGroup = node('div', 'operational-preference-lane-heading');
      labelGroup.append(node('strong', '', label));
      const grid = settingsCardGrid(...rendered.filter((entry) => entry.area === area)
        .map((entry) => entry.card));
      grid.classList.add(`operational-preference-${area}-grid`);
      host.append(labelGroup, grid);
      return host;
    };
    if (options.fields) lanes.replaceChildren(...rendered.map((entry) => entry.card));
    else lanes.replaceChildren(
      lane('output', 'Calls & audio'),
      lane('activity', 'Activity history')
    );
  }

  reload.addEventListener('click', async () => {
    reload.disabled = true;
    try {
      confirmed = await requestOperationalPreference();
      drafts.clear();
      status.textContent = '';
      renderFields();
    } catch (error) {
      status.textContent = error.message || 'These settings are unavailable. Reload the page and try again.';
    } finally {
      reload.disabled = false;
    }
  });
  try {
    confirmed = await requestOperationalPreference();
    if (!renderIsCurrent(renderContext)) return;
    renderFields();
    status.textContent = '';
  } catch (error) {
    if (renderIsCurrent(renderContext)) {
      status.textContent = error.message || 'These settings are unavailable. Reload the page and try again.';
    }
  } finally {
    reload.disabled = false;
  }
  return panel;
}

function p25OverrideInput(label, field, value = '', options = {}) {
  const input = node('input');
  input.dataset.p25OverrideField = field;
  input.type = options.type || 'text';
  input.value = value;
  if (options.required) input.required = true;
  if (options.pattern) input.pattern = options.pattern;
  if (options.placeholder) input.placeholder = options.placeholder;
  if (options.min !== undefined) input.min = String(options.min);
  if (options.max !== undefined) input.max = String(options.max);
  if (options.step !== undefined) input.step = String(options.step);
  return formField(label, input, options.detail || '');
}

function p25OverrideNumber(value, divisor) {
  if (!Number.isFinite(Number(value))) return '';
  return String(Number((Number(value) / divisor).toFixed(6)));
}

function p25OverrideBandValue(value, divisor, precision, unit) {
  if (value === null || value === undefined || value === '' || !Number.isFinite(Number(value))) return '—';
  return `${(Number(value) / divisor).toFixed(precision)} ${unit}`;
}

function p25OverrideBandRow(band = null) {
  const row = node('section', 'ui-surface-inset p25-override-band-row');
  const header = node('div', 'p25-override-band-header');
  const title = node('h3', 'ui-record-card-title', band ? `Band ${band.identifier}` : 'New band');
  const type = node('select');
  type.dataset.p25OverrideField = 'type';
  [['FDMA', 'FDMA'], ['TDMA', 'P25 2-slot TDMA']].forEach(([value, label]) => {
    const option = node('option', '', label);
    option.value = value;
    type.append(option);
  });
  type.value = band?.type === 'TDMA' ? 'TDMA' : 'FDMA';
  const remove = iconButton('icon-trash', 'Remove band',
    'ui-button ui-button-danger-quiet ui-icon-button p25-override-remove');
  remove.addEventListener('click', () => row.remove());
  header.append(title, remove);
  const fields = node('div', 'p25-override-band-fields');
  fields.append(
    p25OverrideInput('Band ID', 'identifier', band?.identifier ?? '',
      { type: 'number', required: true, min: 0, max: 15, step: 1 }),
    formField('Type', type),
    p25OverrideInput('Base frequency (MHz)', 'base_frequency',
      p25OverrideNumber(band?.base_frequency, 1_000_000),
      { type: 'number', required: true, min: 0, step: 0.000001 }),
    p25OverrideInput('Bandwidth (kHz)', 'bandwidth', p25OverrideNumber(band?.bandwidth, 1_000),
      { type: 'number', required: true, min: 0.001, step: 0.001 }),
    p25OverrideInput('Spacing (kHz)', 'channel_spacing',
      p25OverrideNumber(band?.channel_spacing, 1_000),
      { type: 'number', required: true, min: 0.001, step: 0.001 }),
    p25OverrideInput('Offset (MHz)', 'transmit_offset',
      p25OverrideNumber(band?.transmit_offset, 1_000_000),
      { type: 'number', required: true, step: 0.000001 })
  );
  fields.addEventListener('input', () => {
    const identifier = fields.querySelector('[data-p25-override-field="identifier"]').value;
    title.textContent = identifier ? `Band ${identifier}` : 'New band';
  });
  row.append(header, fields);
  return row;
}

function p25OverrideIdentityRow(profile, knownSystems = []) {
  const wacn = profile?.wacn;
  const system = profile?.system;
  const known = knownSystems.find((row) => row.wacn === wacn && (row.system ?? row.system_id) === system);
  return { protocol: 'P25', wacn, system_id: system,
    radio_system_key: Number.isInteger(wacn) && wacn >= 0 && wacn <= 0xfffff &&
      Number.isInteger(system) && system >= 0 && system <= 0xfff ?
      `p25:${wacn.toString(16).padStart(5, '0')}:${system.toString(16).padStart(3, '0')}` : '',
    system_name: known?.system_name || profile?.system_name || '',
    radio_system_entity_ref: known?.radio_system_entity_ref || profile?.radio_system_entity_ref };
}

function p25OverrideDisplayName(profile, knownSystems = []) {
  return radioSystemDisplayName(p25OverrideIdentityRow(profile, knownSystems));
}

function p25OverrideProfileCard(profile = null, knownSystems = []) {
  const card = node('div', 'p25-override-profile');
  const body = node('div', 'p25-override-editor-body');
  const systemTitle = node('h3', 'ui-record-card-title', 'System and site');
  const identity = node('div', 'p25-override-identity');
  const systemName = node('p', 'ui-record-title');
  const updateSystemName = (value) => {
    const row = p25OverrideIdentityRow(value, knownSystems);
    systemName.replaceChildren();
    const name = radioSystemPrimaryName(row);
    if (name) systemName.append(radioSystemLink(row.radio_system_entity_ref, name));
    systemName.hidden = !name;
  };
  updateSystemName(profile);
  const hex = (value, width) => Number.isInteger(value) ? value.toString(16).toUpperCase().padStart(width, '0') : '';
  identity.append(
    p25OverrideInput('WACN (hex)', 'wacn', hex(profile?.wacn, 5),
      { required: true, pattern: '[0-9A-Fa-f]{1,5}', placeholder: 'BEE00' }),
    p25OverrideInput('System ID (hex)', 'system', hex(profile?.system, 3),
      { required: true, pattern: '[0-9A-Fa-f]{1,3}', placeholder: '49F' }),
    p25OverrideInput('RFSS (hex, optional)', 'rfss', hex(profile?.rfss, 2),
      { pattern: '[0-9A-Fa-f]{1,2}', placeholder: '01' }),
    p25OverrideInput('Site ID (hex, optional)', 'site', hex(profile?.site, 2),
      { pattern: '[0-9A-Fa-f]{1,2}', placeholder: '01' })
  );
  identity.addEventListener('input', () => {
    const wacn = identity.querySelector('[data-p25-override-field="wacn"]').value.trim();
    const system = identity.querySelector('[data-p25-override-field="system"]').value.trim();
    updateSystemName(/^[0-9a-f]{1,5}$/i.test(wacn) && /^[0-9a-f]{1,3}$/i.test(system) ?
      { wacn: parseInt(wacn, 16), system: parseInt(system, 16) } : null);
  });
  const bands = node('div', 'p25-override-bands');
  (profile?.bands || [null]).forEach((band) => bands.append(p25OverrideBandRow(band)));
  const addBand = node('button', 'ui-button ui-button-secondary', 'Add band');
  addBand.type = 'button';
  addBand.addEventListener('click', () => bands.append(p25OverrideBandRow()));
  const actions = node('div', 'ui-action-row p25-override-profile-actions');
  actions.append(addBand);
  body.append(systemTitle, systemName, identity,
    node('p', 'ui-field-detail', 'Enter both RFSS and Site ID, or leave both blank.'),
    node('h3', 'ui-record-card-title p25-override-bands-title', 'Replacement bands'), bands, actions);
  card.append(body);
  return card;
}

function p25OverrideProfilesFromForm(list) {
  const value = (host, field) => host.querySelector(`[data-p25-override-field="${field}"]`)?.value.trim() || '';
  const integer = (host, field, multiplier = 1) => Math.round(Number(value(host, field)) * multiplier);
  return [...list.querySelectorAll(':scope > .p25-override-profile')].map((profile) => {
    const rfss = value(profile, 'rfss');
    const site = value(profile, 'site');
    if (Boolean(rfss) !== Boolean(site)) throw new Error('Enter both RFSS and Site ID, or leave both blank.');
    const bands = [...profile.querySelectorAll('.p25-override-band-row')].map((band) => ({
      identifier: integer(band, 'identifier'),
      type: value(band, 'type'),
      base_frequency: integer(band, 'base_frequency', 1_000_000),
      bandwidth: integer(band, 'bandwidth', 1_000),
      channel_spacing: integer(band, 'channel_spacing', 1_000),
      transmit_offset: integer(band, 'transmit_offset', 1_000_000)
    }));
    if (!bands.length) throw new Error('Each P25 override must contain at least one band.');
    return {
      wacn: parseInt(value(profile, 'wacn'), 16),
      system: parseInt(value(profile, 'system'), 16),
      rfss: rfss ? parseInt(rfss, 16) : null,
      site: site ? parseInt(site, 16) : null,
      bands
    };
  });
}

async function requestP25BandplanOverrides(method = 'GET', profiles = null) {
  const headers = { Accept: 'application/json' };
  const options = { method, headers };
  if (method === 'PUT') {
    headers['Content-Type'] = 'application/json';
    options.body = JSON.stringify({ profiles: profiles.map(({ wacn, system, rfss, site, bands }) =>
      ({ wacn, system, rfss, site, bands })) });
  }
  const response = await jsonDocumentFetch('/api/v1/admin/p25-bandplan-overrides', options);
  let documentValue = null;
  try { documentValue = await response.json(); } catch (_) { }
  if (!response.ok) {
    const failure = documentValue?.error && typeof documentValue.error === 'object' ? documentValue.error : null;
    throw new Error(failure?.message || 'P25 band plan overrides could not be saved. Try again.');
  }
  if (!documentValue || !Array.isArray(documentValue.profiles)) {
    throw new Error('P25 band plan overrides could not be loaded. Reload the page and try again.');
  }
  return documentValue;
}

async function renderAdminP25BandplanOverrides() {
  const renderContext = captureRenderContext();
  const body = node('div', 'admin-section-body p25-overrides-workspace');
  const intro = node('p', 'p25-overrides-intro muted',
    'Site overrides take priority over system overrides.');
  const list = node('div', 'p25-override-profile-list');
  const message = node('div', 'admin-form-message', 'Loading P25 band plan overrides…');
  message.setAttribute('role', 'status');
  const add = node('button', 'ui-button ui-button-primary', 'Add P25 override');
  add.prepend(iconGlyph('icon-plus'));
  add.id = 'admin-add-p25-override';
  add.type = 'button';
  add.disabled = true;
  const save = node('button', 'ui-button ui-button-primary', 'Save overrides');
  save.type = 'button';
  save.disabled = true;
  const actions = node('div', 'ui-action-row');
  actions.append(save);
  const footer = node('div', 'ui-record-card-footer p25-override-footer');
  footer.append(actions, message);
  body.append(intro, list, footer);
  const titleActions = sectionActionHost(add);
  content.append(section('P25 band plan overrides', body, titleActions));
  let profiles = [];
  let knownSystems = [];
  let saving = false;
  const hex = (value, width) => Number.isInteger(value) ? value.toString(16).toUpperCase().padStart(width, '0') : '—';
  const displayName = (profile) => p25OverrideDisplayName(profile, knownSystems);
  const draftChanged = () => { message.textContent = 'Unsaved changes'; };

  const editProfile = (index = null) => {
    const existing = index === null ? null : profiles[index];
    const form = node('form', 'admin-form p25-overrides-form');
    const editorList = node('div', 'p25-override-profile-list');
    const card = p25OverrideProfileCard(existing, knownSystems);
    editorList.append(card);
    const status = node('div', 'admin-form-message');
    status.setAttribute('role', 'status');
    let modal;
    const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
    cancel.type = 'button';
    cancel.addEventListener('click', () => modal.close());
    const apply = node('button', 'ui-button ui-button-primary', existing ? 'Apply changes' : 'Add override');
    apply.type = 'submit';
    form.append(editorList, status, aliasModalFooter(cancel, apply));
    modal = openReadOnlyModal(existing ? `Edit P25 override · ${displayName(existing)}` : 'Add P25 override', form,
      { id: 'p25-override-editor', className: 'p25-override-editor-modal',
        returnFocusSelector: index === null ? '#admin-add-p25-override' : `#p25-override-edit-${index}` });
    form.addEventListener('input', () => modal.setDirty(true));
    form.addEventListener('change', () => modal.setDirty(true));
    editorList.addEventListener('click', (event) => {
      if (event.target.closest('button')) modal.setDirty(true);
    });
    form.addEventListener('submit', (event) => {
      event.preventDefault();
      if (!form.reportValidity()) return;
      try {
        const [next] = p25OverrideProfilesFromForm(editorList);
        if (index === null) profiles.push(next);
        else profiles[index] = next;
        draw();
        draftChanged();
        modal.setDirty(false);
        modal.close();
      } catch (error) {
        status.textContent = error.message;
      }
    });
  };

  const deleteProfile = (index) => {
    const profile = profiles[index];
    const scene = node('div');
    scene.append(node('p', '', `Delete the P25 override for ${displayName(profile)}?`),
      keyValues([['WACN', hex(profile.wacn, 5)], ['System ID', hex(profile.system, 3)],
        ['RFSS', profile.rfss === null ? 'All' : hex(profile.rfss, 2)],
        ['Site ID', profile.site === null ? 'All' : hex(profile.site, 2)]]),
      node('p', 'muted', 'The removal remains a draft until you save overrides.'));
    let modal;
    const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
    cancel.type = 'button';
    cancel.addEventListener('click', () => modal.close());
    const remove = node('button', 'ui-button ui-button-danger', 'Delete override');
    remove.type = 'button';
    remove.addEventListener('click', () => {
      profiles.splice(index, 1);
      draw();
      draftChanged();
      modal.close();
    });
    scene.append(aliasModalFooter(cancel, remove));
    modal = openReadOnlyModal('Delete P25 override', scene, { id: 'p25-override-delete',
      returnFocusSelector: '#admin-add-p25-override' });
  };

  function draw() {
    if (!profiles.length) {
      list.replaceChildren(node('div', 'ui-feedback ui-feedback-empty', 'No P25 overrides configured.'));
      return;
    }
    list.replaceChildren(...profiles.map((profile, index) => {
      const record = node('article', 'ui-record-section p25-override-record');
      const header = node('div', 'ui-record-card-header p25-override-profile-header');
      const label = node('div', 'ui-record-card-copy');
      const title = node('h3', 'ui-record-card-title');
      const system = p25OverrideIdentityRow(profile, knownSystems);
      title.append(radioSystemLink(system.radio_system_entity_ref, displayName(profile)));
      title.id = `p25-override-title-${index}`;
      record.setAttribute('aria-labelledby', title.id);
      const siteOverride = profile.rfss !== null && profile.site !== null;
      const scope = node('p', 'muted', siteOverride ?
        `RFSS ${hex(profile.rfss, 2)} · Site ${hex(profile.site, 2)}` : 'Entire system');
      label.append(title, scope);
      const icon = node('span', 'ui-record-card-icon');
      icon.append(iconGlyph('icon-radio-tower'));
      const controls = node('div', 'ui-action-row');
      const edit = node('button', 'ui-button ui-button-secondary', 'Edit');
      edit.prepend(iconGlyph('icon-edit'));
      edit.type = 'button';
      edit.id = `p25-override-edit-${index}`;
      edit.setAttribute('aria-label', `Edit P25 override ${displayName(profile)}`);
      edit.disabled = saving;
      edit.addEventListener('click', () => editProfile(index));
      const remove = iconButton('icon-trash', `Delete P25 override ${displayName(profile)}`,
        'ui-button ui-button-danger-quiet ui-icon-button');
      remove.disabled = saving;
      remove.addEventListener('click', () => deleteProfile(index));
      controls.append(edit, remove);
      header.append(icon, label, controls);
      const details = node('div', 'ui-record-card-body p25-override-record-body');
      const facts = keyValues([
        ['WACN', hex(profile.wacn, 5)], ['System ID', hex(profile.system, 3)],
        ['RFSS', siteOverride ? hex(profile.rfss, 2) : 'All'],
        ['Site ID', siteOverride ? hex(profile.site, 2) : 'All']
      ]);
      facts.classList.add('ui-record-facts', 'p25-override-profile-facts');
      const bandsHeading = node('div', 'p25-override-bands-heading');
      bandsHeading.append(node('h4', 'ui-record-card-title', 'Replacement bands'),
        node('span', 'muted', `${number(profile.bands.length)} band${profile.bands.length === 1 ? '' : 's'}`));
      const bands = node('div', 'p25-override-band-records');
      bands.append(...profile.bands.map((band) => {
        const item = node('section', 'ui-surface-inset p25-override-band-record');
        const bandHeader = node('div', 'p25-override-band-header');
        bandHeader.append(node('h5', 'ui-record-card-title', `Band ${band.identifier}`),
          uiPill(band.type === 'TDMA' ? 'P25 2-slot TDMA' : 'FDMA'));
        const values = keyValues([
          ['Base frequency', p25OverrideBandValue(band.base_frequency, 1_000_000, 6, 'MHz')],
          ['Bandwidth', p25OverrideBandValue(band.bandwidth, 1_000, 3, 'kHz')],
          ['Spacing', p25OverrideBandValue(band.channel_spacing, 1_000, 3, 'kHz')],
          ['Offset', p25OverrideBandValue(band.transmit_offset, 1_000_000, 6, 'MHz')]
        ]);
        values.classList.add('ui-record-facts', 'p25-override-band-facts');
        item.append(bandHeader, values);
        return item;
      }));
      details.append(facts, bandsHeading, bands);
      record.append(header, details);
      return record;
    }));
  }
  add.addEventListener('click', () => editProfile());
  save.addEventListener('click', async () => {
    if (saving || save.disabled) return;
    saving = true;
    add.disabled = true;
    save.disabled = true;
    draw();
    message.textContent = 'Saving overrides…';
    try {
      const documentValue = await requestP25BandplanOverrides('PUT', profiles);
      profiles = documentValue.profiles;
      knownSystems = documentValue.known_systems || knownSystems;
      message.textContent = 'Overrides saved.';
    } catch (error) {
      message.textContent = error.message;
    } finally {
      saving = false;
      add.disabled = false;
      save.disabled = false;
      draw();
    }
  });
  try {
    const documentValue = await requestP25BandplanOverrides();
    if (!renderIsCurrent(renderContext)) return;
    profiles = documentValue.profiles;
    knownSystems = documentValue.known_systems || [];
    draw();
    message.textContent = '';
    add.disabled = false;
    save.disabled = false;
  } catch (error) {
    message.textContent = error.message;
  }
}

function adminStatusBytes(value) {
  const numeric = typeof value === 'number' ? value : Number.NaN;
  if (!Number.isFinite(numeric) || numeric < 0) return '—';
  if (numeric >= 1073741824) return `${(numeric / 1073741824).toFixed(1)} GB`;
  if (numeric >= 1048576) return `${(numeric / 1048576).toFixed(numeric >= 10485760 ? 0 : 1)} MB`;
  if (numeric >= 1024) return `${(numeric / 1024).toFixed(0)} KB`;
  return `${number(numeric)} B`;
}

function adminDatabaseDisplay(database) {
  if (typeof database?.database_exists !== 'boolean') return 'Unknown';
  if (!database.database_exists) return 'No saved activity';
  const size = adminStatusBytes(database.database_bytes);
  return size === '—' ? 'Available' : size;
}

function receiverHealthText(value, fallback = '—') {
  if (value === null || value === undefined) return fallback;
  const text = String(value).trim();
  return text || fallback;
}

function receiverHealthTime(value) {
  return dateTime(value) || node('span', 'muted', '—');
}

function receiverHealthSeverityBadge(value) {
  const severity = receiverHealthSeverity(value);
  const label = severity === 'critical' ? 'Action needed' : severity === 'warning' ? 'Check soon' : 'Normal';
  const tone = severity === 'critical' ? 'danger' : severity === 'warning' ? 'warning' : 'success';
  return uiPill(label, tone);
}

function receiverHealthStatus(value) {
  const severity = receiverHealthSeverity(value);
  return uiStatus(severity === 'critical' ? 'Action needed' : severity === 'warning' ? 'Check soon' : 'Normal',
    severity === 'critical' ? 'danger' : severity === 'warning' ? 'warning' : 'success');
}

function receiverHealthScope(row) {
  const name = radioSystemPrimaryName(row);
  const channel = receiverHealthText(row?.channel_name, '');
  return receiverHealthText(row?.display_scope, '') || (name ?
    [...new Set([name, channel].filter(Boolean))].join(' · ') : receiverHealthText(row?.scope, 'Receiver'));
}

function receiverHealthScopeLink(row) {
  const label = receiverHealthScope(row);
  const configurationId = receiverHealthText(row?.configuration_id, '');
  return configurationId && viewAllowed('channel-setup') ?
    anchor(label, href('channel-setup', { channel: configurationId })) : label;
}

function receiverHealthIncident(incident, resolved = false, expanded = false, onToggle = null) {
  const severity = receiverHealthSeverity(incident.severity);
  const card = node(resolved ? 'details' : 'article',
    `ui-record-card${resolved ? ' ui-section-disclosure' : ''} receiver-health-incident receiver-health-${severity}`);
  const heading = node(resolved ? 'summary' : 'div',
    `${resolved ? 'ui-section-summary' : 'ui-record-card-header'} receiver-health-incident-heading`);
  const identity = node('div', 'ui-record-card-copy receiver-health-incident-identity');
  const scope = node('p', 'muted receiver-health-incident-scope');
  scope.append(receiverHealthScopeLink(incident));
  identity.append(node('h3', 'ui-record-card-title', receiverHealthText(incident.title, 'Receiver issue')),
    scope);
  if (resolved) {
    const resolvedSummary = node('p', 'muted receiver-health-incident-resolved-summary');
    resolvedSummary.append('Cleared ', receiverHealthTime(incident.resolved_at_ms));
    identity.append(resolvedSummary);
  }
  heading.append(identity, receiverHealthSeverityBadge(incident.severity));

  const facts = node('dl', 'ui-fact-list receiver-health-incident-facts');
  const entries = [
    ['Started', receiverHealthTime(incident.opened_at_ms)],
    ['Last detected', receiverHealthTime(incident.last_seen_ms)]
  ];
  if (receiverHealthScope(incident) !== receiverHealthText(incident.scope, 'Receiver')) {
    entries.push(['Radio identity', receiverHealthText(incident.scope)]);
  }
  if (resolved) entries.push(['Cleared', receiverHealthTime(incident.resolved_at_ms)]);
  entries.forEach(([label, value]) => {
    facts.append(node('dt', '', label));
    const detail = node('dd');
    detail.append(valueNode(value));
    facts.append(detail);
  });

  const guidance = node('dl', 'ui-facts ui-record-facts receiver-health-incident-guidance');
  [
    ['What happened', incident.observed],
    ['Possible cause', incident.likely_cause],
    ['What this may affect', incident.impact],
    ['What to do', incident.check_next]
  ].forEach(([label, value]) => {
    const item = node('div', 'ui-fact receiver-health-guidance-item');
    item.append(node('dt', '', label), node('dd', '', receiverHealthText(value)));
    guidance.append(item);
  });
  const body = node('div', 'ui-record-card-body receiver-health-incident-body');
  body.append(facts, guidance);
  card.append(heading, body);
  if (resolved) {
    heading.dataset.receiverHealthFocus = `resolved-incident:${receiverHealthResolvedIncidentKey(incident)}`;
    card.open = expanded;
    card.addEventListener('toggle', () => onToggle?.(card.open));
  }
  return card;
}

function receiverHealthResolvedIncidentKey(incident) {
  const occurrence = String(incident?.occurrence_id ?? '').trim();
  if (occurrence) return `occurrence:${occurrence}`;
  return ['fallback', incident?.code, incident?.scope, incident?.opened_at_ms, incident?.resolved_at_ms]
    .map((value) => String(value ?? '')).join('\u0000');
}

function receiverHealthSortedResolvedIncidents(incidents, sort) {
  const sorted = [...incidents];
  const compareText = (left, right) => String(left || '').localeCompare(String(right || ''), undefined,
    { sensitivity: 'base', numeric: true });
  sorted.sort((left, right) => {
    if (sort === 'type') {
      const title = compareText(left.title || left.code, right.title || right.code);
      if (title) return title;
      const code = compareText(left.code, right.code);
      if (code) return code;
      const scope = compareText(left.scope, right.scope);
      if (scope) return scope;
    }
    const resolved = Number(right.resolved_at_ms || 0) - Number(left.resolved_at_ms || 0);
    if (resolved) return resolved;
    return compareText(right.occurrence_id, left.occurrence_id);
  });
  return sorted;
}

function receiverHealthResolvedPage(incidents, sort, requestedPage) {
  const sorted = receiverHealthSortedResolvedIncidents(incidents, sort);
  const pageCount = Math.ceil(sorted.length / RECEIVER_HEALTH_RESOLVED_PAGE_SIZE);
  const numericPage = Number(requestedPage);
  const page = Math.max(0, Math.min(Number.isFinite(numericPage) ? Math.trunc(numericPage) : 0,
    Math.max(0, pageCount - 1)));
  const offset = page * RECEIVER_HEALTH_RESOLVED_PAGE_SIZE;
  const rows = sorted.slice(offset, offset + RECEIVER_HEALTH_RESOLVED_PAGE_SIZE);
  return {
    rows,
    page,
    page_count: pageCount,
    total_count: sorted.length,
    offset,
    limit: RECEIVER_HEALTH_RESOLVED_PAGE_SIZE,
    has_more: offset + rows.length < sorted.length
  };
}

function receiverHealthPruneExpandedResolvedIncidents(incidents) {
  const current = new Set(incidents.map(receiverHealthResolvedIncidentKey));
  receiverHealthController.expandedResolvedIncidents.forEach((key) => {
    if (!current.has(key)) receiverHealthController.expandedResolvedIncidents.delete(key);
  });
}

function receiverHealthIncidentList(incidents, resolved = false) {
  if (!incidents.length) {
    const empty = node('div', 'ui-feedback receiver-health-empty');
    empty.append(resolved ? 'No issues have cleared recently.' :
      uiStatus('No receiver issues need attention.', 'success'));
    return empty;
  }
  const list = node('div', 'receiver-health-incident-list');
  list.append(...incidents.map((incident) => {
    if (!resolved) return receiverHealthIncident(incident);
    const key = receiverHealthResolvedIncidentKey(incident);
    return receiverHealthIncident(incident, true,
      receiverHealthController.expandedResolvedIncidents.has(key), (open) => {
        if (open) receiverHealthController.expandedResolvedIncidents.add(key);
        else receiverHealthController.expandedResolvedIncidents.delete(key);
      });
  }));
  return list;
}

function receiverHealthResolvedPager(page, onPage) {
  const navigation = browsingWorkflows.createBrowsingPager({ node,
    className: 'receiver-health-resolved-pager', ariaLabel: 'Recently cleared issues',
    countText: `${browsingWorkflows.pageRangeText({ offset: page.offset, visible: page.rows.length,
      total: page.total_count, label: 'Cleared issues', format: number })} · ` +
      `Page ${number(page.page + 1)} of ${number(page.page_count)}`,
    previous: { enabled: page.page > 0, onClick: () => onPage(page.page - 1),
      focusKey: 'resolved-previous' },
    next: { enabled: page.has_more, onClick: () => onPage(page.page + 1), focusKey: 'resolved-next' }
  });
  navigation.dataset.receiverHealthFocus = 'resolved-pager';
  navigation.tabIndex = -1;
  return navigation;
}

function receiverHealthResolvedSection(incidents) {
  receiverHealthPruneExpandedResolvedIncidents(incidents);
  if (!incidents.length) {
    receiverHealthController.resolvedPage = 0;
    return receiverHealthSection('resolved', 'Recently cleared', receiverHealthIncidentList(incidents, true),
      null, 'No recently cleared issues');
  }
  const body = node('div');
  const sort = node('select', 'ui-select receiver-health-resolved-select');
  sort.setAttribute('aria-label', 'Sort cleared issues');
  sort.dataset.receiverHealthFocus = 'resolved-sort';
  [['recent', 'Most recently cleared'], ['type', 'Issue type (A–Z)']].forEach(([value, label]) => {
    const option = node('option', '', label);
    option.value = value;
    option.selected = receiverHealthController.resolvedSort === value;
    sort.append(option);
  });
  const control = node('label', 'receiver-health-resolved-sort');
  control.append(node('span', '', 'Sort'), sort);
  const draw = (focusPager = false) => {
    const page = receiverHealthResolvedPage(incidents, receiverHealthController.resolvedSort,
      receiverHealthController.resolvedPage);
    receiverHealthController.resolvedPage = page.page;
    const paginator = receiverHealthResolvedPager(page, (nextPage) => {
      receiverHealthController.resolvedPage = nextPage;
      draw(true);
    });
    body.replaceChildren(receiverHealthIncidentList(page.rows, true), paginator);
    if (focusPager) paginator.focus();
  };
  sort.addEventListener('change', () => {
    receiverHealthController.resolvedSort = sort.value === 'type' ? 'type' : 'recent';
    receiverHealthController.resolvedPage = 0;
    draw();
  });
  draw();
  return receiverHealthSection('resolved', 'Recently cleared', body, control,
    `${number(incidents.length)} cleared issue${incidents.length === 1 ? '' : 's'}`);
}

let receiverHealthSectionSequence = 0;

function receiverHealthSection(key, title, child, action = null, summary = '', status = null) {
  const wrapper = node('section', 'section ui-section ui-settings-panel ui-section-collapsible receiver-health-section');
  wrapper.dataset.receiverHealthSection = key;
  const titleBar = node('div', 'section-title ui-section-title');
  const body = node('div', 'ui-settings-panel-body receiver-health-section-body');
  body.id = `receiver-health-section-body-${++receiverHealthSectionSequence}`;
  if (child) body.append(child);

  const toggle = node('button', 'ui-disclosure-toggle receiver-health-section-toggle');
  toggle.type = 'button';
  const copy = node('span', 'ui-disclosure-copy');
  copy.append(node('span', '', title));
  if (summary) copy.append(node('small', '', summary));
  toggle.append(copy);
  if (status) toggle.append(status);
  toggle.dataset.receiverHealthFocus = `section:${key}`;
  toggle.setAttribute('aria-controls', body.id);
  const applyExpanded = (expanded) => {
    toggle.setAttribute('aria-expanded', String(expanded));
    body.hidden = !expanded;
    wrapper.classList.toggle('collapsed', !expanded);
  };
  applyExpanded(receiverHealthController.openHealthSections.has(key));
  toggle.addEventListener('click', () => {
    const expanded = body.hidden;
    if (expanded) receiverHealthController.openHealthSections.add(key);
    else receiverHealthController.openHealthSections.delete(key);
    applyExpanded(expanded);
  });

  titleBar.append(toggle);
  if (action) titleBar.append(action);
  wrapper.append(titleBar, body);
  return wrapper;
}

function receiverHealthResourceScale(row) {
  const numeric = Number(row?.value);
  const available = Number.isFinite(numeric) && numeric >= 0;
  const label = receiverHealthText(row?.label).toLowerCase();
  const unit = receiverHealthText(row?.unit, '').toLowerCase();
  const maximum = unit === '%' ? 100 :
    label === 'time spent freeing memory' && unit === 'ms in last sample' ?
      RECEIVER_HEALTH_GC_BAR_MAXIMUM_MILLISECONDS : available ? Math.max(1, numeric) : 100;
  return {
    available,
    maximum,
    value: available ? Math.min(maximum, numeric) : 0
  };
}

function receiverHealthResourceBar(row) {
  const severity = receiverHealthSeverity(row.severity);
  const label = receiverHealthText(row.label, 'Computer resource');
  const value = receiverHealthText(row.value);
  const unit = receiverHealthText(row.unit, '');
  const formattedValue = unit ? `${value} ${unit}` : value;
  const scale = receiverHealthResourceScale(row);
  const item = metricCard(label, row.value, value);
  item.classList.remove('ui-metric-blue');
  item.classList.add('receiver-health-resource-bar', 'ui-metric-compact', 'ui-metric-meter',
    `receiver-health-${severity}`,
    `ui-metric-${severity === 'critical' ? 'danger' : severity === 'warning' ? 'warning' : 'success'}`);
  const copy = item.querySelector('.ui-metric-copy');
  const labelNode = copy.querySelector('.ui-metric-label');
  const heading = node('div', 'ui-metric-heading receiver-health-resource-heading');
  labelNode.replaceWith(heading);
  heading.append(labelNode, receiverHealthStatus(row.severity));
  const reading = copy.querySelector('strong');
  reading.classList.add('receiver-health-resource-value');
  if (unit) reading.append(node('small', 'ui-metric-unit', unit));
  const progress = node('progress', 'ui-metric-progress receiver-health-resource-progress');
  progress.max = scale.maximum;
  progress.value = scale.value;
  progress.setAttribute('aria-label', label);
  progress.setAttribute('aria-valuetext', scale.available ? formattedValue : 'Unavailable');
  copy.append(progress);
  const detail = receiverHealthText(row.detail, '');
  if (detail) copy.append(node('small', 'ui-metric-detail receiver-health-resource-detail', detail));
  return item;
}

function receiverHealthHostResourceOverview(snapshot) {
  const group = snapshot.measurements.find((measurement) =>
    receiverHealthText(measurement.id).toLowerCase() === 'host');
  const body = node('div', 'ui-metric-grid ui-metric-grid-embedded ui-metric-grid-4 receiver-health-resource-bars');
  if (group?.rows?.length) body.append(...group.rows.map(receiverHealthResourceBar));
  else body.append(node('div', 'ui-feedback receiver-health-empty', 'Computer resource data is unavailable.'));
  return receiverHealthSection('host-overview', 'Computer resources', body);
}

function receiverHealthMeasurementRow(row) {
  const severity = receiverHealthSeverity(row.severity);
  const item = node('div', `ui-record-section receiver-health-measurement-row receiver-health-${severity}`);
  item.setAttribute('role', 'listitem');
  const heading = node('div', 'ui-record-card-header receiver-health-measurement-heading');
  const identity = node('div', 'ui-record-card-copy');
  const scope = node('p', 'muted receiver-health-measurement-scope');
  scope.append(receiverHealthScopeLink(row));
  const label = node('div', 'ui-record-title receiver-health-measurement-label',
    receiverHealthText(row.display_label || row.label));
  identity.append(scope, label);
  const reading = node('div', 'receiver-health-measurement-value');
  const value = node('strong', '', receiverHealthText(row.value));
  const unit = receiverHealthText(row.unit, '');
  if (unit) value.append(node('small', 'ui-metric-unit', unit));
  reading.append(value);
  heading.append(identity, reading, receiverHealthStatus(row.severity));
  item.append(heading);
  const detail = receiverHealthText(row.detail, '');
  if (detail) item.append(node('div', 'ui-record-card-body muted receiver-health-measurement-detail', detail));
  if (row.display_label && row.display_label !== row.label) {
    const technical = node('details', 'ui-section-disclosure ui-section-disclosure-flat');
    technical.append(node('summary', 'ui-section-summary', 'Radio identity'),
      keyValues([['Receiver', receiverHealthText(row.scope)], ['Identity', receiverHealthText(row.label)]]));
    const technicalBody = node('div', 'ui-record-card-body');
    technicalBody.append(technical);
    item.append(technicalBody);
  }
  return item;
}

function receiverHealthMeasurementGroup(group, index) {
  const body = node('div', 'ui-record-card receiver-health-measurement-list');
  body.setAttribute('role', 'list');
  if (group.rows.length) body.append(...group.rows.map(receiverHealthMeasurementRow));
  else body.append(node('div', 'ui-feedback receiver-health-empty', 'No measurements available.'));
  const title = receiverHealthText(group.title, 'Detailed measurements');
  const key = `measurement:${receiverHealthText(group.id, `${title}:${index}`)}`;
  const severity = group.rows.some((row) => receiverHealthSeverity(row.severity) === 'critical') ? 'critical' :
    group.rows.some((row) => receiverHealthSeverity(row.severity) === 'warning') ? 'warning' : 'healthy';
  return receiverHealthSection(key, title, body, null,
    `${number(group.rows.length)} measurement${group.rows.length === 1 ? '' : 's'}`,
    group.rows.length ? receiverHealthStatus(severity) : uiStatus('Unavailable', 'neutral'));
}

function receiverHealthRefreshButton() {
  const refresh = node('button', 'ui-button ui-button-secondary', 'Check again');
  refresh.type = 'button';
  refresh.dataset.receiverHealthFocus = 'refresh';
  refresh.addEventListener('click', async () => {
    refresh.disabled = true;
    await Promise.all([receiverHealthController.refresh(), loadStatus(true)]);
    if (refresh.isConnected) refresh.disabled = false;
  });
  return refresh;
}

function receiverHealthAccountSettingNotice(snapshot) {
  const settings = receiverHealthAccountAlertSummary(snapshot, activeUserPreferences());
  const notice = node('aside', 'receiver-health-account-setting');
  let message = '';
  if (settings.disabled_count > 0) {
    message = `${number(settings.disabled_count)} current issue${settings.disabled_count === 1 ? '' : 's'} ` +
      `${settings.disabled_count === 1 ? 'is' : 'are'} hidden from your status icon.`;
  }
  const settingsLink = node('button', 'ui-button ui-button-secondary', 'Choose status icon issues');
  settingsLink.type = 'button';
  settingsLink.id = 'receiver-health-alert-settings';
  settingsLink.dataset.receiverHealthFocus = 'alert-settings';
  settingsLink.addEventListener('click', () =>
    openStatusIconSettings('#receiver-health-alert-settings'));
  if (message) notice.append(node('span', '', message));
  notice.append(settingsLink);
  return notice;
}

function receiverHealthFocusedControl(host) {
  const active = document.activeElement;
  return active && host.contains(active) ? active.dataset.receiverHealthFocus || '' : '';
}

function receiverHealthRestoreFocus(host, key) {
  if (!key) return;
  const target = [...host.querySelectorAll('[data-receiver-health-focus]')]
    .find((element) => element.dataset.receiverHealthFocus === key);
  target?.focus({ preventScroll: true });
}

function renderReceiverHealthPage(host, snapshot, stale, lastError) {
  const focusedControl = receiverHealthFocusedControl(host);
  host.replaceChildren();
  if (!snapshot) {
    const message = stale ? (lastError || 'Receiver status is unavailable right now. Select Check again to try again.') :
      'Loading receiver status…';
    const body = node('div');
    body.append(node('div', stale ? 'ui-notice ui-notice-warning' :
      'ui-feedback ui-feedback-loading receiver-health-loading-message', message));
    host.append(receiverHealthSection('current', 'Summary', body, receiverHealthRefreshButton()),
      receiverHealthSavedActivitySection());
    receiverHealthRestoreFocus(host, focusedControl);
    return;
  }

  const summary = snapshot.summary;
  const stateLabel = stale ? 'Status out of date' : summary.severity === 'critical' ? 'Action needed' :
    summary.severity === 'warning' ? 'Check soon' : 'Normal';
  const overview = node('div', 'receiver-health-overview');
  const status = metricCard('Receiver status', summary.active_count, stateLabel);
  status.classList.remove('ui-metric-blue');
  status.classList.add('receiver-health-overview-state',
    `receiver-health-${stale ? 'stale' : summary.severity}`,
    `ui-metric-${stale ? 'neutral' : summary.severity === 'critical' ? 'danger' :
      summary.severity === 'warning' ? 'warning' : 'success'}`);
  const overviewMetrics = metrics([
    ['Current issues', summary.active_count],
    ['Need action', summary.critical_count],
    ['Check soon', summary.warning_count]
  ], true);
  overviewMetrics.classList.add('ui-metric-grid-4', 'ui-metric-grid-inline', 'receiver-health-overview-metrics');
  overviewMetrics.prepend(status);
  overview.append(overviewMetrics);
  const timing = node('dl', 'ui-fact-list receiver-health-timing');
  [
    ['Monitoring since', receiverHealthTime(snapshot.started_at_ms)],
    ['Last update', receiverHealthTime(snapshot.generated_at_ms)]
  ].forEach(([label, value]) => {
    timing.append(node('dt', '', label));
    const detail = node('dd');
    detail.append(valueNode(value));
    timing.append(detail);
  });
  const footer = node('div', 'receiver-health-overview-footer');
  footer.append(timing, receiverHealthAccountSettingNotice(snapshot));
  overview.append(footer);
  if (stale) overview.append(node('div', 'ui-notice ui-notice-warning receiver-health-stale-notice',
    'Live status is delayed. Showing the last update received.'));

  const issues = node('div', 'ui-settings-page receiver-health-issues-grid');
  issues.classList.toggle('receiver-health-issues-grid-active', snapshot.active.length > 0);
  issues.append(receiverHealthSection('active', 'Issues needing attention',
    receiverHealthIncidentList(snapshot.active), null,
    `${number(summary.active_count)} current issue${summary.active_count === 1 ? '' : 's'}`),
    receiverHealthResolvedSection(snapshot.resolved));
  host.append(receiverHealthSection('current', 'Receiver overview', overview, receiverHealthRefreshButton()),
    receiverHealthHostResourceOverview(snapshot),
    receiverHealthSavedActivitySection(),
    issues);
  const diagnostics = node('section', 'receiver-health-diagnostics');
  diagnostics.setAttribute('aria-label', 'Receiver diagnostics');
  const heading = node('div', 'ui-heading-group ui-heading-group-quiet receiver-health-diagnostics-heading');
  const measurementCount = snapshot.measurements.reduce((total, group) => total + group.rows.length, 0);
  heading.append(node('h2', '', 'Receiver diagnostics'), node('p', '',
    `${number(snapshot.measurements.length)} groups · ${number(measurementCount)} measurements`));
  const groups = node('div', 'ui-settings-page receiver-health-diagnostics-grid');
  if (snapshot.measurements.length) {
    groups.append(...snapshot.measurements.map(receiverHealthMeasurementGroup));
  } else {
    groups.append(receiverHealthSection('measurements', 'Detailed measurements', node('div', 'ui-feedback receiver-health-empty',
      'No measurements available.')));
  }
  diagnostics.append(heading, groups);
  host.append(diagnostics);
  receiverHealthRestoreFocus(host, focusedControl);
}

async function renderAdminHealth() {
  const host = node('div', 'ui-settings-page receiver-health-page');
  content.append(host);
  receiverHealthController.bindPage(host);
  void receiverHealthController.refresh();
}

function preferenceCheckbox(name, label, checked, detail = '') {
  const toggle = uiToggle(checked === true, label);
  const input = toggle.querySelector('input');
  input.name = name;
  const copy = node('span', 'admin-toggle-copy');
  copy.append(node('strong', '', label));
  if (detail) copy.append(node('span', '', detail));
  const control = node('div', 'admin-toggle-control ui-field-row');
  control.append(copy, toggle);
  return { input, control };
}

function preferenceSelect(name, choices, selected) {
  const select = node('select', 'ui-select');
  select.name = name;
  choices.forEach(([value, label]) => {
    const option = node('option', '', label);
    option.value = value;
    select.append(option);
  });
  select.value = selected;
  return select;
}

function settingsCard(title, description, ...items) {
  const card = node('section', 'settings-card');
  if (route.get('view') === 'admin') card.classList.add('ui-settings-panel');
  const header = node('div', 'settings-card-header');
  header.append(node('h3', 'settings-card-title', title));
  if (description) header.append(node('p', 'settings-card-description', description));
  const body = node('div', 'settings-card-body');
  body.append(...items);
  card.append(header, body);
  return card;
}

function settingsCardGrid(...cards) {
  const grid = node('div', 'settings-card-grid');
  grid.append(...cards);
  return grid;
}

function settingsSummary(rows) {
  const summary = node('dl', 'settings-summary');
  rows.forEach(([label, value]) => {
    summary.append(node('dt', '', label), node('dd', '', value));
  });
  return summary;
}

function settingsEnabled(value) {
  return value === true ? 'On' : 'Off';
}

function sourceNameDisplayLabel(mode) {
  return ({ talker_alias: 'Talker Alias preferred', source_alias: 'Source Alias preferred', both: 'Both' })[mode];
}

function selectedScanListSummary(ids) {
  if (!ids.length) return 'None';
  const names = new Map((webCallPlayer?.viewState()?.scanLists || [])
    .map((scanList) => [Number(scanList.id), scanList.name]));
  return ids.map((id) => names.get(id) || `Scan list ${id}`).join(', ');
}

function disabledHealthAlertSummary(codes) {
  if (!codes.length) return 'None';
  const names = new Map(receiverHealthAlertGroups.flatMap((group) => group.alerts)
    .map((alert) => [alert.id, alert.name]));
  return codes.map((code) => names.has(code) ? `${names.get(code)} — ${code}` : code).join(', ');
}

function tableLayoutSummary(tables) {
  const entries = Object.entries(tables);
  if (!entries.length) return node('div', 'muted', 'No customized table layouts.');
  const list = node('div', 'settings-table-layouts');
  entries.forEach(([tableId, layout]) => {
    const details = node('details', 'settings-table-layout');
    details.append(node('summary', '', semanticLabel(tableId)), settingsSummary([
      ['Available columns', layout.schema.map(semanticLabel).join(', ')],
      ['Column order', layout.column_order.map(semanticLabel).join(', ')],
      ['Hidden columns', layout.hidden_columns.length ? layout.hidden_columns.map(semanticLabel).join(', ') : 'None'],
      ['Custom widths', Object.entries(layout.column_widths)
        .map(([column, width]) => `${semanticLabel(column)} ${number(width)} px`).join(', ') || 'Defaults']
    ]));
    list.append(details);
  });
  return list;
}

function userPreferenceSummaryCards(preferences) {
  const disabledAlerts = preferences.health_alerts.disabled_codes;
  const knownDisabledAlerts = receiverHealthAlertIds.filter((id) => disabledAlerts.includes(id)).length;
  return settingsCardGrid(
    settingsCard('Appearance', 'Choose coordinated colors here or switch the theme in the header.', settingsSummary([
      ['Theme', semanticLabel(preferences.appearance.theme)],
      ['Hue', preferences.appearance.hue === null ? 'Original colors' : `${preferences.appearance.hue}°`]
    ])),
    settingsCard('Scanner', 'Changed on the Scanner page.', settingsSummary([
      ['Playing call in every page title', settingsEnabled(preferences.page_titles.prepend_playing_call)],
      ['Playback volume', `${Math.round(preferences.playback.volume * 100)}%`],
      ['Selected scan lists', selectedScanListSummary(preferences.playback.selected_scan_list_ids)],
      ['Group calls by target', settingsEnabled(preferences.playback.target_grouping)],
      ['Calls per target', number(preferences.playback.target_burst_limit)],
      ['Detail level', semanticLabel(preferences.scanner.detail_mode)]
    ])),
    settingsCard('Source names', 'Changed here in My Settings.', settingsSummary([
      ['Source name display', sourceNameDisplayLabel(preferences.presentation.source_name_display)]
    ])),
    settingsCard('Live presentation', 'Changed from the presentation icon on the Live page.', settingsSummary([
      ['Row density', preferences.presentation.live_row_density === 'dense' ? 'Dense' : 'Normal'],
      ['Show only active trunked channels', settingsEnabled(preferences.presentation.show_only_active_trunked_channels)],
      ['Sort calls by', ({ lcn: 'LCN', order_appeared: 'Order appeared', frequency: 'Frequency' })[
        liveChannelSortMethod(preferences.presentation)]],
      ['Retain the last call on idle rows', settingsEnabled(preferences.presentation.retain_last_call_on_idle_rows)],
      ['Clear voice quality on idle rows', settingsEnabled(preferences.presentation.clear_voice_quality_when_idle)],
      ['Show encryption algorithm and key ID', settingsEnabled(preferences.presentation.show_encryption_details)],
      ['Show control-channel quality', settingsEnabled(preferences.presentation.show_control_decode_quality)],
      ['Show voice-channel quality', settingsEnabled(preferences.presentation.show_voice_decode_quality)],
      ['Decode quality format', semanticLabel(preferences.presentation.decode_quality_display_mode)],
      ['Matching rows shown', number(preferences.presentation.live_detail_row_limit)]
    ])),
    settingsCard('Tuner spectrum', 'Changed from a tuner Spectrum view.', settingsSummary([
      ['Display floor', `${number(preferences.tuner.floor_db)} dB`],
      ['Display ceiling', `${number(preferences.tuner.ceiling_db)} dB`],
      ['Waterfall speed', `${number(preferences.tuner.waterfall_speed)}×`],
      ['Snap frequency', settingsEnabled(preferences.tuner.snap_frequency)],
      ['Smooth FFT', settingsEnabled(preferences.tuner.smooth_fft)],
      ['Idle FFT markers', settingsEnabled(preferences.tuner.show_idle_channels)],
      ['Performance profile', semanticLabel(preferences.tuner.profile)]
    ])),
    settingsCard('Status icon', 'Changed here in My Settings.', settingsSummary([
      ['Issue types shown', `${number(receiverHealthAlertIds.length - knownDisabledAlerts)} of ` +
        number(receiverHealthAlertIds.length)],
      ['Hidden issue types', disabledHealthAlertSummary(disabledAlerts)]
    ])),
    settingsCard('Table layouts', 'Changed with the Columns control on each table.',
      tableLayoutSummary(preferences.tables))
  );
}

// Reuse map: My Settings summary, shared range/field controls, form feedback,
// and the shared modal lifecycle cover light/dark and desktop/phone layouts.
async function openAppearanceSettings(returnFocusSelector = null) {
  const snapshot = userPreferenceController.snapshot();
  if (!snapshot.loaded) return;
  const identity = snapshot.identity;
  let savedHue = snapshot.preferences.appearance.hue;
  let draftHue = savedHue;
  let sessionChanged = false;
  const form = node('form', 'admin-form');
  const hue = node('input', 'ui-range');
  hue.type = 'range';
  hue.id = 'appearance-hue';
  hue.name = 'appearance-hue';
  hue.min = '0';
  hue.max = '359';
  hue.step = '1';
  hue.value = String(savedHue ?? 215);
  hue.setAttribute('aria-valuetext', savedHue === null ? 'Original colors' : `${savedHue} degrees`);
  const value = node('output', 'ui-field-detail', savedHue === null ? 'Original colors' : `${savedHue}°`);
  value.htmlFor = hue.id;
  const field = node('label', 'ui-field');
  field.append(node('span', 'ui-field-label', 'Hue'), hue);
  const paletteHint = node('span', 'ui-field-detail', 'Matching accent colors update with your choice.');
  paletteHint.id = 'appearance-palette-hint';
  hue.setAttribute('aria-describedby', paletteHint.id);
  const useDefault = node('button', 'ui-button ui-button-secondary', 'Use original colors');
  useDefault.type = 'button';
  const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancel.type = 'button';
  const save = node('button', 'ui-button ui-button-primary', 'Save appearance');
  save.type = 'submit';
  const feedback = node('div', 'admin-form-message');
  const actions = aliasModalFooter(cancel, save);
  form.append(field, value, paletteHint, useDefault, feedback, actions);
  let preview = null;
  const modal = openReadOnlyModal('Appearance', form, {
    id: 'appearance-settings', className: 'admin-modal', returnFocusSelector,
    cleanup: () => {
      if (appearanceHuePreview === preview) appearanceHuePreview = null;
      applyTheme();
    }
  });
  if (!modal) return;
  const workflow = createFormWorkflow({ form, submit: save, feedback, modal,
    changed: () => !sessionChanged && draftHue !== savedHue });
  const refreshPreview = () => {
    value.textContent = draftHue === null ? 'Original colors' : `${draftHue}°`;
    hue.setAttribute('aria-valuetext', draftHue === null ? 'Original colors' : `${draftHue} degrees`);
    if (appearanceHuePreview === preview) {
      preview.hue = draftHue;
      applyTheme();
    }
  };
  const loadSavedHue = (current) => {
    savedHue = current.preferences.appearance.hue;
    draftHue = savedHue;
    hue.value = String(savedHue ?? 215);
    refreshPreview();
    workflow.refresh();
  };
  const closeForChangedSession = () => {
    let owned = activeReadOnlyModal;
    while (owned && owned !== modal.state) owned = owned.parent;
    if (!owned) return;
    // The former account's draft and any discard confirmation share this root.
    // Close only that owned stack through the shared cleanup/focus lifecycle.
    closeReadOnlyModal(true);
    void render();
  };
  preview = {
    identity, hue: savedHue,
    onSnapshot: (current) => {
      if (current.identity === identity) return;
      sessionChanged = true;
      if (appearanceHuePreview === preview) appearanceHuePreview = null;
      workflow.setReady(false);
      if (!workflow.isBusy()) closeForChangedSession();
    }
  };
  hue.addEventListener('input', () => {
    draftHue = Number(hue.value);
    refreshPreview();
  });
  useDefault.addEventListener('click', () => {
    draftHue = preferenceSchema.defaults.appearance.hue;
    hue.value = String(draftHue ?? 215);
    refreshPreview();
    form.dispatchEvent(new Event('input', { bubbles: true }));
  });
  cancel.addEventListener('click', modal.close);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const selectedHue = draftHue;
    await workflow.save(async () => {
      await updateUserPreferences((preferences) => {
        preferences.appearance.hue = selectedHue;
      }, false);
      loadSavedHue(userPreferenceController.snapshot());
    }, {
      saving: 'Saving appearance…',
      onSuccess: async () => {
        modal.setDirty(false);
        if (modal.close()) await render();
        document.querySelector(returnFocusSelector || '#appearance-settings')?.focus({ preventScroll: true });
      },
      onError: (error) => {
        if (sessionChanged || error?.code === 'preference_session_changed') {
          sessionChanged = true;
          workflow.setReady(false);
          return { state: 'warning', message: 'The signed-in account changed. Reopen Appearance for this account.' };
        }
        if (error?.code === 'preference_conflict' && !error.reloadError) {
          loadSavedHue(userPreferenceController.snapshot());
          return { state: 'warning', message: 'Appearance changed in another session. The saved hue was loaded.' };
        }
        refreshPreview();
        return { state: 'error', message: error?.code === 'preference_conflict' ?
          'Appearance changed in another session, but the saved hue could not be loaded. Try saving again or reload the page.' :
          'Appearance could not be saved. Your hue is still here. Try saving again.' };
      }
    });
    if (sessionChanged) {
      modal.setDirty(false);
      closeForChangedSession();
    }
  });
  if (!await modal.ready) return;
  if (userPreferenceController.snapshot().identity !== identity) {
    modal.close();
    return;
  }
  appearanceHuePreview = preview;
  modal.focus(hue);
}

// Reuse map: shared settings summary, select, form feedback and modal footer
// provide the same source-name choice on phones and desktops in both themes.
async function openSourceNameSettings(returnFocusSelector = null) {
  const snapshot = userPreferenceController.snapshot();
  if (!snapshot.loaded) return;
  const identity = snapshot.identity;
  let savedMode = snapshot.preferences.presentation.source_name_display;
  let sessionChanged = false;
  const form = node('form', 'admin-form');
  const select = preferenceSelect('source-name-display', [
    ['talker_alias', 'Talker Alias preferred'], ['source_alias', 'Source Alias preferred'], ['both', 'Both']
  ], savedMode);
  select.setAttribute('aria-label', 'Source name display');
  const feedback = node('div', 'admin-form-message');
  const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
  cancel.type = 'button';
  const save = node('button', 'ui-button ui-button-primary', 'Save source names');
  save.type = 'submit';
  form.append(formField('Source name display', select,
    'Use the other name when the preferred name is unavailable. Both shows each distinct name once.'),
  feedback, aliasModalFooter(cancel, save));
  const modal = openReadOnlyModal('Source names', form, {
    id: 'source-name-settings', className: 'admin-modal', returnFocusSelector
  });
  if (!modal) return;
  const workflow = createFormWorkflow({ form, submit: save, feedback, modal,
    changed: () => !sessionChanged && select.value !== savedMode });
  const loadSavedMode = () => {
    savedMode = userPreferenceController.snapshot().preferences.presentation.source_name_display;
    select.value = savedMode;
    workflow.refresh();
  };
  const refreshSettings = () => {
    void render().then(() => document.querySelector(returnFocusSelector || '#source-name-settings')
      ?.focus({ preventScroll: true }));
  };
  cancel.addEventListener('click', modal.close);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const selectedMode = select.value;
    await workflow.save(async () => {
      if (userPreferenceController.snapshot().identity !== identity) {
        const error = new Error('The signed-in account changed. Reopen Source names for this account.');
        error.code = 'preference_session_changed';
        throw error;
      }
      await updateUserPreferences((preferences) => {
        preferences.presentation.source_name_display = selectedMode;
      }, false);
      loadSavedMode();
    }, {
      saving: 'Saving source names…',
      onSuccess: () => {
        modal.setDirty(false);
        if (modal.close(refreshSettings)) refreshSettings();
      },
      onError: (error) => {
        if (error?.code === 'preference_session_changed') {
          sessionChanged = true;
          workflow.setReady(false);
          modal.setDirty(false);
          return { state: 'warning', message: 'The signed-in account changed. Reopen Source names for this account.' };
        }
        if (error?.code === 'preference_conflict' && !error.reloadError) {
          loadSavedMode();
          return { state: 'warning', message: 'Source names changed in another session. The saved choice was loaded.' };
        }
        return { state: 'error', message: error?.code === 'preference_conflict' ?
          'Source names changed in another session, but the saved choice could not be loaded. Try saving again or reload the page.' :
          'Source names could not be saved. Your choice is still here. Try saving again.' };
      }
    });
  });
  if (!await modal.ready) return;
  if (userPreferenceController.snapshot().identity !== identity) {
    modal.close();
    return;
  }
  modal.focus(select);
}

async function savePreferenceForm(workflow, modal, mutate, options) {
  const { identity, saving, apply, renderAfterSave = true,
    conflictMessage = 'These settings changed in another session. The current saved values were loaded.',
    reloadMessage = 'These settings changed in another session, but the current values could not be ' +
      'reloaded. Try saving again or reopen this panel.' } = options;
  let sessionChanged = false;
  await workflow.save(async () => {
    if (userPreferenceController.snapshot().identity !== identity) {
      throw Object.assign(new Error('The signed-in account changed.'), { code: 'preference_session_changed' });
    }
    await updateUserPreferences(mutate, false);
  }, {
    saving,
    onSuccess: () => { if (modal.close() && renderAfterSave) void render(); },
    onError: (error) => {
      if (error?.code === 'preference_session_changed') {
        sessionChanged = true;
        workflow.setReady(false);
      } else if (error?.code === 'preference_conflict') {
        if (error.reloadError) return { state: 'error', message: reloadMessage };
        const latest = userPreferenceController.snapshot();
        if (latest.loaded) apply(latest.preferences);
        workflow.setDirty(false);
        return { state: 'warning', message: conflictMessage };
      }
      return null;
    }
  });
  if (sessionChanged) {
    workflow.setDirty(false);
    if (modal.close()) void render();
  }
}

function openStatusIconSettings(returnFocusSelector = null) {
  const snapshot = userPreferenceController.snapshot();
  if (!snapshot.loaded) return;

  const form = node('form', 'admin-form health-alert-settings-form');
  const message = node('div', 'admin-form-message');
  message.setAttribute('role', 'status');
  const controls = new Map();
  const apply = (preferences) => {
    receiverHealthAlertIds.forEach((id) => {
      const input = controls.get(id);
      if (input) setUiToggle(input, isReceiverHealthAlertEnabled(preferences, id));
    });
  };
  const cards = receiverHealthAlertGroups.map((group) => {
    const toggles = group.alerts.map((alert) => {
      const setting = preferenceCheckbox(`health-alert-${alert.id}`, alert.name, true, alert.description);
      setting.input.dataset.alertCode = alert.id;
      controls.set(alert.id, setting.input);
      return setting.control;
    });
    const card = settingsCard(group.name, group.description, ...toggles);
    card.classList.add('health-alert-settings-card');
    return card;
  });
  apply(snapshot.preferences);

  const save = node('button', 'ui-button ui-button-primary', 'Save choices');
  save.type = 'submit';
  const actions = node('div', 'admin-form-actions');
  actions.append(save);
  const footer = node('div', 'settings-form-footer');
  footer.append(message, actions);
  form.append(settingsCardGrid(...cards), footer);
  const modal = openReadOnlyModal('Status icon issues', form, {
    id: 'status-icon-settings', className: 'health-alert-settings-modal', returnFocusSelector
  });
  if (!modal) return;
  const workflow = createFormWorkflow({ form, submit: save, feedback: message, modal });
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    await savePreferenceForm(workflow, modal, (preferences) => {
      preferences.health_alerts.disabled_codes = receiverHealthDisabledCodesForSave(preferences, controls);
    }, { identity: snapshot.identity, saving: 'Saving status icon choices…', apply,
      conflictMessage: 'These choices changed elsewhere. The saved choices were loaded.',
      reloadMessage: 'These choices changed elsewhere, but the saved choices could not be loaded. ' +
        'Close and reopen this window.' });
  });
}

function openLivePresentationSettings(returnFocusSelector = null) {
  const snapshot = userPreferenceController.snapshot();
  if (!snapshot.loaded) return;
  let current = snapshot.preferences.presentation;
  const form = node('form', 'admin-form live-presentation-form');
  const message = node('div', 'admin-form-message');
  message.setAttribute('role', 'status');
  const encryption = preferenceCheckbox('show-encryption-details', 'Show encryption algorithm and key ID',
    current.show_encryption_details,
    'Show the encryption algorithm and key ID reported in received signaling. A key ID is not encryption key material.');
  const controlQuality = preferenceCheckbox('show-control-quality', 'Show control-channel decode quality',
    current.show_control_decode_quality,
    'Add the rolling control-channel quality reading to Live rows.');
  const voiceQuality = preferenceCheckbox('show-voice-quality', 'Show voice-channel decode quality',
    current.show_voice_decode_quality,
    'Add call-level voice quality when enough frames have been received.');
  const activeOnly = preferenceCheckbox('show-only-active-trunked', 'Show only active trunked channels',
    current.show_only_active_trunked_channels,
    'Hide inactive trunked rows. Conventional channels are always shown.');
  const callSort = preferenceSelect('live-channel-sort', [
    ['lcn', 'LCN'], ['order_appeared', 'Order appeared'], ['frequency', 'Frequency']
  ], liveChannelSortMethod(current));
  const rowDensity = preferenceSelect('live-row-density', [['normal', 'Normal'], ['dense', 'Dense']],
    current.live_row_density);
  const retainLastCall = preferenceCheckbox('retain-last-call-on-idle', 'Retain the last call on idle rows',
    current.retain_last_call_on_idle_rows,
    'Keep the last source, target, alias, talker, encryption algorithm, and key ID visible after a row becomes idle.');
  const clearIdleQuality = preferenceCheckbox('clear-idle-voice-quality',
    'Clear voice quality when a row becomes idle', current.clear_voice_quality_when_idle,
    'Hide the completed call\'s voice-quality result after its row becomes idle.');
  const syncIdleRowOptions = () => {
    const disabled = activeOnly.input.checked;
    [retainLastCall.input, clearIdleQuality.input].forEach((input) => {
      if (disabled) setUiToggle(input, false);
      input.disabled = disabled;
    });
  };
  activeOnly.input.addEventListener('change', () => {
    callSort.value = activeOnly.input.checked ? 'order_appeared' : 'lcn';
    syncIdleRowOptions();
  });
  syncIdleRowOptions();
  const qualityMode = preferenceSelect('quality-mode', [['percentage', 'Percentage'], ['detailed', 'Detailed counters']],
    current.decode_quality_display_mode);
  const rowLimit = node('input');
  rowLimit.type = 'number';
  rowLimit.name = 'live-detail-row-limit';
  rowLimit.min = '25';
  rowLimit.max = '500';
  rowLimit.required = true;
  rowLimit.value = String(current.live_detail_row_limit);
  const apply = (presentation) => {
    current = presentation;
    setUiToggle(encryption.input, presentation.show_encryption_details);
    setUiToggle(controlQuality.input, presentation.show_control_decode_quality);
    setUiToggle(voiceQuality.input, presentation.show_voice_decode_quality);
    setUiToggle(activeOnly.input, presentation.show_only_active_trunked_channels);
    callSort.value = liveChannelSortMethod(presentation);
    rowDensity.value = presentation.live_row_density;
    setUiToggle(retainLastCall.input, presentation.retain_last_call_on_idle_rows);
    setUiToggle(clearIdleQuality.input, presentation.clear_voice_quality_when_idle);
    syncIdleRowOptions();
    qualityMode.value = presentation.decode_quality_display_mode;
    rowLimit.value = String(presentation.live_detail_row_limit);
  };
  const fields = node('div', 'settings-field-grid');
  fields.append(formField('Decode quality format', qualityMode,
    'Choose a compact percentage or the underlying frame and error counters.'),
  formField('Matching rows shown', rowLimit, 'Limit each matching Live detail list to 25–500 rows.'));
  const save = node('button', 'ui-button ui-button-primary', 'Save Live Presentation');
  save.type = 'submit';
  const actions = node('div', 'admin-form-actions');
  actions.append(save);
  const footer = node('div', 'settings-form-footer');
  footer.append(message, actions);
  const presentationCard = settingsCard('Live details',
    'Choose how decoded activity is shown on the Live page.',
    formField('Row density', rowDensity),
    activeOnly.control, formField('Sort calls by', callSort,
      'Active-only view defaults to Order appeared; showing idle rows defaults to LCN.'),
    node('p', 'ui-field-detail', 'Turn off “Show only active trunked channels” to use idle-row options.'),
    retainLastCall.control, clearIdleQuality.control,
    encryption.control, controlQuality.control, voiceQuality.control, fields);
  form.append(node('p', 'live-presentation-intro',
    'These choices affect only this signed-in user.'),
  settingsCardGrid(presentationCard), footer);
  const modal = openReadOnlyModal('Live presentation', form, {
    id: 'live-presentation-settings', className: 'live-presentation-modal', returnFocusSelector
  });
  if (!modal) return;
  const workflow = createFormWorkflow({ form, submit: save, feedback: message, modal });
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const submitted = {
      show_encryption_details: encryption.input.checked,
      show_control_decode_quality: controlQuality.input.checked,
      show_voice_decode_quality: voiceQuality.input.checked,
      decode_quality_display_mode: qualityMode.value,
      live_detail_row_limit: Number(rowLimit.value),
      show_only_active_trunked_channels: activeOnly.input.checked,
      live_channel_sort: callSort.value,
      live_row_density: rowDensity.value,
      retain_last_call_on_idle_rows: !activeOnly.input.checked && retainLastCall.input.checked,
      clear_voice_quality_when_idle: !activeOnly.input.checked && clearIdleQuality.input.checked
    };
    const densityOnly = Object.entries(submitted).every(([key, value]) =>
      key === 'live_row_density' || value === current[key]);
    await savePreferenceForm(workflow, modal, (preferences) => {
      preferences.presentation = { ...preferences.presentation, ...submitted };
    }, { identity: snapshot.identity, saving: 'Saving Live presentation…',
      apply: (preferences) => apply(preferences.presentation), renderAfterSave: !densityOnly });
    if (!workflow.isBusy()) syncIdleRowOptions();
  });
}

async function activateScannerSettings(button) {
  const returnFocusSelector = `#${button.id}`;
  let snapshot = userPreferenceController.snapshot();
  if (!snapshot.loaded && !accessSession.authenticated) {
    showLoginModal(returnFocusSelector);
    return;
  }
  if (!snapshot.loaded) {
    button.disabled = true;
    button.classList.add('is-loading');
    button.replaceChildren();
    button.setAttribute('aria-label', 'Loading Scanner settings');
    button.removeAttribute('title');
    snapshot = await synchronizeUserPreferences();
    if (!button.isConnected) return;
    button.disabled = false;
    button.classList.remove('is-loading');
    setIconButton(button, 'icon-live-presentation', snapshot.loaded ?
      'Scanner settings' : 'Retry Scanner settings');
  }
  if (snapshot.loaded) openScannerSettings(returnFocusSelector);
}

