function tunerInventoryRows(response) {
  if (!response || !Array.isArray(response.tuners)) {
    throw new Error('The receiver returned an invalid tuner list.');
  }
  return response.tuners.filter((tuner) => tuner && typeof tuner === 'object' &&
    typeof tuner.id === 'string' && tuner.id && typeof tuner.name === 'string');
}

function tunerInventoryFrequency(value) {
  const hz = Number(value);
  return Number.isFinite(hz) && hz > 0 ? `${frequency(hz)} MHz` : 'Unavailable';
}

function tunerIsRecording(tuner) {
  return ['RECORDING', 'RECORDING_TUNER'].includes(String(tuner?.tuner_class).toUpperCase());
}

function tunerInventoryRate(value) {
  const hz = Number(value);
  if (!Number.isFinite(hz) || hz <= 0) return 'Unavailable';
  return hz >= 1_000_000 ? `${Number((hz / 1_000_000).toFixed(3))} MHz` :
    `${Number((hz / 1_000).toFixed(1))} kHz`;
}

function tunerSampleRateOptionLabel(label) {
  const text = String(label || '');
  const match = text.match(/^(\d+(?:\.\d+)?)\s*(MHz|kHz)$/i);
  return match ? `${Number(match[1])} ${match[2]}` : text;
}

function tunerSettingValue(setting, value) {
  if (setting.kind === 'action') return setting.label;
  if (setting.kind === 'boolean') return value ? 'On' : 'Off';
  const option = (Array.isArray(setting.options) ? setting.options : [])
    .find((choice) => String(choice.value) === String(value));
  return option ? String(option.label) : `${value}${setting.unit ? ` ${setting.unit}` : ''}`;
}

function tunerSettingInputValue(setting, value) {
  if (value == null) return '';
  const numeric = Number(value);
  const step = Number(setting?.step);
  if (Number.isFinite(numeric) && Number.isFinite(step) && step > 0) {
    const [coefficient, exponentText = '0'] = String(step).toLowerCase().split('e');
    const fractionDigits = (coefficient.split('.')[1] || '').length;
    const decimalPlaces = Math.min(12, Math.max(0, fractionDigits - Number(exponentText)));
    const rounded = Number(numeric.toFixed(decimalPlaces));
    return String(Object.is(rounded, -0) ? 0 : rounded);
  }
  return String(value);
}

function tunerSettingInput(setting, draft = null) {
  const value = setting.value;
  if (setting.kind === 'boolean') {
    const control = uiToggleField(setting.label, draft === null ? Boolean(value) : Boolean(draft), setting.label);
    return { element: control, input: control.querySelector('input'), read: (input) => input.checked,
      confirmedValue: Boolean(value) };
  }
  if (setting.kind === 'choice') {
    const input = node('select', 'ui-select');
    for (const choice of Array.isArray(setting.options) ? setting.options : []) {
      const label = setting.id === 'sample_rate' ?
        tunerSampleRateOptionLabel(choice.label) : String(choice.label);
      const option = node('option', '', label);
      option.value = String(choice.value);
      input.append(option);
    }
    input.value = draft === null ? String(value ?? '') : String(draft);
    const field = node('label', 'ui-field');
    field.append(node('span', '', setting.label), uiSelectFrame(input));
    return { element: field, input, read: (select) => select.value,
      confirmedValue: String(value ?? '') };
  }
  const input = node('input', 'ui-input');
  input.type = 'number';
  input.required = true;
  if (setting.minimum != null && Number.isFinite(Number(setting.minimum))) input.min = String(setting.minimum);
  if (setting.maximum != null && Number.isFinite(Number(setting.maximum))) input.max = String(setting.maximum);
  if (setting.step != null && Number.isFinite(Number(setting.step)) && Number(setting.step) > 0) {
    input.step = String(setting.step);
  }
  const confirmedValue = tunerSettingInputValue(setting, value);
  input.value = draft === null ? confirmedValue : String(draft);
  const field = node('label', 'ui-field');
  field.append(node('span', '', `${setting.label}${setting.unit ? ` (${setting.unit})` : ''}`), input);
  return { element: field, input, read: (numberInput) => Number(numberInput.value),
    confirmedValue: confirmedValue === '' ? '' : Number(confirmedValue) };
}

function tunerOperatorState(tuner) {
  const state = String(tuner?.operator_state || '').toLowerCase();
  if (['disabled', 'setup', 'live'].includes(state)) return state;
  return 'disabled';
}

function tunerOperatorStateLabel(tuner) {
  const transition = String(tuner?.transition || '').toLowerCase();
  const transitions = {
    disabling: 'Stopping', starting_setup: 'Starting', going_live: 'Going live', restoring: 'Restarting channels'
  };
  if (transitions[transition]) return { label: transitions[transition], tone: 'warning' };
  const state = tunerOperatorState(tuner);
  if (state === 'setup') return { label: 'Setup', tone: 'warning' };
  if (state === 'live') return { label: 'Live', tone: 'success' };
  return { label: 'Disabled', tone: 'neutral' };
}

function tunerStoppedChannels(tuner) {
  return (Array.isArray(tuner?.stopped_channels) ? tuner.stopped_channels : [])
    .filter((channel) => channel && typeof channel.id === 'string')
    .map((channel) => {
      const name = String(channel.name || channel.id);
      const kind = String(channel.kind || '').toLowerCase() === 'traffic' ||
        (!channel.kind && name.startsWith('T-')) ? 'traffic' : 'standard';
      const parentName = kind === 'traffic' ? name.replace(/^T-/, '') : name;
      const frequencyHz = Number(channel.frequency_hz);
      return {
        id: channel.id, name, kind,
        parentId: String(channel.parent_id || channel.parentId || '').trim(),
        parentName: parentName || 'Channel',
        frequencyHz: Number.isFinite(frequencyHz) && frequencyHz > 0 ? frequencyHz : null,
        system: String(channel.system || '').trim(), site: String(channel.site || '').trim()
      };
    });
}

function tunerStoppedChannelGroups(channels) {
  const groups = new Map();
  for (const channel of channels) {
    const key = channel.parentId ||
      `${channel.system}\u0000${channel.site}\u0000${channel.parentName}`;
    if (!groups.has(key)) groups.set(key, {
      name: channel.parentName, system: channel.system, site: channel.site, primary: [], voiceCount: 0
    });
    const group = groups.get(key);
    if (channel.kind === 'traffic') group.voiceCount += 1;
    else {
      group.primary.push(channel);
      group.name = channel.name;
      group.system = channel.system || group.system;
      group.site = channel.site || group.site;
    }
  }
  return [...groups.values()];
}

function tunerSettingDependencyMet(setting, settings) {
  const dependencies = Array.isArray(setting?.dependencies) ? setting.dependencies : [];
  return dependencies.every((dependency) => {
    const source = settings.find((candidate) => candidate?.id === dependency?.setting_id);
    return source && String(source.value) === String(dependency.equals);
  });
}

function tunerSettingUsability(setting, tuner, settings) {
  const reason = (value) => ({
    'Use Setup': 'Switch to Setup to adjust',
    'Unlock center': 'Unlock center to tune',
    'Turn off Auto PPM': 'Turn off Auto PPM to adjust',
    'Use manual gain': 'Select Manual gain to adjust',
    'Use Custom gain': 'Select Custom gain to adjust',
    'Tuner 1': 'Change this on Tuner 1',
    'Disable tuner 2': 'Disable tuner 2 to adjust',
    Fixed: 'Fixed by this tuner'
  })[String(value)] || String(value);
  if (setting?.editable !== true) {
    return { enabled: false, reason: reason(setting?.unavailable_reason || 'Not available') };
  }
  const state = tunerOperatorState(tuner);
  const setupOnly = String(setting?.availability || '').toLowerCase() === 'setup';
  if (setupOnly && state === 'live') {
    return { enabled: false, reason: reason(setting?.unavailable_reason || 'Switch to Setup to adjust') };
  }
  if (!tunerSettingDependencyMet(setting, settings)) {
    return { enabled: false, reason: reason(setting?.unavailable_reason || 'Change the related setting first') };
  }
  return { enabled: true, reason: '' };
}

function tunerCenterFrequencyText(value) {
  const numeric = Math.max(0, Math.min(9_999.99999, Number(value) || 0));
  const [whole, fraction] = numeric.toFixed(5).split('.');
  return `${whole.padStart(4, '0')}.${fraction}`;
}

function tunerCenterFrequencyControl(tuner, setting, usability, callbacks = {}) {
  const settingDrafts = callbacks.drafts || new Map();
  const saveTunerSetting = callbacks.save;
  let centerKeydownCleanup = null;
  const key = `${tuner.id}:${setting.id}`;
  let value = Number(settingDrafts.has(key) ? settingDrafts.get(key) : setting.value);
  const wrapper = node('div', 'tuners-center-frequency');
  wrapper.setAttribute('role', 'group');
  wrapper.setAttribute('aria-label', 'Center frequency');
  wrapper.setAttribute('aria-disabled', String(!usability.enabled));
  wrapper.tabIndex = usability.enabled ? 0 : -1;
  wrapper.dataset.tunerSetting = setting.id;
  const label = node('span', 'tuners-center-label tuners-readout-label', 'Center frequency');
  const digits = node('div', 'tuners-frequency-digits');
  const controlRow = node('div', 'tuners-center-control-row');
  const valueRow = node('div', 'tuners-center-value');
  valueRow.append(digits);
  controlRow.append(valueRow);
  const message = node('div', 'tuners-setting-message');
  message.setAttribute('role', 'status');
  const positions = [1_000, 100, 10, 1, .1, .01, .001, .0001, .00001];
  let hoverIndex = -1;
  let typingStart = -1;
  let typingValue = '';
  let saving = false;

  const commit = async (next) => {
    if (!usability.enabled || saving) return;
    const minimum = Number(setting.minimum);
    const maximum = Number(setting.maximum);
    if ((Number.isFinite(minimum) && next < minimum) || (Number.isFinite(maximum) && next > maximum)) {
      value = Number(setting.value);
      settingDrafts.delete(key);
      draw();
      message.textContent = 'Out of range';
      return;
    }
    saving = true;
    draw();
    digits.setAttribute('aria-busy', 'true');
    message.textContent = 'Saving…';
    try {
      await saveTunerSetting(tuner, setting, Number(next.toFixed(5)), message);
    } catch (error) {
      saving = false;
      value = Number(setting.value);
      settingDrafts.delete(key);
      digits.removeAttribute('aria-busy');
      message.textContent = error.message || 'Could not save';
      draw();
    }
  };
  const draw = () => {
    const text = tunerCenterFrequencyText(value);
    let valueIndex = 0;
    const parts = [];
    [...text].forEach((character) => {
      if (character === '.') {
        parts.push(node('span', 'tuners-frequency-decimal', '.'));
        return;
      }
      const index = valueIndex++;
      const column = node('span', `tuners-frequency-digit${index === hoverIndex ? ' is-active' : ''}`);
      const up = node('button', 'tuners-frequency-step tuners-frequency-step-up');
      up.type = 'button';
      up.tabIndex = -1;
      up.disabled = !usability.enabled || saving;
      up.setAttribute('aria-label', `Increase ${positions[index]} MHz place`);
      const shown = node('span', '', character);
      shown.setAttribute('aria-hidden', 'true');
      const down = node('button', 'tuners-frequency-step tuners-frequency-step-down');
      down.type = 'button';
      down.tabIndex = -1;
      down.disabled = !usability.enabled || saving;
      down.setAttribute('aria-label', `Decrease ${positions[index]} MHz place`);
      column.append(up, shown, down);
      column.addEventListener('pointerenter', () => { hoverIndex = index; column.classList.add('is-active'); });
      column.addEventListener('pointerleave', () => column.classList.remove('is-active'));
      up.addEventListener('click', () => {
        if (saving) return;
        value = Math.max(0, Math.min(9_999.99999, value + positions[index]));
        settingDrafts.set(key, value);
        draw();
        void commit(value);
      });
      down.addEventListener('click', () => {
        if (saving) return;
        value = Math.max(0, Math.min(9_999.99999, value - positions[index]));
        settingDrafts.set(key, value);
        draw();
        void commit(value);
      });
      parts.push(column);
    });
    digits.replaceChildren(...parts, node('span', 'tuners-frequency-unit', 'MHz'));
  };
  const keydown = (event) => {
    if (event.defaultPrevented) return;
    if (!wrapper.isConnected || hoverIndex < 0 || !usability.enabled || saving ||
        event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement ||
        event.target instanceof HTMLTextAreaElement) return;
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault();
      hoverIndex = Math.max(0, Math.min(positions.length - 1,
        hoverIndex + (event.key === 'ArrowLeft' ? -1 : 1)));
      draw();
    } else if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault();
      value += (event.key === 'ArrowUp' ? 1 : -1) * positions[hoverIndex];
      settingDrafts.set(key, value);
      draw();
      void commit(value);
    } else if (/^[0-9]$/.test(event.key)) {
      event.preventDefault();
      if (typingStart < 0) {
        typingStart = hoverIndex;
        typingValue = '';
      }
      if (typingStart + typingValue.length >= positions.length) return;
      typingValue += event.key;
      const currentDigits = tunerCenterFrequencyText(value).replace('.', '').split('');
      [...typingValue].forEach((character, offset) => { currentDigits[typingStart + offset] = character; });
      value = Number(`${currentDigits.slice(0, 4).join('')}.${currentDigits.slice(4).join('')}`);
      settingDrafts.set(key, value);
      wrapper.classList.add('is-typing');
      draw();
    } else if (event.key === 'Enter' && typingStart >= 0) {
      event.preventDefault();
      typingStart = -1;
      typingValue = '';
      wrapper.classList.remove('is-typing');
      void commit(value);
    } else if (event.key === 'Escape' && typingStart >= 0) {
      event.preventDefault();
      typingStart = -1;
      typingValue = '';
      value = Number(setting.value);
      settingDrafts.delete(key);
      wrapper.classList.remove('is-typing');
      message.textContent = '';
      draw();
    }
  };
  const detachKeydown = () => {
    document.removeEventListener('keydown', keydown);
    if (centerKeydownCleanup === detachKeydown) centerKeydownCleanup = null;
  };
  wrapper.addEventListener('pointerenter', () => {
    centerKeydownCleanup?.();
    document.addEventListener('keydown', keydown);
    centerKeydownCleanup = detachKeydown;
  });
  wrapper.addEventListener('pointerleave', () => {
    hoverIndex = -1;
    detachKeydown();
  });
  wrapper.addEventListener('focus', () => {
    if (hoverIndex < 0) {
      hoverIndex = 0;
      draw();
    }
  });
  wrapper.addEventListener('keydown', keydown);
  if (!usability.enabled && callbacks.unavailableHint) {
    wrapper.dataset.uiHint = usability.reason;
    wrapper.setAttribute('aria-description', usability.reason);
    wrapper.tabIndex = 0;
  } else if (!usability.enabled) {
    const help = iconButton('icon-about', usability.reason,
      'ui-button ui-button-secondary ui-icon-button ui-icon-button-compact tuners-center-help');
    help.dataset.tunerHelp = setting.id;
    controlRow.append(help);
  }
  wrapper.append(label, controlRow);
  wrapper.append(message);
  wrapper.close = detachKeydown;
  wrapper.previewFrequency = (megahertz) => {
    if (!Number.isFinite(megahertz)) return;
    value = megahertz;
    const characters = tunerCenterFrequencyText(value).replace('.', '');
    digits.querySelectorAll('.tuners-frequency-digit > span').forEach((digit, index) => {
      digit.textContent = characters[index];
    });
  };
  draw();
  return wrapper;
}

async function renderTuners() {
  const renderContext = captureRenderContext();
  const listBody = node('div', 'tuners-list');
  const detailsBody = node('div', 'tuners-details');
  const centerLockBody = node('div', 'tuners-center-lock');
  const centerHost = node('div', 'tuners-center-host tuners-readout tuners-readout-center');
  const spectrumBody = node('div', 'tuners-spectrum');
  const readoutsBody = node('div', 'tuners-readouts');
  const channelReadout = node('div', 'tuners-readout tuners-channel-readout');
  const channelValue = node('strong', 'tuners-readout-value', '—');
  channelReadout.append(node('span', 'tuners-readout-label', 'Active channels'), channelValue);
  const lockReadout = node('div', 'tuners-readout tuners-lock-readout');
  lockReadout.append(node('span', 'tuners-readout-label', 'Tuning'), centerLockBody);
  const recoveryBody = node('div', 'tuners-recovery');
  const messagesBody = node('div', 'tuners-messages');
  const gainBody = node('div', 'tuners-setting-group-body');
  const commonPrimaryBody = node('div', 'tuners-setting-group-body tuners-common-primary');
  const commonMoreBody = node('div', 'tuners-setting-group-body tuners-common-more');
  const commonLimitsBody = node('div', 'tuners-common-limits');
  const commonSampleBody = node('div', 'tuners-common-sample tuners-readout');
  commonMoreBody.append(commonLimitsBody);
  const deviceBody = node('div', 'tuners-setting-group-body');
  const addTunerButton = node('button', 'ui-button ui-button-primary', 'Add tuner');
  addTunerButton.type = 'button';
  addTunerButton.id = 'add-recording-tuner';
  addTunerButton.prepend(iconGlyph('icon-plus'));
  const rescanUsbButton = node('button', 'ui-button ui-button-secondary', 'Rescan USB');
  rescanUsbButton.type = 'button';
  rescanUsbButton.prepend(iconGlyph('icon-refresh'));
  const analyzeButton = node('button', 'ui-button ui-button-secondary tuners-analyze-button',
    'Plan tuner placement');
  analyzeButton.type = 'button';
  analyzeButton.disabled = true;
  analyzeButton.title = 'Open RadioResolve in a new tab with all tuners and running channels';
  analyzeButton.prepend(iconGlyph('icon-share'));
  const tunerCount = node('span', 'tuners-sidebar-count', 'Loading tuners…');
  const tunerListActions = node('div', 'tuners-sidebar-actions ui-action-row');
  tunerListActions.append(rescanUsbButton, tunerCount);
  const tunerListPanel = node('div', 'tuners-sidebar-panel');
  tunerListPanel.append(tunerListActions, listBody);
  const left = section('Receiver tuners', tunerListPanel, sectionActionHost(addTunerButton));
  left.classList.add('tuners-receivers');
  const right = node('div', 'tuners-main');
  const controls = node('div', 'tuners-controls');
  controls.setAttribute('aria-label', 'Selected tuner controls');
  const selectedSection = node('section', 'section ui-section tuners-selected-section');
  selectedSection.setAttribute('aria-label', 'Selected tuner');
  readoutsBody.append(channelReadout, commonSampleBody, centerHost, lockReadout);
  selectedSection.append(detailsBody, spectrumBody, readoutsBody, recoveryBody, messagesBody);
  const gainSection = section('Gain', gainBody);
  gainSection.classList.add('tuners-gain-section');
  const commonMore = node('details', 'tuners-common-details');
  commonMore.append(node('summary', '', 'Frequency limits'), commonMoreBody);
  const commonContent = node('div', 'tuners-common-content');
  commonContent.append(commonPrimaryBody, commonMore);
  const commonSection = section('Common tuning', commonContent);
  const deviceSection = section('Device settings', deviceBody);
  deviceSection.classList.add('tuners-device-section');
  controls.append(gainSection, commonSection, deviceSection);
  right.append(selectedSection, controls);
  const workspace = node('div', 'tuners-workspace editor-workspace');
  workspace.append(left, right);
  const heading = pageHeader('Tuners', 'Tune and watch receiver signal');
  heading.classList.add('tuners-page-header');
  heading.append(analyzeButton);
  if (!beginPage(renderContext, heading, workspace)) return;

  let rows = [];
  let selectedId = '';
  let operationNotice = '';
  let spectrum = null;
  let refreshGeneration = 0;
  let refreshTimer = null;
  let recordingRequest = 0;
  let analyzing = false;
  let promptedSetupId = '';
  let centerKeydownCleanup = null;
  const settingDrafts = new Map();
  pageConnections.add({ close() {
    if (refreshTimer !== null) window.clearTimeout(refreshTimer);
    centerKeydownCleanup?.();
  } });
  listBody.append(node('div', 'loading', 'Loading tuners…'));
  detailsBody.append(node('div', 'loading', 'Loading tuner details…'));
  spectrumBody.append(node('div', 'loading', 'Loading spectrum…'));

  function openAddRecordingTuner() {
    const body = node('div', 'tuners-recordings-body');
    const intro = node('p', 'tuners-recordings-hint',
      'Files come from data/recording_tuners/. Nothing is uploaded.');
    const catalogBody = node('div', 'tuners-recordings-catalog');
    const rescanButton = node('button', 'ui-button ui-button-secondary', 'Rescan files');
    rescanButton.type = 'button';
    rescanButton.prepend(iconGlyph('icon-refresh'));
    body.append(intro, rescanButton, catalogBody);
    const modal = openReadOnlyModal('Add recording tuner', body, {
      id: 'add-recording-tuner', className: 'tuners-recordings-modal',
      returnFocusSelector: '#add-recording-tuner', onClose: () => { recordingRequest += 1; }
    });
    if (!modal) return;

    async function loadRecordingFiles(rescan = false) {
      if (modal.ready && !await modal.ready) return;
      if (!modal.dialog.isConnected) return;
      const request = ++recordingRequest;
      rescanButton.disabled = true;
      catalogBody.replaceChildren(node('div', 'loading', 'Reading recording tuner files…'));
      try {
        const catalog = rescan ? await requestJson('/api/v1/admin/tuners/recordings/rescan', {
          method: 'POST', signal: renderContext.signal
        }) : await api('/api/v1/admin/tuners/recordings', {}, { signal: renderContext.signal });
        if (!renderIsCurrent(renderContext) || request !== recordingRequest || !modal.dialog.isConnected) return;
        const entries = Array.isArray(catalog?.entries) ? catalog.entries : [];
        catalogBody.replaceChildren();
        if (catalog?.truncated) catalogBody.append(node('div', 'ui-notice',
          'Only the first supported files are listed. Remove unneeded files locally and rescan.'));
        if (Number(catalog?.rejected_count) > 0) catalogBody.append(node('p', 'tuners-recordings-hint',
          `${number(catalog.rejected_count)} file${Number(catalog.rejected_count) === 1 ? '' : 's'} could not be used.`));
        if (!entries.length) {
          catalogBody.append(node('div', 'empty', 'No supported I/Q WAV files are in the folder.'));
          return;
        }
        const form = node('form', 'tuners-recordings-form admin-form');
        const files = node('fieldset', 'tuners-recordings-files');
        files.append(node('legend', 'ui-field-label', 'Recording WAV'));
        const center = node('input', 'ui-input');
        center.type = 'number';
        center.min = '0.000001';
        center.step = '0.000001';
        center.required = true;
        let selectedId = String(entries[0].id || '');
        for (const [index, entry] of entries.entries()) {
          const choice = node('label', 'ui-choice-card tuners-recordings-file');
          const radio = node('input', 'ui-choice-radio');
          radio.type = 'radio';
          radio.name = 'recordingFile';
          radio.value = String(entry.id || '');
          radio.checked = index === 0;
          const copy = node('span', 'tuners-recordings-file-copy');
          copy.append(node('strong', '', String(entry.name || 'Recording')),
            node('small', 'ui-field-detail',
              `${tunerInventoryRate(entry.sample_rate_hz)} sample rate · ` +
                `${(Number(entry.size_bytes) / (1024 ** 3)).toFixed(2)} GiB`));
          choice.append(radio, copy);
          files.append(choice);
          radio.addEventListener('change', () => {
            selectedId = radio.value;
            center.value = entry.suggested_center_frequency_hz ?
              String(Number(entry.suggested_center_frequency_hz) / 1_000_000) : '';
          });
        }
        center.value = entries[0].suggested_center_frequency_hz ?
          String(Number(entries[0].suggested_center_frequency_hz) / 1_000_000) : '';
        const message = node('div', 'admin-form-message');
        message.setAttribute('role', 'status');
        const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
        cancel.type = 'button';
        cancel.addEventListener('click', modal.close);
        const add = node('button', 'ui-button ui-button-primary', 'Add recording tuner');
        add.type = 'submit';
        const actions = aliasModalFooter();
        actions.append(cancel, add);
        form.append(files, formField('Center frequency (MHz)', center), message, actions);
        const workflow = createFormWorkflow({ form, submit: add, feedback: message, modal });
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          await workflow.save(async () => {
            const centerFrequencyHz = Math.round(Number(center.value) * 1_000_000);
            if (!Number.isSafeInteger(centerFrequencyHz) || centerFrequencyHz <= 0) {
              throw new Error('Enter a valid center frequency.');
            }
            await requestJson('/api/v1/admin/tuners/recordings', {
              method: 'POST', body: { file_id: selectedId, center_frequency_hz: centerFrequencyHz }
            });
          }, { saving: 'Adding recording tuner…', onSuccess: async () => {
              operationNotice = 'Recording tuner added.';
              modal.close();
              await refresh();
            }, onError: (error) => ({ message: error.message || 'Could not add recording tuner.' }) });
        });
        catalogBody.append(form);
      } catch (error) {
        if (renderIsCurrent(renderContext) && request === recordingRequest && modal.dialog.isConnected) {
          catalogBody.replaceChildren(node('div', 'error', error.message || 'Could not read recording tuner files.'));
        }
      } finally {
        if (modal.dialog.isConnected && request === recordingRequest) rescanButton.disabled = false;
      }
    }
    rescanButton.addEventListener('click', async () => {
      if (modal.isDirty() && !await confirmAction('Discard changes and rescan recording files?', {
        title: 'Rescan recording files', confirmLabel: 'Discard and rescan', cancelLabel: 'Keep editing'
      })) return;
      if (!modal.dialog.isConnected) return;
      modal.setDirty(false);
      void loadRecordingFiles(true);
    });
    void loadRecordingFiles();
  }
  addTunerButton.addEventListener('click', openAddRecordingTuner);

  const selectedTuner = () => rows.find((row) => row.id === selectedId) || null;
  async function saveTunerSetting(tuner, setting, value, message = null) {
    const path = `/api/v1/admin/tuners/${encodeURIComponent(tuner.id)}/settings/${setting.id}`;
    if (message) message.textContent = 'Saving…';
    await requestJson(path, { method: 'PUT', body: { value } });
    settingDrafts.delete(`${tuner.id}:${setting.id}`);
    if (message) message.textContent = '';
    await refresh();
  }

  function centerFrequencyControl(tuner, setting, usability) {
    centerKeydownCleanup?.();
    const control = tunerCenterFrequencyControl(tuner, setting, usability, {
      drafts: settingDrafts, save: saveTunerSetting
    });
    centerKeydownCleanup = control.close;
    return control;
  }

  function renderSettings(tuner) {
    for (const body of [gainBody, centerLockBody, commonPrimaryBody, commonLimitsBody,
      commonSampleBody, deviceBody]) {
      body.replaceChildren();
    }
    const settings = (Array.isArray(tuner.settings) ? tuner.settings : [])
      .filter((setting) => setting && typeof setting.id === 'string' && /^[a-z0-9_]+$/.test(setting.id));
    const center = settings.find((setting) => setting.id === 'frequency_mhz');
    centerHost.replaceChildren();
    if (center) {
      const centerControl = centerFrequencyControl(tuner, center,
        tunerSettingUsability(center, tuner, settings));
      centerHost.append(centerControl);
    } else {
      centerHost.append(node('span', 'tuners-readout-label', 'Center frequency'),
        node('strong', 'tuners-readout-value',
          tunerInventoryFrequency(tuner.frequency_hz ?? tuner.configured_frequency_hz)));
    }

    for (const setting of settings) {
      if (setting.id === 'frequency_mhz') continue;
      const draftKey = `${tuner.id}:${setting.id}`;
      const usability = tunerSettingUsability(setting, tuner, settings);
      const group = String(setting.group || '').toLowerCase();
      const actionSetting = setting.kind === 'action';
      const form = node('form', `tuners-setting${actionSetting ? ' tuners-setting-action' : ''}`);
      form.dataset.settingId = setting.id;
      const control = actionSetting ? null : tunerSettingInput(setting,
        settingDrafts.has(draftKey) ? settingDrafts.get(draftKey) : null);
      if (control && group === 'gain') control.element.classList.add('tuners-gain-control');
      if (control && setting.id === 'automatic_ppm') {
        control.element.classList.add('tuners-auto-ppm-field');
        control.element.querySelector('.ui-toggle-copy')?.classList.add('tuners-auto-ppm-copy');
        control.element.querySelector('.ui-toggle')?.classList.add('tuners-auto-ppm-control');
      } else if (control && setting.id === 'center_frequency_locked') {
        control.element.classList.add('tuners-center-lock-field');
      }
      const message = node('div', 'tuners-setting-message');
      message.setAttribute('role', 'status');
      const actions = node('div', 'tuners-setting-actions ui-action-row');
      const discard = node('button', 'ui-button ui-button-secondary', 'Discard');
      discard.type = 'button';
      const save = node('button', `ui-button ${actionSetting ? 'ui-button-secondary' : 'ui-button-primary'}`,
        actionSetting ? setting.label : 'Save');
      save.type = 'submit';
      save.disabled = !usability.enabled;
      const baseValue = control ? control.confirmedValue : setting.value;
      const isDirty = () => control && String(control.read(control.input)) !== String(baseValue);
      let booleanSaveFailed = false;
      const updateActions = () => {
        save.hidden = !actionSetting && (!isDirty() ||
          (setting.kind === 'boolean' && !booleanSaveFailed));
        actions.hidden = save.hidden;
      };
      if (control) {
        control.input.disabled = !usability.enabled;
        control.input.dataset.tunerSetting = setting.id;
        if (String(setting.group).toLowerCase() === 'gain' &&
            ['integer', 'decimal'].includes(setting.kind) && Number.isFinite(Number(setting.minimum)) &&
            Number.isFinite(Number(setting.maximum))) {
          control.input.type = 'range';
          control.input.classList.add('ui-range', 'tuners-gain-slider');
          const output = node('output', 'tuners-gain-value', tunerSettingValue(setting, control.input.value));
          control.element.classList.add('tuners-gain-field');
          control.element.append(output);
          control.input.addEventListener('input', () => {
            output.textContent = tunerSettingValue(setting, control.input.value);
          });
        }
        const inputEvent = ['integer', 'decimal'].includes(setting.kind) ? 'input' : 'change';
        control.input.addEventListener(inputEvent, () => {
          const draft = setting.kind === 'boolean' ? control.input.checked : control.input.value;
          if (String(draft) === String(baseValue)) settingDrafts.delete(draftKey);
          else settingDrafts.set(draftKey, draft);
          if (setting.kind === 'boolean') booleanSaveFailed = false;
          updateActions();
          if (setting.kind === 'boolean' && usability.enabled) form.requestSubmit();
        });
      }
      discard.addEventListener('click', () => {
        if (!control) return;
        settingDrafts.delete(draftKey);
        if (setting.kind === 'boolean') setUiToggle(control.input, Boolean(baseValue));
        else control.input.value = String(baseValue);
        const output = control.element.querySelector('.tuners-gain-value');
        if (output) output.textContent = tunerSettingValue(setting, baseValue);
        message.textContent = '';
        booleanSaveFailed = false;
        updateActions();
      });
      if (!actionSetting) actions.append(discard);
      actions.append(save);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (!usability.enabled || (!actionSetting && !isDirty()) ||
            (control && !control.input.reportValidity())) return;
        save.disabled = true;
        try {
          await saveTunerSetting(tuner, setting, actionSetting ? true : control.read(control.input), message);
        } catch (error) {
          message.textContent = error.message || 'Could not save';
          save.disabled = false;
          if (setting.kind === 'boolean') {
            booleanSaveFailed = true;
            updateActions();
          }
        }
      });
      if (control) {
        const controlRow = node('div', 'tuners-setting-control-row');
        controlRow.append(control.element);
        if (!usability.enabled && usability.reason) {
          const help = iconButton('icon-about', usability.reason,
            'ui-button ui-button-secondary ui-icon-button ui-icon-button-compact tuners-setting-help');
          help.dataset.tunerHelp = setting.id;
          controlRow.append(help);
          if (control.element.classList.contains('ui-field')) {
            controlRow.classList.add('tuners-setting-control-row-aligned');
          }
        }
        form.append(controlRow);
      } else if (!usability.enabled && usability.reason) {
        const help = iconButton('icon-about', usability.reason,
          'ui-button ui-button-secondary ui-icon-button ui-icon-button-compact tuners-setting-help');
        help.dataset.tunerHelp = setting.id;
        form.append(help);
      }
      if (!usability.enabled) {
        form.setAttribute('aria-disabled', 'true');
      }
      if (usability.enabled) form.append(actions);
      form.append(message);
      updateActions();

      const commonPrimary = ['frequency_correction_ppm', 'automatic_ppm'].includes(setting.id);
      const commonMore = ['minimum_frequency_mhz', 'maximum_frequency_mhz',
        'reset_frequency_extents', 'sample_rate'].includes(setting.id);
      if (setting.id === 'center_frequency_locked') centerLockBody.append(form);
      else if (group === 'gain') gainBody.append(form);
      else if (setting.id === 'automatic_ppm') commonPrimaryBody.prepend(form);
      else if (commonPrimary) commonPrimaryBody.append(form);
      else if (commonMore) {
        if (setting.id === 'sample_rate') commonSampleBody.append(form);
        else commonLimitsBody.append(form);
      }
      else deviceBody.append(form);
    }
    if (!commonSampleBody.childElementCount) commonSampleBody.append(
      node('span', 'tuners-readout-label', 'Sample rate'),
      node('strong', 'tuners-readout-value',
        tunerInventoryRate(tuner.sample_rate_hz ?? tuner.configured_sample_rate_hz)));
    lockReadout.hidden = centerLockBody.childElementCount === 0;
    readoutsBody.dataset.count = lockReadout.hidden ? '3' : '4';
    gainSection.hidden = gainBody.childElementCount === 0;
    commonMore.hidden = commonLimitsBody.childElementCount === 0;
    commonSection.hidden = commonPrimaryBody.childElementCount === 0 && commonMore.hidden;
    deviceSection.hidden = deviceBody.childElementCount === 0;
    controls.dataset.count = String(Number(!gainSection.hidden) + Number(!commonSection.hidden) +
      Number(!deviceSection.hidden));
  }

  async function changeOperatorState(tuner, state) {
    const path = `/api/v1/admin/tuners/${encodeURIComponent(tuner.id)}/state`;
    await requestJson(path, { method: 'PUT', body: { state } });
    operationNotice = '';
    await refresh();
  }

  function openChannelList(title, channels, returnFocusSelector = '#selected-tuner-stopped') {
    const body = node('div', 'tuners-channel-list');
    for (const group of tunerStoppedChannelGroups(channels)) {
      const card = node('section', 'tuners-channel-group ui-surface');
      const heading = node('div', 'tuners-channel-group-heading');
      heading.append(node('strong', '', group.name));
      const context = [group.system, group.site]
        .filter((value) => value && value.toLowerCase() !== group.name.toLowerCase());
      if (context.length) heading.append(node('small', 'ui-field-detail', context.join(' · ')));
      card.append(heading);
      if (group.primary.length) {
        const count = group.primary.length;
        const label = group.voiceCount ? 'Control' : 'Channel';
        const frequencyHz = group.primary.find((channel) => channel.frequencyHz)?.frequencyHz;
        card.append(node('div', 'tuners-channel-group-line',
          `${count} ${label}${count === 1 ? '' : 's'}${frequencyHz ? ` · ${tunerInventoryFrequency(frequencyHz)}` : ''}`));
      }
      if (group.voiceCount) card.append(node('div', 'tuners-channel-group-line',
        `${group.voiceCount} Voice channel${group.voiceCount === 1 ? '' : 's'}`));
      body.append(card);
    }
    openReadOnlyModal(title, body, { id: 'tuner-channel-list', returnFocusSelector, className: 'admin-modal' });
  }

  async function restoreStoppedChannels(tuner) {
    operationNotice = '';
    renderSelection();
    await requestJson(`/api/v1/admin/tuners/${encodeURIComponent(tuner.id)}/restore`, {
      method: 'POST'
    });
    const deadline = Date.now() + 30_000;
    while (Date.now() < deadline) {
      await refresh(true);
      if (!renderIsCurrent(renderContext)) throw new Error('Restart status unavailable');
      const current = rows.find((candidate) => candidate.id === tuner.id);
      if (!current) throw new Error('Tuner is no longer available');
      if (String(current.transition || '').toLowerCase() === 'restoring') {
        await new Promise((resolve) => window.setTimeout(resolve, 500));
        continue;
      }
      if (current.maintenance_error) throw new Error(String(current.maintenance_error));
      if (!current.restore_result || !Array.isArray(current.restore_result.failed)) {
        throw new Error('Restart result unavailable');
      }
      return tunerStoppedChannels({ stopped_channels: current.restore_result.failed });
    }
    throw new Error('Restart is still running');
  }

  function promptRestore(tuner) {
    const channels = tunerStoppedChannels(tuner);
    if (!channels.length) return;
    const body = node('div', 'admin-confirmation');
    body.append(node('p', '', `${channels.length} channel${channels.length === 1 ? '' : 's'} stopped ` +
      'when this tuner entered Setup. Try to restart eligible channels and return the tuner to Live?'));
    body.append(node('p', 'ui-field-detail', 'Voice channels are temporary and are not resumed.'));
    const message = node('div', 'admin-form-message');
    message.setAttribute('role', 'alert');
    const actions = aliasModalFooter();
    const later = node('button', 'ui-button ui-button-secondary', 'Not now');
    later.type = 'button';
    const restore = node('button', 'ui-button ui-button-primary', 'Resume channels');
    restore.type = 'button';
    actions.append(later, restore);
    body.append(message, actions);
    const modal = openReadOnlyModal('Resume previous channels', body, {
      id: 'restore-tuner-channels', returnFocusSelector: '#selected-tuner-restore', className: 'admin-modal'
    });
    if (!modal) return;
    later.addEventListener('click', modal.close);
    restore.addEventListener('click', () => {
      later.disabled = true;
      restore.disabled = true;
      modal.setBusy(true);
      message.textContent = 'Resuming channels…';
      void restoreStoppedChannels(tuner).then((failed) => {
        modal.setBusy(false);
        modal.close();
        if (failed.length) {
          window.setTimeout(() => openChannelList('Couldn’t start', failed, '#selected-tuner-restore'), 0);
        } else {
          operationNotice = 'Eligible channels resumed';
          renderSelection();
        }
      }).catch((error) => {
        message.textContent = error.message || 'Could not resume channels';
        later.disabled = false;
        restore.disabled = false;
        modal.setBusy(false);
      });
    });
    modal.focus?.(restore);
  }

  function confirmGoLiveWithoutResuming(tuner) {
    const body = node('div', 'admin-confirmation');
    body.append(node('p', '', 'Make this tuner available without resuming the channels stopped for Setup?'));
    body.append(node('p', 'ui-field-detail',
      'Those channels will stay stopped, and this tuner will no longer remember them for the Resume action.'));
    const message = node('div', 'admin-form-message');
    message.setAttribute('role', 'alert');
    const actions = aliasModalFooter();
    const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
    cancel.type = 'button';
    const confirm = node('button', 'ui-button ui-button-primary', 'Go live without resuming');
    confirm.type = 'button';
    actions.append(cancel, confirm);
    body.append(message, actions);
    const modal = openReadOnlyModal('Go live without resuming', body, {
      id: 'tuner-live-without-resuming', returnFocusSelector: '#selected-tuner-live', className: 'admin-modal'
    });
    if (!modal) return;
    cancel.addEventListener('click', modal.close);
    confirm.addEventListener('click', () => {
      confirm.disabled = true;
      cancel.disabled = true;
      modal.setBusy(true);
      message.textContent = 'Going live…';
      void changeOperatorState(tuner, 'live').then(() => {
        modal.setBusy(false);
        modal.close();
      }).catch((error) => {
        message.textContent = error.message || 'Could not go live';
        confirm.disabled = false;
        cancel.disabled = false;
        modal.setBusy(false);
      });
    });
    modal.focus?.(confirm);
  }

  function confirmStateChange(tuner, state, returnFocusSelector) {
    const body = node('div', 'admin-confirmation');
    const channelCount = Math.max(0, Number(tuner.channel_count) || 0);
    const stateLabel = state === 'setup' ? 'Enter Setup' : 'Disable tuner';
    const stoppedCopy = channelCount > 0 ?
      `${channelCount} active channel${channelCount === 1 ? '' : 's'} will stop. ` : '';
    body.append(node('p', '', state === 'setup' ?
      `${stoppedCopy}The tuner stays on for adjustments but is unavailable to channels until you return to Live.` :
      `${stoppedCopy}The tuner hardware will also stop.`));
    const message = node('div', 'admin-form-message');
    message.setAttribute('role', 'alert');
    const actions = aliasModalFooter();
    const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
    cancel.type = 'button';
    const confirm = node('button', state === 'disabled' ? 'ui-button ui-button-danger' : 'ui-button ui-button-primary',
      stateLabel);
    confirm.type = 'button';
    actions.append(cancel, confirm);
    body.append(message, actions);
    const modal = openReadOnlyModal(stateLabel, body, {
      id: 'change-tuner-state', returnFocusSelector, className: 'admin-modal'
    });
    if (!modal) return;
    cancel.addEventListener('click', modal.close);
    confirm.addEventListener('click', () => {
      confirm.disabled = true;
      cancel.disabled = true;
      modal.setBusy(true);
      message.textContent = state === 'setup' ? 'Entering Setup…' : 'Stopping…';
      void changeOperatorState(tuner, state).then(() => {
        modal.setBusy(false);
        modal.close();
      }).catch((error) => {
        message.textContent = error.message || 'Could not change state';
        confirm.disabled = false;
        cancel.disabled = false;
        modal.setBusy(false);
      });
    });
    modal.focus?.(confirm);
  }

  function confirmRemoveRecording(tuner) {
    const body = node('div', 'admin-confirmation');
    body.append(node('p', '', `Remove the recording tuner for ${tuner.name}? The WAV file will stay on disk.`));
    const message = node('div', 'admin-form-message');
    message.setAttribute('role', 'alert');
    const actions = aliasModalFooter();
    const cancel = node('button', 'ui-button ui-button-secondary', 'Cancel');
    cancel.type = 'button';
    const remove = node('button', 'ui-button ui-button-danger', 'Remove recording tuner');
    remove.type = 'button';
    actions.append(cancel, remove);
    body.append(message, actions);
    const modal = openReadOnlyModal('Remove recording tuner', body, {
      id: 'remove-recording-tuner', returnFocusSelector: '#selected-tuner-remove', className: 'admin-modal'
    });
    if (!modal) return;
    cancel.addEventListener('click', modal.close);
    remove.addEventListener('click', () => {
      remove.disabled = true;
      cancel.disabled = true;
      modal.setBusy(true);
      message.textContent = 'Removing recording tuner…';
      void requestJson(`/api/v1/admin/tuners/${encodeURIComponent(tuner.id)}`, { method: 'DELETE' })
        .then(async () => {
          selectedId = '';
          operationNotice = 'Recording tuner removed';
          modal.setBusy(false);
          modal.close();
          await refresh();
        }).catch((error) => {
          message.textContent = error.message || 'Could not remove the recording tuner.';
          remove.disabled = false;
          cancel.disabled = false;
          modal.setBusy(false);
        });
    });
    modal.focus?.(remove);
  }

  function renderSelection() {
    const tuner = selectedTuner();
    listBody.replaceChildren();
    if (!rows.length) {
      listBody.append(node('div', 'empty', 'No tuners found'));
    }
    for (const row of rows) {
      const button = node('button', 'tuners-list-item ui-button ui-button-secondary');
      button.type = 'button';
      button.setAttribute('aria-pressed', String(row.id === selectedId));
      const main = node('span', 'tuners-list-item-main');
      const copy = node('span', 'tuners-list-item-copy');
      const channelCount = Math.max(0, Number(row.channel_count) || 0);
      const center = row.frequency_hz ?? row.configured_frequency_hz;
      const rate = row.sample_rate_hz ?? row.configured_sample_rate_hz;
      copy.append(node('span', 'tuners-list-item-name', row.name),
        node('span', 'tuners-list-item-meta',
          `${channelCount} active · ${tunerInventoryFrequency(center)} · ${tunerInventoryRate(rate)}`));
      main.append(iconGlyph(String(row.tuner_type).toLowerCase() === 'recording' ?
        'icon-recording' : 'icon-tuner'), copy);
      const status = tunerOperatorStateLabel(row);
      const indicators = node('span', 'tuners-list-item-indicators');
      indicators.append(uiPill(status.label, status.tone));
      button.append(main, indicators);
      button.addEventListener('click', () => {
        if (selectedId === row.id) return;
        selectedId = row.id;
        operationNotice = '';
        renderSelection();
      });
      listBody.append(button);
    }

    detailsBody.replaceChildren();
    recoveryBody.replaceChildren();
    messagesBody.replaceChildren();
    if (!tuner) {
      detailsBody.append(node('div', 'empty', 'Select a tuner'));
      if (operationNotice) messagesBody.append(
        node('div', 'ui-notice ui-notice-warning tuners-detail-message', operationNotice));
      gainBody.replaceChildren();
      centerHost.replaceChildren();
      centerLockBody.replaceChildren();
      commonPrimaryBody.replaceChildren();
      commonLimitsBody.replaceChildren();
      commonSampleBody.replaceChildren();
      deviceBody.replaceChildren();
      spectrumBody.hidden = true;
      readoutsBody.hidden = true;
      recoveryBody.hidden = true;
      controls.hidden = true;
      controls.dataset.count = '0';
      gainSection.hidden = true;
      commonSection.hidden = true;
      deviceSection.hidden = true;
      spectrum?.selectTarget('');
      return;
    }
    spectrumBody.hidden = false;
    readoutsBody.hidden = false;
    controls.hidden = false;
    const status = tunerOperatorStateLabel(tuner);
    const state = tunerOperatorState(tuner);
    const transitioning = Boolean(tuner.transition);
    const stoppedChannels = tunerStoppedChannels(tuner);
    const title = node('div', 'tuners-detail-heading');
    const identity = node('div', 'tuners-detail-identity');
    identity.append(node('h2', '', tuner.name));
    if (tuner.device_group?.kind && tuner.device_group.kind !== 'single') {
      identity.append(node('small', 'ui-field-detail',
        `${tuner.device_group.kind} · ${tuner.device_group.role || 'member'}`));
    }
    title.append(uiIconTile(String(tuner.tuner_type).toLowerCase() === 'recording' ?
      'icon-recording' : 'icon-tuner'), identity);
    if (transitioning) title.append(uiPill(status.label, status.tone));
    const mode = node('div', 'tuners-mode ui-segmented');
    mode.setAttribute('role', 'group');
    mode.setAttribute('aria-label', 'Tuner mode');
    for (const next of ['live', 'setup', 'disabled']) {
      const button = node('button', 'ui-segmented-option',
        next === 'live' ? 'Live' : next === 'setup' ? 'Setup' : 'Disabled');
      button.type = 'button';
      button.dataset.mode = next;
      button.id = next === 'setup' && state === 'disabled' ? 'selected-tuner-start' :
        `selected-tuner-${next === 'disabled' ? 'disable' : next}`;
      button.setAttribute('aria-pressed', String(next === state));
      const unavailable = transitioning || (state === 'disabled' && next === 'live');
      button.setAttribute('aria-disabled', String(unavailable));
      button.title = unavailable ? (transitioning ? 'Wait for the tuner to finish changing state' :
        'Start Setup first') : next === 'live' ? 'Available to channels' :
        next === 'setup' ? 'Keep tuner on for adjustments; active channels stop' :
          'Stop channels and turn off tuner hardware';
      button.addEventListener('click', () => {
        if (unavailable || next === state) return;
        if (next === 'setup' && state === 'disabled') {
          button.setAttribute('aria-disabled', 'true');
          promptedSetupId = tuner.id;
          void changeOperatorState(tuner, 'setup').catch((error) => {
            promptedSetupId = '';
            operationNotice = error.message || 'Could not start tuner';
            renderSelection();
          });
        } else if (next === 'setup') {
          confirmStateChange(tuner, 'setup', '#selected-tuner-setup');
        } else if (next === 'live' && stoppedChannels.length) {
          confirmGoLiveWithoutResuming(tuner);
        } else if (next === 'live') {
          button.setAttribute('aria-disabled', 'true');
          void changeOperatorState(tuner, 'live').catch((error) => {
            operationNotice = error.message || 'Could not go live';
            renderSelection();
          });
        } else {
          confirmStateChange(tuner, 'disabled', '#selected-tuner-disable');
        }
      });
      mode.append(button);
    }
    const headerActions = node('div', 'tuners-header-actions');
    if (String(tuner.tuner_class).toLowerCase() === 'recording') {
      const remove = iconButton('icon-trash', 'Remove recording tuner',
        'ui-button ui-button-danger-quiet ui-icon-button');
      remove.id = 'selected-tuner-remove';
      remove.addEventListener('click', () => confirmRemoveRecording(tuner));
      headerActions.append(remove);
    }
    headerActions.append(mode);
    const selectedHeader = node('div', 'tuners-selected-header ui-section-title');
    selectedHeader.append(title, headerActions);
    detailsBody.append(selectedHeader);
    channelValue.textContent = String(Math.max(0, Number(tuner.channel_count) || 0));
    if (stoppedChannels.length) {
      const stopped = node('button', 'ui-button ui-button-secondary tuners-stopped-channels',
        'View stopped channels');
      stopped.type = 'button';
      stopped.id = 'selected-tuner-stopped';
      stopped.addEventListener('click', () => openChannelList('Stopped channels', stoppedChannels));
      recoveryBody.append(node('span', '',
        `${stoppedChannels.length} channel${stoppedChannels.length === 1 ? '' : 's'} stopped for Setup`));
      const recoveryActions = node('div', 'tuners-recovery-actions');
      recoveryActions.append(stopped);
      if (state === 'setup') {
        const restore = node('button', 'ui-button ui-button-primary', 'Resume & go Live');
        restore.type = 'button';
        restore.id = 'selected-tuner-restore';
        restore.disabled = transitioning;
        restore.addEventListener('click', () => promptRestore(tuner));
        recoveryActions.prepend(restore);
      }
      recoveryBody.append(recoveryActions);
    }
    recoveryBody.hidden = !stoppedChannels.length;
    if (operationNotice) messagesBody.append(node('div', 'ui-notice tuners-detail-message', operationNotice));
    if (tuner.maintenance_error) messagesBody.append(node('div',
      'ui-notice ui-notice-danger tuners-detail-message',
      String(tuner.maintenance_error)));
    if (tuner.error_message) messagesBody.append(
      node('div', 'error tuners-detail-message', String(tuner.error_message)));
    renderSettings(tuner);
    selectedSection.classList.toggle('tuners-signal-idle', !tuner.spectrum_available);
    spectrum?.selectTarget(tuner.spectrum_target_id || '');
    if (state === 'setup' && !transitioning && promptedSetupId === tuner.id) {
      promptedSetupId = '';
      window.setTimeout(() => promptRestore(tuner), 0);
    }
  }

  async function refresh(throwOnError = false) {
    const generation = ++refreshGeneration;
    if (refreshTimer !== null) window.clearTimeout(refreshTimer);
    refreshTimer = null;
    try {
      const response = await api('/api/v1/admin/tuners', {}, { signal: renderContext.signal });
      if (!renderIsCurrent(renderContext) || generation !== refreshGeneration) return;
      const active = right.contains(document.activeElement) ?
        document.activeElement : null;
      const activeSetting = active?.dataset?.tunerSetting || '';
      const activeHelp = active?.dataset?.tunerHelp || '';
      const activeId = active?.id || '';
      const selectionStart = active instanceof HTMLInputElement ? active.selectionStart : null;
      const selectionEnd = active instanceof HTMLInputElement ? active.selectionEnd : null;
      const typingCenter = Boolean(right.querySelector('.tuners-center-frequency.is-typing'));
      rows = tunerInventoryRows(response);
      tunerCount.textContent = `${number(rows.length)} tuner${rows.length === 1 ? '' : 's'}`;
      analyzeButton.disabled = analyzing;
      if (!rows.some((row) => row.id === selectedId)) selectedId = rows[0]?.id || '';
      if (typingCenter) {
        spectrum?.selectTarget(selectedTuner()?.spectrum_target_id || '');
      } else {
        renderSelection();
        const replacement = activeSetting ? right.querySelector(`[data-tuner-setting="${activeSetting}"]`) :
          activeHelp ? right.querySelector(`[data-tuner-help="${activeHelp}"]`) :
            activeId ? document.getElementById(activeId) : null;
        if (replacement instanceof HTMLElement && right.contains(replacement) &&
            !replacement.matches(':disabled')) {
          replacement.focus({ preventScroll: true });
          if (replacement instanceof HTMLInputElement && selectionStart != null && selectionEnd != null) {
            replacement.setSelectionRange(selectionStart, selectionEnd);
          }
        }
      }
    } catch (error) {
      if (!renderIsCurrent(renderContext) || generation !== refreshGeneration) return;
      listBody.replaceChildren(node('div', 'error', error.message || 'Could not load tuners.'));
      tunerCount.textContent = 'Unavailable';
      detailsBody.replaceChildren(node('div', 'error', 'Tuner details are unavailable.'));
      centerHost.replaceChildren();
      spectrumBody.hidden = true;
      readoutsBody.hidden = true;
      recoveryBody.replaceChildren();
      messagesBody.replaceChildren();
      controls.hidden = true;
      controls.dataset.count = '0';
      gainBody.replaceChildren();
      gainSection.hidden = true;
      analyzeButton.disabled = true;
      spectrum?.selectTarget('');
      if (throwOnError) throw error;
    } finally {
      if (renderIsCurrent(renderContext) && generation === refreshGeneration) {
        refreshTimer = window.setTimeout(() => {
          if (document.hidden) {
            refreshTimer = window.setTimeout(() => void refresh(), 5_000);
          } else void refresh();
        }, 5_000);
      }
    }
  }

  analyzeButton.addEventListener('click', async () => {
    const plannerTab = window.open('about:blank', '_blank');
    if (!plannerTab) {
      operationNotice = 'Allow pop-ups to open RadioResolve.';
      renderSelection();
      return;
    }
    plannerTab.opener = null;
    analyzing = true;
    analyzeButton.disabled = true;
    try {
      const snapshot = await api('/api/v1/admin/tuners/rf-analysis', {}, { signal: renderContext.signal });
      if (!renderIsCurrent(renderContext)) {
        plannerTab.close();
        return;
      }
      plannerTab.location.replace(buildRadioResolvePlannerUrl(snapshot));
    } catch (error) {
      plannerTab.close();
      if (renderIsCurrent(renderContext)) {
        operationNotice = error.message || 'Could not open external RF analysis.';
        renderSelection();
      }
    } finally {
      analyzing = false;
      if (renderIsCurrent(renderContext)) analyzeButton.disabled = false;
    }
  });
  rescanUsbButton.addEventListener('click', async () => {
    rescanUsbButton.disabled = true;
    try {
      await requestJson('/api/v1/admin/tuners/rescan', { method: 'POST' });
      operationNotice = 'USB tuner rescan requested.';
      await refresh();
    } catch (error) {
      operationNotice = error.message || 'Could not rescan USB tuners.';
      renderSelection();
    } finally {
      rescanUsbButton.disabled = false;
    }
  });
  void refresh();
  try {
    const snapPresetDocument = await requestSpectrumSnapPresetDocument();
    if (!renderIsCurrent(renderContext)) return;
    spectrum = tunerSpectrumPanel(snapPresetDocument, {
      managedSelection: true,
      inlineDisplayOptions: true,
      basicOperator: true,
      frequencyCursor: true,
      viewportControls: true,
      wheelZoom: false,
      profileSelection: true,
      targetId: selectedTuner()?.spectrum_target_id || ''
    });
    pageConnections.add(spectrum);
    spectrumBody.replaceChildren(spectrum.element);
  } catch (error) {
    if (renderIsCurrent(renderContext)) spectrumBody.replaceChildren(
      node('div', 'error', error.message || 'Spectrum is unavailable.'));
  }
}

function receiverHealthSavedActivitySection() {
  const activityPage = route.get('view') === 'admin' && route.get('tab') === 'activity';
  const database = serviceStatus?.database;
  const logging = statsLoggingState();
  const loggingState = logging.available && logging.state ? semanticLabel(logging.state) : 'Unknown';
  const failed = loggingState === 'Failed';
  const summaryState = !logging.available ? 'Unknown' : logging.summaryActive ? 'On' :
    (failed ? 'Error' : logging.summaryConfigured ? 'On · Not running' : 'Off');
  const historyState = !logging.available ? 'Unknown' : logging.historyActive ? 'On' :
    (failed && logging.historyConfigured ? 'Error' : logging.historyConfigured ? 'On · Not running' :
      (logging.historyRetained ? 'Off · Saved history available' : 'Off'));
  const databaseDisplay = adminDatabaseDisplay(database);
  const body = node('div', 'receiver-health-saved-activity-body');
  let actions = null;
  if (capabilityAllowed(ACCESS_CAPABILITIES.ADMIN_SETTINGS)) {
    const settingsLink = anchor(activityPage ? 'Receiver status' : 'Open Activity settings',
      href('admin', { tab: activityPage ? 'health' : 'activity' }),
      'ui-button ui-button-secondary');
    settingsLink.dataset.receiverHealthFocus = 'saved-activity-settings';
    actions = sectionActionHost(settingsLink);
  }
  const collectionMetrics = metrics([
    ['Activity summaries', logging.summaryActive, summaryState],
    ['Individual events', logging.historyActive, historyState],
    ['Activity storage', database?.database_bytes, databaseDisplay]
  ], true);
  collectionMetrics.classList.add('ui-metric-grid-3');
  [...collectionMetrics.children].forEach((metric) => metric.classList.add('ui-metric-compact'));
  body.append(collectionMetrics);
  const result = receiverHealthSection('saved-activity', activityPage ? 'Current collection status' : 'Saved activity', body, actions);
  result.id = 'receiver-health-saved-activity';
  return result;
}

function adminSettingsTree(groups, active) {
  const navigation = node('nav', 'admin-settings-tree ui-settings-navigation');
  navigation.setAttribute('aria-label', 'Administration sections');
  const picker = node('label', 'admin-settings-picker ui-settings-picker');
  const pickerLabel = node('span', 'admin-settings-picker-label ui-settings-picker-label', 'Administration section');
  const select = node('select', 'ui-select');
  select.setAttribute('aria-label', 'Administration section');
  groups.forEach((group) => {
    const optionGroup = node('optgroup');
    optionGroup.label = group.label;
    group.items.forEach((item) => {
      const option = node('option', '', item.label);
      option.value = item.id;
      option.selected = item.id === active;
      optionGroup.append(option);
    });
    select.append(optionGroup);
  });
  select.addEventListener('change', () => navigateTo(href('admin', { tab: select.value })));
  picker.append(pickerLabel, select);
  navigation.append(node('div', 'admin-settings-sidebar-heading ui-settings-navigation-title', 'Administration'), picker);
  groups.forEach((group) => {
    const disclosure = node('section', 'admin-settings-branch ui-settings-nav-group');
    disclosure.append(node('h2', 'admin-settings-group-title ui-settings-nav-group-title', group.label));
    const links = node('div', 'admin-settings-branch-items ui-settings-nav-items');
    group.items.forEach((item) => {
      const link = anchor('', href('admin', { tab: item.id }), 'admin-settings-leaf ui-settings-nav-link');
      link.append(iconGlyph(`icon-${item.icon}`), node('span', '', item.label));
      link.classList.toggle('active', item.id === active);
      if (item.id === active) link.setAttribute('aria-current', 'page');
      links.append(link);
    });
    disclosure.append(links);
    navigation.append(disclosure);
  });
  return navigation;
}

